/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2017_SEED = {"dse/writing/part-b/2017/Q2":[{"front":"let slip","meaning":"錯失；白白放走","examples":[{"en":"I once let an important chance slip because I was afraid.","zh":"我曾因為害怕而錯失一個重要機會。"},{"en":"To let an opportunity slip means to lose it because you do not act in time.","zh":"「let an opportunity slip」表示因為沒有及時行動而錯失機會。"},{"en":"She let the scholarship slip by forgetting to submit the application.","zh":"她忘記提交申請，白白錯失了獎學金機會。"},{"en":"Fear can make people let good chances slip even when they truly want them.","zh":"恐懼可以令人即使真心想把握，也讓好機會溜走。"},{"en":"Once a time-limited opportunity has slipped away, it may not return.","zh":"有時限的機會一旦錯失，未必會再次出現。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"the chance I chose","meaning":"我選擇把握的機會","examples":[{"en":"The chance I chose helped me become braver.","zh":"我選擇把握的機會令我變得更勇敢。"},{"en":"“The chance I chose” means an opportunity I deliberately decided to accept rather than avoid.","zh":"「the chance I chose」表示我刻意決定接受，而不是逃避的一個機會。"},{"en":"The course I joined became the chance I chose to challenge myself.","zh":"我參加的課程成為了我選擇用來挑戰自己的機會。"},{"en":"Unlike the opportunity I missed, the chance I chose required me to act despite fear.","zh":"與我錯失的機會不同，我選擇把握的機會要求我即使害怕仍要行動。"},{"en":"A chance becomes meaningful when choosing it changes what we are willing to do next.","zh":"當一個機會改變了我們下一次願意做甚麼，它便變得有意義。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"posted after midnight","meaning":"午夜後發布","examples":[{"en":"The reflection was posted after midnight.","zh":"這篇反思文章在午夜後發布。"},{"en":"“Posted after midnight” means uploaded or published online after twelve o’clock at night.","zh":"「posted after midnight」表示在晚上十二時之後上載或發布到網上。"},{"en":"She posted the photograph after midnight when everyone else was asleep.","zh":"大家都睡着後，她在午夜後發布了那張照片。"},{"en":"A reflection posted after midnight may feel especially personal because it was written late at night.","zh":"午夜後發布的反思可能特別私人，因為它是在深夜寫成。"},{"en":"Posting something after midnight suggests the writer was still thinking about it very late.","zh":"午夜後仍發布內容，往往表示作者很晚仍在想着那件事。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"while a song is still looping in my head","meaning":"當一首歌仍在腦海中不斷播放","examples":[{"en":"I wrote this while a song was still looping in my head.","zh":"我寫這篇文章時，一首歌仍在腦海中不斷播放。"},{"en":"This means the writer was composing the reflection while the same song kept repeating mentally.","zh":"這句話表示作者寫反思時，同一首歌仍在腦海反覆重播。"},{"en":"I tried to study while a song was still looping in my head from the café.","zh":"我嘗試溫習時，咖啡店那首歌仍在腦海中不斷播放。"},{"en":"When a song is still looping in your head, its words or mood may influence what you are thinking about.","zh":"當一首歌仍在腦海中重播，它的歌詞或情緒可能影響你的思考。"},{"en":"Music can stay mentally present even after it has stopped playing aloud.","zh":"即使音樂已經停止播放，它仍可能繼續留在人的腦海中。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"loop in my head","meaning":"在腦海中不斷重播","examples":[{"en":"The song kept looping in my head after midnight.","zh":"午夜過後，那首歌仍在我腦海中不斷重播。"},{"en":"To loop in someone’s head means to repeat again and again in their mind.","zh":"「loop in someone’s head」表示某段聲音或說話在腦海中反覆出現。"},{"en":"The same advertising jingle looped in my head all afternoon.","zh":"同一段廣告旋律整個下午都在我腦海中不斷重播。"},{"en":"A powerful lyric may loop in your head because it connects with a personal memory.","zh":"一句有力量的歌詞可能因為連結到個人回憶而在腦海中反覆出現。"},{"en":"When something loops in your head, it can be difficult to stop thinking about it.","zh":"當某件事在腦海中不斷重播，人往往很難停止想它。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"do not merely play","meaning":"不只是播放","examples":[{"en":"Some songs do not merely play; they challenge you.","zh":"有些歌不只是播放；它們還會挑戰你。"},{"en":"“Do not merely play” means the songs do more than provide sound or entertainment.","zh":"「do not merely play」表示歌曲不只是提供聲音或娛樂。"},{"en":"Some films do not merely entertain; they force viewers to question their beliefs.","zh":"有些電影不只是娛樂，還會迫使觀眾反思自己的信念。"},{"en":"A meaningful song may not merely play in the background but stay with the listener emotionally.","zh":"一首有意義的歌可能不只是作為背景播放，而會在情感上留在聽眾心中。"},{"en":"“Not merely” emphasises that something has a deeper effect than its basic function.","zh":"「not merely」強調某件事的影響比基本功能更深。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"interrogate you","meaning":"盤問；深深追問","examples":[{"en":"Some songs seem to interrogate you about your choices.","zh":"有些歌好像會深深追問你作出的選擇。"},{"en":"To interrogate you here means to make you question yourself deeply and uncomfortably.","zh":"這裏的「interrogate you」表示令你深刻、甚至有點不舒服地質問自己。"},{"en":"The novel seemed to interrogate me about how I treated my family.","zh":"那本小說好像在追問我平時如何對待家人。"},{"en":"A powerful lyric can interrogate listeners by forcing them to examine decisions they usually avoid thinking about.","zh":"有力量的歌詞可以迫使聽眾檢視平時避而不想的決定。"},{"en":"In this figurative use, no one is literally questioning you; the message creates the questions inside your mind.","zh":"這是比喻用法，並非真的有人盤問你，而是訊息在你心中產生問題。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"the one I heard tonight","meaning":"我今晚聽到的那一首","examples":[{"en":"The one I heard tonight made me think about missed chances.","zh":"我今晚聽到的那一首令我想起錯失的機會。"},{"en":"“The one I heard tonight” refers to a particular song or piece already understood from the context.","zh":"「the one I heard tonight」指上下文已清楚知道的某一首歌或作品。"},{"en":"Of all the songs on the album, the one I heard tonight stayed with me most strongly.","zh":"整張專輯之中，我今晚聽到的那一首最令我難忘。"},{"en":"The one I heard tonight connected with my memories because its message was about opportunity.","zh":"我今晚聽到的那一首談及機會，因此勾起了我的回憶。"},{"en":"“The one” avoids repeating a noun that has already been mentioned.","zh":"「the one」可以避免重複之前已提及的名詞。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"life handed us “one shot”","meaning":"人生給予我們一次機會","examples":[{"en":"The song asks what we would do if life handed us “one shot”.","zh":"那首歌問，如果人生給予我們一次機會，我們會怎樣做。"},{"en":"If life hands us “one shot”, it gives us one important opportunity that may not return.","zh":"如果人生給予我們「one shot」，就是給我們一個可能不會再來的重要機會。"},{"en":"An interview for a dream job may feel as if life has handed you one shot.","zh":"夢想工作的面試可能令人感覺人生給了自己一次重要機會。"},{"en":"Thinking of a chance as “one shot” creates urgency because delay may mean losing it.","zh":"把機會看成「只有一次」，會帶來緊迫感，因為拖延可能代表失去它。"},{"en":"The phrase presents opportunity as something life offers but does not force us to accept.","zh":"這個說法把機會描寫成人生給予的東西，但人生不會逼我們接受。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"take it","meaning":"把握它","examples":[{"en":"If life gives us one chance, we may choose to take it.","zh":"如果人生給我們一次機會，我們可以選擇把握它。"},{"en":"To take an opportunity means to accept it and act on it.","zh":"把握一個機會表示接受它並採取行動。"},{"en":"She was offered a place on the exchange programme and decided to take it.","zh":"她獲得交流計劃名額後，決定把握這個機會。"},{"en":"Taking a chance often requires action before we know exactly what will happen.","zh":"把握機會往往需要在還不知道結果時先行動。"},{"en":"An opportunity has little value if we never choose to take it.","zh":"如果我們從不選擇把握，機會本身便沒有太大價值。"}],"source":"2017 Q2.pdf","sourcePage":1},{"front":"let it slip","meaning":"錯失它","examples":[{"en":"Sometimes fear makes us let an opportunity slip.","zh":"有時恐懼會令我們錯失一個機會。"},{"en":"To let it slip means to fail to use or keep an opportunity until it is gone.","zh":"「let it slip」表示未有使用或把握一個機會，直到它消失。"},{"en":"He let the internship slip by replying after the deadline.","zh":"他在截止日期後才回覆，因此錯失了實習機會。"},{"en":"People may let a chance slip because waiting feels safer than acting.","zh":"人可能因為等待感覺比行動安全，而白白讓機會溜走。"},{"en":"Regret often begins when we realise we let something valuable slip through hesitation.","zh":"當我們發現因猶豫而錯失珍貴事物，遺憾往往便開始。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"like to imagine","meaning":"喜歡想像","examples":[{"en":"We like to imagine opportunities as grand entrances.","zh":"我們喜歡把機會想像成隆重登場。"},{"en":"To like to imagine something in a certain way means to prefer thinking of it through an attractive mental picture.","zh":"「like to imagine」表示喜歡用某種吸引的畫面去理解一件事。"},{"en":"People like to imagine success as one dramatic moment, although it usually develops gradually.","zh":"人喜歡把成功想像成一個戲劇性的時刻，雖然它通常是逐步形成。"},{"en":"We may like to imagine opportunities as obvious because that feels easier than noticing small chances.","zh":"我們可能喜歡把機會想像得很明顯，因為這比留意小機會容易。"},{"en":"What we like to imagine is not always how life actually works.","zh":"我們喜歡想像的情況，未必就是人生真正運作的方式。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"opportunities as grand entrances","meaning":"把機會想像成隆重登場","examples":[{"en":"We often imagine opportunities as grand entrances with applause.","zh":"我們常把機會想像成伴隨掌聲的隆重登場。"},{"en":"“Opportunities as grand entrances” presents chances as dramatic, obvious events that attract everyone’s attention.","zh":"「opportunities as grand entrances」把機會描寫成戲劇化、明顯而吸引所有人注意的事件。"},{"en":"People may expect a dream opportunity to arrive like a grand entrance with lights and excitement.","zh":"人可能期待夢想機會像伴隨燈光和興奮氣氛的隆重登場一樣出現。"},{"en":"In reality, many important chances look ordinary rather than like grand entrances.","zh":"事實上，很多重要機會看起來都很平凡，而不是隆重登場。"},{"en":"The metaphor contrasts dramatic expectations with the quiet way opportunities often appear.","zh":"這個比喻把戲劇化的期望與機會經常安靜出現的方式作對比。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"a stage, a prize and applause","meaning":"舞台、獎項和掌聲","examples":[{"en":"We imagine opportunities as a stage, a prize and applause.","zh":"我們把機會想像成舞台、獎項和掌聲。"},{"en":"“A stage, a prize and applause” represents obvious public success and recognition.","zh":"「a stage, a prize and applause」代表明顯的公開成功和認可。"},{"en":"Winning a competition may bring a stage, a prize and applause, but many valuable opportunities bring none of these.","zh":"贏得比賽可能帶來舞台、獎項和掌聲，但很多有價值的機會甚麼也沒有。"},{"en":"Young people may mistake public recognition for the only form of success.","zh":"年輕人可能誤以為公開認可就是成功唯一的形式。"},{"en":"The phrase highlights glamorous rewards that can make opportunities look more dramatic than they really are.","zh":"這個片語突出光鮮的獎勵，令機會看起來比實際更戲劇化。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"in reality","meaning":"事實上","examples":[{"en":"In reality, opportunities often arrive quietly.","zh":"事實上，機會往往安靜地出現。"},{"en":"“In reality” introduces what is actually true rather than what people imagine or expect.","zh":"「in reality」用來帶出真正的情況，而不是人們想像或期望的情況。"},{"en":"The job looked easy online, but in reality it required long hours.","zh":"那份工作在網上看起來很容易，但事實上工時很長。"},{"en":"We may expect confidence to come first; in reality, confidence often grows after action.","zh":"我們可能期望先有自信才行動；事實上，自信常在行動後才成長。"},{"en":"This phrase is useful for correcting an unrealistic idea with the actual situation.","zh":"這個片語適合用真正情況修正不切實際的想法。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"arrive in ordinary forms","meaning":"以平凡的形式出現","examples":[{"en":"Opportunities often arrive in ordinary forms.","zh":"機會往往以平凡的形式出現。"},{"en":"To arrive in ordinary forms means to appear through simple, everyday situations rather than dramatic events.","zh":"以平凡的形式出現是指透過簡單日常情況，而不是戲劇化事件出現。"},{"en":"A new friendship may arrive in the ordinary form of sitting beside someone in class.","zh":"一段新友誼可能以在課堂坐在某人旁邊這種平凡形式開始。"},{"en":"An opportunity may arrive in the form of a form, email, invitation or small request.","zh":"一個機會可能以表格、電郵、邀請或小請求的形式出現。"},{"en":"People can miss important chances when they expect opportunity to look extraordinary.","zh":"如果人總期望機會看起來非同尋常，就可能錯過重要機會。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"a form on a teacher’s desk","meaning":"老師桌上的一張表格","examples":[{"en":"An opportunity may arrive as a form on a teacher’s desk.","zh":"一個機會可能以老師桌上的一張表格出現。"},{"en":"“A form on a teacher’s desk” is an ordinary application sheet that may represent a larger opportunity.","zh":"「a form on a teacher’s desk」是一張普通申請表，但可能代表更大的機會。"},{"en":"The exchange programme first appeared to me as a form on a teacher’s desk.","zh":"那個交流計劃最初只是以老師桌上一張表格的形式出現在我面前。"},{"en":"A simple piece of paper can lead to a competition, trip or new experience.","zh":"一張簡單紙張可以帶來比賽、旅程或新經歷。"},{"en":"Important opportunities do not always look important when we first see them.","zh":"重要機會第一次出現時，不一定看起來很重要。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"hesitate to answer","meaning":"猶豫是否回覆","examples":[{"en":"An opportunity may come as a message we hesitate to answer.","zh":"一個機會可能以一則我們猶豫是否回覆的訊息出現。"},{"en":"To hesitate to answer means to pause because you are uncertain, nervous or afraid of replying.","zh":"「hesitate to answer」表示因不確定、緊張或害怕而停下來，不立即回覆。"},{"en":"She hesitated to answer the invitation because she worried she would not fit in.","zh":"她擔心自己融入不了，所以猶豫是否回覆那個邀請。"},{"en":"Fear can make us hesitate to answer even when the message contains something we want.","zh":"即使訊息帶來我們想要的東西，恐懼也可以令我們猶豫是否回覆。"},{"en":"A short delay can matter when an opportunity requires a quick response.","zh":"如果機會需要快速回應，短暫拖延也可能有影響。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"a seat where our voice might shake","meaning":"一個可能令我們聲音顫抖的位置","examples":[{"en":"An opportunity may be a seat where our voice might shake.","zh":"一個機會可能是一個令我們聲音顫抖的位置。"},{"en":"This phrase means a place or role where we have to speak despite feeling nervous.","zh":"這個片語表示一個需要我們即使緊張仍要發言的位置或角色。"},{"en":"A seat at a meeting may become a place where your voice shakes because you are speaking publicly for the first time.","zh":"第一次公開發言時，會議中的一個座位可能變成令你聲音顫抖的位置。"},{"en":"Valuable opportunities can feel frightening when they put us in situations where our confidence is tested.","zh":"有價值的機會可能令人害怕，因為它們會把我們放進考驗自信的情況。"},{"en":"A shaking voice does not mean we should leave the seat; it may mean we are doing something new.","zh":"聲音顫抖不代表我們應離開那個位置；它可能代表我們正在做新事情。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"make me look back at","meaning":"令我回望","examples":[{"en":"The song made me look back at two important moments.","zh":"那首歌令我回望兩個重要時刻。"},{"en":"To make someone look back at something means to cause them to remember and reconsider a past experience.","zh":"「make someone look back at」表示令某人回想並重新思考過去經歷。"},{"en":"Finding my old diary made me look back at how much I had changed.","zh":"找到舊日記令我回望自己改變了多少。"},{"en":"Music can make us look back at choices we thought we had forgotten.","zh":"音樂可以令我們回望原以為已忘記的選擇。"},{"en":"Looking back becomes useful when past experiences help us understand present behaviour.","zh":"當過去經歷幫助我們理解現在的行為，回望便會有價值。"}],"source":"2017 Q2.pdf","sourcePage":2},{"front":"fear chose for me","meaning":"恐懼替我作出選擇","examples":[{"en":"There was one moment when fear chose for me.","zh":"有一次，恐懼替我作出了選擇。"},{"en":"“Fear chose for me” means fear controlled the decision instead of the person consciously choosing what they wanted.","zh":"「fear chose for me」表示恐懼控制了決定，而不是由自己有意識地選擇真正想要的東西。"},{"en":"I wanted to speak, but fear chose for me and I stayed silent.","zh":"我本來想發言，但恐懼替我作出選擇，我最後保持沉默。"},{"en":"Fear chooses for us when avoiding embarrassment becomes more important than pursuing what matters.","zh":"當避免尷尬變得比追求重要事情更重要，恐懼便會替我們作決定。"},{"en":"The phrase personifies fear as if it were another person making the decision.","zh":"這個說法把恐懼擬人化，好像它是另一個替我們作決定的人。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"for once","meaning":"終於有一次","examples":[{"en":"For once, I chose for myself.","zh":"終於有一次，我為自己作出了選擇。"},{"en":"“For once” means on this particular occasion, especially when the usual behaviour has been different.","zh":"「for once」表示這一次特別如此，尤其當平時的行為並不一樣。"},{"en":"For once, I stopped worrying about everyone else’s opinion.","zh":"終於有一次，我不再擔心所有人的看法。"},{"en":"I had allowed fear to decide before, but for once I acted differently.","zh":"過去我讓恐懼替我決定，但這一次我採取了不同做法。"},{"en":"The phrase highlights a rare or important break from an old pattern.","zh":"這個片語突出一次難得而重要的改變，打破舊有模式。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"choose for myself","meaning":"為自己作出選擇","examples":[{"en":"I finally chose for myself instead of letting fear decide.","zh":"我終於為自己作出選擇，而不是讓恐懼決定。"},{"en":"To choose for yourself means to make a decision based on your own values and wishes rather than pressure or fear.","zh":"為自己作出選擇是指根據自己的價值和願望決定，而不是受壓力或恐懼控制。"},{"en":"She chose the university course for herself instead of simply following her friends.","zh":"她為自己選擇大學課程，而不是單純跟隨朋友。"},{"en":"Choosing for yourself requires accepting responsibility for the result.","zh":"為自己作出選擇，需要接受結果帶來的責任。"},{"en":"Personal growth often begins when people stop letting fear or other people make every decision for them.","zh":"當人停止讓恐懼或別人替自己作所有決定，個人成長往往便開始。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"the opportunity I missed","meaning":"我錯失的機會","examples":[{"en":"The opportunity I missed came in Secondary Three.","zh":"我錯失的機會在中三時出現。"},{"en":"“The opportunity I missed” means a chance that was available to me but disappeared because I did not take it.","zh":"「the opportunity I missed」表示曾經擺在我面前，但因我沒有把握而消失的機會。"},{"en":"The internship I never applied for became the opportunity I missed that summer.","zh":"那年夏天我沒有申請的實習，成為了我錯失的機會。"},{"en":"We often remember a missed opportunity because we imagine what might have happened.","zh":"我們常記得錯失的機會，因為會想像如果當時把握了會怎樣。"},{"en":"A missed opportunity can still teach us something if it changes how we respond next time.","zh":"如果錯失的機會能改變我們下一次的反應，它仍然可以帶來教訓。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"came in Secondary Three","meaning":"在中三時出現","examples":[{"en":"The opportunity came in Secondary Three.","zh":"那個機會在中三時出現。"},{"en":"“Came in Secondary Three” means the event or opportunity happened while the student was in Secondary Three.","zh":"「came in Secondary Three」表示事件或機會在學生就讀中三期間出現。"},{"en":"My interest in public speaking began in Secondary Three.","zh":"我對公開演說的興趣在中三時開始。"},{"en":"The chance came in Secondary Three, when I was old enough to understand it but still very afraid.","zh":"那個機會在中三時出現，當時我已大到足以理解它，卻仍非常害怕。"},{"en":"Mentioning the school year helps place an important memory clearly in time.","zh":"提及學年可以把重要回憶清楚放在某個時間點。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"encourage someone to","meaning":"鼓勵某人去……","examples":[{"en":"My English teacher encouraged me to enter a speech festival.","zh":"我的英文老師鼓勵我參加朗誦節。"},{"en":"To encourage someone to do something means to give them support or confidence so they feel more willing to try.","zh":"鼓勵某人去做某事，是指給予支持或信心，令對方更願意嘗試。"},{"en":"My parents encouraged me to apply for the exchange programme.","zh":"父母鼓勵我申請交流計劃。"},{"en":"A good teacher may encourage a quiet student to speak because they see potential the student does not yet see.","zh":"好老師可能鼓勵安靜的學生發言，因為他看見學生自己尚未察覺的潛能。"},{"en":"Encouragement can open a door, but the person still has to decide whether to walk through it.","zh":"鼓勵可以打開一扇門，但本人仍要決定是否走進去。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"enter a speech festival","meaning":"參加朗誦節","examples":[{"en":"My teacher encouraged me to enter an inter-school speech festival.","zh":"老師鼓勵我參加校際朗誦節。"},{"en":"To enter a speech festival means to register and take part in a competition involving speaking, recitation or performance.","zh":"參加朗誦節是指報名並參與涉及演說、朗誦或表演的比賽。"},{"en":"She entered a speech festival to practise speaking clearly in front of an audience.","zh":"她參加朗誦節，練習在觀眾面前清楚說話。"},{"en":"Entering a speech festival can feel frightening because participants perform publicly and are judged.","zh":"參加朗誦節可能令人害怕，因為參賽者要公開表演並接受評審。"},{"en":"Competitions can provide useful practice even when someone does not win.","zh":"即使沒有勝出，比賽仍可以提供有用練習。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"inter-school speech festival","meaning":"校際朗誦節","examples":[{"en":"The inter-school speech festival seemed exciting and frightening.","zh":"校際朗誦節看起來既令人興奮又令人害怕。"},{"en":"An inter-school speech festival is a speaking or recitation competition involving students from different schools.","zh":"校際朗誦節是由不同學校學生參與的演說或朗誦比賽。"},{"en":"Students from across the district joined the inter-school speech festival.","zh":"區內不同學校的學生都參加了校際朗誦節。"},{"en":"An inter-school speech festival gives young people a chance to perform beyond their own classroom.","zh":"校際朗誦節讓年輕人在自己課室以外的場合表演。"},{"en":"Such events can test confidence because participants speak in front of unfamiliar people.","zh":"這類活動會考驗自信，因為參賽者要在陌生人面前說話。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"public speaking","meaning":"公開演說","examples":[{"en":"Public speaking had always fascinated me.","zh":"公開演說一直深深吸引我。"},{"en":"Public speaking is the act of speaking to a group or audience in a clear, organised way.","zh":"公開演說是有組織而清楚地向一群人或觀眾說話。"},{"en":"Giving a presentation to the whole class is a form of public speaking.","zh":"向全班作簡報就是一種公開演說。"},{"en":"Public speaking can feel frightening because many people are listening and watching at once.","zh":"公開演說可能令人害怕，因為很多人會同時聆聽和注視。"},{"en":"Practice helps speakers manage nervousness and communicate more confidently.","zh":"練習可以幫助講者管理緊張，並更自信地溝通。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"fascinate someone","meaning":"深深吸引某人","examples":[{"en":"Public speaking had always fascinated me.","zh":"公開演說一直深深吸引我。"},{"en":"To fascinate someone means to attract their interest so strongly that they want to keep watching, learning or thinking about it.","zh":"「fascinate someone」表示強烈吸引某人的興趣，令他想繼續看、學習或思考。"},{"en":"Space exploration fascinated the child from an early age.","zh":"太空探索從小便深深吸引那個孩子。"},{"en":"Something can fascinate us even when it also frightens us.","zh":"某件事即使令我們害怕，也可以同時深深吸引我們。"},{"en":"Strong fascination often reveals an interest we may want to develop further.","zh":"強烈的吸引往往反映一項值得進一步發展的興趣。"}],"source":"2017 Q2.pdf","sourcePage":3},{"front":"deep down","meaning":"內心深處","examples":[{"en":"Deep down, I wanted to speak confidently in public.","zh":"內心深處，我希望能自信地公開演說。"},{"en":"“Deep down” refers to someone’s true feelings or wishes beneath what they show outwardly.","zh":"「deep down」指一個人在表面表現之下真正的感受或願望。"},{"en":"He laughed at the idea, but deep down he wanted to join the team.","zh":"他表面上笑那個想法，但內心深處其實很想加入隊伍。"},{"en":"Deep down, people sometimes know what they want even while fear makes them deny it.","zh":"有時人內心深處知道自己真正想要甚麼，只是恐懼令他們否認。"},{"en":"This phrase contrasts inner truth with outward behaviour.","zh":"這個片語把內在真實感受與外在行為作對比。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"one of those people who","meaning":"那種能夠……的人之一","examples":[{"en":"I wanted to be one of those people who could hold an audience’s attention.","zh":"我希望成為那種能夠抓住觀眾注意力的人之一。"},{"en":"“One of those people who” introduces a type of person whose quality or ability the speaker recognises.","zh":"「one of those people who」用來帶出一類具有某項特質或能力的人。"},{"en":"She is one of those people who can make strangers feel comfortable immediately.","zh":"她是那種能夠立即令陌生人感到自在的人之一。"},{"en":"I admired confident speakers and wanted to become one of those people who could command a room.","zh":"我很欣賞自信的講者，也想成為那種能掌控全場的人之一。"},{"en":"The structure is useful when describing a group defined by a particular ability or habit.","zh":"這個句式適合描述由某種能力或習慣界定的一群人。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"turn silence into attention","meaning":"把沉默變成專注","examples":[{"en":"I wanted to turn silence into attention when I spoke.","zh":"我希望自己說話時能把沉默變成專注。"},{"en":"To turn silence into attention means to use speaking skill to make a quiet audience listen closely.","zh":"把沉默變成專注，是指用說話能力令安靜的觀眾認真聆聽。"},{"en":"The speaker turned the room’s silence into attention with a powerful opening question.","zh":"那位講者用一個有力量的開場問題，把全場沉默變成專注。"},{"en":"Confident speakers can make silence feel focused rather than awkward.","zh":"自信的講者可以令沉默感覺像專心，而不是尷尬。"},{"en":"The phrase suggests transforming an empty quietness into active listening.","zh":"這個說法表示把空洞的安靜轉化成主動聆聽。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"the trouble was that","meaning":"問題是","examples":[{"en":"The trouble was that I was afraid of being seen trying.","zh":"問題是，我害怕別人看見自己努力嘗試。"},{"en":"“The trouble was that” introduces the main difficulty or problem in a situation.","zh":"「the trouble was that」用來帶出某個情況中的主要困難或問題。"},{"en":"I wanted to go hiking; the trouble was that I had injured my ankle.","zh":"我想去行山；問題是我的腳踝受傷了。"},{"en":"The trouble was not lack of interest but fear of embarrassment.","zh":"問題不是沒有興趣，而是害怕尷尬。"},{"en":"This phrase helps explain what prevented an otherwise possible action.","zh":"這個句式有助解釋是甚麼阻礙了一項本來可以做到的行動。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"wanting something is one thing","meaning":"想要某件事是一回事","examples":[{"en":"Wanting something is one thing; admitting it is another.","zh":"想要某件事是一回事；承認它又是另一回事。"},{"en":"“Wanting something is one thing” means having a desire is only one part of a more complicated situation.","zh":"「wanting something is one thing」表示有願望只是較複雜情況中的其中一部分。"},{"en":"Wanting to improve is one thing; practising every day is another.","zh":"想進步是一回事；每天練習又是另一回事。"},{"en":"It can be easy to want success privately but harder to admit how much it matters to you.","zh":"私下想成功可以很容易，但承認它對自己有多重要可能更困難。"},{"en":"This structure prepares a contrast between desire and the more difficult action that follows.","zh":"這個句式為願望與之後更困難的行動之間的對比作準備。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"being seen wanting it is another","meaning":"被人看見自己渴望它又是另一回事","examples":[{"en":"Being seen wanting it is another, more frightening matter.","zh":"被人看見自己渴望它又是另一件更令人害怕的事。"},{"en":"This means openly showing other people that you strongly want something can feel more difficult than simply wanting it privately.","zh":"這表示公開讓別人知道自己非常想得到某樣東西，可能比私下想要更困難。"},{"en":"Wanting the lead role was easy, but being seen wanting it made her feel vulnerable.","zh":"想得到主角很容易，但被別人看見她很想得到，卻令她感到脆弱。"},{"en":"People may fear public failure more when others know how badly they wanted to succeed.","zh":"當別人知道我們多麼渴望成功，人可能會更加害怕公開失敗。"},{"en":"The phrase shows that visibility can add emotional risk to ambition.","zh":"這個片語顯示被人看見會令抱負增加情感風險。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"forget my lines","meaning":"忘記台詞","examples":[{"en":"I imagined forgetting my lines during the competition.","zh":"我想像自己在比賽期間忘記台詞。"},{"en":"To forget your lines means to forget the words you are supposed to say during a speech or performance.","zh":"忘記台詞是指忘記演說或表演中原本應該說的說話。"},{"en":"The actor paused because he suddenly forgot his lines.","zh":"那位演員突然忘記台詞，所以停頓了一下。"},{"en":"Fear of forgetting my lines made the competition seem more frightening than it actually was.","zh":"害怕忘記台詞，令比賽在我想像中比實際更可怕。"},{"en":"Performers practise repeatedly so they can recover even if they briefly forget a line.","zh":"表演者會反覆練習，令自己即使短暫忘詞也能重新接下去。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"hear classmates laugh","meaning":"聽到同學嘲笑","examples":[{"en":"I imagined hearing classmates laugh at me.","zh":"我想像自己會聽到同學嘲笑我。"},{"en":"To hear classmates laugh at you means to hear people from your class laughing because of something you did or said.","zh":"「hear classmates laugh at you」表示聽到同班同學因你做或說的事情而取笑你。"},{"en":"He feared hearing classmates laugh if his presentation went badly.","zh":"他害怕簡報做得不好時會聽到同學嘲笑。"},{"en":"Imagined laughter can feel powerful even before anything embarrassing has happened.","zh":"即使尷尬的事情還未發生，想像中的笑聲也可以帶來很大壓力。"},{"en":"Fear often exaggerates how negatively other people will react to our mistakes.","zh":"恐懼常會誇大別人對我們犯錯時的負面反應。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"have my nervous face remembered","meaning":"讓自己緊張的樣子被記住","examples":[{"en":"I imagined having my nervous face remembered after the competition.","zh":"我想像比賽後，大家會記住我緊張的樣子。"},{"en":"This means fearing that other people would remember how anxious or uncomfortable I looked.","zh":"這句話表示害怕別人會記得自己看起來有多焦慮或不自在。"},{"en":"She worried about having her nervous expression remembered after the presentation.","zh":"她擔心簡報後大家會記住她緊張的表情。"},{"en":"People often overestimate how closely others remember their embarrassing moments.","zh":"人常高估別人會多仔細記住自己的尷尬時刻。"},{"en":"Fear of being remembered negatively can stop someone trying something valuable.","zh":"害怕被人留下負面印象，可以令一個人不敢嘗試有價值的事情。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"application form","meaning":"報名表；申請表","examples":[{"en":"The application form stayed in my bag for a week.","zh":"那張報名表在我的書包裏放了一星期。"},{"en":"An application form is a document used to provide information when requesting a place, opportunity or service.","zh":"報名表或申請表是申請名額、機會或服務時用來填寫資料的文件。"},{"en":"Students had to complete the application form before Friday.","zh":"學生必須在星期五前填妥報名表。"},{"en":"An application form can represent the first practical step towards joining a programme.","zh":"一張報名表可以代表加入某個計劃的第一個實際步驟。"},{"en":"If a form is never submitted, the opportunity connected to it may disappear.","zh":"如果表格一直沒有提交，與它相關的機會可能會消失。"}],"source":"2017 Q2.pdf","sourcePage":4},{"front":"stay in my bag like a secret","meaning":"像秘密一樣留在書包裏","examples":[{"en":"The application form stayed in my bag like a secret.","zh":"那張報名表像秘密一樣留在我的書包裏。"},{"en":"“Stayed in my bag like a secret” means I kept the form hidden and did not act on it or discuss it openly.","zh":"「stayed in my bag like a secret」表示我把表格藏着，既沒有行動，也沒有公開談論。"},{"en":"The letter stayed in her drawer like a secret because she was afraid to answer it.","zh":"那封信像秘密一樣留在她的抽屜裏，因為她害怕回覆。"},{"en":"Keeping the form hidden reflected how uncomfortable I felt about admitting I wanted the opportunity.","zh":"把表格藏起來反映我很不自在，不敢承認自己其實想要那個機會。"},{"en":"The comparison shows that fear can turn a simple document into something emotionally difficult to face.","zh":"這個比喻顯示恐懼可以把一張普通文件變成情感上很難面對的東西。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"told myself I would","meaning":"告訴自己會……","examples":[{"en":"Each day I told myself I would submit it tomorrow.","zh":"每一天我都告訴自己明天會交表格。"},{"en":"“Told myself I would” means repeatedly making a promise or prediction to myself about a future action.","zh":"「told myself I would」表示反覆向自己承諾或預計將來會做某件事。"},{"en":"I told myself I would start revising after dinner, but I kept delaying.","zh":"我告訴自己晚飯後會開始溫習，但一直拖延。"},{"en":"Telling ourselves we will act later can sometimes make delay feel acceptable.","zh":"告訴自己稍後才行動，有時會令拖延感覺合理。"},{"en":"A promise to ourselves only matters if it eventually becomes action.","zh":"對自己的承諾只有最後變成行動才真正有意義。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"submit it tomorrow","meaning":"明天才交","examples":[{"en":"I kept telling myself I would submit it tomorrow.","zh":"我不停告訴自己明天才交。"},{"en":"To submit it tomorrow means to hand in or send the form the following day rather than today.","zh":"「submit it tomorrow」表示不在今天，而是在翌日提交或交出表格。"},{"en":"She planned to submit the assignment tomorrow but completed it tonight.","zh":"她原本打算明天才交功課，但今晚已經完成。"},{"en":"Repeatedly saying “I’ll submit it tomorrow” can become a form of procrastination.","zh":"不斷說「明天才交」可以變成一種拖延。"},{"en":"When there is a deadline, too many tomorrows can eventually become too late.","zh":"當事情有截止日期，太多個「明天」最後可能變成太遲。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time I unfolded the form, the deadline had passed.","zh":"到我打開表格的時候，截止日期已經過了。"},{"en":"“By the time” shows that one event had already happened before another point was reached.","zh":"「by the time」表示到了另一個時間點時，某件事早已發生。"},{"en":"By the time we arrived, the meeting had already started.","zh":"到我們抵達的時候，會議已經開始。"},{"en":"By the time I finally acted, the opportunity was no longer available.","zh":"到我終於行動的時候，那個機會已經不存在。"},{"en":"This structure is useful for showing the consequence of delay.","zh":"這個句式很適合表示拖延帶來的後果。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"unfold it","meaning":"打開它；攤開它","examples":[{"en":"By the time I unfolded it, the deadline had passed.","zh":"到我打開它的時候，截止日期已經過了。"},{"en":"To unfold something means to open something that has been folded.","zh":"「unfold」表示把原本摺起的東西打開或攤開。"},{"en":"She unfolded the letter and read it slowly.","zh":"她打開那封信，慢慢閱讀。"},{"en":"I finally unfolded the application form after carrying it around for days.","zh":"我把申請表帶在身邊很多天後，終於把它攤開。"},{"en":"Physically opening the form represented finally facing the decision I had avoided.","zh":"真正打開表格，也象徵我終於面對一直逃避的決定。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"the deadline had passed","meaning":"截止日期已經過了","examples":[{"en":"When I unfolded the form, the deadline had already passed.","zh":"當我打開表格時，截止日期已經過了。"},{"en":"“The deadline had passed” means the final permitted time for completing something was already over.","zh":"「the deadline had passed」表示完成某件事所允許的最後時間已經結束。"},{"en":"I could not enter the competition because the deadline had passed.","zh":"我不能參加比賽，因為截止日期已經過了。"},{"en":"Once the deadline had passed, wanting to apply was no longer enough.","zh":"一旦截止日期過去，單純想申請已經沒有用。"},{"en":"Deadlines turn hesitation into real consequences because opportunities can close.","zh":"截止日期令猶豫帶來真實後果，因為機會真的會關上。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"for a while","meaning":"有一段時間","examples":[{"en":"For a while, I pretended it did not matter.","zh":"有一段時間，我假裝這件事不重要。"},{"en":"“For a while” means for a limited period of time.","zh":"「for a while」表示持續一段有限的時間。"},{"en":"We sat quietly for a while before continuing the discussion.","zh":"我們安靜坐了一會兒，才繼續討論。"},{"en":"For a while, avoiding the truth made the disappointment easier to bear.","zh":"有一段時間，逃避事實令失望較容易承受。"},{"en":"Feelings may be hidden for a while, but that does not mean they have disappeared.","zh":"感受可以被隱藏一段時間，但不代表它們已消失。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"pretend it did not matter","meaning":"假裝這不重要","examples":[{"en":"I pretended it did not matter.","zh":"我假裝這件事不重要。"},{"en":"To pretend something does not matter means to act as if you do not care even though you actually do.","zh":"假裝某件事不重要，是指表現得好像自己不在乎，即使實際很在意。"},{"en":"He pretended the rejection did not matter, but he was clearly disappointed.","zh":"他假裝被拒絕不重要，但明顯感到失望。"},{"en":"Pretending a missed chance does not matter can protect pride for a short time.","zh":"假裝錯失機會不重要，可以短暫保護自尊。"},{"en":"Denying disappointment does not remove the reason for it.","zh":"否認失望並不能消除造成失望的原因。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"There will be other chances","meaning":"將來還會有其他機會","examples":[{"en":"I told myself that there would be other chances.","zh":"我告訴自己將來還會有其他機會。"},{"en":"“There will be other chances” means more opportunities are expected to appear in the future.","zh":"「There will be other chances」表示預期未來還會出現更多機會。"},{"en":"After failing one interview, she reminded herself that there would be other chances.","zh":"一次面試失敗後，她提醒自己將來還會有其他機會。"},{"en":"The thought can be comforting, but it should not become an excuse for avoiding every difficult opportunity.","zh":"這個想法可以安慰人，但不應變成逃避所有困難機會的藉口。"},{"en":"Future chances may come, but they may not be exactly the same as the one we lost.","zh":"未來可能還有機會，但未必與錯失的那一次完全相同。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"as if regret could be reasoned with","meaning":"彷彿可以用道理說服遺憾","examples":[{"en":"I spoke as if regret could be reasoned with.","zh":"我說得好像可以用道理說服遺憾一樣。"},{"en":"This phrase imagines regret as if it were a person who could be persuaded by logical arguments.","zh":"這個片語把遺憾想像成人，好像可以用邏輯理由說服它。"},{"en":"I told myself the mistake was unimportant, as if regret could be reasoned with.","zh":"我告訴自己那個錯誤不重要，彷彿可以用道理說服遺憾。"},{"en":"Emotions do not always disappear simply because we give ourselves sensible explanations.","zh":"情緒不會只因我們給自己合理解釋便一定消失。"},{"en":"The figurative phrase shows the gap between logical thinking and emotional experience.","zh":"這個比喻顯示理性思考與情感經驗之間的差距。"}],"source":"2017 Q2.pdf","sourcePage":5},{"front":"regret could be reasoned with","meaning":"遺憾可以被說服","examples":[{"en":"Regret cannot always be reasoned with.","zh":"遺憾並不總是可以用道理說服的。"},{"en":"If regret could be reasoned with, logical explanations would be enough to make the painful feeling disappear.","zh":"如果遺憾可以被說服，合理解釋便足以令痛苦感受消失。"},{"en":"She knew the decision had been understandable, but her regret could not simply be argued away.","zh":"她知道那個決定可以理解，但遺憾並不能單靠辯解消除。"},{"en":"Emotions often continue even when we understand the reasons behind a choice.","zh":"即使我們明白選擇背後的原因，情緒仍可能持續。"},{"en":"The expression treats regret like a stubborn person who refuses to accept an argument.","zh":"這個表達把遺憾當成一個固執的人，不願接受道理。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"joined the festival instead","meaning":"反而參加了比賽","examples":[{"en":"Mary joined the festival instead.","zh":"Mary反而參加了比賽。"},{"en":"“Joined the festival instead” means Mary took the opportunity that the speaker did not take.","zh":"「joined the festival instead」表示Mary把握了說話者沒有把握的機會。"},{"en":"I stayed home, while my friend joined the workshop instead.","zh":"我留在家裏，而朋友反而參加了工作坊。"},{"en":"Seeing someone else join the festival showed me what acting despite fear could look like.","zh":"看見別人參加比賽，令我看到即使害怕仍然行動是甚麼樣子。"},{"en":"“Instead” highlights a contrast between two different choices.","zh":"「instead」突出兩個不同選擇之間的對比。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"lose her place","meaning":"忘記講到哪裏","examples":[{"en":"She did not win, and she even lost her place once.","zh":"她沒有勝出，甚至有一次忘記講到哪裏。"},{"en":"To lose your place means to forget where you are in a speech, text, song or performance.","zh":"「lose your place」表示忘記自己在演說、文章、歌曲或表演中進行到哪個位置。"},{"en":"The reader lost her place and had to look back at the previous paragraph.","zh":"那位讀者忘記讀到哪裏，要回看上一段。"},{"en":"Mary lost her place during the speech but recovered and continued.","zh":"Mary在演說途中忘記講到哪裏，但最後重新找到位置並繼續。"},{"en":"Losing your place can be embarrassing, but it does not have to end the whole performance.","zh":"忘記講到哪裏可以令人尷尬，但不一定代表整個表演要結束。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"return to school laughing at herself","meaning":"回到學校時自嘲地笑","examples":[{"en":"She returned to school laughing at herself.","zh":"她回到學校時自嘲地笑。"},{"en":"To laugh at yourself means to see humour in your own mistakes instead of feeling only shame.","zh":"自嘲地笑是指能從自己的錯誤中看到幽默，而不只是感到羞恥。"},{"en":"After dropping all her notes, she laughed at herself and continued the presentation.","zh":"她把所有筆記掉在地上後，自嘲地笑了一下便繼續簡報。"},{"en":"Mary returned laughing at herself because the mistake no longer felt disastrous.","zh":"Mary回校時自嘲地笑，因為那個錯誤對她來說已不再像災難。"},{"en":"Being able to laugh at yourself can show that embarrassment has lost some of its power.","zh":"能夠自嘲，可以表示尷尬已失去部分控制力。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"something about her had changed","meaning":"她身上有些東西改變了","examples":[{"en":"After the festival, something about her had changed.","zh":"朗誦節之後，她身上有些東西改變了。"},{"en":"“Something about her had changed” means her attitude, confidence or manner was noticeably different even if the exact change was hard to name.","zh":"「something about her had changed」表示她的態度、自信或舉止明顯不同，即使很難說出具體是哪一點。"},{"en":"After returning from the trip, something about him had changed; he seemed more independent.","zh":"旅行回來後，他身上有些東西改變了；看起來更獨立。"},{"en":"Mary had not won, but something about her had changed because she had faced public failure and survived it.","zh":"Mary雖然沒有勝出，但她面對過公開失敗並安然度過，因此有些地方改變了。"},{"en":"Growth is sometimes visible in behaviour before we can explain it clearly.","zh":"成長有時會先在行為中看得見，我們之後才懂得解釋。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"stand taller","meaning":"站得更挺直；更有自信","examples":[{"en":"She stood taller after joining the festival.","zh":"參加朗誦節後，她站得更挺直，也更有自信。"},{"en":"To stand taller can literally mean holding the body more upright and figuratively mean appearing more confident.","zh":"「stand taller」既可以字面表示站得更直，也可以比喻顯得更有自信。"},{"en":"The student stood taller after the teacher praised her work.","zh":"老師稱讚她的作品後，那名學生站得更挺直。"},{"en":"Mary’s posture changed because she no longer seemed ashamed of making mistakes.","zh":"Mary的姿態改變了，因為她不再好像那麼害怕犯錯。"},{"en":"Confidence can affect the way people physically carry themselves.","zh":"自信可以影響一個人如何用身體姿態呈現自己。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"speak more freely","meaning":"說話更自在","examples":[{"en":"She spoke more freely in lessons.","zh":"她在課堂上說話更自在。"},{"en":"To speak more freely means to express yourself with less fear, hesitation or self-consciousness.","zh":"「speak more freely」表示較少害怕、猶豫或顧慮地表達自己。"},{"en":"Students speak more freely when they know mistakes will not be mocked.","zh":"當學生知道犯錯不會被嘲笑，他們會說話得更自在。"},{"en":"Mary spoke more freely because one imperfect performance had shown her that embarrassment was survivable.","zh":"Mary說話更自在，因為一次不完美的表演令她明白尷尬其實可以承受。"},{"en":"Confidence often appears as a willingness to speak before every sentence is perfect.","zh":"自信往往表現在願意開口，而不是等每一句都完美才說。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"watching her","meaning":"看着她","examples":[{"en":"Watching her, I realised that I had misunderstood failure.","zh":"看着她，我明白自己一直誤解了失敗。"},{"en":"“Watching her” means observing what she did and how she behaved after the experience.","zh":"「watching her」表示觀察她做甚麼，以及經歷事情後如何表現。"},{"en":"Watching my friend practise every day taught me more than hearing advice.","zh":"看着朋友每天練習，比單純聽勸告教會我更多。"},{"en":"Watching Mary recover from mistakes showed me that failure did not destroy her.","zh":"看着Mary從錯誤中恢復，令我明白失敗並沒有摧毀她。"},{"en":"Sometimes another person’s example teaches a lesson more clearly than words.","zh":"有時別人的實際榜樣，比說話更能清楚教我們一課。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"misunderstand failure","meaning":"誤解失敗","examples":[{"en":"I realised that I had misunderstood failure.","zh":"我明白自己一直誤解了失敗。"},{"en":"To misunderstand failure means to hold an inaccurate idea about what failing means or what it does to a person.","zh":"誤解失敗是指對失敗代表甚麼或會對人造成甚麼影響持有錯誤看法。"},{"en":"A student may misunderstand failure if they think one bad mark proves they are incapable.","zh":"如果學生以為一次低分就證明自己沒有能力，他就是誤解了失敗。"},{"en":"I had treated embarrassment as disaster instead of a temporary part of learning.","zh":"我一直把尷尬看成災難，而不是學習中短暫的一部分。"},{"en":"Failure can provide information and growth rather than simply proving weakness.","zh":"失敗可以提供資訊和成長，而不只是證明軟弱。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"embarrassment would break me","meaning":"尷尬會擊垮我","examples":[{"en":"I had thought embarrassment would break me.","zh":"我曾以為尷尬會擊垮我。"},{"en":"“Embarrassment would break me” means I feared humiliation would damage my confidence so badly that I could not recover.","zh":"「embarrassment would break me」表示我害怕羞辱會嚴重打擊自信，令自己無法恢復。"},{"en":"He avoided performing because he believed one mistake would break him emotionally.","zh":"他避免表演，因為相信一次錯誤便會在情感上擊垮自己。"},{"en":"Mary showed me that embarrassment could be uncomfortable without being destructive.","zh":"Mary令我看見尷尬可以令人不舒服，卻不一定具有破壞性。"},{"en":"Fear often makes temporary discomfort seem far more dangerous than it really is.","zh":"恐懼常把短暫不適想像得比實際危險得多。"}],"source":"2017 Q2.pdf","sourcePage":6},{"front":"hesitation quietly diminished me","meaning":"猶豫悄悄削弱了我","examples":[{"en":"Instead, hesitation quietly diminished me.","zh":"相反，猶豫悄悄削弱了我。"},{"en":"“Hesitation quietly diminished me” means repeated avoidance slowly reduced my confidence, growth or sense of possibility.","zh":"「hesitation quietly diminished me」表示反覆逃避慢慢削弱我的自信、成長或對可能性的感覺。"},{"en":"Years of saying “maybe later” quietly diminished his belief that he could change careers.","zh":"多年不斷說「遲些吧」，悄悄削弱了他轉行的信心。"},{"en":"Unlike one visible failure, hesitation can cause damage so gradually that we barely notice it.","zh":"與一次明顯失敗不同，猶豫可以慢慢造成傷害，令人甚至沒有察覺。"},{"en":"Avoiding every risk may protect us from embarrassment while also making our world smaller.","zh":"逃避所有風險可以保護我們免於尷尬，同時也把自己的世界變小。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"not until then did I understand","meaning":"直到那時我才明白","examples":[{"en":"Not until then did I understand the cost of a missed opportunity.","zh":"直到那時我才明白錯失機會的代價。"},{"en":"“Not until then did I understand” means I only understood something after that particular moment or experience.","zh":"「not until then did I understand」表示直到某個特定時刻或經歷之後，我才真正明白某件事。"},{"en":"Not until I moved away did I understand how much I valued home.","zh":"直到搬走後，我才明白自己有多珍惜家。"},{"en":"I only understood the deeper cost of hesitation after watching Mary change.","zh":"看着Mary改變後，我才真正明白猶豫更深層的代價。"},{"en":"This inverted structure strongly emphasises how late the understanding arrived.","zh":"這種倒裝句式強烈突出理解來得很遲。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"the cost of a missed opportunity","meaning":"錯失機會的代價","examples":[{"en":"The cost of a missed opportunity is not only what we fail to achieve.","zh":"錯失機會的代價不只是我們未能達成的事情。"},{"en":"The cost of a missed opportunity means the losses or consequences caused by not taking a valuable chance.","zh":"錯失機會的代價是指沒有把握有價值機會而造成的損失或後果。"},{"en":"Missing a training course may cost more than a certificate; it may also delay confidence and experience.","zh":"錯過培訓課程的代價可能不只是一張證書，也可能延遲自信和經驗的建立。"},{"en":"A missed opportunity can affect both what happens and who we become.","zh":"錯失機會既可以影響發生甚麼，也可以影響我們成為怎樣的人。"},{"en":"The deepest cost is sometimes invisible because it appears as growth that never had the chance to begin.","zh":"最深的代價有時看不見，因為它表現在從未開始的成長。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"what we fail to achieve","meaning":"我們未能達成的事","examples":[{"en":"The cost is not only what we fail to achieve.","zh":"代價不只是我們未能達成的事。"},{"en":"“What we fail to achieve” means the goals, results or experiences we do not reach.","zh":"「what we fail to achieve」表示我們沒有達成的目標、結果或經歷。"},{"en":"A missed competition may cost us more than what we fail to achieve on the stage.","zh":"錯過一次比賽的代價可能不只是在舞台上未能達成的成就。"},{"en":"When we avoid trying, we lose both possible results and possible learning.","zh":"當我們逃避嘗試，就會同時失去可能的成果和可能的學習。"},{"en":"Achievement is only one part of what an opportunity can give us.","zh":"成就只是機會可以給予我們的其中一部分。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"the person we postpone becoming","meaning":"我們延遲成為的那個自己","examples":[{"en":"A missed chance can delay the person we might become.","zh":"錯失的機會可以令我們延遲成為原本可能成為的那個自己。"},{"en":"“The person we postpone becoming” means a future, more developed version of ourselves whose growth is delayed by inaction.","zh":"「the person we postpone becoming」表示因為沒有行動，而延遲出現的更成熟、更進步的未來自己。"},{"en":"Avoiding every challenge may postpone becoming a more confident speaker.","zh":"逃避所有挑戰，可能令一個人延遲成為更有自信的講者。"},{"en":"Opportunities can develop courage, skill or independence that shape our future identity.","zh":"機會可以培養勇氣、技能或獨立，進而塑造未來身份。"},{"en":"The phrase suggests that delay can affect not only events but personal development.","zh":"這個說法表示拖延影響的不只是事情，也包括個人成長。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"postpone becoming","meaning":"延遲成為","examples":[{"en":"Fear can make us postpone becoming braver.","zh":"恐懼可以令我們延遲成為更勇敢的人。"},{"en":"To postpone becoming something means to delay the development of a quality or identity we could otherwise begin building now.","zh":"「postpone becoming」表示延遲發展本來現在已可開始建立的特質或身份。"},{"en":"Avoiding responsibility can postpone becoming more independent.","zh":"逃避責任可以令人延遲成為更獨立的人。"},{"en":"Every time I refused to speak, I postponed becoming the confident person I wanted to be.","zh":"每次拒絕發言，我都延遲成為自己想要成為的自信的人。"},{"en":"Growth is delayed when we continually wait for fear to disappear before acting.","zh":"如果我們總要等恐懼完全消失才行動，成長便會被延遲。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"the opportunity I took","meaning":"我把握的機會","examples":[{"en":"The opportunity I took arrived the following year.","zh":"我把握的機會在第二年出現。"},{"en":"“The opportunity I took” means the chance I accepted and acted on instead of allowing it to pass.","zh":"「the opportunity I took」表示我接受並採取行動，而沒有讓它錯失的機會。"},{"en":"The volunteer role became the opportunity I took to practise speaking.","zh":"那個義工崗位成為我用來練習說話、並真正把握的機會。"},{"en":"Unlike the competition I missed, the opportunity I took looked small at first.","zh":"與我錯失的比賽不同，我把握的機會起初看起來很小。"},{"en":"Taking one opportunity can begin changing how we respond to later chances.","zh":"把握一次機會，可以開始改變我們之後面對其他機會的方式。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"the following year","meaning":"第二年；翌年","examples":[{"en":"The opportunity arrived the following year.","zh":"那個機會在第二年出現。"},{"en":"“The following year” means the year immediately after the year already mentioned.","zh":"「the following year」表示緊接之前所提年份之後的一年。"},{"en":"She failed the examination but passed it the following year.","zh":"她那年考試不合格，但翌年通過了。"},{"en":"The following year gave me another chance to respond differently to fear.","zh":"第二年給了我另一個機會，以不同方式回應恐懼。"},{"en":"This phrase connects two events that happened one year apart.","zh":"這個片語連接相隔一年的兩件事。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"with far less glamour","meaning":"遠沒有那麼光鮮","examples":[{"en":"The opportunity arrived with far less glamour.","zh":"那個機會出現時遠沒有那麼光鮮。"},{"en":"“With far less glamour” means in a much less exciting, impressive or publicly attractive form.","zh":"「with far less glamour」表示以遠較不刺激、不耀眼或不吸引公眾注意的形式出現。"},{"en":"The volunteer job had far less glamour than a stage performance, but it taught me more.","zh":"義工工作遠沒有舞台表演那麼光鮮，卻教會我更多。"},{"en":"Useful opportunities may come with little glamour because their value lies in experience rather than attention.","zh":"有用的機會可能一點也不光鮮，因為其價值在經驗而不是關注。"},{"en":"Something can be meaningful even when it looks ordinary and brings no public recognition.","zh":"一件事即使看起來平凡、沒有公開認可，也可以很有意義。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"recruit volunteers","meaning":"招募義工","examples":[{"en":"Our school was recruiting volunteers for storytelling sessions.","zh":"我們學校正在為講故事活動招募義工。"},{"en":"To recruit volunteers means to find and invite people to give their time and help without regular pay.","zh":"招募義工是指尋找並邀請人無償或非一般受薪地提供時間和協助。"},{"en":"The charity recruited volunteers to distribute food at weekends.","zh":"慈善機構招募義工在週末派發食物。"},{"en":"Schools recruit volunteers when community projects need extra people to help.","zh":"社區活動需要額外人手時，學校會招募義工。"},{"en":"Volunteering gives participants experience while providing useful support to others.","zh":"義工服務既讓參與者獲得經驗，也為其他人提供實際幫助。"}],"source":"2017 Q2.pdf","sourcePage":7},{"front":"run storytelling sessions","meaning":"舉辦講故事活動","examples":[{"en":"Volunteers helped run Saturday storytelling sessions for children.","zh":"義工協助舉辦星期六的兒童講故事活動。"},{"en":"To run storytelling sessions means to organise and lead activities in which stories are read, told or discussed.","zh":"舉辦講故事活動是指組織和帶領閱讀、講述或討論故事的活動。"},{"en":"The librarians run storytelling sessions every Sunday morning.","zh":"圖書館員每個星期日早上都舉辦講故事活動。"},{"en":"Running a storytelling session involves more than reading; the leader must also keep children interested.","zh":"舉辦講故事活動不只是讀書，帶領者還要保持孩子的興趣。"},{"en":"Such sessions can help children enjoy books and practise imagination.","zh":"這類活動可以幫助孩子享受閱讀和練習想像力。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"Saturday storytelling sessions","meaning":"星期六講故事活動","examples":[{"en":"The school needed volunteers for Saturday storytelling sessions.","zh":"學校需要義工協助星期六講故事活動。"},{"en":"Saturday storytelling sessions are organised weekend activities where children listen to and take part in stories.","zh":"星期六講故事活動是週末舉行、讓兒童聆聽和參與故事的有組織活動。"},{"en":"Parents brought young children to the Saturday storytelling sessions at the community centre.","zh":"家長帶年幼孩子到社區中心參加星期六講故事活動。"},{"en":"Weekend sessions can give children learning opportunities outside normal school hours.","zh":"週末活動可以在正常上課時間以外提供學習機會。"},{"en":"Volunteers may read aloud, ask questions and invite children to invent parts of the story.","zh":"義工可以朗讀、提問，並邀請孩子創作部分故事內容。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"community centre","meaning":"社區中心","examples":[{"en":"The sessions were held at a community centre.","zh":"活動在社區中心舉行。"},{"en":"A community centre is a local public place where residents can join activities, classes and services.","zh":"社區中心是本地居民可以參加活動、課程和服務的公共場所。"},{"en":"The community centre offers homework support, exercise classes and activities for older people.","zh":"那間社區中心提供功課輔導、運動課和長者活動。"},{"en":"Storytelling at a community centre makes the activity accessible to local families.","zh":"在社區中心舉辦講故事活動，令本區家庭較容易參加。"},{"en":"Community centres often bring people of different ages together.","zh":"社區中心常把不同年齡的人聚集在一起。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"no stage lights, no judges and no prize","meaning":"沒有舞台燈光、評判和獎項","examples":[{"en":"There were no stage lights, no judges and no prize.","zh":"那裏沒有舞台燈光、評判和獎項。"},{"en":"This phrase emphasises that the activity lacked the glamorous features of a formal competition.","zh":"這個片語強調活動沒有正式比賽那些光鮮元素。"},{"en":"The workshop had no stage lights, no judges and no prize, but participants still learned a great deal.","zh":"工作坊沒有舞台燈光、評判和獎項，但參加者仍學到很多。"},{"en":"Valuable experiences do not need public recognition to matter.","zh":"有價值的經歷不需要公開認可才有意義。"},{"en":"Removing prizes and judges can shift attention from winning to learning and helping.","zh":"沒有獎項和評判時，注意力可以由勝負轉向學習和幫助別人。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"restless children","meaning":"坐不定的小朋友","examples":[{"en":"The room was full of twenty restless children.","zh":"房間裏有二十個坐不定的小朋友。"},{"en":"Restless children are children who find it difficult to sit still or stay quietly focused for long.","zh":"坐不定的小朋友是難以長時間安坐或保持安靜專注的孩子。"},{"en":"The restless children kept moving in their seats and asking questions.","zh":"那些坐不定的小朋友不停在座位上動來動去和發問。"},{"en":"A storyteller needs energy and flexibility when working with restless children.","zh":"與坐不定的小朋友相處時，講故事的人需要活力和靈活應變。"},{"en":"Restlessness does not necessarily mean children are uninterested; they may simply need more interaction.","zh":"坐不定不一定代表孩子沒有興趣；他們可能只是需要更多互動。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"a stack of picture books","meaning":"一疊圖畫書","examples":[{"en":"There were twenty restless children and a stack of picture books.","zh":"那裏有二十個坐不定的小朋友和一疊圖畫書。"},{"en":"A stack of picture books is a pile of illustrated books placed one on top of another.","zh":"一疊圖畫書是幾本有插圖的書一本疊在另一本上。"},{"en":"The teacher put a stack of picture books beside the reading corner.","zh":"老師在閱讀角旁放了一疊圖畫書。"},{"en":"Each week the volunteers chose a story from the stack of picture books.","zh":"義工每星期都從那疊圖畫書中選一個故事。"},{"en":"Picture books use both images and words to help young children follow a story.","zh":"圖畫書同時使用圖片和文字，幫助年幼孩子理解故事。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, the opportunity seemed small.","zh":"乍看之下，那個機會似乎很小。"},{"en":"“At first glance” means based on the first quick impression before looking more carefully.","zh":"「at first glance」表示在未仔細了解前，根據第一眼快速印象作出的判斷。"},{"en":"At first glance, the room looked empty, but someone was sitting in the corner.","zh":"乍看之下，房間好像沒有人，但角落其實坐着一個人。"},{"en":"At first glance, volunteering seemed less important than a competition.","zh":"乍看之下，做義工似乎沒有比賽那麼重要。"},{"en":"First impressions can be misleading because deeper value may only appear after closer attention.","zh":"第一印象可能會誤導人，因為更深的價值往往要仔細看才會出現。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"on closer inspection","meaning":"仔細看來","examples":[{"en":"On closer inspection, it was exactly the test I needed.","zh":"仔細看來，那正正是我需要的考驗。"},{"en":"“On closer inspection” means after examining something more carefully than at first.","zh":"「on closer inspection」表示比最初更仔細檢視之後。"},{"en":"The jacket looked plain, but on closer inspection the stitching was excellent.","zh":"那件外套起初看似普通，但仔細看來縫工非常好。"},{"en":"On closer inspection, the small volunteer role offered exactly the kind of challenge I had avoided before.","zh":"仔細看來，那個小小的義工崗位正提供我以前一直逃避的挑戰。"},{"en":"This phrase contrasts a quick first impression with a more thoughtful judgement.","zh":"這個片語把快速的第一印象與較深入的判斷作對比。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"exactly the kind of test","meaning":"正正是那種考驗","examples":[{"en":"It was exactly the kind of test I needed.","zh":"那正正是我需要的那種考驗。"},{"en":"“Exactly the kind of test” means precisely the type of challenge that could develop a particular ability.","zh":"「exactly the kind of test」表示正正是能發展某項能力的那一類挑戰。"},{"en":"Leading a small group was exactly the kind of test she needed to build confidence.","zh":"帶領小組正正是她建立自信所需要的那種考驗。"},{"en":"The storytelling sessions tested public speaking without the pressure of judges or prizes.","zh":"講故事活動考驗公開說話，卻沒有評判和獎項帶來的壓力。"},{"en":"The right challenge is difficult enough to stretch us without making growth impossible.","zh":"合適的挑戰應該足以推動我們成長，但又不至於令成長變得不可能。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"before I could talk myself out of it","meaning":"在我說服自己退縮之前","examples":[{"en":"Before I could talk myself out of it, I signed up.","zh":"在我說服自己退縮之前，我便報名了。"},{"en":"This means I acted quickly before my own fears and excuses could persuade me not to participate.","zh":"這表示我快速行動，趁恐懼和藉口還未說服自己不要參加。"},{"en":"She sent the application before she could talk herself out of applying.","zh":"她在說服自己不要申請之前，便先把申請寄出了。"},{"en":"Acting quickly can sometimes prevent overthinking from turning into avoidance.","zh":"有時快速行動可以防止過度思考變成逃避。"},{"en":"The phrase shows a struggle between the desire to act and the mind’s habit of creating reasons not to.","zh":"這個片語顯示想行動的自己與不停找理由退縮的自己之間的拉扯。"}],"source":"2017 Q2.pdf","sourcePage":8},{"front":"talk myself out of it","meaning":"說服自己放棄","examples":[{"en":"I signed up before I could talk myself out of it.","zh":"我在說服自己放棄之前便先報名。"},{"en":"To talk yourself out of something means to persuade yourself not to do something you originally wanted or intended to do.","zh":"「talk yourself out of something」表示把原本想做或打算做的事說服自己不要做。"},{"en":"I nearly talked myself out of applying because I focused only on what could go wrong.","zh":"我差點因只想着可能出錯的地方，而說服自己不要申請。"},{"en":"Fear often talks us out of opportunities by producing sensible-sounding excuses.","zh":"恐懼常用聽起來很合理的藉口，說服我們放棄機會。"},{"en":"Recognising this habit can help people act before doubt becomes a final decision.","zh":"察覺這種習慣，可以幫助人在懷疑變成最後決定前先行動。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"sign up","meaning":"報名參加","examples":[{"en":"I signed up for the storytelling sessions.","zh":"我報名參加了講故事活動。"},{"en":"To sign up means to register your name to take part in an activity, programme or service.","zh":"「sign up」表示登記姓名，參加活動、計劃或服務。"},{"en":"Students can sign up for the workshop online.","zh":"學生可以在網上報名參加工作坊。"},{"en":"Signing up turned an idea into a real commitment.","zh":"報名令一個想法變成真正的承諾。"},{"en":"The first practical step towards an opportunity is often simply registering before you change your mind.","zh":"面對機會的第一個實際步驟，往往只是趁自己未改變主意前先完成登記。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"painful in a very educational way","meaning":"痛苦但很有教育意義","examples":[{"en":"The first session was painful in a very educational way.","zh":"第一次活動痛苦，但非常有教育意義。"},{"en":"This phrase means the experience was uncomfortable and embarrassing, but it taught valuable lessons.","zh":"這個片語表示經歷令人不舒服和尷尬，卻教會了有價值的東西。"},{"en":"My first driving lesson was painful in an educational way because every mistake showed me what to improve.","zh":"我的第一堂駕駛課痛苦但很有教育意義，因為每個錯誤都顯示我需要改善甚麼。"},{"en":"The storytelling session felt difficult, yet the discomfort gave me useful information about my fears.","zh":"講故事活動感覺很困難，但不舒服的經驗令我看清自己的恐懼。"},{"en":"Some learning experiences are valuable precisely because they expose weaknesses we need to work on.","zh":"有些學習經歷正正因為暴露需要改善的弱點，所以特別有價值。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"voice shook so badly that","meaning":"聲音抖得厲害，以致……","examples":[{"en":"My voice shook so badly that one boy asked whether I was cold.","zh":"我的聲音抖得厲害，以致一個男孩問我是不是很冷。"},{"en":"“My voice shook so badly that…” means nervousness made my voice tremble strongly enough to cause a noticeable result.","zh":"「my voice shook so badly that…」表示緊張令聲音顫抖得非常明顯，甚至造成某個結果。"},{"en":"Her voice shook so badly that she had to pause and breathe.","zh":"她的聲音抖得厲害，以致要停下來呼吸。"},{"en":"A shaking voice can be a physical sign of anxiety during public speaking.","zh":"聲音顫抖可以是公開說話時焦慮的身體表現。"},{"en":"The “so…that…” structure shows how strong one condition was by giving its consequence.","zh":"「so…that…」句式透過結果顯示某個情況有多強烈。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"ask whether","meaning":"問是否","examples":[{"en":"One boy asked whether I was cold.","zh":"一個男孩問我是否覺得冷。"},{"en":"To ask whether means to ask if something is true or if one possibility is the case.","zh":"「ask whether」表示詢問某件事是否屬實，或某種可能性是否成立。"},{"en":"The teacher asked whether everyone had finished.","zh":"老師問大家是否已經完成。"},{"en":"The child asked whether I was cold because my voice was shaking.","zh":"那個孩子因為我的聲音在抖，所以問我是否覺得冷。"},{"en":"“Whether” is often used when the answer may be yes or no.","zh":"當答案可能是「是」或「不是」時，常可以用「whether」。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"keep interrupting","meaning":"不斷打斷","examples":[{"en":"Another child kept interrupting the story.","zh":"另一個孩子不斷打斷故事。"},{"en":"To keep interrupting means to repeatedly stop someone while they are speaking or doing something.","zh":"「keep interrupting」表示反覆在某人說話或做事時打斷對方。"},{"en":"He kept interrupting the teacher before she could finish the explanation.","zh":"老師還未解釋完，他便不斷打斷。"},{"en":"The child kept interrupting because he was excited and wanted to change the story.","zh":"那個孩子因為很興奮又想改故事，所以不停打斷。"},{"en":"Repeated interruptions can be frustrating, but they may also show that an audience is engaged.","zh":"不斷被打斷可以令人煩躁，但也可能顯示觀眾非常投入。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"immediately","meaning":"立即；馬上","examples":[{"en":"One child asked if the dragon could eat the king immediately.","zh":"一個孩子問巨龍可不可以立即把國王吃掉。"},{"en":"Immediately means at once, without delay.","zh":"「immediately」表示立刻發生，沒有延誤。"},{"en":"Please call me immediately if the situation becomes dangerous.","zh":"如果情況變得危險，請立即致電給我。"},{"en":"The child wanted the exciting event to happen immediately rather than waiting for the story to develop.","zh":"那個孩子希望刺激事件馬上發生，而不是等故事慢慢發展。"},{"en":"“Immediately” emphasises that no time should pass before the action happens.","zh":"「immediately」強調事情發生前不應有任何時間間隔。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"at one point","meaning":"有一刻","examples":[{"en":"At one point, I nearly gave up.","zh":"有一刻，我差點放棄。"},{"en":"“At one point” means at one particular moment during a longer event or period.","zh":"「at one point」表示一段較長事件或時間中的某一個特定時刻。"},{"en":"At one point during the hike, we considered turning back.","zh":"行山途中有一刻，我們考慮過回頭。"},{"en":"The session was difficult enough that at one point I wanted to escape.","zh":"那次活動十分困難，有一刻我甚至想逃走。"},{"en":"This phrase introduces one notable moment without saying exactly when it happened.","zh":"這個片語可以帶出一個值得注意的時刻，而不需要說明準確時間。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"nearly give up","meaning":"差點放棄","examples":[{"en":"At one point, I nearly gave up.","zh":"有一刻，我差點放棄。"},{"en":"To nearly give up means to come very close to stopping because something feels too difficult.","zh":"「nearly give up」表示因事情太困難而幾乎停止，但最後未真正放棄。"},{"en":"She nearly gave up after failing the test twice.","zh":"她考試兩次不合格後差點放棄。"},{"en":"I nearly gave up because my nervousness and the children’s interruptions felt overwhelming.","zh":"我的緊張和孩子不停打斷令我感到難以應付，所以差點放棄。"},{"en":"Nearly giving up is different from actually quitting; there is still a chance to continue.","zh":"差點放棄與真正退出不同，因為仍然有機會繼續。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"as quickly as possible","meaning":"盡快","examples":[{"en":"I nearly read as quickly as possible just to escape.","zh":"我差點只想盡快讀完，好讓自己逃離。"},{"en":"“As quickly as possible” means at the fastest speed you are able to manage.","zh":"「as quickly as possible」表示以自己能做到的最快速度。"},{"en":"We left the building as quickly as possible when the alarm sounded.","zh":"警報響起時，我們盡快離開大樓。"},{"en":"I wanted to finish the story as quickly as possible because I felt embarrassed.","zh":"因為感到尷尬，我只想盡快把故事讀完。"},{"en":"Doing something as quickly as possible is not always helpful if the goal requires quality or connection.","zh":"如果目標需要質素或互動，盡快完成不一定是最好做法。"}],"source":"2017 Q2.pdf","sourcePage":9},{"front":"just to escape","meaning":"只為了逃避","examples":[{"en":"I wanted to read quickly just to escape.","zh":"我想快速讀完，只為了逃避。"},{"en":"“Just to escape” means doing something mainly because you want to leave an uncomfortable situation.","zh":"「just to escape」表示做某件事主要只是希望離開一個令人不舒服的情況。"},{"en":"He agreed immediately just to escape the awkward conversation.","zh":"他立即答應，只為了逃離那場尷尬對話。"},{"en":"I was no longer focused on the children; I wanted only to finish and escape.","zh":"我已不再專注孩子，只想完成活動然後逃走。"},{"en":"When our goal becomes escape, we may stop engaging properly with the experience.","zh":"當我們的目標只剩逃避，就可能不再真正投入那段經歷。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"remember the folded application form","meaning":"想起摺起的報名表","examples":[{"en":"I remembered the folded application form from the year before.","zh":"我想起前一年那張摺起的報名表。"},{"en":"This means the earlier missed opportunity suddenly returned to my memory through the image of the old form.","zh":"這表示之前錯失機會的回憶，以那張舊表格的畫面突然重新出現在腦海。"},{"en":"Seeing the new sign-up sheet made me remember the folded application form I had never submitted.","zh":"看見新的報名表，令我想起那張從未交出的摺起申請表。"},{"en":"The old form symbolised what happened when I allowed fear to delay action.","zh":"那張舊表格象徵我讓恐懼拖延行動後發生的事情。"},{"en":"Past regrets can become useful reminders when we face a similar decision again.","zh":"當我們再次面對相似決定，過去的遺憾可以成為有用提醒。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"from the year before","meaning":"前一年","examples":[{"en":"I remembered the application form from the year before.","zh":"我想起前一年的那張報名表。"},{"en":"“From the year before” means belonging to or happening in the previous year.","zh":"「from the year before」表示屬於或發生在前一年。"},{"en":"She found photographs from the year before in an old folder.","zh":"她在舊資料夾找到前一年的照片。"},{"en":"The memory from the year before influenced how I acted in the new situation.","zh":"前一年的回憶影響了我在新情況中的行動。"},{"en":"Comparing one year with the next can show how a person’s choices have changed.","zh":"比較前一年與下一年，可以看出一個人的選擇如何改變。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"Enough already","meaning":"夠了","examples":[{"en":"Enough already, I told the old version of myself.","zh":"「夠了。」我對過去那個自己說。"},{"en":"“Enough already” means stop now because something has continued for too long.","zh":"「Enough already」表示某件事已持續太久，現在應該停止。"},{"en":"After listening to the same excuse repeatedly, she finally said, “Enough already.”","zh":"聽了同一個藉口很多次後，她終於說：「夠了。」"},{"en":"I used the phrase against my own habit of letting fear control me.","zh":"我用這句話對抗自己一直讓恐懼控制的習慣。"},{"en":"Saying “enough already” can mark a firm decision to stop repeating an old pattern.","zh":"說「夠了」可以標誌一個堅定決定：不再重複舊模式。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"the old version of myself","meaning":"過去那個自己","examples":[{"en":"I spoke firmly to the old version of myself.","zh":"我堅定地對過去那個自己說話。"},{"en":"“The old version of myself” means the person I used to be, especially with earlier habits, fears or beliefs.","zh":"「the old version of myself」表示以前的我，尤其是擁有舊習慣、恐懼或信念的自己。"},{"en":"Looking back, she barely recognised the old version of herself who never spoke in meetings.","zh":"回望過去，她幾乎認不出那個從不在會議發言的舊自己。"},{"en":"My old version avoided embarrassment even when avoidance cost me opportunities.","zh":"過去那個我即使因此錯失機會，也總是選擇逃避尷尬。"},{"en":"Personal growth often involves noticing that our earlier habits no longer have to control us.","zh":"個人成長往往包括明白舊習慣已不必再控制現在的我們。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"slow down","meaning":"放慢下來","examples":[{"en":"I slowed down and began to enjoy the story.","zh":"我放慢下來，開始享受那個故事。"},{"en":"To slow down means to reduce your speed or pace.","zh":"「slow down」表示降低速度或步伐。"},{"en":"The teacher asked the student to slow down so everyone could understand him.","zh":"老師叫學生放慢下來，讓大家都能聽懂。"},{"en":"Slowing down helped me stop thinking only about escape and start noticing the children.","zh":"放慢下來令我不再只想着逃走，而開始留意孩子們。"},{"en":"Sometimes better performance comes from becoming calmer rather than becoming faster.","zh":"有時表現改善來自變得更冷靜，而不是變得更快。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"give the dragon a ridiculous voice","meaning":"用滑稽的聲音扮演巨龍","examples":[{"en":"I gave the dragon a ridiculous voice.","zh":"我用滑稽的聲音扮演巨龍。"},{"en":"To give a character a ridiculous voice means to speak for that character in an exaggerated and funny way.","zh":"用滑稽的聲音扮演角色，是指用誇張而有趣的方式替角色說話。"},{"en":"The teacher gave the monster a ridiculous voice and made the children laugh.","zh":"老師用滑稽的聲音扮演怪獸，把孩子們逗笑了。"},{"en":"Changing my voice turned the reading into a more playful performance.","zh":"改變聲音令朗讀變成更有玩味的表演。"},{"en":"Humour can reduce nervousness by shifting attention from the speaker to the story.","zh":"幽默可以把注意力由講者轉到故事，從而減少緊張。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"invent the ending","meaning":"創作結局","examples":[{"en":"I asked the children to invent the ending.","zh":"我叫孩子們創作結局。"},{"en":"To invent the ending means to create your own final part of a story instead of using an existing one.","zh":"創作結局是指不用原有結局，而自己想出故事的最後部分。"},{"en":"The teacher stopped before the final page and asked students to invent the ending.","zh":"老師在最後一頁前停下來，叫學生創作結局。"},{"en":"Inviting children to invent the ending turned them from passive listeners into participants.","zh":"邀請孩子創作結局，令他們由被動聽眾變成參與者。"},{"en":"Creative questions help audiences become more involved in a story.","zh":"創意問題可以令觀眾更加投入故事。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"little by little","meaning":"一點一點地","examples":[{"en":"Little by little, the room changed.","zh":"一點一點地，房間裏的氣氛改變了。"},{"en":"“Little by little” means gradually, through many small changes rather than one sudden change.","zh":"「little by little」表示逐漸地，透過很多小變化，而不是突然一下改變。"},{"en":"Little by little, the shy child began speaking to the group.","zh":"那個害羞的孩子一點一點地開始向小組說話。"},{"en":"The room became warmer and more energetic little by little as everyone joined in.","zh":"隨着大家加入，房間的氣氛一點一點地變得更溫暖、更有活力。"},{"en":"Confidence often grows little by little through repeated experience.","zh":"自信往往透過反覆經驗一點一點地建立。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"by the second session","meaning":"到第二次活動時","examples":[{"en":"By the second session, the children were shouting ideas.","zh":"到第二次活動時，孩子們已經大聲提出想法。"},{"en":"“By the second session” means that the change had already happened no later than the second meeting.","zh":"「by the second session」表示最遲到了第二次活動時，某個改變已經出現。"},{"en":"By the second lesson, the students already knew each other’s names.","zh":"到第二堂課時，學生已經知道彼此的名字。"},{"en":"The improvement came quickly; by the second session, the group was participating actively.","zh":"改善來得很快；到第二次活動時，小組已經積極參與。"},{"en":"This phrase shows progress between an earlier first experience and a later one.","zh":"這個片語顯示第一次經歷與之後活動之間的進展。"}],"source":"2017 Q2.pdf","sourcePage":10},{"front":"shout ideas","meaning":"大聲提出想法","examples":[{"en":"The children were shouting ideas before I turned the first page.","zh":"我還未翻開第一頁，孩子們已經大聲提出想法。"},{"en":"To shout ideas means to call out suggestions excitedly and loudly.","zh":"「shout ideas」表示興奮而大聲地喊出建議或想法。"},{"en":"Students shouted ideas when the teacher asked how the story should end.","zh":"老師問故事應如何結束時，學生大聲提出不同想法。"},{"en":"The children shouted ideas because they now felt involved rather than simply being told to listen.","zh":"孩子們大聲提出想法，是因為他們已真正參與，而不只是被要求安靜聽。"},{"en":"Excited participation can be noisy while still showing strong engagement.","zh":"興奮參與可以很嘈吵，但同時顯示投入程度很高。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"before I had turned the first page","meaning":"在我翻開第一頁之前","examples":[{"en":"They were shouting ideas before I had turned the first page.","zh":"在我翻開第一頁之前，他們已經大聲提出想法。"},{"en":"This means the children became excited and involved even before the story had properly begun.","zh":"這表示故事還未真正開始，孩子們已經十分興奮和投入。"},{"en":"The audience was asking questions before I had finished the introduction.","zh":"我還未完成介紹，觀眾已開始提問。"},{"en":"Their early enthusiasm showed how much the atmosphere had changed since the first session.","zh":"他們這麼早便表現出的熱情，顯示氣氛與第一次活動相比已改變很多。"},{"en":"The phrase emphasises that a reaction happened earlier than expected.","zh":"這個片語強調某個反應比預期更早發生。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"what surprised me most was","meaning":"最令我驚訝的是","examples":[{"en":"What surprised me most was not only that I became more confident.","zh":"最令我驚訝的，不只是我變得更有自信。"},{"en":"“What surprised me most was” introduces the result or discovery the speaker found most unexpected.","zh":"「what surprised me most was」用來帶出最出乎說話者意料的結果或發現。"},{"en":"What surprised me most was how quickly the children became comfortable with me.","zh":"最令我驚訝的是孩子們很快便和我變得自在。"},{"en":"The greatest surprise was not only personal improvement but also the effect on someone else.","zh":"最大的驚喜不只是個人進步，也包括對其他人的影響。"},{"en":"This structure helps focus attention on the most important unexpected lesson.","zh":"這個句式幫助把注意力集中在最重要的意外收穫。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"become more confident","meaning":"變得更有自信","examples":[{"en":"I became more confident through storytelling.","zh":"我透過講故事變得更有自信。"},{"en":"To become more confident means to gradually develop stronger belief in your ability to act or speak effectively.","zh":"變得更有自信是指逐漸更相信自己有能力有效行動或說話。"},{"en":"She became more confident after giving several short presentations.","zh":"她做了幾次短簡報後變得更有自信。"},{"en":"Confidence grew because repeated practice showed me that mistakes were manageable.","zh":"反覆練習讓我知道錯誤可以處理，因此自信逐漸增加。"},{"en":"People often become more confident by doing difficult things, not by waiting until fear disappears.","zh":"人往往是透過做困難的事情變得更有自信，而不是等恐懼消失才開始。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"not just a doorway for","meaning":"不只是通往……的門口","examples":[{"en":"An opportunity is not just a doorway for personal success.","zh":"一個機會不只是通往個人成功的門口。"},{"en":"“Not just a doorway for” means something does more than provide access to one particular result.","zh":"「not just a doorway for」表示某件事不只提供通往某一個結果的途徑。"},{"en":"Education is not just a doorway for employment; it can also change how people think.","zh":"教育不只是通往就業的門口，也可以改變人的思考方式。"},{"en":"An opportunity may help us grow while also allowing us to help someone else.","zh":"一個機會可以令我們成長，同時也讓我們幫助別人。"},{"en":"This metaphor presents opportunity as an entrance into possibilities beyond a single benefit.","zh":"這個比喻把機會形容成通往多種可能的入口，而不只是一項好處。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"personal success","meaning":"個人成功","examples":[{"en":"An opportunity is not only about personal success.","zh":"一個機會不只是關於個人成功。"},{"en":"Personal success means achievement that benefits or develops the individual person.","zh":"個人成功是對個人帶來成就或成長的成果。"},{"en":"Winning a prize is one form of personal success, but learning a new skill can be another.","zh":"贏得獎項是一種個人成功，學會新技能也可以是另一種。"},{"en":"Volunteering showed me that an opportunity could matter even without obvious personal success.","zh":"義工經驗令我明白，即使沒有明顯個人成功，一個機會仍可以很重要。"},{"en":"Growth becomes broader when success includes helping other people as well as ourselves.","zh":"當成功包括幫助別人而不只是自己，成長便會更廣闊。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"make room for other people","meaning":"為他人騰出空間","examples":[{"en":"An opportunity can make room for other people.","zh":"一個機會可以為其他人騰出空間。"},{"en":"To make room for other people means to create space, chances or benefits that allow others to participate or grow.","zh":"為他人騰出空間是指創造空間、機會或好處，讓其他人也能參與或成長。"},{"en":"A good group leader makes room for quieter members to speak.","zh":"好的小組領袖會為較安靜的成員騰出發言空間。"},{"en":"By becoming more confident, I could make room for children to enjoy and shape the story.","zh":"當我變得更有自信，我便能為孩子騰出空間，讓他們享受並一起塑造故事。"},{"en":"Personal growth becomes meaningful when it creates opportunities for others too.","zh":"當個人成長同時為其他人創造機會，它便變得更有意義。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"a quiet girl named Jane","meaning":"一個名叫Jane的文靜女孩","examples":[{"en":"A quiet girl named Jane stayed behind after one session.","zh":"一次活動後，一個名叫Jane的文靜女孩留了下來。"},{"en":"“A quiet girl named Jane” identifies a girl called Jane whose manner was shy or not very talkative.","zh":"「a quiet girl named Jane」指一個名叫Jane、個性較害羞或不太多說話的女孩。"},{"en":"A quiet student named Leo rarely spoke during group discussions.","zh":"一個名叫Leo的安靜學生在小組討論中很少發言。"},{"en":"Jane’s quiet manner made her later request especially memorable.","zh":"Jane平時很文靜，因此她之後的請求特別令人難忘。"},{"en":"Quiet people may still be deeply engaged even when they do not speak much during an activity.","zh":"安靜的人即使活動中說話不多，也可能非常投入。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"stay behind","meaning":"留下來","examples":[{"en":"Jane stayed behind after one session.","zh":"一次活動後，Jane留了下來。"},{"en":"To stay behind means to remain in a place after other people have left.","zh":"「stay behind」表示其他人離開後，仍然留在原來的地方。"},{"en":"I stayed behind after class to ask the teacher a question.","zh":"下課後我留下來問老師一個問題。"},{"en":"Jane stayed behind because she wanted to speak privately.","zh":"Jane留下來，因為她想私下說話。"},{"en":"Staying behind can create a quieter moment for a conversation that might not happen in a crowd.","zh":"留下來可以創造較安靜的時刻，讓在人群中未必會發生的對話出現。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"borrow the book","meaning":"借那本書","examples":[{"en":"Jane asked if she could borrow the book.","zh":"Jane問她可不可以借那本書。"},{"en":"To borrow a book means to take it temporarily with permission and return it later.","zh":"借書是指得到允許後暫時拿走一本書，之後再歸還。"},{"en":"Students can borrow books from the school library for two weeks.","zh":"學生可以從學校圖書館借書兩星期。"},{"en":"Jane wanted to borrow the picture book so she could share it at home.","zh":"Jane想借那本圖畫書，好讓她可以在家分享。"},{"en":"A request to borrow a book can show that a story has made someone curious enough to continue reading.","zh":"主動要求借一本書，可以顯示故事已令某人產生足夠興趣繼續閱讀。"}],"source":"2017 Q2.pdf","sourcePage":11},{"front":"younger brother","meaning":"弟弟","examples":[{"en":"Jane wanted to read the book to her younger brother.","zh":"Jane想把那本書讀給弟弟聽。"},{"en":"A younger brother is a male sibling who is younger than you.","zh":"弟弟是年紀比自己小的男性兄弟。"},{"en":"She helps her younger brother with homework after dinner.","zh":"她晚飯後幫弟弟做功課。"},{"en":"Jane wanted to take the story home and share it with her younger brother.","zh":"Jane想把故事帶回家，與弟弟分享。"},{"en":"Learning can spread beyond one person when someone passes an experience to a family member.","zh":"當一個人把經歷傳給家人，學習便可以由一個人擴散出去。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"tiny request","meaning":"小小的請求","examples":[{"en":"That tiny request made my day.","zh":"那個小小的請求令我非常開心。"},{"en":"A tiny request is a very small and simple thing someone asks for.","zh":"小小的請求是很簡單、很微小的一項要求。"},{"en":"His tiny request was simply to borrow a pencil.","zh":"他的小小請求只是想借一支鉛筆。"},{"en":"Jane’s request was small, but it showed that the storytelling had mattered to her.","zh":"Jane的請求雖然很小，卻顯示講故事活動對她有意義。"},{"en":"Small moments can carry large emotional meaning when they reveal an unexpected impact.","zh":"當小事情顯示出意想不到的影響，它也可以帶來很大的情感意義。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"make my day","meaning":"令我非常開心","examples":[{"en":"Jane’s tiny request made my day.","zh":"Jane的小小請求令我非常開心。"},{"en":"To make someone’s day means to make them feel especially happy or pleased.","zh":"「make someone’s day」表示令某人特別高興或滿足。"},{"en":"The unexpected thank-you message really made my day.","zh":"那封意外收到的感謝訊息真的令我非常開心。"},{"en":"Jane’s request made my day because it showed that my imperfect storytelling had helped someone.","zh":"Jane的請求令我非常開心，因為它顯示我不完美的講故事仍幫助了別人。"},{"en":"A small positive response can feel powerful when we have been doubting ourselves.","zh":"當我們一直懷疑自己，一個小小的正面回應也可以非常有力量。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"trembling voice","meaning":"顫抖的聲音","examples":[{"en":"My trembling voice had still carried something useful across the room.","zh":"我顫抖的聲音仍然把一些有用的東西傳到了房間另一邊。"},{"en":"A trembling voice is a voice that shakes because of fear, emotion or nervousness.","zh":"顫抖的聲音是因恐懼、情緒或緊張而不穩定的聲音。"},{"en":"She gave the speech in a trembling voice but finished every sentence.","zh":"她用顫抖的聲音完成演說，但每一句都說完了。"},{"en":"A trembling voice does not mean the message has no value.","zh":"聲音顫抖並不代表訊息沒有價值。"},{"en":"Courage can mean speaking even while the voice still shakes.","zh":"勇氣可以是即使聲音仍在顫抖，也願意開口。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"carry something useful across the room","meaning":"把有用的東西傳到房間另一邊","examples":[{"en":"My trembling voice carried something useful across the room.","zh":"我顫抖的聲音把有用的東西傳到了房間另一邊。"},{"en":"This phrase means my words successfully delivered an idea, feeling or benefit to the listeners despite my nervousness.","zh":"這個片語表示即使我很緊張，我的說話仍成功把想法、感受或好處傳給聽眾。"},{"en":"A quiet explanation can carry useful knowledge across a classroom.","zh":"一個安靜的解釋也可以把有用知識傳遍整個課室。"},{"en":"My voice was imperfect, but the story still reached Jane and gave her something worth sharing.","zh":"我的聲音並不完美，但故事仍傳到Jane心中，令她想帶回家分享。"},{"en":"Communication succeeds when something meaningful reaches another person, not only when the delivery is flawless.","zh":"溝通是否成功，在於有意義的東西有沒有傳到另一個人，而不只是表達是否完美。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"lack in glamour","meaning":"缺少光彩","examples":[{"en":"The experience lacked in glamour.","zh":"那段經歷缺少光彩。"},{"en":"To lack glamour means not to have much excitement, beauty, prestige or public attention.","zh":"缺少光彩表示沒有太多刺激、漂亮外表、聲望或公眾注意。"},{"en":"Cleaning a community centre lacks glamour, but the work is still useful.","zh":"清潔社區中心沒有甚麼光彩，但工作仍然有用。"},{"en":"The storytelling sessions lacked glamour because there were no prizes, lights or judges.","zh":"講故事活動沒有獎項、燈光或評判，因此缺少光彩。"},{"en":"An experience can lack glamour while still having deep practical value.","zh":"一段經歷即使不光鮮，也可以有深刻而實際的價值。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"make up for in meaning","meaning":"以意義彌補","examples":[{"en":"What the experience lacked in glamour, it made up for in meaning.","zh":"那段經歷在光彩方面有所欠缺，卻以意義彌補。"},{"en":"To make up for something in another quality means to compensate for one weakness by having strength elsewhere.","zh":"以另一種特質作彌補，是指某方面不足，但由另一項優點補償。"},{"en":"The café lacked space but made up for it in warmth and service.","zh":"那間咖啡店空間不大，卻以溫暖氣氛和服務彌補。"},{"en":"The volunteer work was not glamorous, but its effect on the children gave it strong meaning.","zh":"義工工作並不光鮮，但對孩子的影響令它充滿意義。"},{"en":"Something does not need every advantage if another quality gives it equal or greater value.","zh":"一件事不需要擁有所有優點，只要另一項特質帶來同等甚至更大的價值。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"keep echoing in my mind","meaning":"在腦海中迴響","examples":[{"en":"The song kept echoing in my mind that night.","zh":"那天晚上，那首歌一直在我腦海中迴響。"},{"en":"To keep echoing in someone’s mind means to continue returning to their thoughts after the original sound or event has ended.","zh":"「keep echoing in someone’s mind」表示原本的聲音或事件結束後，仍不斷回到某人的思緒中。"},{"en":"The teacher’s final question kept echoing in my mind on the way home.","zh":"回家途中，老師最後的問題一直在我腦海中迴響。"},{"en":"The song stayed with me because its message matched my own experience.","zh":"那首歌一直留在我心裏，因為它的訊息與我的經歷相呼應。"},{"en":"Ideas often echo in the mind when they connect with unresolved memories or questions.","zh":"當一個想法連結到尚未解決的回憶或問題，它常會在腦海中反覆迴響。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"be left with a simple truth","meaning":"留下一個簡單的道理","examples":[{"en":"I was left with a simple truth about opportunities.","zh":"最後，我心裏留下了一個關於機會的簡單道理。"},{"en":"To be left with a simple truth means to reach one clear conclusion after a complicated experience or period of thought.","zh":"「be left with a simple truth」表示經過複雜經歷或思考後，最後得出一個清楚結論。"},{"en":"After months of debate, we were left with a simple truth: the old system was not working.","zh":"經過幾個月爭論後，我們只剩下一個簡單事實：舊制度行不通。"},{"en":"My experiences reduced many complicated feelings to one clear lesson about action and fear.","zh":"我的經歷把很多複雜感受化成一個關於行動和恐懼的清楚教訓。"},{"en":"A simple truth can be powerful because it is easy to remember when the next decision arrives.","zh":"簡單的道理很有力量，因為下一次要作決定時很容易記起。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"announce themselves as life-changing","meaning":"以改變人生的姿態出現","examples":[{"en":"Opportunities do not always announce themselves as life-changing.","zh":"機會不一定總會以「能改變人生」的姿態出現。"},{"en":"To announce themselves as life-changing means to appear obviously important enough to transform someone’s future.","zh":"「announce themselves as life-changing」表示一開始就明顯顯得重要到足以改變某人的未來。"},{"en":"A small conversation may never announce itself as life-changing, yet it can change a career decision.","zh":"一次簡單對話可能從不以改變人生的姿態出現，卻可以改變職業決定。"},{"en":"Important chances often look ordinary because their future effect is impossible to see at first.","zh":"重要機會常看起來很普通，因為起初很難看見它日後的影響。"},{"en":"Waiting only for dramatic opportunities can make us overlook quiet ones with lasting impact.","zh":"如果只等待戲劇化的機會，我們可能會忽略安靜但影響長遠的機會。"}],"source":"2017 Q2.pdf","sourcePage":12},{"front":"slip away","meaning":"悄悄溜走","examples":[{"en":"Some opportunities slip away because we wait too long.","zh":"有些機會因為我們等得太久而悄悄溜走。"},{"en":"To slip away means to disappear gradually or quietly before we manage to hold onto something.","zh":"「slip away」表示在我們未能把握之前，某件事逐漸或安靜地消失。"},{"en":"The chance to buy the ticket slipped away when all the seats sold out.","zh":"所有座位售罄後，買票的機會便溜走了。"},{"en":"Opportunities can slip away without dramatic warning when deadlines pass.","zh":"當截止日期過去，機會可以在沒有戲劇性警告下悄悄消失。"},{"en":"Waiting feels passive, but it can still produce an active consequence: losing the chance.","zh":"等待看起來很被動，但仍可帶來很實際的後果：失去機會。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"wait too long","meaning":"等得太久","examples":[{"en":"Some chances disappear because we wait too long.","zh":"有些機會因為我們等得太久而消失。"},{"en":"To wait too long means to delay action beyond the useful or permitted time.","zh":"「wait too long」表示拖延行動超過仍然有用或允許的時間。"},{"en":"If you wait too long to reply, the job may be offered to someone else.","zh":"如果你等得太久才回覆，工作可能已經給了另一個人。"},{"en":"Fear can make people wait too long because delay temporarily feels safer.","zh":"恐懼可以令人等得太久，因為拖延暫時感覺比較安全。"},{"en":"Knowing when to stop thinking and start acting is important when time matters.","zh":"當時間重要，知道何時停止思考並開始行動十分重要。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"open only because","meaning":"只因為……才打開","examples":[{"en":"Other chances open only because we move before fear stops us.","zh":"另一些機會只因為我們在恐懼阻止之前先行動，才會打開。"},{"en":"“Open only because” means an opportunity becomes possible specifically because a particular action happens.","zh":"「open only because」表示某個機會之所以成為可能，正是因為某項特定行動發生。"},{"en":"Some friendships open only because someone decides to start the first conversation.","zh":"有些友誼只因為有人主動開始第一段對話，才會打開。"},{"en":"The volunteering opportunity became meaningful only because I signed up before changing my mind.","zh":"那個義工機會之所以變得有意義，只因為我在改變主意前先報名。"},{"en":"Certain doors do not open automatically; our action is what creates access to them.","zh":"有些門不會自動打開；真正創造入口的是我們的行動。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"move before fear finishes its argument","meaning":"在恐懼說服我們之前先行動","examples":[{"en":"Some opportunities open because we move before fear finishes its argument.","zh":"有些機會之所以打開，是因為我們在恐懼完成它的說服之前先行動。"},{"en":"This means acting before anxious thoughts have enough time to persuade us not to try.","zh":"這表示在焦慮想法有足夠時間說服我們不要嘗試之前先採取行動。"},{"en":"She sent the application before fear could finish listing every possible problem.","zh":"她在恐懼還未列完所有可能問題前，便先寄出了申請。"},{"en":"Fear often sounds logical, but acting early can prevent overthinking from controlling the final decision.","zh":"恐懼常聽起來很有道理，但提早行動可以防止過度思考控制最後決定。"},{"en":"The phrase personifies fear as a speaker trying to win an argument against action.","zh":"這個片語把恐懼擬人化成一個正在辯論、企圖說服我們不要行動的人。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"fear finishes its argument","meaning":"恐懼完成它的說服","examples":[{"en":"Fear often tries to finish its argument before we act.","zh":"恐懼常想在我們行動前完成它的說服。"},{"en":"“Fear finishes its argument” means anxious thoughts complete their process of giving us reasons not to act.","zh":"「fear finishes its argument」表示焦慮想法把所有不要行動的理由完整說完。"},{"en":"By the time fear finished its argument, he had convinced himself the interview was too risky.","zh":"到恐懼完成它的說服時，他已說服自己那場面試風險太大。"},{"en":"Fear may argue with predictions of embarrassment, rejection and failure.","zh":"恐懼可能用尷尬、被拒絕和失敗的預測來說服我們。"},{"en":"The phrase shows how internal worry can behave like persuasive reasoning even when its conclusions are exaggerated.","zh":"這個說法顯示內在擔憂可以像有說服力的推理，即使結論其實被誇大。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"cannot undo","meaning":"無法改變；無法挽回","examples":[{"en":"I cannot undo the missed speech festival.","zh":"我無法挽回那次錯失的朗誦節。"},{"en":"To cannot undo something means to be unable to reverse or remove something that has already happened.","zh":"「cannot undo」表示無法逆轉或取消已經發生的事情。"},{"en":"We cannot undo the mistake, but we can learn from it.","zh":"我們無法挽回錯誤，但可以從中學習。"},{"en":"I could not change the missed deadline, only change how I responded to the next chance.","zh":"我無法改變已錯過的截止日期，只能改變下一次面對機會時的反應。"},{"en":"Accepting what cannot be undone allows attention to move from regret towards future action.","zh":"接受無法挽回的事情，可以把注意力由遺憾轉向未來行動。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"What is past cannot be recalled","meaning":"往事不可追","examples":[{"en":"What is past cannot be recalled.","zh":"往事不可追。"},{"en":"This proverb means past events cannot be brought back and changed.","zh":"這句話表示過去發生的事情無法重新帶回來並改變。"},{"en":"We can apologise for an old mistake, but what is past cannot be recalled.","zh":"我們可以為舊錯誤道歉，但往事不可追。"},{"en":"The saying encourages people to learn from regret rather than live inside it forever.","zh":"這句話鼓勵人從遺憾中學習，而不是永遠困在其中。"},{"en":"Although the past cannot be changed, its lesson can influence future choices.","zh":"雖然過去不能改變，但它的教訓可以影響未來選擇。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"the next time life asks whether","meaning":"下一次人生問我是否……","examples":[{"en":"The next time life asks whether I will capture the moment, I hope I say yes.","zh":"下一次人生問我是否會把握當下，我希望自己會回答「會」。"},{"en":"This phrase personifies life as if it were asking us to decide whether we will accept a future opportunity.","zh":"這個片語把人生擬人化，好像它在問我們是否會接受未來機會。"},{"en":"The next time life asks whether she will step forward, she wants to act before fear answers.","zh":"下一次人生問她是否願意站出來時，她希望在恐懼回答前先行動。"},{"en":"Future opportunities may take different forms, but they still ask the same basic question: will we respond?","zh":"未來機會可以以不同形式出現，但仍在問同一個基本問題：我們會不會回應？"},{"en":"The metaphor turns a future decision into a conversation between life and the self.","zh":"這個比喻把未來決定變成人生與自己之間的一場對話。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"capture the moment","meaning":"把握當下","examples":[{"en":"I hope I will capture the moment next time.","zh":"我希望下一次自己會把握當下。"},{"en":"To capture the moment means to recognise an important opportunity and act before it passes.","zh":"「capture the moment」表示察覺一個重要機會，並在它消失前採取行動。"},{"en":"She captured the moment by volunteering to speak when nobody else would.","zh":"沒有人願意發言時，她主動站出來，成功把握當下。"},{"en":"Capturing the moment requires noticing that the chance matters and responding in time.","zh":"把握當下需要察覺機會的重要性，並及時回應。"},{"en":"The phrase suggests holding onto something brief before it disappears.","zh":"這個說法帶有在短暫事物消失前把它抓住的意思。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"quicker, braver and louder","meaning":"更快、更勇敢、更響亮","examples":[{"en":"I hope my answer will be quicker, braver and louder.","zh":"我希望下一次的回答會更快、更勇敢、更響亮。"},{"en":"“Quicker, braver and louder” means responding sooner, with more courage and with clearer commitment.","zh":"「quicker, braver and louder」表示更快回應、更有勇氣，而且更清楚堅定地表態。"},{"en":"After years of hesitation, she wanted her next “yes” to be quicker, braver and louder.","zh":"經過多年猶豫，她希望下一次說「好」時會更快、更勇敢、更響亮。"},{"en":"A quicker answer reduces delay, a braver answer faces fear, and a louder answer shows certainty.","zh":"更快的回答減少拖延，更勇敢的回答面對恐懼，更響亮的回答顯示決心。"},{"en":"The three adjectives describe a stronger response to future opportunities.","zh":"這三個形容詞描述了面對未來機會時更堅定的回應。"}],"source":"2017 Q2.pdf","sourcePage":13},{"front":"prove the point","meaning":"證明這一點","examples":[{"en":"The experience proved the point that opportunities can be small but meaningful.","zh":"那段經歷證明了一點：機會可以很小，卻很有意義。"},{"en":"To prove the point means to provide evidence showing that an idea or argument is correct.","zh":"「prove the point」表示提供證據，顯示某個觀點或論點是正確的。"},{"en":"Her improvement after regular practice proved the point that confidence can be trained.","zh":"她定期練習後有所進步，證明了自信可以透過訓練建立這一點。"},{"en":"Jane’s request proved the point because it showed that an ordinary volunteer role could affect someone else.","zh":"Jane的請求證明了這一點，因為它顯示一個普通義工崗位也可以影響其他人。"},{"en":"A real example often proves a point more clearly than an abstract statement alone.","zh":"真實例子往往比單純抽象陳述更能清楚證明一個觀點。"}],"source":"2017 Q2.pdf","sourcePage":14}],"dse/writing/part-b/2017/Q3":[{"front":"the first thing people ask","meaning":"人們首先會問的事","examples":[{"en":"The first thing people ask is how a lion got into our kitchen.","zh":"人們首先會問的事，是一隻獅子怎會走進我們的廚房。"},{"en":"The first thing people ask means the question that naturally comes to people’s minds before anything else.","zh":"the first thing people ask 指人們在其他問題之前自然最先想到的問題。"},{"en":"When a window is broken, the first thing people ask is whether anyone was hurt.","zh":"當窗戶被打破時，人們首先會問的事是有沒有人受傷。"},{"en":"People ask the most obvious question first because they need to understand the basic facts.","zh":"人們會先問最明顯的問題，因為他們需要理解基本事實。"},{"en":"Sometimes the first thing people ask is not the most important question.","zh":"有時人們首先會問的事，並不是最重要的問題。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"got into our kitchen","meaning":"走進我們的廚房","examples":[{"en":"People asked how a lion got into our kitchen.","zh":"人們問一隻獅子怎會走進我們的廚房。"},{"en":"Got into our kitchen means entered the kitchen, usually in a surprising or unexpected way.","zh":"got into our kitchen 指進入廚房，通常是以令人意外的方式。"},{"en":"A stray cat got into our kitchen when someone left the back door open.","zh":"有人忘記關後門時，一隻流浪貓走進了我們的廚房。"},{"en":"If an animal gets into a kitchen, people may worry about safety and food.","zh":"如果動物走進廚房，人們可能會擔心安全和食物。"},{"en":"The phrase suggests surprise because kitchens are not places where wild animals should appear.","zh":"這個短語帶有驚訝感，因為廚房不是野生動物應該出現的地方。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"the better question","meaning":"更值得問的問題","examples":[{"en":"The better question is why the lion came back.","zh":"更值得問的問題是，為甚麼那隻獅子回來了。"},{"en":"The better question means the more important or meaningful question to ask.","zh":"the better question 指更重要或更有意義、值得提出的問題。"},{"en":"If a student fails a test, the better question may be why they could not understand the topic.","zh":"如果學生測驗不及格，更值得問的問題可能是他為何不能理解該題目。"},{"en":"The better question often looks beyond the surface and asks about causes or meaning.","zh":"更值得問的問題往往會看穿表面，追問原因或意義。"},{"en":"In the story, how the lion entered matters less than why he returned.","zh":"在故事中，獅子如何進入並不如牠為何回來重要。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"came back","meaning":"回來","examples":[{"en":"The lion came back seven years later.","zh":"那隻獅子七年後回來了。"},{"en":"Came back means returned to a place, person, or situation after leaving.","zh":"came back 指離開後返回某個地方、某個人身邊或某種情況。"},{"en":"A child came back to the old playground years after moving away.","zh":"一個孩子搬走多年後，回到舊遊樂場。"},{"en":"People often come back when a place still holds memory, safety, or unfinished feeling.","zh":"當一個地方仍承載記憶、安全感或未完的感覺時，人們常會回來。"},{"en":"When Kito came back, the return showed that farewell had not truly ended everything.","zh":"當 Kito 回來時，這次歸來顯示告別並沒有真正結束一切。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"seven years before","meaning":"七年前","examples":[{"en":"Seven years before the photograph was taken, Father brought home a strange box.","zh":"相片被拍下的七年前，爸爸帶了一個奇怪的箱子回家。"},{"en":"Seven years before means seven years earlier than the time being discussed.","zh":"seven years before 指比正在討論的時間早七年。"},{"en":"Seven years before she became a doctor, she was still a nervous medical student.","zh":"在她成為醫生的七年前，她仍是一名緊張的醫科學生。"},{"en":"This phrase helps a story move into the past and explain what happened earlier.","zh":"這個短語幫助故事回到過去，解釋較早前發生的事。"},{"en":"Seven years before the lion returned, the family had first met him as a cub.","zh":"獅子回來的七年前，這個家庭第一次以幼獅的身份遇見牠。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"the photograph was taken","meaning":"相片被拍下","examples":[{"en":"The photograph was taken after Kito returned.","zh":"這張相片是在 Kito 回來後被拍下的。"},{"en":"The photograph was taken means someone used a camera to capture the image at that time.","zh":"the photograph was taken 指有人在那一刻用相機拍下影像。"},{"en":"The family photograph was taken before everyone left the old flat.","zh":"這張家庭相片是在所有人離開舊單位前被拍下的。"},{"en":"Photographs are often taken to preserve moments that people do not want to forget.","zh":"相片常被拍下來保存人們不想忘記的時刻。"},{"en":"In this story, the photograph records proof of an unbelievable return.","zh":"在這個故事中，相片記錄了一次難以置信的歸來。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"bring home","meaning":"帶回家","examples":[{"en":"Father brought home a cardboard box that breathed.","zh":"爸爸帶了一個會呼吸的紙皮箱回家。"},{"en":"To bring home means to carry or take something back to the place where one lives.","zh":"bring home 指把某物帶回自己居住的地方。"},{"en":"A child may bring home a lost kitten after finding it in the rain.","zh":"孩子可能在雨中發現走失的小貓後，把牠帶回家。"},{"en":"Bringing something home can change family life if the thing needs care or attention.","zh":"如果帶回家的東西需要照顧或關注，家庭生活可能因此改變。"},{"en":"Father did not simply bring home a box; he brought home a life that needed protection.","zh":"爸爸帶回家的不只是一個箱子；他帶回了一個需要保護的生命。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"a cardboard box that breathed","meaning":"一個會呼吸的紙皮箱","examples":[{"en":"Father brought home a cardboard box that breathed.","zh":"爸爸帶回家一個會呼吸的紙皮箱。"},{"en":"A cardboard box that breathed means a box with a living creature inside it.","zh":"a cardboard box that breathed 指裏面有活物的紙皮箱。"},{"en":"A cardboard box that breathed would frighten a child because boxes are not supposed to sound alive.","zh":"一個會呼吸的紙皮箱可能會嚇到孩子，因為箱子本不應像活物一樣有聲音。"},{"en":"The description creates suspense because readers want to know what is hidden inside.","zh":"這個描寫製造懸念，因為讀者想知道裏面藏着甚麼。"},{"en":"The breathing box shows that something fragile and alive has entered the home.","zh":"這個會呼吸的箱子顯示，一個脆弱而活着的生命進入了家中。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"black summer night","meaning":"漆黑的夏夜","examples":[{"en":"It was a black summer night when the rain hammered the windows.","zh":"那是一個漆黑的夏夜，雨猛烈敲打窗戶。"},{"en":"A black summer night is a very dark night in summer, often with a heavy or frightening mood.","zh":"black summer night 指非常黑暗的夏夜，常帶有沉重或令人害怕的氣氛。"},{"en":"On a black summer night, the streets may look empty even though the air is warm.","zh":"在漆黑的夏夜，街道即使空氣溫暖，也可能看起來空無一人。"},{"en":"Darkness and summer heat together can make a storm feel strange and heavy.","zh":"黑暗和夏天悶熱結合起來，會令暴風雨感覺奇怪而沉重。"},{"en":"This phrase prepares readers for something unusual to happen.","zh":"這個短語為讀者預告將會發生不尋常的事。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"the kind of night when","meaning":"那種……的夜晚","examples":[{"en":"It was the kind of night when rain seemed to be trying to get in.","zh":"那是那種雨水彷彿想闖進來的夜晚。"},{"en":"The kind of night when means a night with a particular feeling or situation.","zh":"the kind of night when 指帶有某種特定感覺或情況的夜晚。"},{"en":"It was the kind of night when every small sound made the house feel lonely.","zh":"那是那種每一點細小聲音都令房子顯得孤單的夜晚。"},{"en":"Writers use this phrase to describe atmosphere before telling what happened.","zh":"作者使用這個短語，在講述事件前描寫氣氛。"},{"en":"This phrase makes the night feel memorable rather than ordinary.","zh":"這個短語令那個夜晚感覺難忘，而不是普通。"}],"source":"2017 Q3.pdf","sourcePage":1},{"front":"hammer the windows","meaning":"猛烈敲打窗戶","examples":[{"en":"Rain hammered the windows all night.","zh":"雨整晚猛烈敲打窗戶。"},{"en":"To hammer the windows means to hit the windows loudly and repeatedly, like a hammer.","zh":"hammer the windows 指像鎚子一樣大聲而反覆地打在窗戶上。"},{"en":"During the storm, branches and rain hammered the windows until nobody could sleep.","zh":"暴風雨期間，樹枝和雨水猛烈敲打窗戶，令沒有人睡得着。"},{"en":"This phrase makes rain sound violent, as if it is trying to break in.","zh":"這個短語令雨聽起來很猛烈，彷彿想破窗而入。"},{"en":"Hammering rain creates a tense mood before the lion cub appears.","zh":"猛烈敲打窗戶的雨，在幼獅出現前營造緊張氣氛。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"as if trying to get in","meaning":"彷彿想闖進來","examples":[{"en":"The rain hammered the windows as if trying to get in.","zh":"雨猛烈敲打窗戶，彷彿想闖進來。"},{"en":"As if trying to get in means seeming like it wants to enter, even though it cannot truly want anything.","zh":"as if trying to get in 指看起來像想進入，雖然它其實不可能真的有意願。"},{"en":"The wind pushed against the door as if trying to get in.","zh":"風吹向門口，彷彿想闖進來。"},{"en":"This phrase gives nature a human-like intention and makes the scene more dramatic.","zh":"這個短語把人的意圖賦予自然，令場面更戲劇化。"},{"en":"It suggests the storm outside feels almost alive.","zh":"它暗示外面的暴風雨幾乎像有生命一樣。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"wildlife veterinarian","meaning":"野生動物獸醫","examples":[{"en":"Father was a wildlife veterinarian.","zh":"爸爸是一名野生動物獸醫。"},{"en":"A wildlife veterinarian is an animal doctor who treats wild animals instead of ordinary pets.","zh":"wildlife veterinarian 指治療野生動物，而不是一般寵物的獸醫。"},{"en":"A wildlife veterinarian may care for injured birds, monkeys, turtles, or big cats.","zh":"野生動物獸醫可能照顧受傷的鳥、猴子、海龜或大型貓科動物。"},{"en":"This job requires medical skill because wild animals may be frightened or dangerous.","zh":"這份工作需要醫療技術，因為野生動物可能受驚或危險。"},{"en":"Father’s work explains why a lion cub could arrive at his home in an emergency.","zh":"爸爸的工作解釋了為何幼獅會在緊急情況下來到他家。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"be called to","meaning":"被召到","examples":[{"en":"Father had been called to a warehouse near the harbour.","zh":"爸爸被召到海港附近的一個倉庫。"},{"en":"To be called to a place means to be asked or ordered to go there because help is needed.","zh":"be called to a place 指因為需要幫助而被要求或命令前往某地。"},{"en":"A doctor may be called to the hospital late at night for an emergency.","zh":"醫生可能在深夜因緊急情況被召到醫院。"},{"en":"People are often called to urgent situations when their skills are needed quickly.","zh":"當人們的技能被急需時，他們常會被召到緊急現場。"},{"en":"Father was called to the warehouse because the animals there needed expert care.","zh":"爸爸被召到倉庫，因為那裏的動物需要專業照顧。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"warehouse","meaning":"倉庫","examples":[{"en":"Customs officers found illegal animals in a warehouse.","zh":"海關人員在一個倉庫裏發現非法動物。"},{"en":"A warehouse is a large building used for storing goods before they are moved or sold.","zh":"warehouse 指用來存放貨物、等待運送或售賣的大型建築物。"},{"en":"Shops may keep boxes of food, clothes, or machines in a warehouse.","zh":"商店可能把食物、衣服或機器箱存放在倉庫裏。"},{"en":"A warehouse can hide illegal goods if people use it secretly.","zh":"如果有人秘密使用倉庫，它可以藏起非法貨物。"},{"en":"In the story, the warehouse becomes the place where the lion cub is discovered.","zh":"在故事中，倉庫成為幼獅被發現的地方。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"near the harbour","meaning":"在海港附近","examples":[{"en":"The warehouse was near the harbour.","zh":"那個倉庫在海港附近。"},{"en":"Near the harbour means close to the area where ships arrive, leave, or load goods.","zh":"near the harbour 指靠近船隻抵達、離開或裝卸貨物的地方。"},{"en":"Many warehouses are near the harbour because goods are moved from ships to land.","zh":"許多倉庫都在海港附近，因為貨物會從船運到陸地。"},{"en":"A place near the harbour may be busy with trucks, containers, and customs officers.","zh":"海港附近的地方可能有貨車、貨櫃和海關人員，非常繁忙。"},{"en":"The harbour setting explains why illegal animals might arrive in a shipment.","zh":"海港背景解釋了為何非法動物可能以貨運方式抵達。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"customs officers","meaning":"海關人員","examples":[{"en":"Customs officers discovered a shipment of illegal animals.","zh":"海關人員發現了一批非法動物貨運。"},{"en":"Customs officers are government workers who check goods and people entering or leaving a place.","zh":"customs officers 指檢查進出某地的人和貨物的政府人員。"},{"en":"Customs officers may inspect suitcases, containers, and shipping records.","zh":"海關人員可能檢查行李、貨櫃和運輸紀錄。"},{"en":"They protect the public by stopping dangerous, illegal, or undeclared goods.","zh":"他們透過阻止危險、非法或未申報貨物來保護公眾。"},{"en":"In this story, customs officers are the first to find the hidden animals.","zh":"在這個故事中，海關人員是最先發現被藏起的動物的人。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"a shipment of illegal animals","meaning":"一批非法動物貨運","examples":[{"en":"The officers discovered a shipment of illegal animals.","zh":"人員發現了一批非法動物貨運。"},{"en":"A shipment of illegal animals means a group of animals transported unlawfully as goods.","zh":"a shipment of illegal animals 指被非法當作貨物運送的一批動物。"},{"en":"Police may stop a shipment of illegal animals hidden inside wooden boxes.","zh":"警方可能截停藏在木箱裏的一批非法動物貨運。"},{"en":"Such shipments are cruel because animals may lack food, air, space, and care.","zh":"這類貨運很殘忍，因為動物可能缺乏食物、空氣、空間和照顧。"},{"en":"The phrase shows that the lion cub was treated like cargo, not like a living creature.","zh":"這個短語顯示幼獅被當成貨物，而不是有生命的動物。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"be left behind","meaning":"被遺下","examples":[{"en":"One lion cub had been left behind.","zh":"有一隻幼獅被遺下了。"},{"en":"To be left behind means to remain somewhere after others have gone or been taken away.","zh":"be left behind 指其他人或東西離開或被帶走後，仍留在原地。"},{"en":"A child’s lunchbox may be left behind in the classroom after school.","zh":"孩子的飯盒可能在放學後被遺留在課室。"},{"en":"Being left behind can be dangerous when someone or something depends on care.","zh":"當某人或某物依賴照顧時，被遺下可能很危險。"},{"en":"The cub was left behind, which made him alone, frightened, and vulnerable.","zh":"這隻幼獅被遺下，因此牠孤單、受驚而脆弱。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"lion cub","meaning":"幼獅","examples":[{"en":"A lion cub was shivering in the dark.","zh":"一隻幼獅在黑暗中發抖。"},{"en":"A lion cub is a young lion that is not yet fully grown.","zh":"lion cub 指尚未完全長大的年幼獅子。"},{"en":"A lion cub may look small and soft, but it will grow into a powerful wild animal.","zh":"幼獅可能看起來細小柔軟，但將來會長成強大的野生動物。"},{"en":"Lion cubs need protection because they cannot survive well without care.","zh":"幼獅需要保護，因為沒有照顧時牠們難以生存。"},{"en":"Calling Kito a lion cub reminds us that he was dangerous by nature but helpless at that moment.","zh":"稱 Kito 為幼獅提醒我們，牠天性上有危險性，但那一刻十分無助。"}],"source":"2017 Q3.pdf","sourcePage":2},{"front":"no longer than","meaning":"長度不超過","examples":[{"en":"The lion cub was no longer than my schoolbag.","zh":"那隻幼獅的長度不超過我的書包。"},{"en":"No longer than means not greater in length than something else.","zh":"no longer than 指長度不比另一樣東西長。"},{"en":"The baby snake was no longer than a pencil.","zh":"那條小蛇的長度不超過一支鉛筆。"},{"en":"This phrase helps readers imagine size by comparing it with a familiar object.","zh":"這個短語透過與熟悉物件比較，幫助讀者想像大小。"},{"en":"Saying the cub was no longer than a schoolbag makes him seem small and vulnerable.","zh":"說幼獅長度不超過書包，令牠顯得細小而脆弱。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"shiver in the dark","meaning":"在黑暗中發抖","examples":[{"en":"The cub was shivering in the dark.","zh":"那隻幼獅在黑暗中發抖。"},{"en":"To shiver in the dark means to shake from cold, fear, or weakness in a place without light.","zh":"shiver in the dark 指在沒有光的地方因寒冷、恐懼或虛弱而發抖。"},{"en":"A lost puppy may shiver in the dark under a staircase during a storm.","zh":"暴風雨中，走失的小狗可能在樓梯底下的黑暗中發抖。"},{"en":"Shivering shows that the animal is frightened or physically weak.","zh":"發抖顯示動物感到害怕或身體虛弱。"},{"en":"This image makes readers feel sympathy before they think of danger.","zh":"這個畫面令讀者在想到危險之前，先感到同情。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"just until morning","meaning":"只到明早","examples":[{"en":"Father said the cub would stay just until morning.","zh":"爸爸說那隻幼獅只會留下到明早。"},{"en":"Just until morning means only for the short period before the next morning arrives.","zh":"just until morning 指只在翌日早上到來前的短暫時間。"},{"en":"The injured bird stayed in a box just until morning, when the rescue centre opened.","zh":"那隻受傷的小鳥只在箱子裏留到明早，等動物救援中心開門。"},{"en":"People use this phrase to make a temporary plan sound simple and limited.","zh":"人們使用這個短語，令臨時計劃聽起來簡單而有限。"},{"en":"In the story, just until morning becomes emotionally longer than it sounds.","zh":"在故事中，「只到明早」在情感上比聽起來更長。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"let go","meaning":"放手","examples":[{"en":"Father’s “until morning” often meant “until my heart lets go.”","zh":"爸爸口中的「到明早」常常意思是「直到我的心能放手」。"},{"en":"To let go means to stop holding onto someone, something, or a feeling.","zh":"let go 指停止抓住某人、某物或某種感情。"},{"en":"A child may find it hard to let go of an old toy full of memories.","zh":"孩子可能很難對充滿回憶的舊玩具放手。"},{"en":"Letting go can hurt because love makes separation difficult.","zh":"放手可能令人痛苦，因為愛令分離變得困難。"},{"en":"Father knew that caring for wildlife also meant knowing when to let go.","zh":"爸爸知道，照顧野生動物也代表要懂得何時放手。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"amber eyes","meaning":"琥珀色眼睛","examples":[{"en":"The cub had amber eyes and mud in his whiskers.","zh":"那隻幼獅有琥珀色眼睛，鬍鬚上沾着泥。"},{"en":"Amber eyes are golden-brown eyes, like the colour of amber stone or honey.","zh":"amber eyes 指金啡色的眼睛，像琥珀石或蜜糖的顏色。"},{"en":"A cat with amber eyes may look warm, bright, and watchful.","zh":"一隻有琥珀色眼睛的貓，可能看起來溫暖、明亮而警覺。"},{"en":"Eye colour can help make an animal feel vivid and memorable in a story.","zh":"眼睛顏色能令故事中的動物更鮮明和難忘。"},{"en":"Kito’s amber eyes later help the narrator recognise him again.","zh":"Kito 的琥珀色眼睛後來幫助敘述者再次認出牠。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"mud in his whiskers","meaning":"鬍鬚上沾着泥","examples":[{"en":"Kito had mud in his whiskers.","zh":"Kito 的鬍鬚上沾着泥。"},{"en":"Mud in his whiskers means dirt was stuck on the long hairs around his mouth.","zh":"mud in his whiskers 指泥土黏在牠嘴邊的長鬚上。"},{"en":"A kitten may have mud in its whiskers after hiding under a wet car.","zh":"小貓躲在濕車底後，鬍鬚上可能沾着泥。"},{"en":"This detail shows that Kito had been neglected, frightened, or trapped somewhere dirty.","zh":"這個細節顯示 Kito 曾被忽視、受驚，或困在骯髒地方。"},{"en":"Small physical details like muddy whiskers make an animal’s suffering easier to imagine.","zh":"像鬍鬚沾泥這些細小身體細節，令動物的痛苦更容易想像。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"a thin white scar","meaning":"一道幼細的白色疤痕","examples":[{"en":"Kito had a thin white scar above his nose.","zh":"Kito 鼻子上方有一道幼細的白色疤痕。"},{"en":"A thin white scar is a narrow pale mark left on the skin after an injury heals.","zh":"thin white scar 指傷口癒合後留在皮膚上的狹窄淺色痕跡。"},{"en":"A child may have a thin white scar on their knee after falling from a bicycle.","zh":"孩子從單車上跌倒後，膝蓋上可能有一道幼細的白色疤痕。"},{"en":"Scars can tell readers that a character has survived pain before the story begins.","zh":"疤痕可以告訴讀者，角色在故事開始前已經承受過痛苦。"},{"en":"Kito’s scar becomes a small sign by which he can be remembered.","zh":"Kito 的疤痕成為一個讓人記住牠的小標記。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"above his nose","meaning":"在鼻子上方","examples":[{"en":"The scar was above Kito’s nose.","zh":"那道疤痕在 Kito 的鼻子上方。"},{"en":"Above his nose means in the area higher than the nose on the face.","zh":"above his nose 指臉上比鼻子更高的位置。"},{"en":"The puppy had a small black spot above his nose.","zh":"那隻小狗鼻子上方有一小點黑斑。"},{"en":"Describing exactly where a mark is helps readers picture the animal clearly.","zh":"準確描寫痕跡的位置，能幫助讀者清楚想像動物的樣子。"},{"en":"The scar above his nose later helps identify Kito when he returns.","zh":"鼻子上方的疤痕後來幫助人認出回來的 Kito。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"name him","meaning":"為他改名","examples":[{"en":"I named the lion cub Kito.","zh":"我為那隻幼獅改名為 Kito。"},{"en":"To name him means to give him a name by which people can call and remember him.","zh":"name him 指給他一個名字，讓人能稱呼和記住他。"},{"en":"A family may name a rescued dog after the street where they found him.","zh":"一家人可能用發現流浪狗的街道名稱為牠改名。"},{"en":"Naming an animal can create emotional connection because it feels less like a stranger.","zh":"為動物改名可以建立情感連繫，因為牠不再像陌生者。"},{"en":"When the narrator named him Kito, the cub became part of the family’s story.","zh":"當敘述者為牠改名 Kito 時，這隻幼獅成為家庭故事的一部分。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"the warmest room in the flat","meaning":"單位裏最暖的房間","examples":[{"en":"The kitchen was the warmest room in the flat.","zh":"廚房是單位裏最暖的房間。"},{"en":"The warmest room in the flat means the room with the highest or most comfortable temperature in the apartment.","zh":"the warmest room in the flat 指公寓中溫度最高或最舒適的房間。"},{"en":"In winter, the living room may be the warmest room in the flat because sunlight enters there.","zh":"冬天時，客廳可能因有陽光照入而成為單位裏最暖的房間。"},{"en":"A sick or young animal may be kept in the warmest room to stay safe.","zh":"生病或年幼的動物可能會被安置在最暖的房間，以保持安全。"},{"en":"The kitchen becomes a place of care because it is warm, bright, and close to food.","zh":"廚房因為溫暖、明亮並接近食物，成為照顧的地方。"}],"source":"2017 Q3.pdf","sourcePage":3},{"front":"feed him milk from a bottle","meaning":"用奶樽餵牠飲奶","examples":[{"en":"I fed him milk from a bottle.","zh":"我用奶樽餵牠飲奶。"},{"en":"To feed him milk from a bottle means to give him milk using a feeding bottle instead of letting him drink by himself.","zh":"feed him milk from a bottle 指用奶樽給牠喝奶，而不是讓牠自己進食。"},{"en":"A volunteer may feed an orphaned puppy milk from a bottle every few hours.","zh":"義工可能每隔幾小時用奶樽餵失去母親的小狗飲奶。"},{"en":"Bottle-feeding shows that the young animal is too small to survive without help.","zh":"用奶樽餵食顯示年幼動物太小，沒有幫助就難以生存。"},{"en":"Feeding Kito from a bottle makes the wild cub seem like a helpless baby.","zh":"用奶樽餵 Kito，令這隻野生幼獅看起來像無助的嬰兒。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"clean the wound","meaning":"清理傷口","examples":[{"en":"Father cleaned the wound on Kito’s paw.","zh":"爸爸清理了 Kito 爪上的傷口。"},{"en":"To clean the wound means to remove dirt from an injury so it can heal safely.","zh":"clean the wound 指清除傷口上的污物，讓它安全癒合。"},{"en":"A nurse cleans the wound before putting on a bandage.","zh":"護士在包紮前會清理傷口。"},{"en":"If a wound is not cleaned, infection may make the injury worse.","zh":"如果傷口沒有被清理，感染可能令傷勢惡化。"},{"en":"Cleaning Kito’s wound shows Father’s care was practical, not only emotional.","zh":"清理 Kito 的傷口顯示爸爸的照顧是實際的，而不只是情感上的。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"on his paw","meaning":"在牠的爪上","examples":[{"en":"The wound was on Kito’s paw.","zh":"那道傷口在 Kito 的爪上。"},{"en":"On his paw means located on the animal’s foot.","zh":"on his paw 指位於動物的腳或爪上。"},{"en":"The dog had a small cut on his paw after stepping on glass.","zh":"那隻狗踩到玻璃後，爪上有一道小傷口。"},{"en":"An injury on a paw can make walking painful for an animal.","zh":"爪上的傷口可能令動物走路時感到疼痛。"},{"en":"Kito’s wounded paw reminds readers that even a lion can be fragile.","zh":"Kito 爪上的傷口提醒讀者，即使獅子也可以很脆弱。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"whenever thunder cracked","meaning":"每當雷聲炸響","examples":[{"en":"Whenever thunder cracked, Kito pressed his head against my knee.","zh":"每當雷聲炸響，Kito 就把頭貼着我的膝蓋。"},{"en":"Whenever thunder cracked means every time thunder suddenly made a loud sharp sound.","zh":"whenever thunder cracked 指每次雷聲突然發出巨大而尖銳的聲響。"},{"en":"Whenever thunder cracked, the child covered her ears and ran to her mother.","zh":"每當雷聲炸響，孩子就會掩住耳朵跑向媽媽。"},{"en":"Thunder can frighten animals because the noise is sudden and powerful.","zh":"雷聲會嚇到動物，因為聲音突然又強烈。"},{"en":"Kito’s reaction shows that he searched for comfort when the storm frightened him.","zh":"Kito 的反應顯示，當暴風雨令牠害怕時，牠會尋找安慰。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"press his forehead against","meaning":"把額頭貼着","examples":[{"en":"Kito pressed his forehead against my knee.","zh":"Kito 把額頭貼着我的膝蓋。"},{"en":"To press his forehead against something means to gently push the front of his head onto it.","zh":"press his forehead against something 指把頭前方輕輕貼向某物。"},{"en":"A tired child may press his forehead against the table before falling asleep.","zh":"疲倦的孩子可能在睡着前把額頭貼着桌子。"},{"en":"Animals may press their heads against trusted people when they want comfort.","zh":"動物想得到安慰時，可能會把頭貼着信任的人。"},{"en":"This action shows fear, trust, and the need to feel safe.","zh":"這個動作顯示恐懼、信任和對安全感的需要。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"not like…, but like…","meaning":"不是像……而是像……","examples":[{"en":"Kito looked not like a king of beasts, but like a frightened kitten.","zh":"Kito 看起來不是像百獸之王，而是像一隻受驚的小貓。"},{"en":"Not like…, but like… is used to correct one image by replacing it with a more accurate one.","zh":"not like…, but like… 用來修正一個形象，並換成更準確的形象。"},{"en":"The old teacher sounded not like a strict judge, but like a worried parent.","zh":"那位老老師聽起來不是像嚴厲法官，而是像憂心的家長。"},{"en":"This pattern creates contrast and helps readers see the scene differently.","zh":"這個句式製造對比，幫助讀者以不同方式看見場景。"},{"en":"Kito’s appearance is surprising because a lion should seem powerful, yet he looks helpless.","zh":"Kito 的樣子令人意外，因為獅子本應強大，但牠看起來很無助。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"king of beasts","meaning":"百獸之王","examples":[{"en":"The lion did not look like a king of beasts that night.","zh":"那晚，那隻獅子看起來不像百獸之王。"},{"en":"King of beasts is a traditional phrase for a lion because lions are seen as powerful animals.","zh":"king of beasts 是傳統上形容獅子的說法，因為獅子被視為強大的動物。"},{"en":"A lion in a zoo may look like a king of beasts when it stands calmly above the crowd.","zh":"動物園裏的獅子平靜地站在人群上方時，可能看起來像百獸之王。"},{"en":"The phrase suggests strength, pride, and control.","zh":"這個短語暗示力量、自尊和控制力。"},{"en":"Calling Kito not a king of beasts makes his fear even more noticeable.","zh":"說 Kito 不像百獸之王，令牠的恐懼更加明顯。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"frightened kitten","meaning":"受驚的小貓","examples":[{"en":"Kito looked like a frightened kitten.","zh":"Kito 看起來像一隻受驚的小貓。"},{"en":"A frightened kitten is a small young cat that is scared and seeking safety.","zh":"frightened kitten 指一隻害怕並尋找安全感的小貓。"},{"en":"A frightened kitten may hide under a chair during a thunderstorm.","zh":"雷雨時，受驚的小貓可能躲在椅子下。"},{"en":"Comparing a lion to a frightened kitten makes the lion seem helpless instead of dangerous.","zh":"把獅子比作受驚的小貓，令獅子顯得無助，而不是危險。"},{"en":"This image helps readers feel pity for Kito before fearing him.","zh":"這個形象幫助讀者在害怕 Kito 前先同情牠。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"whose kingdom had been stolen","meaning":"王國被奪走的","examples":[{"en":"He looked like a frightened kitten whose kingdom had been stolen.","zh":"牠看起來像一隻王國被奪走的受驚小貓。"},{"en":"Whose kingdom had been stolen means someone or something has lost the place where they should belong or feel powerful.","zh":"whose kingdom had been stolen 指某人或某物失去了本應屬於自己、讓自己感到有力量的地方。"},{"en":"A child forced to leave an old home may feel like their small kingdom has been stolen.","zh":"被迫離開舊家的孩子，可能覺得自己的小王國被奪走了。"},{"en":"This image suggests loss because Kito has been taken away from his natural world.","zh":"這個形象暗示失去，因為 Kito 被帶離了牠的自然世界。"},{"en":"The phrase makes his fear feel noble and tragic, not merely weak.","zh":"這個短語令牠的恐懼顯得高貴而悲傷，不只是軟弱。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"became his world","meaning":"成為牠的世界","examples":[{"en":"For three weeks, our kitchen became Kito’s world.","zh":"三個星期裏，我們的廚房成為 Kito 的世界。"},{"en":"Became his world means became the main place where he lived, learned, and felt safe.","zh":"became his world 指成為牠生活、學習和感到安全的主要地方。"},{"en":"For a sick child, a small bedroom may become their world during recovery.","zh":"對生病的孩子來說，小小睡房在康復期間可能成為他的世界。"},{"en":"A place becomes someone’s world when almost all their experiences happen there.","zh":"當一個人幾乎所有經驗都在某個地方發生時，那地方就成為他的世界。"},{"en":"The kitchen became Kito’s world because it held warmth, food, care, and trust.","zh":"廚房成為 Kito 的世界，因為那裏有溫暖、食物、照顧和信任。"}],"source":"2017 Q3.pdf","sourcePage":4},{"front":"the fridge hummed","meaning":"雪櫃發出嗡嗡聲","examples":[{"en":"The fridge hummed in the kitchen.","zh":"雪櫃在廚房裏發出嗡嗡聲。"},{"en":"The fridge hummed means the refrigerator made a low steady sound.","zh":"the fridge hummed 指雪櫃發出低沉而穩定的聲音。"},{"en":"At night, the fridge hummed quietly while the rest of the flat was silent.","zh":"夜晚，雪櫃安靜地發出嗡嗡聲，而單位其他地方一片寂靜。"},{"en":"A humming fridge can make a kitchen feel ordinary, safe, and lived-in.","zh":"雪櫃的嗡嗡聲可以令廚房感覺普通、安全而有人生活。"},{"en":"This small sound contrasts with the wildness of the lion cub.","zh":"這細小聲音與幼獅的野性形成對比。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"the sound of my whistle","meaning":"我的口哨聲","examples":[{"en":"Kito learned that the sound of my whistle meant food.","zh":"Kito 學會了我的口哨聲代表有食物。"},{"en":"The sound of my whistle means the noise made when I blow air through my lips or teeth.","zh":"the sound of my whistle 指我用嘴唇或牙縫吹氣時發出的聲音。"},{"en":"A dog may run home when it hears the sound of its owner’s whistle.","zh":"狗聽到主人的口哨聲時，可能會跑回家。"},{"en":"Repeated sounds can become signals when animals connect them with food or safety.","zh":"當動物把重複出現的聲音與食物或安全連繫起來時，聲音就會成為信號。"},{"en":"For Kito, the whistle became a memory linked to care.","zh":"對 Kito 來說，口哨聲成為與照顧相連的記憶。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"meant food","meaning":"代表有食物","examples":[{"en":"The sound of my whistle meant food to Kito.","zh":"我的口哨聲對 Kito 來說代表有食物。"},{"en":"Meant food means was understood as a signal that food was coming.","zh":"meant food 指被理解為食物即將出現的信號。"},{"en":"To the class hamster, the sound of the box opening meant food.","zh":"對班上的倉鼠來說，盒子打開的聲音代表有食物。"},{"en":"Animals learn signals when the same sound is followed by the same result.","zh":"當同一聲音之後總有同一結果，動物就會學會信號。"},{"en":"For Kito, the whistle did not only mean food; it also meant someone was near.","zh":"對 Kito 來說，口哨聲不只代表有食物，也代表有人在附近。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"do justice to","meaning":"充分表達","examples":[{"en":"No words can do justice to the tenderness of being trusted.","zh":"沒有文字能充分表達被信任的溫柔感。"},{"en":"To do justice to something means to describe or represent it fully and fairly.","zh":"do justice to something 指完整而恰當地描述或呈現某事物。"},{"en":"A photo may not do justice to the beauty of a mountain sunset.","zh":"一張相片可能不能充分表達山上日落的美。"},{"en":"People use this phrase when an experience is too deep for simple words.","zh":"當一段體驗太深，簡單文字不足以表達時，人們會使用這個短語。"},{"en":"The narrator feels that ordinary language cannot fully express Kito’s trust.","zh":"敘述者覺得普通語言不能完全表達 Kito 的信任。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"tenderness","meaning":"溫柔感；柔情","examples":[{"en":"No words can describe the tenderness of being trusted by Kito.","zh":"沒有文字能描述被 Kito 信任的溫柔感。"},{"en":"Tenderness is a gentle, warm feeling of care, softness, or affection.","zh":"tenderness 指關懷、柔軟或情感上的溫暖感覺。"},{"en":"A grandmother’s quiet hand on a child’s shoulder can show tenderness.","zh":"祖母安靜地把手放在孩子肩上，可以顯示柔情。"},{"en":"Tenderness often appears when someone strong becomes gentle or vulnerable.","zh":"當強大的存在變得溫柔或脆弱時，溫柔感常會出現。"},{"en":"Kito’s trust creates tenderness because a wild animal chooses not to fear the narrator.","zh":"Kito 的信任帶來溫柔感，因為一隻野生動物選擇不害怕敘述者。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"be trusted by","meaning":"被……信任","examples":[{"en":"I was trusted by something that should have feared me.","zh":"我被某個本應害怕我的生命信任。"},{"en":"To be trusted by someone or something means they believe you will not harm or betray them.","zh":"be trusted by someone or something 指對方相信你不會傷害或背叛他們。"},{"en":"A teacher feels honoured when a shy student trusts them with a problem.","zh":"當害羞學生把問題交託給老師時，老師會感到榮幸。"},{"en":"Being trusted by a frightened animal is special because trust is not automatic.","zh":"被受驚動物信任很特別，因為信任不是自動出現的。"},{"en":"The narrator values being trusted by Kito because it proves care had become safety.","zh":"敘述者重視被 Kito 信任，因為這證明照顧已變成安全感。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"should have feared me","meaning":"本應害怕我","examples":[{"en":"Kito should have feared me, but he trusted me.","zh":"Kito 本應害怕我，但牠信任我。"},{"en":"Should have feared me means he would normally be expected to be afraid of me.","zh":"should have feared me 指按照正常情況，牠應該會害怕我。"},{"en":"A rescued bird should have feared people after being hurt, but it slowly accepted care.","zh":"一隻受傷後獲救的小鳥本應害怕人類，但牠慢慢接受照顧。"},{"en":"This phrase shows that trust is surprising because fear would have been natural.","zh":"這個短語顯示信任令人意外，因為恐懼本來才是自然反應。"},{"en":"Kito’s trust matters because a wild animal had reason to fear humans.","zh":"Kito 的信任很重要，因為一隻野生動物有理由害怕人類。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"keep reminding someone","meaning":"不斷提醒某人","examples":[{"en":"Father kept reminding me that wildlife is not ours to keep.","zh":"爸爸不斷提醒我，野生動物不是屬於我們可以留下的。"},{"en":"To keep reminding someone means to tell them the same important point again and again.","zh":"keep reminding someone 指一次又一次告訴某人同一個重要重點。"},{"en":"Parents keep reminding children to look both ways before crossing the road.","zh":"父母不斷提醒孩子過馬路前要左右看。"},{"en":"People repeat reminders when they know emotions may make someone forget the truth.","zh":"當人們知道情感可能令人忘記事實時，就會反覆提醒。"},{"en":"Father kept reminding the narrator because love for Kito could easily become attachment.","zh":"爸爸不斷提醒敘述者，因為對 Kito 的愛很容易變成依戀。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"wildlife","meaning":"野生動物","examples":[{"en":"Wildlife is not ours to keep.","zh":"野生動物不是屬於我們可以留下的。"},{"en":"Wildlife means animals and plants that live naturally without being owned or controlled by people.","zh":"wildlife 指自然生活、不被人類擁有或控制的動植物。"},{"en":"Birds, deer, sea turtles, and lions are examples of wildlife.","zh":"鳥、鹿、海龜和獅子都是野生動物的例子。"},{"en":"Wildlife needs suitable habitats, not just human affection.","zh":"野生動物需要合適棲息地，而不只是人類的喜愛。"},{"en":"Respecting wildlife means protecting it without turning it into a possession.","zh":"尊重野生動物，意味着保護牠們而不把牠們變成個人物品。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"not ours to keep","meaning":"不是屬於我們可以留下的","examples":[{"en":"Wildlife is not ours to keep.","zh":"野生動物不是屬於我們可以留下的。"},{"en":"Not ours to keep means something does not belong to us and should not be held for ourselves.","zh":"not ours to keep 指某物不屬於我們，不應被我們為自己留下。"},{"en":"A beautiful shell from a protected beach may not be ours to keep.","zh":"受保護海灘上的美麗貝殼，可能不是屬於我們可以帶走的。"},{"en":"Some things can be loved without being owned.","zh":"有些事物可以被愛，而不必被擁有。"},{"en":"Kito was cared for at home, but he was never the family’s possession.","zh":"Kito 曾在家中受到照顧，但牠從來不是這個家庭的所有物。"}],"source":"2017 Q3.pdf","sourcePage":5},{"front":"love is not the same as ownership","meaning":"愛不等於擁有","examples":[{"en":"Father taught me that love is not the same as ownership.","zh":"爸爸教我，愛不等於擁有。"},{"en":"Love is not the same as ownership means caring for someone does not give you the right to possess them.","zh":"love is not the same as ownership 指關心某人並不等於你有權佔有他。"},{"en":"Parents love their children, but they do not own their children’s dreams.","zh":"父母愛孩子，但不擁有孩子的夢想。"},{"en":"True love may require letting someone or something go when freedom is better for them.","zh":"真正的愛可能需要在自由對對方更好時放手。"},{"en":"Father’s lesson explains why Kito had to leave when he became strong enough.","zh":"爸爸的教導解釋了為何 Kito 足夠強壯後必須離開。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"ownership","meaning":"擁有權；佔有","examples":[{"en":"Love is not the same as ownership.","zh":"愛不等於擁有權。"},{"en":"Ownership means the legal or personal right to possess and control something.","zh":"ownership 指擁有和控制某物的法律或個人權利。"},{"en":"Owning a bicycle gives you the right to use it, lend it, or sell it.","zh":"擁有單車代表你有權使用、借出或售賣它。"},{"en":"Ownership can become harmful when people treat living beings like objects.","zh":"當人們把有生命的存在當作物件時，擁有權可能變得有害。"},{"en":"Kito’s story separates care from ownership because he needed freedom, not possession.","zh":"Kito 的故事把照顧與擁有分開，因為牠需要自由，而不是被佔有。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"strong enough","meaning":"足夠強壯","examples":[{"en":"When Kito was strong enough, he was taken to a sanctuary.","zh":"當 Kito 足夠強壯時，牠被帶到動物保護中心。"},{"en":"Strong enough means having enough physical strength or health to do the next necessary thing.","zh":"strong enough 指有足夠體力或健康狀況去做下一件必要的事。"},{"en":"A rescued bird can be released when it is strong enough to fly again.","zh":"受救助的小鳥足夠強壯再次飛行時，就可以被放生。"},{"en":"Being strong enough changes what kind of care is needed.","zh":"足夠強壯會改變所需要的照顧方式。"},{"en":"Once Kito was strong enough, keeping him in a kitchen would no longer be right.","zh":"一旦 Kito 足夠強壯，把牠留在廚房裏就不再合適。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"be taken to","meaning":"被帶到","examples":[{"en":"Kito was taken to Green Ark Sanctuary.","zh":"Kito 被帶到 Green Ark 動物保護中心。"},{"en":"To be taken to a place means to be brought or transported there by someone.","zh":"be taken to a place 指被某人帶去或運送到某地。"},{"en":"The injured dog was taken to an animal clinic by a neighbour.","zh":"那隻受傷的狗被鄰居帶到動物診所。"},{"en":"Animals are taken to safe places when they need care that ordinary homes cannot provide.","zh":"當動物需要普通家庭不能提供的照顧時，牠們會被帶到安全地方。"},{"en":"Kito was taken to the sanctuary because he belonged in a protected wild setting.","zh":"Kito 被帶到保護中心，因為牠屬於受保護的野生環境。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"sanctuary","meaning":"動物保護中心","examples":[{"en":"Kito was taken to Green Ark Sanctuary.","zh":"Kito 被帶到 Green Ark 動物保護中心。"},{"en":"A sanctuary is a safe place where animals are protected and cared for.","zh":"sanctuary 指動物受到保護和照顧的安全地方。"},{"en":"An elephant sanctuary may care for animals that cannot return to the wild immediately.","zh":"大象保護中心可能照顧暫時不能回到野外的動物。"},{"en":"Sanctuaries exist because rescued animals often need space, food, medical care, and safety.","zh":"保護中心存在，是因為獲救動物常需要空間、食物、醫療照顧和安全。"},{"en":"For Kito, the sanctuary was a step away from the kitchen and back toward freedom.","zh":"對 Kito 來說，保護中心是離開廚房、走回自由的一步。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"cry so hard that","meaning":"哭得非常厲害，以致","examples":[{"en":"I cried so hard that Father let me keep Kito’s feeding bowl.","zh":"我哭得非常厲害，以致爸爸讓我留下 Kito 的餵食碗。"},{"en":"Cry so hard that means cry with such strong emotion that it causes a result.","zh":"cry so hard that 指哭得情緒很強烈，以致造成某個結果。"},{"en":"The child cried so hard that the teacher sat beside him until he calmed down.","zh":"那孩子哭得非常厲害，以致老師坐在他旁邊直到他平靜下來。"},{"en":"This pattern shows how the strength of an action leads to what happens next.","zh":"這個句式顯示一個行動的強度如何導致之後的結果。"},{"en":"The narrator cried so hard because losing Kito felt like losing family.","zh":"敘述者哭得非常厲害，因為失去 Kito 感覺像失去家人。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"feeding bowl","meaning":"餵食碗","examples":[{"en":"Father let me keep Kito’s old feeding bowl.","zh":"爸爸讓我留下 Kito 的舊餵食碗。"},{"en":"A feeding bowl is a bowl used to give food to an animal.","zh":"feeding bowl 指用來給動物放食物的碗。"},{"en":"A dog may run to its feeding bowl when it hears dinner being prepared.","zh":"狗聽到準備晚餐的聲音時，可能會跑向自己的餵食碗。"},{"en":"Objects like feeding bowls can carry strong memories after an animal leaves.","zh":"像餵食碗這類物件，在動物離開後可以承載強烈回憶。"},{"en":"Kito’s feeding bowl becomes a small reminder of care, trust, and goodbye.","zh":"Kito 的餵食碗成為照顧、信任和告別的小小提醒。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"life moved on","meaning":"生活繼續","examples":[{"en":"After Kito left, life moved on.","zh":"Kito 離開後，生活繼續。"},{"en":"Life moved on means ordinary life continued after a sad or important event.","zh":"life moved on 指在悲傷或重要事件之後，日常生活仍然繼續。"},{"en":"After the family moved away, life moved on with new schools and new routines.","zh":"一家人搬走後，生活以新學校和新習慣繼續。"},{"en":"This phrase can sound calm, but it often hides sadness underneath.","zh":"這個短語聽起來平靜，但常在下面藏着傷感。"},{"en":"Life moved on after Kito left, but the memory of him stayed.","zh":"Kito 離開後生活繼續，但關於牠的記憶仍留下。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"exams replaced bedtime stories","meaning":"考試取代睡前故事","examples":[{"en":"Exams replaced bedtime stories as I grew older.","zh":"隨着我長大，考試取代了睡前故事。"},{"en":"Exams replaced bedtime stories means school pressure took the place of childhood comfort and imagination.","zh":"exams replaced bedtime stories 指學業壓力取代了童年的安慰和想像。"},{"en":"As children grow older, homework may replace playtime in the evening.","zh":"孩子長大後，功課可能取代晚上的玩耍時間。"},{"en":"This phrase shows how growing up changes what fills a person’s daily life.","zh":"這個短語顯示成長如何改變一個人日常生活中的內容。"},{"en":"The narrator’s childhood with Kito faded as exams and responsibilities arrived.","zh":"隨着考試和責任出現，敘述者與 Kito 共度的童年逐漸淡去。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"framed photograph","meaning":"裱起來的相片","examples":[{"en":"Kito became a framed photograph on our shelf.","zh":"Kito 變成我們架上一張裱起來的相片。"},{"en":"A framed photograph is a photo placed inside a frame for display or protection.","zh":"framed photograph 指放進相框中展示或保護的相片。"},{"en":"Families often keep framed photographs of people, pets, or places they miss.","zh":"家庭常保存想念的人、寵物或地方的裱起來的相片。"},{"en":"A framed photograph can turn a living memory into a quiet object.","zh":"裱起來的相片可以把活生生的記憶變成安靜的物件。"},{"en":"Kito’s framed photograph shows that he had become part of the family’s past.","zh":"Kito 的相框相片顯示牠已成為家庭過去的一部分。"}],"source":"2017 Q3.pdf","sourcePage":6},{"front":"on our shelf","meaning":"在我們的架上","examples":[{"en":"Kito’s photograph stayed on our shelf.","zh":"Kito 的相片一直放在我們的架上。"},{"en":"On our shelf means placed on a flat board or surface used for keeping or displaying things.","zh":"on our shelf 指放在用來存放或展示物件的平板或架子上。"},{"en":"A small trophy on our shelf reminded us of the school race.","zh":"我們架上的小獎杯提醒我們那場學校賽跑。"},{"en":"Objects kept on a shelf are often things people want to see and remember.","zh":"放在架上的物件常是人們想看見和記住的東西。"},{"en":"Kito’s photo on the shelf kept him present in the home even after he left.","zh":"Kito 的相片放在架上，令牠離開後仍像存在於家中。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"up until then","meaning":"直到那時為止","examples":[{"en":"Up until then, I had believed that farewell meant ending.","zh":"直到那時為止，我一直相信告別等於結束。"},{"en":"Up until then means before that moment or before that event changed things.","zh":"up until then 指在那一刻之前，或在那件事改變一切之前。"},{"en":"Up until then, the child thought all dogs were frightening.","zh":"直到那時為止，那個孩子一直以為所有狗都很可怕。"},{"en":"This phrase marks a turning point because the speaker’s understanding is about to change.","zh":"這個短語標示轉折點，因為說話者的理解即將改變。"},{"en":"Before Kito returned, the narrator believed goodbyes were final.","zh":"在 Kito 回來之前，敘述者相信告別就是最終結局。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"farewell meant ending","meaning":"告別等於結束","examples":[{"en":"I had believed that farewell meant ending.","zh":"我一直相信告別等於結束。"},{"en":"Farewell meant ending means saying goodbye was understood as the final close of a relationship or experience.","zh":"farewell meant ending 指把說再見理解為一段關係或經歷的最終完結。"},{"en":"A student may think farewell means ending when a best friend moves overseas.","zh":"當最好的朋友搬到海外時，學生可能以為告別等於結束。"},{"en":"This belief can change when memories, letters, or reunions keep a bond alive.","zh":"當記憶、書信或重逢令連繫繼續存在時，這種信念可能改變。"},{"en":"Kito’s return teaches that farewell may be separation, not complete ending.","zh":"Kito 的回來教會人，告別可能只是分離，而不是完全結束。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"then came","meaning":"然後……來臨","examples":[{"en":"Then came Typhoon Helena.","zh":"然後，颱風 Helena 來臨。"},{"en":"Then came means after that, something important or dramatic arrived or happened.","zh":"then came 指在那之後，某件重要或戲劇性的事到來或發生。"},{"en":"The town was quiet for weeks; then came the storm.","zh":"小鎮安靜了幾個星期；然後暴風雨來臨。"},{"en":"Writers use this phrase to make a new event feel sudden and powerful.","zh":"作者使用這個短語，令新事件感覺突然而有力量。"},{"en":"Then came Typhoon Helena, and the calm memory of Kito became urgent again.","zh":"然後颱風 Helena 來臨，關於 Kito 的平靜記憶再次變得迫切。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"typhoon","meaning":"颱風","examples":[{"en":"Typhoon Helena brought heavy rain and danger.","zh":"颱風 Helena 帶來大雨和危險。"},{"en":"A typhoon is a powerful tropical storm with strong winds and heavy rain.","zh":"typhoon 指帶有強風和暴雨的強烈熱帶風暴。"},{"en":"During a typhoon, schools may close and people may stay indoors for safety.","zh":"颱風期間，學校可能停課，人們可能留在室內以保安全。"},{"en":"Typhoons can damage buildings, flood roads, and endanger people and animals.","zh":"颱風可以破壞建築物、淹浸道路，並危及人和動物。"},{"en":"In the story, the typhoon creates the crisis that brings Kito back.","zh":"在故事中，颱風製造危機，令 Kito 回來。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"by seven in the evening","meaning":"到晚上七點時","examples":[{"en":"By seven in the evening, the city had vanished behind sheets of rain.","zh":"到晚上七點時，城市已消失在雨幕後。"},{"en":"By seven in the evening means no later than 7 p.m., the situation had already happened.","zh":"by seven in the evening 指不遲於晚上七點時，情況已經發生。"},{"en":"By seven in the evening, the streets were empty and the shops had closed.","zh":"到晚上七點時，街道已空無一人，商店也已關門。"},{"en":"This phrase shows a point in time by which the storm had already changed the city.","zh":"這個短語指出到某個時間點時，暴風雨已經改變了城市。"},{"en":"It helps readers feel how quickly the weather became dangerous.","zh":"它幫助讀者感覺天氣變得危險的速度有多快。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"vanish behind","meaning":"消失在……後面","examples":[{"en":"The city had vanished behind sheets of rain.","zh":"城市已消失在雨幕後面。"},{"en":"To vanish behind something means to disappear from sight because something blocks the view.","zh":"vanish behind something 指因某物遮擋視線而看不見。"},{"en":"The mountains vanished behind thick fog in the morning.","zh":"早上，群山消失在濃霧後面。"},{"en":"Heavy rain can make buildings vanish behind a grey curtain of water.","zh":"大雨可以令建築物消失在灰色水簾後面。"},{"en":"In the story, the city vanishing behind rain shows how powerful the storm is.","zh":"在故事中，城市消失在雨後，顯示暴風雨有多強大。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"sheets of rain","meaning":"傾盆大雨；雨幕","examples":[{"en":"The city disappeared behind sheets of rain.","zh":"城市消失在傾盆大雨形成的雨幕後。"},{"en":"Sheets of rain means very heavy rain falling in thick, continuous layers.","zh":"sheets of rain 指厚厚一層接一層落下的猛烈大雨。"},{"en":"Drivers slowed down because sheets of rain covered the road ahead.","zh":"司機放慢速度，因為雨幕遮住前方道路。"},{"en":"This phrase makes rain seem like a curtain that hides everything behind it.","zh":"這個短語令雨看起來像簾幕，把後面的東西遮住。"},{"en":"Sheets of rain create danger because people cannot see clearly.","zh":"傾盆大雨會造成危險，因為人們看不清楚。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"receive a call from","meaning":"接到……的電話","examples":[{"en":"Father received a call from Green Ark.","zh":"爸爸接到 Green Ark 的電話。"},{"en":"To receive a call from someone means to get a phone call from that person or organisation.","zh":"receive a call from someone 指接到某人或某機構打來的電話。"},{"en":"A parent may receive a call from school if a child feels sick.","zh":"如果孩子不舒服，家長可能會接到學校的電話。"},{"en":"Receiving a call during a storm can create worry because it may bring urgent news.","zh":"暴風雨中接到電話可能令人擔心，因為它可能帶來緊急消息。"},{"en":"Father’s call from Green Ark begins the search for the missing lion.","zh":"爸爸接到 Green Ark 的電話，開始了尋找失蹤獅子的事件。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"a section of fencing","meaning":"一段圍欄","examples":[{"en":"A section of fencing had collapsed.","zh":"一段圍欄倒塌了。"},{"en":"A section of fencing means one part of a barrier or fence.","zh":"a section of fencing 指屏障或圍欄的一部分。"},{"en":"A section of fencing around the playground was repaired after the storm.","zh":"暴風雨後，遊樂場周圍的一段圍欄被修理。"},{"en":"If one section of fencing breaks, animals or people may pass through the gap.","zh":"如果一段圍欄破裂，動物或人可能從缺口穿過。"},{"en":"In the sanctuary, one broken section was enough to let danger escape.","zh":"在保護中心，一段破損圍欄已足以讓危險逃出。"}],"source":"2017 Q3.pdf","sourcePage":7},{"front":"fencing","meaning":"圍欄","examples":[{"en":"The sanctuary’s fencing had collapsed in the storm.","zh":"動物保護中心的圍欄在暴風雨中倒塌。"},{"en":"Fencing means the material or structure used to form a fence around an area.","zh":"fencing 指用來圍住某個地方的材料或結構。"},{"en":"Farms use fencing to keep animals inside safe fields.","zh":"農場使用圍欄把動物安全地留在田地內。"},{"en":"Strong fencing is important when large or dangerous animals must be protected and contained.","zh":"當大型或危險動物需要被保護和限制在範圍內時，堅固圍欄很重要。"},{"en":"When the fencing failed, Kito could leave the sanctuary during the typhoon.","zh":"當圍欄失效時，Kito 能在颱風中離開保護中心。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"collapse","meaning":"倒塌","examples":[{"en":"A section of fencing collapsed during the typhoon.","zh":"一段圍欄在颱風期間倒塌。"},{"en":"To collapse means to fall down suddenly because something is weak, damaged, or under pressure.","zh":"collapse 指因脆弱、受損或受壓而突然倒下。"},{"en":"An old wall may collapse after days of heavy rain.","zh":"一道舊牆在多日大雨後可能倒塌。"},{"en":"When structures collapse, they can create danger and open unexpected gaps.","zh":"當結構倒塌時，會製造危險並打開意想不到的缺口。"},{"en":"The collapsed fence turns the storm into a crisis for both people and Kito.","zh":"倒塌的圍欄令暴風雨變成人和 Kito 都要面對的危機。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"adult male lion","meaning":"成年雄獅","examples":[{"en":"One adult male lion was missing.","zh":"有一隻成年雄獅失蹤。"},{"en":"An adult male lion is a fully grown male lion, usually large, powerful, and dangerous if frightened.","zh":"adult male lion 指已完全長大的雄性獅子，通常體型龐大、有力量，受驚時可能危險。"},{"en":"An adult male lion has a much stronger body than a small cub.","zh":"成年雄獅的身體比幼獅強壯得多。"},{"en":"People react seriously when an adult male lion escapes because it can harm others even without meaning to.","zh":"成年雄獅逃走時，人們會嚴肅處理，因為牠即使無意也可能傷人。"},{"en":"The phrase changes Kito from a helpless cub in memory to a powerful animal in the present.","zh":"這個短語把記憶中無助的幼獅，變成現在強大的動物。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"go missing","meaning":"失蹤","examples":[{"en":"An adult male lion had gone missing.","zh":"一隻成年雄獅失蹤了。"},{"en":"To go missing means to disappear so that people do not know where someone or something is.","zh":"go missing 指消失了，令人不知道某人或某物在哪裏。"},{"en":"A child’s schoolbag may go missing during a crowded trip.","zh":"孩子的書包可能在擁擠旅行中失蹤。"},{"en":"When an animal goes missing, search teams must act quickly before danger increases.","zh":"當動物失蹤時，搜索隊必須迅速行動，以免危險增加。"},{"en":"Kito going missing creates fear because nobody knows where he will run.","zh":"Kito 失蹤令人恐懼，因為沒有人知道牠會跑到哪裏。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"drive out immediately","meaning":"立即開車出去","examples":[{"en":"Father drove out immediately after the call.","zh":"爸爸接到電話後立即開車出去。"},{"en":"To drive out immediately means to leave by car at once, without delay.","zh":"drive out immediately 指馬上開車離開，沒有拖延。"},{"en":"The doctor drove out immediately when the hospital reported an emergency.","zh":"醫院報告有緊急情況時，醫生立即開車出去。"},{"en":"People drive out immediately when waiting could make the situation more dangerous.","zh":"當等待可能令情況更危險時，人們會立即開車出去。"},{"en":"Father’s quick response shows that the missing lion was urgent and serious.","zh":"爸爸迅速反應，顯示失蹤獅子的情況緊急而嚴重。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"be told to stay home","meaning":"被吩咐留在家中","examples":[{"en":"I was told to stay home with Mum.","zh":"我被吩咐和媽媽留在家中。"},{"en":"To be told to stay home means someone instructed you not to leave the house.","zh":"be told to stay home 指有人指示你不要離開家。"},{"en":"During a typhoon, children may be told to stay home for safety.","zh":"颱風期間，孩子可能被吩咐留在家中以保安全。"},{"en":"Adults tell young people to stay home when outside conditions are dangerous.","zh":"當外面環境危險時，成年人會叫年輕人留在家中。"},{"en":"The narrator is told to stay home, but worry for Kito pushes her to disobey.","zh":"敘述者被吩咐留在家中，但對 Kito 的擔心促使她違抗。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"armed officers","meaning":"武裝人員","examples":[{"en":"Armed officers were searching nearby.","zh":"武裝人員正在附近搜索。"},{"en":"Armed officers are police or security officers carrying weapons.","zh":"armed officers 指攜帶武器的警察或保安人員。"},{"en":"Armed officers may be called when a dangerous animal or violent person is loose.","zh":"當危險動物或暴力人士逃脫時，武裝人員可能被召來。"},{"en":"Their presence shows that the situation is considered serious and risky.","zh":"他們的出現顯示情況被視為嚴重而有風險。"},{"en":"In the story, armed officers increase the danger because Kito may be shot if he charges.","zh":"在故事中，武裝人員增加危險，因為如果 Kito 衝過來，牠可能會被射擊。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"search nearby","meaning":"在附近搜索","examples":[{"en":"Armed officers were searching nearby.","zh":"武裝人員正在附近搜索。"},{"en":"To search nearby means to look carefully in the area close to where something happened.","zh":"search nearby 指在事情發生地點附近仔細尋找。"},{"en":"Volunteers searched nearby after a child lost her dog in the park.","zh":"一名孩子在公園遺失小狗後，義工在附近搜索。"},{"en":"Searchers stay nearby first because the missing person or animal may not have gone far.","zh":"搜索者會先留在附近，因為失蹤的人或動物可能還沒有走遠。"},{"en":"The officers searched nearby because Kito might still be close to the sanctuary or the neighbourhood.","zh":"人員在附近搜索，因為 Kito 可能仍接近保護中心或社區。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"if the animal charges","meaning":"如果動物衝過來","examples":[{"en":"If the animal charges, the officers may have no choice.","zh":"如果動物衝過來，人員可能別無選擇。"},{"en":"If the animal charges means if the animal suddenly runs aggressively toward someone.","zh":"if the animal charges 指如果動物突然有攻擊性地衝向某人。"},{"en":"If a bull charges, people must move away quickly.","zh":"如果公牛衝過來，人們必須迅速避開。"},{"en":"A charging animal may be frightened rather than evil, but it can still be dangerous.","zh":"衝過來的動物可能是受驚，而不是邪惡，但仍然危險。"},{"en":"This phrase makes the situation tense because one movement could decide Kito’s fate.","zh":"這個短語令情況緊張，因為一個動作可能決定 Kito 的命運。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"have no choice","meaning":"別無選擇","examples":[{"en":"The officers may have no choice if the lion charges.","zh":"如果獅子衝過來，人員可能別無選擇。"},{"en":"To have no choice means to be forced to do something because no other safe option remains.","zh":"have no choice 指因沒有其他安全選項而被迫做某事。"},{"en":"A driver may have no choice but to stop when the road is flooded.","zh":"當道路水浸時，司機可能別無選擇，只能停車。"},{"en":"People say they have no choice when the situation leaves them with only one possible action.","zh":"當情況只剩一個可能行動時，人們會說自己別無選擇。"},{"en":"The phrase frightens the narrator because it suggests Kito could be killed.","zh":"這個短語令敘述者害怕，因為它暗示 Kito 可能被殺。"}],"source":"2017 Q3.pdf","sourcePage":8},{"front":"strike me like a slap","meaning":"像一巴掌打中我","examples":[{"en":"The phrase struck me like a slap.","zh":"那句話像一巴掌打中我。"},{"en":"To strike me like a slap means to shock or hurt me suddenly, as if I had been hit.","zh":"strike me like a slap 指突然震驚或傷害我，感覺像被打了一巴掌。"},{"en":"The teacher’s criticism struck him like a slap because he had tried his best.","zh":"老師的批評像一巴掌打中他，因為他已經盡力。"},{"en":"This phrase describes emotional pain using the feeling of physical impact.","zh":"這個短語用身體被打中的感覺來描寫情感上的痛。"},{"en":"The warning about shooting Kito hits the narrator with sudden fear.","zh":"關於射擊 Kito 的警告，以突然的恐懼擊中了敘述者。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"headline","meaning":"新聞標題","examples":[{"en":"Kito was not just a frightening headline.","zh":"Kito 不只是一個令人害怕的新聞標題。"},{"en":"A headline is the title of a news story, usually written to catch attention.","zh":"headline 指新聞故事的標題，通常用來吸引注意。"},{"en":"A newspaper headline may describe an escaped animal in a simple and frightening way.","zh":"報紙標題可能用簡單而可怕的方式描述逃走的動物。"},{"en":"Headlines can make complex stories seem smaller or more shocking than they really are.","zh":"新聞標題可以令複雜故事看起來更簡單或更震撼。"},{"en":"To the narrator, Kito is not a headline but a living creature with memory.","zh":"對敘述者來說，Kito 不是新聞標題，而是有記憶的生命。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"monster","meaning":"怪物","examples":[{"en":"Kito was not a monster.","zh":"Kito 不是怪物。"},{"en":"A monster is a frightening creature or person imagined as cruel, dangerous, or unnatural.","zh":"monster 指被想像成殘忍、危險或不自然的可怕生物或人。"},{"en":"People may wrongly call an animal a monster when they are afraid of it.","zh":"當人們害怕動物時，可能錯誤地稱牠為怪物。"},{"en":"Calling something a monster can make people forget its fear, pain, or history.","zh":"稱某物為怪物，可能令人忘記牠的恐懼、痛苦或過去。"},{"en":"Kito may be dangerous, but the narrator sees him as frightened, not evil.","zh":"Kito 可能危險，但敘述者看見的是受驚，而不是邪惡。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"frightened animal","meaning":"受驚的動物","examples":[{"en":"Kito was a frightened animal in a storm.","zh":"Kito 是暴風雨中一隻受驚的動物。"},{"en":"A frightened animal is an animal that is scared and may act unpredictably.","zh":"frightened animal 指感到害怕，並可能作出難以預測行為的動物。"},{"en":"A frightened animal may hide, run, bite, or freeze because it does not feel safe.","zh":"受驚的動物可能會躲藏、逃跑、咬人或僵住，因為牠感到不安全。"},{"en":"Understanding fear helps people respond more carefully to animal behaviour.","zh":"理解恐懼有助人們更小心地回應動物行為。"},{"en":"Kito is dangerous partly because he is frightened, not because he wants to harm anyone.","zh":"Kito 危險，部分原因是牠受驚，而不是牠想傷害任何人。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"chasing whatever memory","meaning":"追尋任何仍然存在的記憶","examples":[{"en":"Kito was chasing whatever memory still smelled like safety.","zh":"Kito 正追尋任何仍然聞起來像安全的記憶。"},{"en":"Chasing whatever memory means following any remembered feeling, place, or sign that might lead back to comfort.","zh":"chasing whatever memory 指追隨任何可能帶回安慰的記憶、地方或信號。"},{"en":"A lost child may chase whatever memory helps them find the way home.","zh":"走失的孩子可能追尋任何能幫助他回家的記憶。"},{"en":"Fear can make people and animals follow old memories of safety.","zh":"恐懼會令人和動物跟隨舊有的安全記憶。"},{"en":"Kito’s return suggests that memory pulled him toward the kitchen.","zh":"Kito 的回來暗示記憶把牠拉向那個廚房。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"smelled like safety","meaning":"聞起來像安全","examples":[{"en":"The memory still smelled like safety to Kito.","zh":"那段記憶對 Kito 來說仍聞起來像安全。"},{"en":"Smelled like safety means seemed connected to protection, comfort, and being safe, especially through memory or scent.","zh":"smelled like safety 指透過記憶或氣味，感覺與保護、安慰和安全相連。"},{"en":"A blanket may smell like safety to a child because it reminds them of home.","zh":"毛氈對孩子來說可能聞起來像安全，因為它令他想起家。"},{"en":"Animals often connect smells with danger, food, people, or comfort.","zh":"動物常把氣味與危險、食物、人或安慰連繫起來。"},{"en":"For Kito, the old kitchen and whistle may have smelled like safety.","zh":"對 Kito 來說，舊廚房和口哨聲可能聞起來像安全。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"pull on","meaning":"匆匆穿上","examples":[{"en":"I pulled on Father’s raincoat and ran.","zh":"我匆匆穿上爸爸的雨衣，然後跑出去。"},{"en":"To pull on clothing means to put it on quickly, often in a hurry.","zh":"pull on clothing 指迅速穿上衣物，通常是很匆忙。"},{"en":"She pulled on her shoes and rushed to catch the bus.","zh":"她匆匆穿上鞋子，趕去追巴士。"},{"en":"People pull on clothes quickly when they have no time to dress carefully.","zh":"當人們沒有時間仔細穿戴時，就會匆匆穿上衣物。"},{"en":"The narrator pulling on the raincoat shows her decision was sudden and urgent.","zh":"敘述者匆匆穿上雨衣，顯示她的決定突然而迫切。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"raincoat","meaning":"雨衣","examples":[{"en":"I pulled on Father’s raincoat before running outside.","zh":"我跑出去前匆匆穿上爸爸的雨衣。"},{"en":"A raincoat is a coat designed to keep the body dry in wet weather.","zh":"raincoat 指設計用來在雨天保持身體乾爽的外套。"},{"en":"Students wear raincoats when they walk to school during heavy rain.","zh":"大雨時，學生步行上學會穿雨衣。"},{"en":"A raincoat protects the body but cannot remove the danger of a storm.","zh":"雨衣可以保護身體，但不能消除暴風雨的危險。"},{"en":"Father’s raincoat also makes the narrator feel connected to him as she runs out.","zh":"爸爸的雨衣也令敘述者跑出去時感到與他相連。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"branches clawed at","meaning":"樹枝像爪子般抓着","examples":[{"en":"Branches clawed at the road in the storm.","zh":"暴風雨中，樹枝像爪子般抓着道路。"},{"en":"Branches clawed at something means branches scratched, struck, or dragged against it like claws.","zh":"branches clawed at something 指樹枝像爪子一樣刮、打或拖過某物。"},{"en":"During the typhoon, tree branches clawed at windows and car roofs.","zh":"颱風期間，樹枝像爪子般抓着窗戶和車頂。"},{"en":"This phrase makes the storm feel animal-like and threatening.","zh":"這個短語令暴風雨感覺像動物般有威脅。"},{"en":"The branches clawing at the road make the journey outside seem dangerous.","zh":"樹枝像爪子般抓着道路，令外出的路程顯得危險。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"whistle between my teeth","meaning":"用牙縫吹口哨","examples":[{"en":"I whistled between my teeth.","zh":"我用牙縫吹口哨。"},{"en":"To whistle between my teeth means to make a sharp sound by forcing air through the teeth.","zh":"whistle between my teeth 指讓空氣穿過牙縫，發出尖而清楚的聲音。"},{"en":"A shepherd may whistle between his teeth to call a dog across a field.","zh":"牧羊人可能用牙縫吹口哨，叫狗越過田地回來。"},{"en":"Whistling can travel through noise better than ordinary speech.","zh":"口哨聲比普通說話更能穿過噪音。"},{"en":"The narrator whistles because this sound once meant food and safety to Kito.","zh":"敘述者吹口哨，因為這聲音曾經對 Kito 代表食物和安全。"}],"source":"2017 Q3.pdf","sourcePage":9},{"front":"the same three notes","meaning":"同樣三個音","examples":[{"en":"I used the same three notes from seven years before.","zh":"我用了七年前同樣三個音。"},{"en":"The same three notes means the exact short pattern of three sounds used in the past.","zh":"the same three notes 指過去使用過的完全相同三個聲音短句。"},{"en":"A mother may sing the same three notes every night to calm her baby.","zh":"母親可能每晚唱同樣三個音來安撫嬰兒。"},{"en":"Repeated sounds can become powerful memories over time.","zh":"重複的聲音隨時間可以變成強大的記憶。"},{"en":"The same three notes connect the adult lion to the frightened cub he once was.","zh":"同樣三個音把成年的獅子與牠曾經是受驚幼獅的過去連接起來。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"from somewhere beyond","meaning":"從……外某處","examples":[{"en":"From somewhere beyond the playground came a familiar sound.","zh":"從遊樂場外某處傳來熟悉的聲音。"},{"en":"From somewhere beyond means from a place farther away than the place named.","zh":"from somewhere beyond 指從比所提地方更遠的某個位置傳來。"},{"en":"From somewhere beyond the trees came the sound of a dog barking.","zh":"從樹林外某處傳來狗吠聲。"},{"en":"This phrase creates suspense because the exact place is not yet clear.","zh":"這個短語製造懸念，因為確實位置尚未清楚。"},{"en":"The sound from beyond the playground tells the narrator that Kito may be close.","zh":"從遊樂場外傳來的聲音告訴敘述者，Kito 可能就在附近。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"playground","meaning":"遊樂場","examples":[{"en":"The sound came from somewhere beyond the playground.","zh":"聲音從遊樂場外某處傳來。"},{"en":"A playground is an outdoor area where children play, often with swings, slides, or open space.","zh":"playground 指孩子玩耍的戶外地方，通常有鞦韆、滑梯或開放空間。"},{"en":"A playground is usually a place of safety, noise, and ordinary childhood.","zh":"遊樂場通常是安全、熱鬧和童年日常的地方。"},{"en":"During a storm, an empty playground can feel strange and frightening.","zh":"暴風雨中，空蕩蕩的遊樂場可能感覺奇怪而可怕。"},{"en":"The playground setting makes Kito’s return feel close to both childhood and danger.","zh":"遊樂場這個背景令 Kito 的回來同時接近童年和危險。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"low, rough and familiar","meaning":"低沉、沙啞而熟悉","examples":[{"en":"The sound was low, rough and familiar.","zh":"那聲音低沉、沙啞而熟悉。"},{"en":"Low, rough and familiar means deep in pitch, harsh in texture, but still recognised.","zh":"low, rough and familiar 指音調低、聲音粗糙，但仍能被認出。"},{"en":"An old dog’s bark may sound low, rough and familiar after many years.","zh":"多年後，一隻老狗的叫聲可能低沉、沙啞而熟悉。"},{"en":"A familiar sound can comfort someone even when it has changed with age.","zh":"熟悉的聲音即使隨年齡改變，仍可以安慰人。"},{"en":"Kito’s voice is rougher now, but the narrator still recognises something from the past.","zh":"Kito 的聲音如今更沙啞，但敘述者仍認出過去的某些東西。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"little by little","meaning":"一點一點地；漸漸地","examples":[{"en":"Little by little, a shape emerged from the rain.","zh":"一點一點地，一個身影從雨中出現。"},{"en":"Little by little means gradually, one small step or change at a time.","zh":"little by little 指漸漸地，一次一小步或一點改變。"},{"en":"Little by little, the shy student began speaking more in class.","zh":"一點一點地，那名害羞學生開始在課堂上說更多話。"},{"en":"This phrase slows the action and lets suspense build.","zh":"這個短語放慢動作，讓懸念逐漸建立。"},{"en":"The lion does not appear suddenly; little by little, he becomes visible.","zh":"獅子不是突然出現；牠是一點一點變得可見。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"emerge from","meaning":"從……中出現","examples":[{"en":"A shape emerged from the rain.","zh":"一個身影從雨中出現。"},{"en":"To emerge from something means to come out and become visible from within or behind it.","zh":"emerge from something 指從某物之中或後面出來並變得可見。"},{"en":"A boat emerged from the fog as the sun rose.","zh":"太陽升起時，一艘船從霧中出現。"},{"en":"When something emerges slowly, people may feel suspense or fear.","zh":"當某物慢慢出現時，人們可能感到懸念或恐懼。"},{"en":"Kito emerging from the rain makes him seem like a memory becoming real.","zh":"Kito 從雨中出現，令牠像一段記憶變成真實。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"mane","meaning":"鬃毛","examples":[{"en":"Kito’s mane was dark with water.","zh":"Kito 的鬃毛因沾水而變深色。"},{"en":"A mane is the long thick hair around the head and neck of a male lion.","zh":"mane 指雄獅頭部和頸部周圍又長又厚的毛。"},{"en":"A lion’s mane can make it look larger and more powerful.","zh":"獅子的鬃毛可以令牠看起來更大、更有力量。"},{"en":"When a mane is wet, it may look darker, heavier, and less majestic.","zh":"當鬃毛濕了，它可能看起來更深色、更沉重，也較不威風。"},{"en":"Kito’s wet mane shows he is now an adult lion, not the small cub from the kitchen.","zh":"Kito 濕透的鬃毛顯示牠如今是成年獅子，而不是廚房裏的小幼獅。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"dark with water","meaning":"因沾水而變深色","examples":[{"en":"The mane was dark with water.","zh":"鬃毛因沾水而變深色。"},{"en":"Dark with water means made darker because it is soaked or wet.","zh":"dark with water 指因被水浸濕而變得更深色。"},{"en":"Her hair was dark with water after she ran through the rain.","zh":"她跑過雨中後，頭髮因沾水而變深色。"},{"en":"Wetness changes colour and texture, making things look heavier or colder.","zh":"潮濕會改變顏色和質感，令事物看起來更重或更冷。"},{"en":"Kito’s mane dark with water shows the force of the storm around him.","zh":"Kito 因沾水而變深色的鬃毛，顯示牠周圍暴風雨的力量。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"still searching","meaning":"仍在尋找","examples":[{"en":"Kito’s amber eyes were still searching.","zh":"Kito 的琥珀色眼睛仍在尋找。"},{"en":"Still searching means continuing to look for something, physically or emotionally.","zh":"still searching 指身體上或情感上仍繼續尋找某物。"},{"en":"After the earthquake, families were still searching for missing relatives.","zh":"地震後，家屬仍在尋找失蹤親人。"},{"en":"Eyes can seem to search when someone is confused, frightened, or hoping to recognise safety.","zh":"當人感到困惑、害怕或希望認出安全感時，眼睛會像在尋找。"},{"en":"Kito’s eyes are still searching because he has not fully found safety yet.","zh":"Kito 的眼睛仍在尋找，因為牠尚未完全找到安全。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"limp towards","meaning":"一拐一拐地走向","examples":[{"en":"Kito limped towards me.","zh":"Kito 一拐一拐地走向我。"},{"en":"To limp towards someone means to walk unevenly and with difficulty in that person’s direction.","zh":"limp towards someone 指以不平穩而困難的步伐走向某人。"},{"en":"A football player limped towards the bench after hurting his ankle.","zh":"足球員扭傷腳踝後，一拐一拐地走向後備席。"},{"en":"Limping suggests pain, injury, or weakness.","zh":"一拐一拐地走路暗示疼痛、受傷或虛弱。"},{"en":"Kito limping towards the narrator makes him seem wounded despite his size.","zh":"Kito 一拐一拐地走向敘述者，令牠即使體型龐大也顯得受傷。"}],"source":"2017 Q3.pdf","sourcePage":10},{"front":"warning light","meaning":"警示燈","examples":[{"en":"A red warning light swept across the street.","zh":"一道紅色警示燈掃過街道。"},{"en":"A warning light is a light used to signal danger, emergency, or the need to be careful.","zh":"warning light 指用來提示危險、緊急情況或需要小心的燈光。"},{"en":"Ambulances and police cars use warning lights to tell people to move aside.","zh":"救護車和警車使用警示燈，告訴人們讓路。"},{"en":"A red warning light makes a scene feel urgent and unsafe.","zh":"紅色警示燈令場面感覺迫切而不安全。"},{"en":"In the story, the warning light announces that armed help has arrived.","zh":"在故事中，警示燈宣告武裝支援已經到達。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"sweep across","meaning":"掃過","examples":[{"en":"A red warning light swept across the street.","zh":"一道紅色警示燈掃過街道。"},{"en":"To sweep across means to move quickly and broadly over an area.","zh":"sweep across 指快速而大範圍地移過某個地方。"},{"en":"The searchlight swept across the playground during the rescue operation.","zh":"搜索燈在救援行動中掃過遊樂場。"},{"en":"Light sweeping across a place makes the scene feel active and tense.","zh":"燈光掃過某地，會令場面感覺活躍而緊張。"},{"en":"The warning light sweeping across the street shows the police van is close.","zh":"警示燈掃過街道，顯示警車已經接近。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"police van","meaning":"警車","examples":[{"en":"A police van turned the corner.","zh":"一輛警車轉過街角。"},{"en":"A police van is a larger police vehicle used to carry officers, equipment, or people.","zh":"police van 指較大型、用來載警員、裝備或人員的警用車輛。"},{"en":"A police van may arrive when officers need to control a serious situation.","zh":"當警員需要控制嚴重情況時，警車可能到達。"},{"en":"Seeing a police van can make people feel safer or more frightened, depending on the scene.","zh":"看見警車可以令人感到較安全，也可能令人更害怕，視乎場景而定。"},{"en":"In this moment, the police van brings danger because officers may shoot Kito.","zh":"在這一刻，警車帶來危險，因為警員可能射擊 Kito。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"turn the corner","meaning":"轉過街角","examples":[{"en":"A police van turned the corner.","zh":"一輛警車轉過街角。"},{"en":"To turn the corner means to move around a corner from one street or side into another.","zh":"turn the corner 指從一條街或一邊繞過轉角，進入另一邊。"},{"en":"The bus turned the corner and disappeared behind the shops.","zh":"巴士轉過街角，消失在商店後面。"},{"en":"When a vehicle turns the corner in a story, something new may suddenly enter the scene.","zh":"當故事中的車輛轉過街角時，常表示新事物突然進入場面。"},{"en":"The police van turning the corner makes the danger immediate.","zh":"警車轉過街角，令危險變得迫在眼前。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"a rifle was raised","meaning":"步槍被舉起","examples":[{"en":"A rifle was raised as the lion came closer.","zh":"當獅子走近時，一支步槍被舉起。"},{"en":"A rifle was raised means someone lifted a long gun and prepared to aim or shoot.","zh":"a rifle was raised 指有人舉起長槍，準備瞄準或射擊。"},{"en":"In a dangerous rescue, a weapon may be raised if officers fear an attack.","zh":"在危險救援中，如果人員害怕受到攻擊，武器可能被舉起。"},{"en":"This action creates fear because it suggests violence may happen next.","zh":"這個動作製造恐懼，因為它暗示暴力可能接着發生。"},{"en":"The raised rifle makes the narrator understand that Kito’s life is at risk.","zh":"被舉起的步槍令敘述者明白 Kito 的生命正處於危險中。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"step between","meaning":"站到……之間","examples":[{"en":"I stepped between Kito and the officers.","zh":"我站到 Kito 和人員之間。"},{"en":"To step between two sides means to move into the space separating them, often to stop harm.","zh":"step between two sides 指走到兩方之間的空間，常是為了阻止傷害。"},{"en":"A teacher stepped between two arguing students before the fight began.","zh":"老師在打架開始前站到兩名爭吵學生之間。"},{"en":"Stepping between danger and someone else shows courage, but it can also be risky.","zh":"站到危險和別人之間顯示勇氣，但也可能很冒險。"},{"en":"The narrator steps between Kito and the officers because she wants to protect him.","zh":"敘述者站到 Kito 和人員之間，因為她想保護牠。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"had I known","meaning":"如果我當時知道","examples":[{"en":"Had I known how foolish I looked, I might have lost my courage.","zh":"如果我當時知道自己看起來多愚蠢，我可能已失去勇氣。"},{"en":"Had I known means if I had known, using a more formal or literary sentence pattern.","zh":"had I known 指 if I had known，是較正式或文學化的句式。"},{"en":"Had I known the road was flooded, I would have left earlier.","zh":"如果我當時知道道路水浸，我會早點離開。"},{"en":"This structure is often used to imagine how things might have been different.","zh":"這個結構常用來想像事情本來可能如何不同。"},{"en":"The narrator says this to show she acted before fear had time to stop her.","zh":"敘述者這樣說，是為了顯示她在恐懼有時間阻止她之前已行動。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"face a lion","meaning":"面對一隻獅子","examples":[{"en":"A schoolgirl was facing a lion in a flooded street.","zh":"一名女學生正在水浸街道上面對一隻獅子。"},{"en":"To face a lion means to stand before a lion and deal with the danger or fear directly.","zh":"face a lion 指站在獅子面前，直接面對危險或恐懼。"},{"en":"Few people would remain calm if they had to face a lion without a barrier.","zh":"如果沒有屏障，很少人能在面對一隻獅子時保持冷靜。"},{"en":"Facing a lion is frightening because the animal is powerful and unpredictable.","zh":"面對獅子令人害怕，因為牠強大而難以預測。"},{"en":"The narrator faces Kito not as a stranger, but as someone who once cared for him.","zh":"敘述者面對 Kito 時，不是把牠當陌生者，而是當作自己曾照顧過的生命。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"flooded street","meaning":"水浸街道","examples":[{"en":"The schoolgirl stood in a flooded street.","zh":"那名女學生站在水浸街道上。"},{"en":"A flooded street is a road covered with too much water after heavy rain or storm damage.","zh":"flooded street 指因大雨或風暴破壞而被過多水覆蓋的道路。"},{"en":"Cars moved slowly through the flooded street after the drain became blocked.","zh":"排水渠堵塞後，汽車慢慢駛過水浸街道。"},{"en":"Flooded streets are dangerous because people may slip, fall, or fail to see holes.","zh":"水浸街道很危險，因為人們可能滑倒、跌倒或看不見洞口。"},{"en":"The flooded street makes the scene feel unstable and urgent.","zh":"水浸街道令場面感覺不穩定而迫切。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"lose my courage","meaning":"失去勇氣","examples":[{"en":"I might have lost my courage if I had realised how foolish I looked.","zh":"如果我意識到自己看起來多愚蠢，我可能已失去勇氣。"},{"en":"To lose my courage means to stop feeling brave enough to continue.","zh":"lose my courage 指不再有足夠勇氣繼續。"},{"en":"A student may lose courage before a speech if everyone looks impatient.","zh":"如果所有人都看起來不耐煩，學生可能在演講前失去勇氣。"},{"en":"People can lose courage when they suddenly become aware of danger or embarrassment.","zh":"當人突然意識到危險或尷尬時，可能會失去勇氣。"},{"en":"The narrator keeps her courage because she focuses on Kito, not on herself.","zh":"敘述者保住勇氣，因為她專注於 Kito，而不是自己。"}],"source":"2017 Q3.pdf","sourcePage":11},{"front":"once more","meaning":"再一次","examples":[{"en":"I whistled once more and backed towards our building.","zh":"我再一次吹口哨，並向我們的大廈後退。"},{"en":"Once more means one more time or again.","zh":"once more 指多一次或再次。"},{"en":"The coach asked the team to try the movement once more before resting.","zh":"教練要求隊伍休息前再一次嘗試那個動作。"},{"en":"This phrase often shows persistence when the first attempt is not enough.","zh":"當第一次嘗試不足夠時，這個短語常顯示堅持。"},{"en":"The narrator whistles once more because she hopes the old signal still works.","zh":"敘述者再一次吹口哨，因為她希望舊信號仍然有效。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"back towards","meaning":"向……後退","examples":[{"en":"I backed towards our building while Kito followed.","zh":"我向我們的大廈後退，而 Kito 跟着我。"},{"en":"To back towards something means to move backwards in its direction.","zh":"back towards something 指朝某個方向倒退。"},{"en":"The teacher backed towards the door while watching the frightened dog.","zh":"老師一邊看着受驚的狗，一邊向門口後退。"},{"en":"People back towards safety when they do not want to turn away from danger.","zh":"當人們不想背向危險時，會向安全地方後退。"},{"en":"The narrator backs towards the building so Kito can follow without feeling chased.","zh":"敘述者向大廈後退，好讓 Kito 跟隨而不覺得被追趕。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"not because…, but because…","meaning":"不是因為……而是因為……","examples":[{"en":"Kito followed not because he was tame, but because he remembered safety.","zh":"Kito 跟着我，不是因為牠馴服，而是因為牠記得安全感。"},{"en":"Not because…, but because… explains that the true reason is the second reason, not the first.","zh":"not because…, but because… 解釋真正原因是第二個原因，而不是第一個。"},{"en":"She helped him not because she wanted praise, but because he needed help.","zh":"她幫助他，不是因為想得到稱讚，而是因為他需要幫助。"},{"en":"This pattern corrects a possible misunderstanding.","zh":"這個句式用來修正可能的誤解。"},{"en":"Kito follows not as a pet, but as an animal guided by memory.","zh":"Kito 跟隨的不是寵物身份，而是被記憶引導的動物。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"tame","meaning":"馴服的","examples":[{"en":"Kito followed me, not because he was tame.","zh":"Kito 跟着我，不是因為牠是馴服的。"},{"en":"Tame means used to humans and not wild or dangerous in the usual way.","zh":"tame 指習慣人類，並不像一般野生動物那樣野性或危險。"},{"en":"A tame rabbit may allow children to touch it gently.","zh":"馴服的兔子可能讓孩子輕輕觸摸。"},{"en":"A wild animal can obey a familiar signal without truly being tame.","zh":"野生動物可以回應熟悉信號，但不代表牠真正馴服。"},{"en":"Kito was not tame; he was a lion responding to memory and trust.","zh":"Kito 並不馴服；牠是一隻回應記憶和信任的獅子。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"memory, like hunger","meaning":"記憶像飢餓一樣","examples":[{"en":"Memory, like hunger, can survive almost anything.","zh":"記憶像飢餓一樣，幾乎任何事都能熬過。"},{"en":"Memory, like hunger compares memory to a strong basic need that does not easily disappear.","zh":"memory, like hunger 把記憶比作一種不易消失的強烈基本需要。"},{"en":"Homesickness, like hunger, can return suddenly when a familiar smell appears.","zh":"思鄉像飢餓一樣，可能在熟悉氣味出現時突然回來。"},{"en":"The comparison suggests memory can remain powerful even after years and distance.","zh":"這個比喻暗示，即使經過多年和距離，記憶仍可以很有力量。"},{"en":"Kito’s memory survives because safety left a deep mark on him.","zh":"Kito 的記憶能存活，因為安全感在牠身上留下很深印記。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"survive almost anything","meaning":"幾乎任何事都能熬過","examples":[{"en":"Memory can survive almost anything.","zh":"記憶幾乎任何事都能熬過。"},{"en":"To survive almost anything means to continue existing despite many difficulties, dangers, or changes.","zh":"survive almost anything 指即使經歷許多困難、危險或改變，仍然存在。"},{"en":"A childhood song can survive almost anything and return when someone hears the first note.","zh":"一首童年歌曲幾乎任何事都能熬過，當人聽到第一個音時便會回來。"},{"en":"Strong memories survive because they are connected to fear, love, safety, or loss.","zh":"強烈記憶能存活，因為它們與恐懼、愛、安全或失去相連。"},{"en":"Kito’s memory of the kitchen survived seven years, storms, and separation.","zh":"Kito 對廚房的記憶熬過了七年、暴風雨和分離。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"for once in her life","meaning":"她人生中難得一次","examples":[{"en":"For once in her life, Mum did not ask questions.","zh":"她人生中難得一次，媽媽沒有問問題。"},{"en":"For once in her life means unusually, perhaps for the first rare time, she acted differently from normal.","zh":"for once in her life 指很不尋常地，可能是難得第一次，她做了和平常不同的事。"},{"en":"For once in his life, the noisy boy sat quietly and listened.","zh":"他人生中難得一次，那個吵鬧的男孩安靜坐着聆聽。"},{"en":"This phrase suggests the behaviour is surprising because it is not typical.","zh":"這個短語暗示行為令人意外，因為它不是平常表現。"},{"en":"Mum usually asks questions, so her silence shows how serious the moment is.","zh":"媽媽通常會問問題，所以她的沉默顯示這一刻多嚴重。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"move aside","meaning":"讓開","examples":[{"en":"Mum simply moved aside and let us in.","zh":"媽媽只是讓開，讓我們進來。"},{"en":"To move aside means to step to one side so someone or something can pass.","zh":"move aside 指走到一旁，讓某人或某物通過。"},{"en":"People moved aside to let the ambulance workers enter the building.","zh":"人們讓開，讓救護人員進入大廈。"},{"en":"Moving aside can show permission, acceptance, or quiet understanding.","zh":"讓開可以表示允許、接受或安靜的理解。"},{"en":"Mum moves aside because she understands there is no time for argument.","zh":"媽媽讓開，因為她明白已沒有時間爭論。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"lead someone into","meaning":"帶領某人進入","examples":[{"en":"I led Kito into the kitchen.","zh":"我帶領 Kito 進入廚房。"},{"en":"To lead someone into a place means to guide them there, often by walking ahead or encouraging them to follow.","zh":"lead someone into a place 指引導某人進入某地，通常是走在前面或鼓勵對方跟隨。"},{"en":"A teacher led the new student into the classroom on the first day.","zh":"老師在第一天帶領新學生進入課室。"},{"en":"Leading a frightened animal requires calm movement and trust.","zh":"帶領受驚動物需要冷靜動作和信任。"},{"en":"The narrator leads Kito into the kitchen because it was once his place of safety.","zh":"敘述者帶領 Kito 進入廚房，因為那裏曾是牠感到安全的地方。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"drip from","meaning":"從……滴下","examples":[{"en":"Water dripped from Kito’s mane onto the tiles.","zh":"水從 Kito 的鬃毛滴到瓷磚上。"},{"en":"To drip from something means to fall in small drops from it.","zh":"drip from something 指以小水滴形式從某物落下。"},{"en":"Rainwater dripped from the umbrella onto the floor.","zh":"雨水從雨傘滴到地板上。"},{"en":"Dripping water shows that something is soaked and still wet.","zh":"滴水顯示某物濕透並仍然帶水。"},{"en":"Water dripping from Kito’s mane brings the storm into the quiet kitchen.","zh":"水從 Kito 的鬃毛滴下，把暴風雨帶進安靜的廚房。"}],"source":"2017 Q3.pdf","sourcePage":12},{"front":"onto the tiles","meaning":"滴到瓷磚上","examples":[{"en":"Water dripped onto the kitchen tiles.","zh":"水滴到廚房的瓷磚上。"},{"en":"Onto the tiles means down onto the hard flat pieces covering the floor or wall.","zh":"onto the tiles 指落到覆蓋地板或牆身的堅硬平面瓷磚上。"},{"en":"The child spilled soup onto the kitchen tiles.","zh":"孩子把湯灑到廚房瓷磚上。"},{"en":"Tiles are easy to clean, so they are common in kitchens and bathrooms.","zh":"瓷磚容易清潔，所以常見於廚房和浴室。"},{"en":"Water on the tiles makes the kitchen scene feel real, cold, and messy.","zh":"瓷磚上的水令廚房場景感覺真實、寒冷而凌亂。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"with shaking hands","meaning":"用發抖的手","examples":[{"en":"I opened the fridge with shaking hands.","zh":"我用發抖的手打開雪櫃。"},{"en":"With shaking hands means while one’s hands tremble because of fear, cold, shock, or emotion.","zh":"with shaking hands 指因恐懼、寒冷、震驚或情緒而雙手顫抖。"},{"en":"The student held the speech paper with shaking hands before going on stage.","zh":"學生上台前用發抖的手拿着演講稿。"},{"en":"Shaking hands show that the body is reacting even if the person keeps acting bravely.","zh":"發抖的手顯示即使人仍勇敢行動，身體已在反應。"},{"en":"The narrator’s shaking hands reveal fear, but she still tries to help Kito.","zh":"敘述者發抖的手透露恐懼，但她仍嘗試幫助 Kito。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"tray of meat","meaning":"一盤肉","examples":[{"en":"I grabbed a tray of meat from the fridge.","zh":"我從雪櫃抓起一盤肉。"},{"en":"A tray of meat is a flat container holding pieces of meat.","zh":"tray of meat 指盛着肉塊的平盤或托盤。"},{"en":"A cook may take a tray of meat from the fridge before preparing dinner.","zh":"廚師準備晚餐前，可能從雪櫃拿出一盤肉。"},{"en":"Meat is offered to Kito because a lion is a carnivore and needs animal food.","zh":"給 Kito 肉，是因為獅子是食肉動物，需要動物性食物。"},{"en":"The tray of meat becomes a practical way to calm and feed the frightened lion.","zh":"這盤肉成為安撫和餵飽受驚獅子的實際方法。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"set the bowl on","meaning":"把碗放在……上","examples":[{"en":"I set the old feeding bowl on the table.","zh":"我把舊餵食碗放在桌上。"},{"en":"To set the bowl on something means to place the bowl carefully on that surface.","zh":"set the bowl on something 指把碗小心放在某個表面上。"},{"en":"She set the soup bowl on the table before calling everyone to dinner.","zh":"她把湯碗放在桌上，然後叫大家吃晚飯。"},{"en":"Placing an old object in the same setting can bring back memory.","zh":"把舊物件放回相似場景，可以喚起記憶。"},{"en":"Setting Kito’s bowl on the table turns the kitchen into a remembered safe place.","zh":"把 Kito 的碗放在桌上，令廚房變回牠記憶中的安全地方。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"only then did I understand","meaning":"直到那時我才明白","examples":[{"en":"Only then did I understand what Father meant.","zh":"直到那時我才明白爸爸的意思。"},{"en":"Only then did I understand means I did not understand until that exact moment.","zh":"only then did I understand 指我直到那一刻才真正明白。"},{"en":"Only then did the student understand why the teacher had insisted on practice.","zh":"直到那時，學生才明白老師為何堅持練習。"},{"en":"This structure emphasises a sudden moment of realisation.","zh":"這個結構強調突然明白的一刻。"},{"en":"The narrator finally understands that care for wildlife must lead back to freedom.","zh":"敘述者終於明白，照顧野生動物必須帶牠回到自由。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"bring wildlife home","meaning":"把野生動物帶回家","examples":[{"en":"I had not brought wildlife home to possess it.","zh":"我不是為了佔有野生動物而把牠帶回家。"},{"en":"To bring wildlife home means to take a wild animal into a human home.","zh":"bring wildlife home 指把野生動物帶進人類家中。"},{"en":"People should not bring wildlife home unless trained rescuers say it is necessary.","zh":"除非受訓救援人員認為有必要，否則人們不應把野生動物帶回家。"},{"en":"Bringing wildlife home can be dangerous because wild animals need special care and space.","zh":"把野生動物帶回家可能危險，因為野生動物需要特別照顧和空間。"},{"en":"In Kito’s case, bringing wildlife home was about temporary rescue, not ownership.","zh":"在 Kito 的情況中，把野生動物帶回家是臨時救助，而不是擁有。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"possess","meaning":"佔有","examples":[{"en":"I did not bring Kito home to possess him.","zh":"我不是為了佔有 Kito 而把牠帶回家。"},{"en":"To possess means to own, control, or keep something as yours.","zh":"possess 指擁有、控制或把某物當作自己的東西留下。"},{"en":"A person may possess a book, but they should not possess another living being’s freedom.","zh":"人可以擁有一本書，但不應佔有另一個生命的自由。"},{"en":"Possessing something gives power, so it must be used responsibly.","zh":"佔有某物帶來權力，所以必須負責任地使用。"},{"en":"The narrator learns that loving Kito does not mean possessing him.","zh":"敘述者學會，愛 Kito 不等於佔有牠。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"protect it","meaning":"保護它","examples":[{"en":"I brought Kito home to protect him.","zh":"我把 Kito 帶回家，是為了保護牠。"},{"en":"To protect it means to keep it safe from harm, danger, or suffering.","zh":"protect it 指讓它免受傷害、危險或痛苦。"},{"en":"A rescue worker may protect an injured bird by keeping it warm and away from cats.","zh":"救援人員可能透過保暖和遠離貓隻來保護受傷小鳥。"},{"en":"Protection is different from possession because the goal is the other being’s safety.","zh":"保護不同於佔有，因為目標是對方的安全。"},{"en":"The narrator protected Kito until he could return to a better place.","zh":"敘述者保護 Kito，直到牠能回到更合適的地方。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"until it could be free again","meaning":"直到它能再次自由","examples":[{"en":"I protected Kito until he could be free again.","zh":"我保護 Kito，直到牠能再次自由。"},{"en":"Until it could be free again means up to the point when it could return to freedom or a more natural life.","zh":"until it could be free again 指直到它能回到自由或較自然生活的時候。"},{"en":"A rescued turtle may stay in care until it can be free again in the sea.","zh":"獲救海龜可能留在照顧中心，直到牠能再次在海中自由生活。"},{"en":"Temporary protection is successful when it leads back to independence.","zh":"臨時保護如果能帶回獨立，就算成功。"},{"en":"This phrase shows that the purpose of care is release, not keeping.","zh":"這個短語顯示照顧的目的，是釋放而不是留下。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"gasp","meaning":"倒抽一口氣","examples":[{"en":"Mum gasped when Kito rose beside the fridge.","zh":"當 Kito 在雪櫃旁站起來時，媽媽倒抽一口氣。"},{"en":"To gasp means to breathe in suddenly because of shock, fear, pain, or surprise.","zh":"gasp 指因震驚、恐懼、痛楚或驚訝而突然吸一口氣。"},{"en":"The class gasped when the magician made the coin disappear.","zh":"魔術師令硬幣消失時，全班倒抽一口氣。"},{"en":"A gasp is a quick body reaction before someone has time to speak.","zh":"倒抽一口氣是人在有時間說話前的快速身體反應。"},{"en":"Mum gasps because seeing a lion rise in the kitchen is terrifying and unbelievable.","zh":"媽媽倒抽一口氣，因為看見獅子在廚房站起來既可怕又難以置信。"}],"source":"2017 Q3.pdf","sourcePage":13},{"front":"rise slowly","meaning":"慢慢站起來","examples":[{"en":"Kito rose slowly beside the table.","zh":"Kito 在桌旁慢慢站起來。"},{"en":"To rise slowly means to stand up or lift upward gradually.","zh":"rise slowly 指逐漸站起或向上升起。"},{"en":"The injured man rose slowly from the chair after resting.","zh":"受傷的男人休息後，從椅子上慢慢站起來。"},{"en":"Rising slowly can show weakness, caution, or great size.","zh":"慢慢站起來可以顯示虛弱、小心或龐大體型。"},{"en":"Kito rises slowly because he is tired, wet, and still uncertain.","zh":"Kito 慢慢站起來，因為牠疲倦、濕透，仍然不確定。"}],"source":"2017 Q3.pdf","sourcePage":14},{"front":"front paws","meaning":"前爪","examples":[{"en":"Kito placed his two front paws on the kitchen table.","zh":"Kito 把兩隻前爪放在廚房桌上。"},{"en":"Front paws are the two front feet of an animal such as a lion, dog, or cat.","zh":"front paws 指獅子、狗或貓等動物前面的兩隻腳爪。"},{"en":"A dog may put its front paws on a chair to look at the food.","zh":"狗可能把前爪放在椅子上，看着食物。"},{"en":"When a large animal raises its front paws, it may suddenly seem much bigger.","zh":"當大型動物抬起前爪時，牠可能突然顯得更巨大。"},{"en":"Kito’s front paws on the table show both his strength and his memory of feeding.","zh":"Kito 的前爪放在桌上，顯示牠的力量，也顯示牠對餵食的記憶。"}],"source":"2017 Q3.pdf","sourcePage":14},{"front":"beside the open fridge","meaning":"在打開的雪櫃旁","examples":[{"en":"Kito stood beside the open fridge.","zh":"Kito 站在打開的雪櫃旁。"},{"en":"Beside the open fridge means next to the refrigerator while its door is open.","zh":"beside the open fridge 指在雪櫃門打開時站在它旁邊。"},{"en":"A child stood beside the open fridge, looking for a midnight snack.","zh":"孩子站在打開的雪櫃旁，尋找宵夜。"},{"en":"An open fridge suggests hurry because someone has not taken time to close it.","zh":"打開的雪櫃暗示匆忙，因為有人沒有時間把它關上。"},{"en":"Kito beside the open fridge creates a strange mix of ordinary home life and wild danger.","zh":"Kito 站在打開的雪櫃旁，形成普通家庭生活與野性危險的奇怪混合。"}],"source":"2017 Q3.pdf","sourcePage":14},{"front":"lower his golden head","meaning":"低下金色的頭","examples":[{"en":"Kito lowered his golden head towards the bowl.","zh":"Kito 向着那隻碗低下金色的頭。"},{"en":"To lower his golden head means to move his yellow-gold head downward.","zh":"lower his golden head 指把他金黃色的頭向下移。"},{"en":"A horse lowered its head toward the bucket of water.","zh":"一匹馬向水桶低下頭。"},{"en":"Lowering the head can show hunger, tiredness, trust, or calmness.","zh":"低下頭可以顯示飢餓、疲倦、信任或平靜。"},{"en":"Kito lowering his head to the bowl shows that memory has guided him back to safety.","zh":"Kito 向碗低下頭，顯示記憶把牠帶回安全感。"}],"source":"2017 Q3.pdf","sourcePage":14},{"front":"towards the bowl","meaning":"向着那隻碗","examples":[{"en":"Kito lowered his head towards the bowl.","zh":"Kito 向着那隻碗低下頭。"},{"en":"Towards the bowl means in the direction of the bowl.","zh":"towards the bowl 指朝着那隻碗的方向。"},{"en":"The cat walked towards the bowl when it smelled dinner.","zh":"貓聞到晚餐氣味時，走向那隻碗。"},{"en":"Moving towards a familiar object can show recognition and trust.","zh":"走向熟悉物件可以顯示認出和信任。"},{"en":"Kito’s movement towards the bowl connects the adult lion to the cub who once drank there.","zh":"Kito 向着那隻碗的動作，把成年獅子與曾經在那裏喝奶的幼獅連接起來。"}],"source":"2017 Q3.pdf","sourcePage":14}],"dse/writing/part-b/2017/Q4":[{"front":"more than moonlight","meaning":"不只是月光；不只是浪漫","examples":[{"en":"A marriage needs more than moonlight and romance.","zh":"婚姻需要的不只是月光和浪漫。"},{"en":"More than moonlight means more than beautiful feelings, sweet words, or romantic moments.","zh":"more than moonlight 指不只是美好感覺、甜言蜜語或浪漫時刻。"},{"en":"A couple may enjoy moonlight walks, but they also need trust when life becomes hard.","zh":"一對伴侶可以享受月下散步，但生活變困難時，他們也需要信任。"},{"en":"Romance alone cannot pay bills, solve arguments, or care for children.","zh":"單靠浪漫不能支付帳單、解決爭執或照顧孩子。"},{"en":"This phrase reminds us that marriage needs practical love as well as poetic love.","zh":"這個片語提醒我們，婚姻需要實際的愛，也需要詩意的愛。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"famous declaration","meaning":"著名宣言","examples":[{"en":"Romeo’s famous declaration presents love as sudden and sacred.","zh":"羅密歐的著名宣言把愛呈現為突然而神聖。"},{"en":"A famous declaration is a well-known statement made strongly and openly.","zh":"famous declaration 指廣為人知、強烈而公開的聲明。"},{"en":"In a play, a famous declaration of love may be remembered by many audiences.","zh":"在戲劇中，著名的愛情宣言可能被許多觀眾記住。"},{"en":"A declaration becomes famous when people repeat it across generations.","zh":"當一個宣言被一代又一代人重複，它就會變得著名。"},{"en":"Romeo’s famous declaration is powerful, but it does not prove that passion is enough for marriage.","zh":"羅密歐的著名宣言很有力量，但它不能證明激情足以支撐婚姻。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"romantic love","meaning":"浪漫愛情","examples":[{"en":"Romantic love is often presented as the foundation of marriage.","zh":"浪漫愛情常被呈現為婚姻的基礎。"},{"en":"Romantic love is love filled with attraction, emotion, idealism, and personal desire.","zh":"romantic love 指充滿吸引、情感、理想化和個人渴望的愛。"},{"en":"Many films show romantic love through music, flowers, and sudden confessions.","zh":"許多電影透過音樂、鮮花和突然表白來呈現浪漫愛情。"},{"en":"Romantic love can bring two people together, but it may not teach them how to live together.","zh":"浪漫愛情可以把兩個人帶到一起，但未必教會他們如何一起生活。"},{"en":"A happy marriage may include romantic love, but it also needs trust and responsibility.","zh":"幸福婚姻可以包含浪漫愛情，但也需要信任和責任。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"be presented in drama as","meaning":"在戲劇中被呈現為","examples":[{"en":"Romantic love is often presented in drama as sudden and dazzling.","zh":"浪漫愛情在戲劇中常被呈現為突然而耀眼。"},{"en":"Be presented in drama as means be shown or described in plays in a particular way.","zh":"be presented in drama as 指在戲劇中以某種方式被展示或描寫。"},{"en":"Heroes are often presented in drama as brave people who make difficult choices.","zh":"英雄在戲劇中常被呈現為作出艱難選擇的勇敢人物。"},{"en":"When love is presented in drama as perfect, students should still ask whether it is realistic.","zh":"當愛情在戲劇中被呈現為完美時，學生仍應思考它是否現實。"},{"en":"In Romeo and Juliet, love is presented in drama as intense, beautiful, and dangerous.","zh":"在《羅密歐與茱麗葉》中，愛情在戲劇中被呈現為強烈、美麗而危險。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"sudden, dazzling and almost sacred","meaning":"突然、耀眼而近乎神聖","examples":[{"en":"Romantic love is often shown as sudden, dazzling and almost sacred.","zh":"浪漫愛情常被展示為突然、耀眼而近乎神聖。"},{"en":"Sudden, dazzling and almost sacred means love appears quickly, feels brilliant, and seems holy or untouchable.","zh":"sudden, dazzling and almost sacred 指愛情出現得很快、感覺燦爛，並像神聖不可碰觸。"},{"en":"A first meeting in a play may feel sudden and dazzling because everything changes at once.","zh":"戲劇中的第一次相遇可能顯得突然而耀眼，因為一切立刻改變。"},{"en":"When love is treated as almost sacred, people may stop questioning it carefully.","zh":"當愛情被視為近乎神聖，人們可能會停止仔細質疑它。"},{"en":"Such love is exciting, but marriage needs steadier qualities too.","zh":"這種愛令人心動，但婚姻也需要更穩定的特質。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"drama lessons","meaning":"戲劇課","examples":[{"en":"Students discussed romantic love in their drama lessons.","zh":"學生在戲劇課中討論浪漫愛情。"},{"en":"Drama lessons are classes where students study plays, performance, characters, and themes.","zh":"drama lessons 是學生學習劇本、表演、人物和主題的課堂。"},{"en":"In drama lessons, students may act out a scene to understand a character’s feelings.","zh":"在戲劇課中，學生可能會演出一幕，以理解角色的感受。"},{"en":"Drama lessons help students see how love, conflict, and choice are presented on stage.","zh":"戲劇課幫助學生看見愛、衝突和選擇如何在舞台上呈現。"},{"en":"Discussing marriage in drama lessons can connect literature with real-life questions.","zh":"在戲劇課討論婚姻，可以把文學連接到現實生活問題。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"consider whether","meaning":"思考是否","examples":[{"en":"Students considered whether passionate attraction should be the foundation of marriage.","zh":"學生思考熱烈的吸引是否應成為婚姻的基礎。"},{"en":"Consider whether means think carefully about whether something is true, right, or suitable.","zh":"consider whether 指仔細思考某事是否真實、正確或合適。"},{"en":"Before choosing a subject, students should consider whether it matches their interests.","zh":"選科前，學生應思考是否符合自己的興趣。"},{"en":"Couples should consider whether love alone is enough before making serious promises.","zh":"伴侶作出嚴肅承諾前，應思考單靠愛是否足夠。"},{"en":"This phrase shows careful thinking rather than a quick answer.","zh":"這個片語顯示仔細思考，而不是匆忙回答。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"passionate attraction","meaning":"熱烈的吸引","examples":[{"en":"Passionate attraction alone cannot guarantee a happy marriage.","zh":"單靠熱烈的吸引不能保證幸福婚姻。"},{"en":"Passionate attraction is a strong emotional and physical pull towards another person.","zh":"passionate attraction 指對另一個人有強烈的情感和身體吸引。"},{"en":"Passionate attraction may make two people want to spend every moment together.","zh":"熱烈的吸引可能令兩個人想每一刻都在一起。"},{"en":"If passionate attraction fades, a couple needs trust and respect to continue.","zh":"如果熱烈的吸引淡去，伴侶需要信任和尊重去繼續。"},{"en":"Passionate attraction can begin a relationship, but it should not be the only support.","zh":"熱烈的吸引可以開始一段關係，但不應成為唯一支撐。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"be treated as","meaning":"被視為","examples":[{"en":"Passionate attraction should not be treated as the only foundation of marriage.","zh":"熱烈的吸引不應被視為婚姻的唯一基礎。"},{"en":"Be treated as means be regarded or handled as a particular thing.","zh":"be treated as 指被看作或處理為某種東西。"},{"en":"A student’s mistake should be treated as a chance to learn, not as a failure.","zh":"學生的錯誤應被視為學習機會，而不是失敗。"},{"en":"If romance is treated as everything, practical problems may be ignored.","zh":"如果浪漫被視為一切，實際問題可能會被忽略。"},{"en":"Passion should be treated as important, but not as the whole meaning of marriage.","zh":"激情應被視為重要，但不應被視為婚姻的全部意義。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"the foundation of marriage","meaning":"婚姻的基礎","examples":[{"en":"Trust may be a stronger foundation of marriage than romance.","zh":"信任可能比浪漫更能成為婚姻的基礎。"},{"en":"The foundation of marriage means the basic support that keeps a marriage strong.","zh":"the foundation of marriage 指支撐婚姻穩固的基本力量。"},{"en":"Honesty can be part of the foundation of marriage because couples must rely on each other.","zh":"誠實可以成為婚姻基礎的一部分，因為夫妻必須依靠彼此。"},{"en":"If the foundation of marriage is weak, small problems can become serious conflicts.","zh":"如果婚姻的基礎薄弱，小問題也可能變成嚴重衝突。"},{"en":"Romance may decorate marriage, but trust often forms its foundation.","zh":"浪漫可以裝飾婚姻，但信任往往構成它的基礎。"}],"source":"2017 Q4.pdf","sourcePage":1},{"front":"secure lasting happiness","meaning":"確保持久幸福","examples":[{"en":"A couple cannot secure lasting happiness through passion alone.","zh":"一對伴侶不能單靠激情確保持久幸福。"},{"en":"To secure lasting happiness means to make long-term happiness more certain or stable.","zh":"secure lasting happiness 指令長久幸福更確定或更穩定。"},{"en":"Money alone cannot secure lasting happiness if a family lacks respect.","zh":"如果家庭缺乏尊重，單靠金錢不能確保持久幸福。"},{"en":"Couples secure lasting happiness by solving problems together over time.","zh":"伴侶透過長期一起解決問題來確保持久幸福。"},{"en":"Passion may bring joy, but character helps secure lasting happiness.","zh":"激情可以帶來快樂，但品格有助確保持久幸福。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, romantic love is desirable but not essential.","zh":"就我而言，浪漫愛情值得擁有，但並非必不可少。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"as far as I am concerned 指在我看來或從我的角度而言。"},{"en":"As far as I am concerned, honesty matters more than popularity.","zh":"就我而言，誠實比受歡迎更重要。"},{"en":"This phrase is useful in essays because it introduces a clear personal position.","zh":"這個片語在作文中很有用，因為它引出清楚的個人立場。"},{"en":"The writer uses it to give a balanced view of romantic love.","zh":"作者用它來表達對浪漫愛情的平衡看法。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"be desirable","meaning":"值得擁有；令人嚮往","examples":[{"en":"Romantic love is desirable in marriage.","zh":"浪漫愛情在婚姻中值得擁有。"},{"en":"Be desirable means be wanted, attractive, or worth having.","zh":"be desirable 指令人想要、有吸引力或值得擁有。"},{"en":"A quiet study space is desirable for students preparing for exams.","zh":"對準備考試的學生來說，安靜的溫習空間令人嚮往。"},{"en":"Romantic love is desirable because it can make marriage warmer and more joyful.","zh":"浪漫愛情值得擁有，因為它能令婚姻更溫暖、更快樂。"},{"en":"Something desirable can be valuable without being absolutely necessary.","zh":"值得擁有的東西可以很有價值，但未必絕對必要。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"strictly necessary for","meaning":"對……來說絕對必要","examples":[{"en":"Romantic love is not strictly necessary for a happy marriage.","zh":"浪漫愛情對幸福婚姻來說並非絕對必要。"},{"en":"Strictly necessary for means absolutely needed for something to happen or succeed.","zh":"strictly necessary for 指某事要發生或成功時絕對需要。"},{"en":"A uniform may be required, but an expensive bag is not strictly necessary for school.","zh":"校服可能是必需的，但昂貴書包對上學來說並非絕對必要。"},{"en":"Passion is pleasant, but it may not be strictly necessary for marital happiness.","zh":"激情令人愉快，但對婚姻幸福來說未必絕對必要。"},{"en":"Trust and kindness are more necessary than constant romantic excitement.","zh":"信任和善良比持續浪漫刺激更必要。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"depend less on...than on...","meaning":"與其依靠……不如依靠……","examples":[{"en":"A happy marriage depends less on passion than on trust.","zh":"幸福婚姻與其依靠激情，不如依靠信任。"},{"en":"Depend less on A than on B means B is more important than A.","zh":"depend less on A than on B 指 B 比 A 更重要。"},{"en":"Exam success depends less on luck than on steady preparation.","zh":"考試成功與其依靠運氣，不如依靠穩定準備。"},{"en":"A friendship depends less on gifts than on loyalty and care.","zh":"友誼與其依靠禮物，不如依靠忠誠和關心。"},{"en":"Marriage may begin with passion, but it depends more deeply on trust.","zh":"婚姻可能由激情開始，但更深層地依靠信任。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"thunderbolt emotion","meaning":"霹靂般的強烈情感","examples":[{"en":"A marriage needs more than thunderbolt emotion.","zh":"婚姻需要的不只是霹靂般的強烈情感。"},{"en":"Thunderbolt emotion means a sudden, powerful feeling that arrives like lightning.","zh":"thunderbolt emotion 指像閃電一樣突然又強烈的感覺。"},{"en":"Falling in love at first sight may feel like thunderbolt emotion.","zh":"一見鍾情可能感覺像霹靂般的強烈情感。"},{"en":"Thunderbolt emotion can be exciting, but it may not last through ordinary difficulties.","zh":"霹靂般的強烈情感令人興奮，但未必能維持到普通困難之中。"},{"en":"A marriage needs steady care after the first thunderbolt fades.","zh":"最初的強烈情感淡去後，婚姻需要穩定照顧。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"trust, character and communication","meaning":"信任、品格和溝通","examples":[{"en":"A happy marriage depends on trust, character and communication.","zh":"幸福婚姻依靠信任、品格和溝通。"},{"en":"Trust, character and communication mean believing each other, having good values, and speaking honestly.","zh":"trust, character and communication 指相信彼此、擁有良好價值觀，並誠實說話。"},{"en":"A couple uses communication when they discuss money instead of hiding problems.","zh":"伴侶討論金錢而不是隱瞞問題時，就是在溝通。"},{"en":"Good character matters because partners must act fairly when nobody is watching.","zh":"品格重要，因為伴侶即使無人監察，也必須公平行事。"},{"en":"These qualities make marriage safer than passion alone can.","zh":"這些特質令婚姻比單靠激情更安全。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"the willingness to","meaning":"願意去……","examples":[{"en":"Marriage requires the willingness to choose one another.","zh":"婚姻需要願意彼此選擇。"},{"en":"The willingness to means being ready and prepared to do something.","zh":"the willingness to 指準備好並願意做某事。"},{"en":"Friendship requires the willingness to listen when someone is upset.","zh":"友誼需要願意在對方難過時聆聽。"},{"en":"A marriage grows stronger when both people have the willingness to apologise.","zh":"當雙方都願意道歉，婚姻會變得更穩固。"},{"en":"Love becomes practical when willingness turns into repeated action.","zh":"當意願變成反覆行動，愛就變得實際。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"choose one another","meaning":"彼此選擇；互相堅守","examples":[{"en":"A happy couple must choose one another again and again.","zh":"幸福伴侶必須一次又一次彼此選擇。"},{"en":"Choose one another means continue to support, value, and stay loyal to each other.","zh":"choose one another 指繼續支持、珍視並忠於彼此。"},{"en":"Couples choose one another when they solve problems instead of walking away immediately.","zh":"伴侶選擇解決問題，而不是立刻離開時，就是在彼此堅守。"},{"en":"Choosing one another again and again turns emotion into commitment.","zh":"一次又一次彼此選擇，會把情感變成承諾。"},{"en":"Marriage lasts when love becomes a daily choice, not just a feeling.","zh":"當愛成為每日選擇，而不只是感覺，婚姻才會持久。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"first of all","meaning":"首先","examples":[{"en":"First of all, romantic love is too unstable to guarantee happiness.","zh":"首先，浪漫愛情太不穩定，不能保證幸福。"},{"en":"First of all introduces the first reason or point in an argument.","zh":"first of all 用來引出論點中的第一個原因或重點。"},{"en":"First of all, students need enough sleep before they can study well.","zh":"首先，學生需要足夠睡眠，才能好好學習。"},{"en":"This phrase helps organise an essay clearly for the reader.","zh":"這個片語幫助作文清楚組織，方便讀者理解。"},{"en":"The writer uses first of all to begin the argument against passion alone.","zh":"作者用 first of all 開始反駁單靠激情的論點。"}],"source":"2017 Q4.pdf","sourcePage":2},{"front":"too unstable to","meaning":"太不穩定以致不能","examples":[{"en":"Romantic love is too unstable to be the only condition for marital happiness.","zh":"浪漫愛情太不穩定，不能成為婚姻幸福的唯一條件。"},{"en":"Too unstable to means not steady enough to do or support something.","zh":"too unstable to 指不夠穩定，不能做或支撐某事。"},{"en":"A broken chair is too unstable to sit on safely.","zh":"壞掉的椅子太不穩定，不能安全坐上去。"},{"en":"A plan based only on strong feelings may be too unstable to last.","zh":"只建基於強烈感覺的計劃，可能太不穩定而不能持久。"},{"en":"Romantic love can change quickly, so it is too unstable to carry marriage alone.","zh":"浪漫愛情可以快速改變，所以太不穩定，不能獨自承托婚姻。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"the only necessary condition","meaning":"唯一必要條件","examples":[{"en":"Romantic love is not the only necessary condition for a happy marriage.","zh":"浪漫愛情不是幸福婚姻的唯一必要條件。"},{"en":"The only necessary condition means the one thing that must be present for success.","zh":"the only necessary condition 指成功必須具備的唯一一項條件。"},{"en":"Hard work is important, but it is not the only necessary condition for good exam results.","zh":"努力很重要，但不是取得好成績的唯一必要條件。"},{"en":"A happy marriage needs several conditions, including trust, patience, and communication.","zh":"幸福婚姻需要幾項條件，包括信任、耐性和溝通。"},{"en":"The phrase helps argue against making romance the single requirement.","zh":"這個片語有助反駁把浪漫視為唯一要求的看法。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"marital happiness","meaning":"婚姻幸福","examples":[{"en":"Trust and communication are important for marital happiness.","zh":"信任和溝通對婚姻幸福很重要。"},{"en":"Marital happiness means happiness within marriage between partners.","zh":"marital happiness 指伴侶在婚姻中的幸福。"},{"en":"Marital happiness grows when both people feel respected at home.","zh":"當雙方在家中感到被尊重，婚姻幸福就會增長。"},{"en":"Poor communication can damage marital happiness even if passion remains.","zh":"即使激情仍在，溝通不良也會傷害婚姻幸福。"},{"en":"A couple builds marital happiness through daily care, not one romantic moment.","zh":"伴侶透過每日關心建立婚姻幸福，而不是靠一個浪漫時刻。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"magnify the beloved","meaning":"美化所愛的人","examples":[{"en":"Romance often magnifies the beloved.","zh":"浪漫常常美化所愛的人。"},{"en":"To magnify the beloved means to make the person one loves seem greater, better, or more perfect than they are.","zh":"magnify the beloved 指把自己所愛的人看得比實際更偉大、更好或更完美。"},{"en":"In early love, a small kindness may magnify the beloved into a hero.","zh":"在戀愛初期，一個小小善意可能令人把所愛的人美化成英雄。"},{"en":"Magnifying the beloved can make people ignore faults and warning signs.","zh":"美化所愛的人可能令人忽略缺點和警號。"},{"en":"Romance becomes risky when admiration turns into blindness.","zh":"當欣賞變成盲目，浪漫就會變得危險。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"a smile becomes a promise","meaning":"一個微笑變成承諾","examples":[{"en":"In romance, a smile can become a promise.","zh":"在浪漫中，一個微笑可以變成承諾。"},{"en":"A smile becomes a promise means a small gesture is imagined as a serious sign of future love.","zh":"a smile becomes a promise 指一個小動作被想像成未來愛情的嚴肅訊號。"},{"en":"A teenager may think a smile means more than it really does.","zh":"青少年可能以為一個微笑代表的意思比實際更多。"},{"en":"Strong feelings can turn ordinary actions into imagined commitments.","zh":"強烈感情可以把普通行動變成想像中的承諾。"},{"en":"This phrase shows how romance can make people read too much into small signs.","zh":"這個片語顯示浪漫如何令人過度解讀小小訊號。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"a glance becomes destiny","meaning":"一眼變成命運","examples":[{"en":"In romance, a glance can seem like destiny.","zh":"在浪漫中，一眼可以看似命運。"},{"en":"A glance becomes destiny means a brief look is treated as if it has decided the future.","zh":"a glance becomes destiny 指短短一眼被視為好像已決定未來。"},{"en":"In films, two characters may meet eyes and believe their lives have changed forever.","zh":"在電影中，兩個角色可能對望一眼，就相信人生永遠改變。"},{"en":"Such thinking is exciting, but it may make people ignore practical reality.","zh":"這種想法令人興奮，但可能令人忽略實際現實。"},{"en":"Marriage needs more than a glance that feels like fate.","zh":"婚姻需要的不只是一眼之間像命運的感覺。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"be explained away","meaning":"被輕易合理化","examples":[{"en":"A disagreement is easily explained away during early romance.","zh":"在戀愛初期，分歧很容易被輕易合理化。"},{"en":"Be explained away means be dismissed or excused so that it seems unimportant.","zh":"be explained away 指被用理由淡化或辯解成不重要。"},{"en":"A student may explain away a bad habit by saying it only happens once.","zh":"學生可能說壞習慣只發生一次，藉此把它合理化。"},{"en":"In early love, people may explain away selfish behaviour because they want to believe the best.","zh":"在戀愛初期，人們可能因想相信對方最好的一面，而合理化自私行為。"},{"en":"Problems that are explained away can return later in marriage.","zh":"被輕易合理化的問題，日後可能在婚姻中再次出現。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"enchantment","meaning":"迷戀；着迷","examples":[{"en":"This enchantment can draw two people closer.","zh":"這種迷戀可以拉近兩人的距離。"},{"en":"Enchantment is a feeling of being delighted, charmed, or almost magically attracted.","zh":"enchantment 指被吸引、着迷，甚至像受魔法吸引的感覺。"},{"en":"A beautiful song may create enchantment in a quiet theatre.","zh":"一首美麗的歌可以在安靜劇院中創造迷人感覺。"},{"en":"Enchantment can make early romance feel special and unforgettable.","zh":"迷戀可以令初期浪漫感覺特別而難忘。"},{"en":"However, enchantment alone cannot solve the ordinary problems of married life.","zh":"然而，單靠迷戀不能解決婚姻生活中的日常問題。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"draw two people closer","meaning":"拉近兩人的距離","examples":[{"en":"Romance can draw two people closer.","zh":"浪漫可以拉近兩人的距離。"},{"en":"To draw two people closer means to make them feel more connected or intimate.","zh":"draw two people closer 指令人們感覺更有連繫或更親密。"},{"en":"Sharing a difficult experience can draw two friends closer.","zh":"共同經歷困難可以拉近兩個朋友的距離。"},{"en":"Kind words after an argument can draw a couple closer again.","zh":"爭執後一句溫柔說話可以再次拉近伴侶的距離。"},{"en":"Romance draws people closer at first, but trust keeps them close over time.","zh":"浪漫起初拉近人們，但信任讓他們長久靠近。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"give someone the courage to begin","meaning":"給某人開始的勇氣","examples":[{"en":"Romance can give two people the courage to begin.","zh":"浪漫可以給兩個人開始的勇氣。"},{"en":"To give someone the courage to begin means to help someone feel brave enough to start something.","zh":"give someone the courage to begin 指幫助某人有足夠勇氣開始某事。"},{"en":"A teacher’s encouragement can give a shy student the courage to begin writing.","zh":"老師的鼓勵可以給害羞學生開始寫作的勇氣。"},{"en":"Love may give a couple the courage to begin a shared life.","zh":"愛可以給伴侶開始共同生活的勇氣。"},{"en":"Beginning is important, but marriage also needs courage to continue.","zh":"開始很重要，但婚姻也需要繼續下去的勇氣。"}],"source":"2017 Q4.pdf","sourcePage":3},{"front":"the very intensity that","meaning":"正是那種……的強烈程度","examples":[{"en":"The very intensity that makes romance thrilling can weaken judgement.","zh":"正是那種令浪漫令人心跳的強烈程度，可能會削弱判斷力。"},{"en":"The very intensity that means exactly the same strong feeling that causes one result also causes another.","zh":"the very intensity that 指正是造成一種結果的強烈感覺，也會造成另一種結果。"},{"en":"The very excitement that helps a student speak may also make her nervous.","zh":"正是幫助學生發言的興奮感，也可能令她緊張。"},{"en":"The very passion that feels beautiful can make practical thinking weaker.","zh":"正是那種美麗的激情，可能令實際思考變弱。"},{"en":"This phrase shows that one quality can be both attractive and dangerous.","zh":"這個片語顯示一種特質可以既吸引又危險。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"make romance thrilling","meaning":"令浪漫令人心跳","examples":[{"en":"Intensity can make romance thrilling.","zh":"強烈感可以令浪漫令人心跳。"},{"en":"To make romance thrilling means to make love feel exciting, powerful, and full of energy.","zh":"make romance thrilling 指令愛情感覺刺激、有力和充滿能量。"},{"en":"A surprise meeting may make romance thrilling in a film.","zh":"電影中的意外相遇可能令浪漫令人心跳。"},{"en":"Romance feels thrilling when every message seems important.","zh":"當每一則訊息都顯得重要，浪漫就令人心跳。"},{"en":"Thrilling romance can be memorable, but it should not replace careful judgement.","zh":"令人心跳的浪漫可以難忘，但不應取代仔細判斷。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"make judgement weaker","meaning":"令判斷力變弱","examples":[{"en":"Strong emotion can make judgement weaker.","zh":"強烈情感可以令判斷力變弱。"},{"en":"Make judgement weaker means reduce someone’s ability to think clearly and wisely.","zh":"make judgement weaker 指削弱一個人清楚而明智思考的能力。"},{"en":"Anger can make judgement weaker during an argument.","zh":"爭執時，憤怒可以令判斷力變弱。"},{"en":"Passion may make judgement weaker if people ignore warning signs.","zh":"如果人們忽略警號，激情可能令判斷力變弱。"},{"en":"Marriage decisions need calm judgement, not only powerful emotion.","zh":"婚姻決定需要冷靜判斷，而不只是強烈情感。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"take Romeo and Juliet, for example","meaning":"以羅密歐與茱麗葉為例","examples":[{"en":"Take Romeo and Juliet, for example.","zh":"以羅密歐與茱麗葉為例。"},{"en":"Take something for example means use it as a case to explain an idea.","zh":"take something for example 指用某事作例子來解釋想法。"},{"en":"Take online learning, for example: it is convenient but not perfect for every student.","zh":"以網上學習為例：它方便，但不適合每個學生。"},{"en":"Writers use examples to make abstract arguments easier to understand.","zh":"作者使用例子，令抽象論點更容易理解。"},{"en":"Romeo and Juliet is a useful example because their love is intense but rushed.","zh":"《羅密歐與茱麗葉》是有用的例子，因為他們的愛強烈但倉促。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"their love is sincere","meaning":"他們的愛是真誠的","examples":[{"en":"Their love is sincere, but it moves too quickly.","zh":"他們的愛是真誠的，但發展得太快。"},{"en":"Their love is sincere means their feelings are real, honest, and not fake.","zh":"their love is sincere 指他們的感情真實、誠懇而不虛假。"},{"en":"A couple may have sincere love even if they still make poor decisions.","zh":"一對伴侶即使作出差劣決定，也可能擁有真誠的愛。"},{"en":"Sincerity makes love meaningful, but it does not guarantee wisdom.","zh":"真誠令愛有意義，但不能保證智慧。"},{"en":"Romeo and Juliet’s love is sincere, yet sincerity alone cannot save them.","zh":"羅密歐與茱麗葉的愛是真誠的，但單靠真誠不能拯救他們。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"move so quickly","meaning":"發展得太快","examples":[{"en":"Their love moves so quickly that practical consequences are ignored.","zh":"他們的愛發展得太快，以致實際後果被忽略。"},{"en":"Move so quickly means develop or happen at a very fast speed.","zh":"move so quickly 指以非常快的速度發展或發生。"},{"en":"A relationship may move so quickly that the couple has no time to know each other well.","zh":"一段關係可能發展得太快，以致伴侶沒有時間真正了解彼此。"},{"en":"When decisions move too quickly, people may miss important risks.","zh":"當決定進展太快，人們可能錯過重要風險。"},{"en":"Romeo and Juliet move so quickly from attraction to marriage that danger is overlooked.","zh":"羅密歐與茱麗葉由吸引走到婚姻太快，以致危險被忽視。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"family conflict","meaning":"家族衝突","examples":[{"en":"Romeo and Juliet do not properly consider family conflict.","zh":"羅密歐與茱麗葉沒有妥善考慮家族衝突。"},{"en":"Family conflict means serious disagreement or hostility between families or family members.","zh":"family conflict 指家族之間或家庭成員之間的嚴重分歧或敵意。"},{"en":"Family conflict can make a marriage stressful if relatives refuse to accept the couple.","zh":"如果親戚拒絕接受伴侶，家族衝突會令婚姻充滿壓力。"},{"en":"Ignoring family conflict may create pressure after the wedding.","zh":"忽略家族衝突可能在婚禮後製造壓力。"},{"en":"In the play, family conflict turns private love into public danger.","zh":"在劇中，家族衝突把私人愛情變成公共危險。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"practical consequence","meaning":"實際後果","examples":[{"en":"Passion can make people ignore practical consequences.","zh":"激情可以令人忽略實際後果。"},{"en":"A practical consequence is a real-life result that affects money, family, safety, or daily living.","zh":"practical consequence 指影響金錢、家庭、安全或日常生活的現實結果。"},{"en":"Quitting a job suddenly has practical consequences for rent and savings.","zh":"突然辭職會對租金和儲蓄造成實際後果。"},{"en":"Marriage has practical consequences because two people must share responsibilities.","zh":"婚姻有實際後果，因為兩個人必須共同承擔責任。"},{"en":"Romantic choices should consider practical consequences, not only feelings.","zh":"浪漫選擇應考慮實際後果，而不只是感受。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"properly considered","meaning":"被妥善考慮","examples":[{"en":"Neither family conflict nor practical consequence is properly considered.","zh":"家族衝突和實際後果都沒有被妥善考慮。"},{"en":"Properly considered means thought about carefully and responsibly.","zh":"properly considered 指被仔細而負責任地思考。"},{"en":"A school trip should not begin until safety risks are properly considered.","zh":"學校旅行應在安全風險被妥善考慮後才開始。"},{"en":"If money problems are not properly considered, a marriage may face stress later.","zh":"如果金錢問題沒有被妥善考慮，婚姻日後可能面對壓力。"},{"en":"Romeo and Juliet suffer partly because important realities are not properly considered.","zh":"羅密歐與茱麗葉受苦，部分因為重要現實沒有被妥善考慮。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"be given time to","meaning":"獲給予時間去","examples":[{"en":"Their passion needed to be given time to mature.","zh":"他們的激情需要獲給予時間去成熟。"},{"en":"Be given time to means be allowed enough time to develop or improve.","zh":"be given time to 指獲得足夠時間去發展或改善。"},{"en":"A new friendship should be given time to become trust.","zh":"新友誼應獲給予時間去變成信任。"},{"en":"Young love needs to be given time to face ordinary problems.","zh":"年輕愛情需要獲給予時間去面對普通問題。"},{"en":"If passion is given time, it may become steadier and wiser.","zh":"如果激情獲給予時間，它可能變得更穩定、更有智慧。"}],"source":"2017 Q4.pdf","sourcePage":4},{"front":"mature into","meaning":"成熟為；發展成","examples":[{"en":"Passion may mature into patience and wisdom.","zh":"激情可能成熟為耐性和智慧。"},{"en":"Mature into means gradually develop into a more complete, steady, or responsible form.","zh":"mature into 指逐漸發展成更完整、穩定或負責任的形式。"},{"en":"A childhood interest in music can mature into serious study.","zh":"童年對音樂的興趣可以發展成認真的學習。"},{"en":"Love matures into commitment when couples learn to forgive and listen.","zh":"當伴侶學會原諒和聆聽，愛就會成熟為承諾。"},{"en":"Passion that never matures may remain exciting but unsafe.","zh":"永不成熟的激情可能仍然刺激，但不安全。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"patience and wisdom","meaning":"耐性和智慧","examples":[{"en":"A marriage needs patience and wisdom as well as love.","zh":"婚姻除了愛，也需要耐性和智慧。"},{"en":"Patience and wisdom mean the ability to wait calmly and make thoughtful choices.","zh":"patience and wisdom 指能冷靜等待並作出深思熟慮選擇的能力。"},{"en":"Parents need patience and wisdom when children are tired or difficult.","zh":"當孩子疲倦或難以照顧時，父母需要耐性和智慧。"},{"en":"Couples need patience when problems take time to solve and wisdom when choices are hard.","zh":"問題需要時間解決時，伴侶需要耐性；選擇困難時，他們需要智慧。"},{"en":"Love becomes stronger when it is guided by patience and wisdom.","zh":"當愛受耐性和智慧引導，它會變得更強。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"less poetic but far less tragic","meaning":"較不詩意但遠不那麼悲劇","examples":[{"en":"Their story might have been less poetic but far less tragic.","zh":"他們的故事也許會較不詩意，但遠不那麼悲劇。"},{"en":"Less poetic but far less tragic means less beautiful as a story, but much less painful in life.","zh":"less poetic but far less tragic 指作為故事較不美麗，但在人生中痛苦少得多。"},{"en":"A careful decision may look less dramatic but lead to fewer regrets.","zh":"謹慎決定可能看起來較不戲劇化，但會帶來較少遺憾。"},{"en":"Real happiness may be less poetic than stage romance but more sustainable.","zh":"真正幸福可能不如舞台浪漫詩意，但更能持久。"},{"en":"The phrase contrasts artistic beauty with real human cost.","zh":"這個片語對比藝術美感和真實人生代價。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"in real life","meaning":"在現實生活中","examples":[{"en":"In real life, couples must face practical problems after marriage.","zh":"在現實生活中，伴侶婚後必須面對實際問題。"},{"en":"In real life means in actual experience, not in stories, dreams, or performances.","zh":"in real life 指在真實經驗中，而不是在故事、夢想或表演中。"},{"en":"In real life, love letters do not remove rent, illness, or family duties.","zh":"在現實生活中，情書不能消除租金、疾病或家庭責任。"},{"en":"Drama may simplify love, but real life makes couples deal with details.","zh":"戲劇可能簡化愛情，但現實生活要求伴侶處理細節。"},{"en":"This phrase brings the discussion from theatre back to ordinary marriage.","zh":"這個片語把討論從劇場帶回普通婚姻。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"fall deeply in love","meaning":"深深相愛","examples":[{"en":"A couple may fall deeply in love before discovering serious disagreements.","zh":"一對伴侶可能先深深相愛，然後才發現嚴重分歧。"},{"en":"Fall deeply in love means develop very strong romantic feelings for someone.","zh":"fall deeply in love 指對某人產生非常強烈的浪漫感情。"},{"en":"Two classmates may fall deeply in love after spending much time together.","zh":"兩名同學相處很多時間後，可能會深深相愛。"},{"en":"Falling deeply in love can hide differences until practical choices appear.","zh":"深深相愛可能會掩蓋差異，直到實際選擇出現。"},{"en":"Deep love is powerful, but couples still need honest discussion.","zh":"深愛很有力量，但伴侶仍需要誠實討論。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"only to discover","meaning":"結果卻發現","examples":[{"en":"They may fall in love, only to discover that they disagree about money.","zh":"他們可能相愛，結果卻發現在金錢方面意見不合。"},{"en":"Only to discover means later finding something unexpected, often disappointing.","zh":"only to discover 指後來發現意想不到、通常令人失望的事情。"},{"en":"She bought the shoes online, only to discover they were the wrong size.","zh":"她在網上買鞋，結果卻發現尺碼不對。"},{"en":"A couple may marry quickly, only to discover they want very different lives.","zh":"一對伴侶可能很快結婚，結果卻發現彼此想要很不同的人生。"},{"en":"This phrase shows that a hopeful beginning can lead to a difficult truth.","zh":"這個片語顯示充滿希望的開始可能通向困難真相。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"disagree about","meaning":"在……方面意見不合","examples":[{"en":"A couple may disagree about money, children or elderly parents.","zh":"一對伴侶可能在金錢、孩子或年老父母方面意見不合。"},{"en":"Disagree about means have different opinions on a subject.","zh":"disagree about 指在某個題目上有不同意見。"},{"en":"Friends may disagree about where to eat but still respect each other.","zh":"朋友可能在去哪裏吃飯方面意見不合，但仍尊重彼此。"},{"en":"Couples need communication when they disagree about important life choices.","zh":"伴侶在重要人生選擇上意見不合時，需要溝通。"},{"en":"Disagreement itself is not fatal, but refusing to discuss it can be.","zh":"分歧本身未必致命，但拒絕討論分歧可能是致命的。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"elderly parents","meaning":"年老父母","examples":[{"en":"Married couples may need to care for elderly parents.","zh":"已婚伴侶可能需要照顧年老父母。"},{"en":"Elderly parents are older mothers and fathers who may need support, care, or companionship.","zh":"elderly parents 指可能需要支援、照顧或陪伴的年長母親和父親。"},{"en":"A couple may discuss how to pay medical bills for elderly parents.","zh":"伴侶可能要討論如何支付年老父母的醫療費。"},{"en":"Caring for elderly parents can test time, money, and patience in marriage.","zh":"照顧年老父母會考驗婚姻中的時間、金錢和耐性。"},{"en":"Responsible love includes respect for family duties, not only romantic feelings.","zh":"負責任的愛包括尊重家庭責任，而不只是浪漫感覺。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, respectful companions may slowly build trust.","zh":"相比之下，互相尊重的伴侶可能慢慢建立信任。"},{"en":"By contrast introduces a different or opposite situation.","zh":"by contrast 用來引出不同或相反的情況。"},{"en":"Some students study only before exams; by contrast, others revise a little every day.","zh":"有些學生只在考試前溫習；相比之下，另一些每天溫習一點。"},{"en":"This phrase helps writers compare two ideas clearly.","zh":"這個片語幫助作者清楚比較兩個想法。"},{"en":"Here, it contrasts rushed passion with slow, respectful trust.","zh":"在這裏，它對比倉促激情和慢慢建立的尊重信任。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"respectful companions","meaning":"互相尊重的伴侶","examples":[{"en":"Two respectful companions may build a happy marriage.","zh":"兩位互相尊重的伴侶可以建立幸福婚姻。"},{"en":"Respectful companions are partners who treat each other with care, fairness, and dignity.","zh":"respectful companions 指以關心、公平和尊嚴對待彼此的伴侶。"},{"en":"Respectful companions listen before blaming each other.","zh":"互相尊重的伴侶會先聆聽，而不是責怪對方。"},{"en":"A marriage between respectful companions can grow even without dramatic romance.","zh":"互相尊重的伴侶即使沒有戲劇化浪漫，也能讓婚姻成長。"},{"en":"Respectful companionship gives love a steady daily shape.","zh":"尊重的陪伴給愛一種穩定的日常形狀。"}],"source":"2017 Q4.pdf","sourcePage":5},{"front":"build confidence in each other","meaning":"建立對彼此的信心","examples":[{"en":"The couple slowly built confidence in each other.","zh":"這對伴侶慢慢建立對彼此的信心。"},{"en":"Build confidence in each other means gradually learn to trust and rely on one another.","zh":"build confidence in each other 指逐漸學會信任和依靠彼此。"},{"en":"Friends build confidence in each other by keeping promises.","zh":"朋友透過遵守承諾建立對彼此的信心。"},{"en":"Couples build confidence when actions match words over time.","zh":"當行動長期與說話一致，伴侶就能建立信心。"},{"en":"Confidence grows slowly, but it can support marriage more firmly than excitement.","zh":"信心慢慢增長，但它比刺激更能穩固地支撐婚姻。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"little by little","meaning":"一點一滴地","examples":[{"en":"Little by little, shared habits became trust.","zh":"一點一滴地，共同習慣變成了信任。"},{"en":"Little by little means gradually, in small steps over time.","zh":"little by little 指隨着時間逐步地、慢慢地。"},{"en":"Little by little, a shy student became comfortable speaking in class.","zh":"一點一滴地，害羞的學生變得能自在地在課堂發言。"},{"en":"Couples build trust little by little through daily reliability.","zh":"伴侶透過每日可靠的行動一點一滴地建立信任。"},{"en":"This phrase shows that strong marriage often grows slowly, not suddenly.","zh":"這個片語顯示穩固婚姻常常是慢慢成長，而不是突然出現。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"shared habits","meaning":"共同習慣","examples":[{"en":"Shared habits can become trust over time.","zh":"共同習慣隨着時間可以變成信任。"},{"en":"Shared habits are regular actions or routines that two people do together.","zh":"shared habits 是兩個人一起定期做的行動或日常規律。"},{"en":"Cooking dinner together every Sunday can become a shared habit.","zh":"每星期日一起煮晚飯可以成為共同習慣。"},{"en":"Shared habits create comfort because partners know what to expect from each other.","zh":"共同習慣能創造安心感，因為伴侶知道可以期待彼此做甚麼。"},{"en":"In marriage, repeated small habits may matter more than grand gestures.","zh":"在婚姻中，反覆的小習慣可能比盛大的舉動更重要。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"emotional safety","meaning":"情感上的安全感","examples":[{"en":"Trust can become emotional safety.","zh":"信任可以變成情感上的安全感。"},{"en":"Emotional safety means feeling safe to speak, be honest, and show weakness without fear.","zh":"emotional safety 指能安心說話、誠實表達和展現脆弱，而不害怕。"},{"en":"A child needs emotional safety at home to talk about worries.","zh":"孩子在家中需要情感上的安全感，才能談論憂慮。"},{"en":"In marriage, emotional safety grows when partners do not mock each other’s feelings.","zh":"在婚姻中，當伴侶不嘲笑彼此感受，情感上的安全感就會增長。"},{"en":"Romantic excitement is pleasant, but emotional safety helps love last.","zh":"浪漫刺激令人愉快，但情感上的安全感幫助愛持久。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"open the door","meaning":"打開大門；帶來開始","examples":[{"en":"Romantic love may open the door to marriage.","zh":"浪漫愛情可能為婚姻打開大門。"},{"en":"Open the door means create the first chance or beginning for something.","zh":"open the door 指為某事創造第一個機會或開始。"},{"en":"A scholarship can open the door to study abroad.","zh":"獎學金可以打開到海外升學的大門。"},{"en":"Romantic love may open the door, but it does not complete the whole journey.","zh":"浪漫愛情可能帶來開始，但不能完成整段旅程。"},{"en":"Marriage needs what comes after the door opens: trust, patience, and care.","zh":"婚姻需要門打開之後的東西：信任、耐性和關心。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"reliability keeps the home warm","meaning":"可靠才令家庭溫暖","examples":[{"en":"Romantic love may open the door, but reliability keeps the home warm.","zh":"浪漫愛情可能打開大門，但可靠才令家庭溫暖。"},{"en":"Reliability keeps the home warm means steady support makes family life safe and loving.","zh":"reliability keeps the home warm 指穩定支援令家庭生活安全而有愛。"},{"en":"A partner who remembers medicine and listens after work keeps the home warm.","zh":"伴侶記得藥物、下班後願意聆聽，就是令家庭溫暖。"},{"en":"Reliability matters when romance is quiet but daily needs remain.","zh":"當浪漫變得安靜但日常需要仍在，可靠就很重要。"},{"en":"This phrase shows that ordinary dependability can be deeply loving.","zh":"這個片語顯示普通的可靠也可以是深切的愛。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"secondly","meaning":"其次","examples":[{"en":"Secondly, marriage is about living responsibly with another person.","zh":"其次，婚姻關乎負責任地與另一個人生活。"},{"en":"Secondly introduces the second point in an argument or explanation.","zh":"secondly 用來引出論點或解釋中的第二個重點。"},{"en":"Firstly, students need practice; secondly, they need feedback.","zh":"首先，學生需要練習；其次，他們需要回饋。"},{"en":"This word helps readers follow the order of ideas in an essay.","zh":"這個詞幫助讀者跟隨作文中的思路次序。"},{"en":"The writer uses secondly to move from emotion to responsibility.","zh":"作者用 secondly 把討論由情感轉向責任。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"not just about...but about...","meaning":"不只是關於……而是關於……","examples":[{"en":"Marriage is not just about feeling loved, but about living responsibly.","zh":"婚姻不只是關乎感到被愛，而是關乎負責任地生活。"},{"en":"Not just about A but about B means B is also central and may be more important.","zh":"not just about A but about B 指 B 也很核心，甚至可能更重要。"},{"en":"Education is not just about passing exams, but about learning how to think.","zh":"教育不只是關乎通過考試，而是關乎學會思考。"},{"en":"Marriage is not just about romance, but about daily choices and duties.","zh":"婚姻不只是關乎浪漫，而是關乎每日選擇和責任。"},{"en":"This structure helps correct a narrow view of marriage.","zh":"這個結構有助修正對婚姻的狹窄看法。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"feeling loved","meaning":"感到被愛","examples":[{"en":"A happy marriage is not just about feeling loved.","zh":"幸福婚姻不只是關乎感到被愛。"},{"en":"Feeling loved means sensing that someone cares for, values, and accepts you.","zh":"feeling loved 指感受到有人關心、重視和接納自己。"},{"en":"Children feel loved when parents listen and spend time with them.","zh":"當父母聆聽並花時間陪伴，孩子會感到被愛。"},{"en":"In marriage, feeling loved is important, but partners must also act responsibly.","zh":"在婚姻中，感到被愛很重要，但伴侶也必須負責任地行動。"},{"en":"A person may feel loved through small daily actions, not only romantic words.","zh":"一個人可以透過每日小行動感到被愛，而不只是透過浪漫說話。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"live responsibly with","meaning":"負責任地與……生活","examples":[{"en":"Marriage means living responsibly with another person.","zh":"婚姻意味着負責任地與另一個人生活。"},{"en":"Live responsibly with someone means share life while taking duties, promises, and consequences seriously.","zh":"live responsibly with someone 指共同生活時認真看待責任、承諾和後果。"},{"en":"Roommates live responsibly with each other when they share chores fairly.","zh":"室友公平分擔家務時，就是負責任地與彼此生活。"},{"en":"Couples live responsibly when they discuss money honestly and care for family needs.","zh":"伴侶誠實討論金錢並照顧家庭需要時，就是負責任地生活。"},{"en":"Marriage asks people to love not only with feelings but with responsibility.","zh":"婚姻要求人不只用感覺去愛，也要用責任去愛。"}],"source":"2017 Q4.pdf","sourcePage":6},{"front":"the trouble with","meaning":"……的問題在於","examples":[{"en":"The trouble with simple slogans is that they hide real problems.","zh":"簡單口號的問題在於它們掩蓋真實問題。"},{"en":"The trouble with means the problem or weakness of something is this.","zh":"the trouble with 指某事的問題或弱點在於這裏。"},{"en":"The trouble with studying only at the last minute is that there is no time to ask questions.","zh":"臨急才溫習的問題在於沒有時間提問。"},{"en":"The trouble with “love conquers all” is that it sounds simple but ignores difficulty.","zh":"「愛能征服一切」的問題在於它聽起來簡單，卻忽略困難。"},{"en":"This phrase introduces criticism in a clear and direct way.","zh":"這個片語以清楚直接的方式引出批評。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"simple slogans","meaning":"簡單口號","examples":[{"en":"Simple slogans such as “love conquers all” can be misleading.","zh":"「愛能征服一切」這類簡單口號可能具誤導性。"},{"en":"Simple slogans are short, easy phrases that express an idea but may hide complexity.","zh":"simple slogans 是簡短易記、表達一個想法但可能掩蓋複雜性的說法。"},{"en":"“Just work harder” is a simple slogan that may ignore unfair conditions.","zh":"「努力一點就好」是簡單口號，可能忽略不公平條件。"},{"en":"Simple slogans can comfort people, but they may also stop careful thinking.","zh":"簡單口號可以安慰人，但也可能阻止仔細思考。"},{"en":"Marriage is too complex to be explained by simple slogans alone.","zh":"婚姻太複雜，不能只靠簡單口號解釋。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"love conquers all","meaning":"愛能征服一切","examples":[{"en":"The slogan “love conquers all” hides the burdens of married life.","zh":"「愛能征服一切」這句口號掩蓋了婚姻生活的負擔。"},{"en":"Love conquers all means love can overcome every difficulty.","zh":"love conquers all 指愛能克服所有困難。"},{"en":"The phrase sounds hopeful, but real couples still need money, patience, and communication.","zh":"這句話聽起來充滿希望，但真實伴侶仍需要金錢、耐性和溝通。"},{"en":"Believing love conquers all may make people ignore practical preparation.","zh":"相信愛能征服一切，可能令人忽略實際準備。"},{"en":"Love is powerful, but it does not automatically solve every problem.","zh":"愛很有力量，但不會自動解決所有問題。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"hide the ordinary burdens of","meaning":"掩蓋……的日常負擔","examples":[{"en":"Romantic slogans can hide the ordinary burdens of married life.","zh":"浪漫口號可以掩蓋婚姻生活的日常負擔。"},{"en":"Hide the ordinary burdens of means cover up the everyday duties and difficulties of something.","zh":"hide the ordinary burdens of 指遮掩某事中的日常責任和困難。"},{"en":"Beautiful wedding photos can hide the ordinary burdens of family life.","zh":"美麗婚照可以掩蓋家庭生活的日常負擔。"},{"en":"If people ignore ordinary burdens, they may enter marriage with unrealistic expectations.","zh":"如果人們忽略日常負擔，可能會帶着不現實期望進入婚姻。"},{"en":"Real love faces these burdens instead of pretending they do not exist.","zh":"真正的愛會面對這些負擔，而不是假裝它們不存在。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"married life","meaning":"婚姻生活","examples":[{"en":"Married life involves bills, careers and family responsibilities.","zh":"婚姻生活包括帳單、事業和家庭責任。"},{"en":"Married life is the daily life shared by two people after marriage.","zh":"married life 指兩個人結婚後共同分享的日常生活。"},{"en":"Married life includes small routines such as cooking, cleaning, and planning money.","zh":"婚姻生活包括煮飯、清潔和理財等小日常。"},{"en":"Married life can be joyful, but it also requires patience and cooperation.","zh":"婚姻生活可以快樂，但也需要耐性和合作。"},{"en":"Romance begins a relationship, but married life tests how people love every day.","zh":"浪漫開始一段關係，但婚姻生活考驗人如何每天去愛。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"after the wedding","meaning":"婚禮之後","examples":[{"en":"After the wedding, a couple must face ordinary responsibilities.","zh":"婚禮之後，伴侶必須面對普通責任。"},{"en":"After the wedding means after the marriage ceremony or celebration has finished.","zh":"after the wedding 指婚禮儀式或慶祝結束之後。"},{"en":"After the wedding, couples may need to plan housing, savings, and family visits.","zh":"婚禮之後，伴侶可能需要計劃住房、儲蓄和探望家人。"},{"en":"The wedding is one day, but marriage continues after the wedding.","zh":"婚禮只有一天，但婚姻在婚禮之後繼續。"},{"en":"This phrase reminds us that romance must become daily responsibility.","zh":"這個片語提醒我們，浪漫必須變成日常責任。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"bills to discuss","meaning":"要商量的賬單","examples":[{"en":"After marriage, there are bills to discuss.","zh":"結婚後，有要商量的賬單。"},{"en":"Bills to discuss are payments that couples need to talk about and manage together.","zh":"bills to discuss 指伴侶需要一起談論和管理的付款。"},{"en":"Rent, electricity, phone plans, and medical costs can become bills to discuss.","zh":"租金、電費、電話計劃和醫療費都可能成為要商量的賬單。"},{"en":"Couples who discuss bills honestly avoid many hidden arguments.","zh":"誠實討論帳單的伴侶，可以避免許多隱藏爭執。"},{"en":"Money talk may not be romantic, but it is part of responsible love.","zh":"談錢未必浪漫，但它是負責任的愛的一部分。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"careers to balance","meaning":"要平衡的事業","examples":[{"en":"A married couple may have careers to balance.","zh":"已婚伴侶可能有要平衡的事業。"},{"en":"Careers to balance are jobs or career plans that must be managed fairly within a relationship.","zh":"careers to balance 指在關係中必須公平安排的工作或事業計劃。"},{"en":"One partner may work late while the other studies for a promotion.","zh":"一方可能工作到很晚，另一方則為升職進修。"},{"en":"Couples need fairness when both have careers to balance and family duties to share.","zh":"當雙方都有事業要平衡，也有家庭責任要分擔時，伴侶需要公平。"},{"en":"Balancing careers requires respect for each person’s goals.","zh":"平衡事業需要尊重每個人的目標。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"illnesses to face","meaning":"要面對的疾病","examples":[{"en":"Married life may bring illnesses to face.","zh":"婚姻生活可能帶來要面對的疾病。"},{"en":"Illnesses to face are health problems a couple must deal with together.","zh":"illnesses to face 指伴侶必須一起處理的健康問題。"},{"en":"A partner may need care after surgery or during a long illness.","zh":"伴侶手術後或長期患病時，可能需要照顧。"},{"en":"Illnesses test whether love includes patience, service, and sacrifice.","zh":"疾病考驗愛是否包括耐性、服務和犧牲。"},{"en":"A strong marriage does not disappear when health becomes difficult.","zh":"當健康變得困難，穩固婚姻不會因此消失。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"relatives to respect","meaning":"要尊重的親戚","examples":[{"en":"Marriage may involve relatives to respect.","zh":"婚姻可能涉及要尊重的親戚。"},{"en":"Relatives to respect are family members who should be treated with care and courtesy.","zh":"relatives to respect 指應被關心和禮貌對待的家庭成員。"},{"en":"A couple may need to respect elderly relatives during festivals and family decisions.","zh":"伴侶可能需要在節日和家庭決定中尊重年長親戚。"},{"en":"Respecting relatives does not mean obeying every demand without discussion.","zh":"尊重親戚不代表不經討論就服從所有要求。"},{"en":"Healthy marriage balances respect for relatives with protection of the couple’s own home.","zh":"健康婚姻會在尊重親戚和保護夫妻自己的家之間取得平衡。"}],"source":"2017 Q4.pdf","sourcePage":7},{"front":"children to raise","meaning":"要撫養的孩子","examples":[{"en":"Some couples also have children to raise.","zh":"有些伴侶也有要撫養的孩子。"},{"en":"Children to raise are children whom parents must care for, guide, and support as they grow.","zh":"children to raise 指父母必須在孩子成長中照顧、引導和支持他們。"},{"en":"Raising children includes feeding them, teaching them, and listening to them.","zh":"撫養孩子包括餵養、教育和聆聽他們。"},{"en":"Children can bring joy, but they also require time, money, and patience.","zh":"孩子可以帶來快樂，但也需要時間、金錢和耐性。"},{"en":"Couples need cooperation when they have children to raise.","zh":"當伴侶有孩子要撫養，他們需要合作。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"in such situations","meaning":"在這些情況下","examples":[{"en":"In such situations, reliability matters more than romance.","zh":"在這些情況下，可靠比浪漫更重要。"},{"en":"In such situations means in the kinds of circumstances just mentioned.","zh":"in such situations 指在剛才提到的那些情況中。"},{"en":"In such situations, a calm answer is better than an angry reaction.","zh":"在這些情況下，冷靜回答比憤怒反應更好。"},{"en":"When a child is sick or bills are heavy, romance alone is not enough.","zh":"當孩子生病或帳單沉重時，單靠浪漫並不足夠。"},{"en":"This phrase connects examples to a general lesson.","zh":"這個片語把例子連接到一般道理。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"what matters is not whether...but whether...","meaning":"重要的不是……而是……","examples":[{"en":"What matters is not whether he writes messages, but whether he listens.","zh":"重要的不是他是否寫動人的訊息，而是他是否聆聽。"},{"en":"What matters is not whether A but whether B means B is the real important question.","zh":"what matters is not whether A but whether B 指真正重要的問題是 B。"},{"en":"What matters is not whether a gift is expensive, but whether it is thoughtful.","zh":"重要的不是禮物是否昂貴，而是它是否用心。"},{"en":"In marriage, beautiful words matter less than daily attention.","zh":"在婚姻中，漂亮說話不如每日留心重要。"},{"en":"This structure helps separate appearance from real value.","zh":"這個結構幫助區分表面和真正價值。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"write beautiful messages","meaning":"寫動人的訊息","examples":[{"en":"A romantic husband may write beautiful messages every night.","zh":"浪漫的丈夫可能每晚寫動人的訊息。"},{"en":"Write beautiful messages means send kind, loving, or poetic words to someone.","zh":"write beautiful messages 指向某人發送溫柔、有愛意或詩意的文字。"},{"en":"A partner may write beautiful messages to comfort someone after a hard day.","zh":"伴侶可能寫動人的訊息，安慰度過艱難一天的人。"},{"en":"Beautiful messages can show love, but they should be matched by real care.","zh":"動人的訊息可以表達愛，但應配合真實關心。"},{"en":"Words are touching when actions behind them are reliable.","zh":"當背後行動可靠，文字才真正動人。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"be exhausted","meaning":"筋疲力盡","examples":[{"en":"A loving partner listens when the other person is exhausted.","zh":"當另一半筋疲力盡時，有愛的伴侶會聆聽。"},{"en":"Be exhausted means be extremely tired physically, mentally, or emotionally.","zh":"be exhausted 指身體、精神或情感上極度疲倦。"},{"en":"A nurse may be exhausted after working a long night shift.","zh":"護士上完漫長夜班後可能筋疲力盡。"},{"en":"When someone is exhausted, gentle listening may help more than advice.","zh":"當一個人筋疲力盡時，溫柔聆聽可能比建議更有幫助。"},{"en":"A marriage becomes strong when partners care for each other during exhaustion.","zh":"當伴侶在彼此疲憊時互相關心，婚姻會變得穩固。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"care for a sick child","meaning":"照顧生病的孩子","examples":[{"en":"A couple caring for a sick child may have little time for romance.","zh":"照顧生病孩子的伴侶可能很少有時間浪漫。"},{"en":"Care for a sick child means look after a child who is ill.","zh":"care for a sick child 指照顧患病的孩子。"},{"en":"Parents care for a sick child by giving medicine, checking temperature, and staying awake.","zh":"父母透過餵藥、量體溫和熬夜來照顧生病的孩子。"},{"en":"Caring for a sick child can test patience more than romantic feeling.","zh":"照顧生病孩子比浪漫感覺更能考驗耐性。"},{"en":"A couple shows love by sharing the tiring work of care.","zh":"伴侶透過分擔疲累的照顧工作來表達愛。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"have little time for","meaning":"很少有時間做……","examples":[{"en":"The couple may have little time for romantic dinners.","zh":"這對伴侶可能很少有時間享受浪漫晚餐。"},{"en":"Have little time for means have very little available time to do something.","zh":"have little time for 指幾乎沒有可用時間做某事。"},{"en":"A student with three exams may have little time for games.","zh":"有三場考試的學生可能很少有時間玩遊戲。"},{"en":"New parents often have little time for quiet evenings together.","zh":"新手父母常常很少有時間一起度過安靜晚上。"},{"en":"Having little time for romance does not mean love has disappeared.","zh":"很少有時間浪漫，並不代表愛已經消失。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"romantic dinners","meaning":"浪漫晚餐","examples":[{"en":"Parents caring for a sick child may miss romantic dinners.","zh":"照顧生病孩子的父母可能會錯過浪漫晚餐。"},{"en":"Romantic dinners are special meals shared by a couple in a loving or intimate mood.","zh":"romantic dinners 指伴侶在充滿愛意或親密氣氛中共享的特別晚餐。"},{"en":"A couple may plan romantic dinners for anniversaries.","zh":"伴侶可能為周年紀念安排浪漫晚餐。"},{"en":"Romantic dinners can strengthen affection, but they are not the whole of marriage.","zh":"浪漫晚餐可以增進感情，但不是婚姻的全部。"},{"en":"Sometimes love appears not at dinner, but beside a child’s sickbed.","zh":"有時愛不是出現在晚餐桌上，而是在孩子病床旁。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, their marriage can still be profoundly happy.","zh":"然而，他們的婚姻仍然可以深切幸福。"},{"en":"Nevertheless means despite what was just said, the next point is still true.","zh":"nevertheless 指儘管剛才所說的情況存在，下一點仍然成立。"},{"en":"The work is difficult; nevertheless, the team continues.","zh":"工作很困難；然而，團隊仍然繼續。"},{"en":"A couple may face illness; nevertheless, their love can deepen.","zh":"伴侶可能面對疾病；然而，他們的愛仍可以加深。"},{"en":"This word helps show contrast without denying the previous problem.","zh":"這個詞有助展示轉折，同時不否定前面的問題。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"divide duties fairly","meaning":"公平分擔責任","examples":[{"en":"A couple can be happy if they divide duties fairly.","zh":"如果伴侶公平分擔責任，他們可以幸福。"},{"en":"Divide duties fairly means share responsibilities in a just and balanced way.","zh":"divide duties fairly 指以公正和平衡的方式分擔責任。"},{"en":"Roommates divide duties fairly when everyone takes turns cleaning.","zh":"室友輪流清潔時，就是公平分擔責任。"},{"en":"Couples avoid resentment when housework and childcare are divided fairly.","zh":"當家務和育兒工作被公平分擔，伴侶可以避免怨氣。"},{"en":"Fair division of duties turns love into practical teamwork.","zh":"公平分擔責任把愛變成實際團隊合作。"}],"source":"2017 Q4.pdf","sourcePage":8},{"front":"speak gently under pressure","meaning":"在壓力下溫柔說話","examples":[{"en":"Good partners speak gently under pressure.","zh":"好伴侶會在壓力下溫柔說話。"},{"en":"Speak gently under pressure means use calm and kind words even when stressed.","zh":"speak gently under pressure 指即使有壓力，也使用冷靜和溫和的說話。"},{"en":"A parent speaks gently under pressure when a child cries in public.","zh":"孩子在公共場所哭鬧時，父母仍溫柔說話，就是在壓力下保持溫和。"},{"en":"Couples protect each other when they speak gently during hard moments.","zh":"伴侶在艱難時刻溫柔說話，就是在保護彼此。"},{"en":"Gentle speech can stop pressure from becoming cruelty.","zh":"溫柔說話可以阻止壓力變成殘酷。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"protect each other from despair","meaning":"保護彼此免於絕望","examples":[{"en":"A strong couple protects each other from despair.","zh":"穩固的伴侶會保護彼此免於絕望。"},{"en":"Protect each other from despair means help one another avoid losing hope completely.","zh":"protect each other from despair 指幫助彼此避免完全失去希望。"},{"en":"Friends protect each other from despair by staying present during hard times.","zh":"朋友在艱難時期陪伴彼此，就是保護彼此免於絕望。"},{"en":"In marriage, small acts of care can protect a partner from feeling alone.","zh":"在婚姻中，小小關心可以保護伴侶不感到孤單。"},{"en":"This kind of protection is deeper than romantic display.","zh":"這種保護比浪漫展示更深刻。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"profoundly happy","meaning":"深切幸福","examples":[{"en":"A responsible marriage can be profoundly happy.","zh":"負責任的婚姻可以深切幸福。"},{"en":"Profoundly happy means deeply and meaningfully happy, not just briefly excited.","zh":"profoundly happy 指深層而有意義地幸福，而不只是短暫興奮。"},{"en":"A family may feel profoundly happy after surviving a difficult year together.","zh":"一個家庭共同度過艱難一年後，可能感到深切幸福。"},{"en":"Profound happiness often comes from trust, safety, and shared effort.","zh":"深切幸福常來自信任、安全感和共同努力。"},{"en":"Marriage can be profoundly happy even when it looks ordinary from outside.","zh":"即使婚姻從外面看起來普通，也可以深切幸福。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"stage romance","meaning":"舞台上的浪漫愛情","examples":[{"en":"A good marriage may not look like a stage romance.","zh":"好婚姻未必看起來像舞台上的浪漫愛情。"},{"en":"Stage romance means dramatic, beautiful love as shown in theatre or performance.","zh":"stage romance 指在劇場或表演中展示的戲劇化、美麗愛情。"},{"en":"Stage romance may include poetic speeches, moonlight, and sudden promises.","zh":"舞台上的浪漫愛情可能包括詩意演說、月光和突然承諾。"},{"en":"Real marriage may look quieter than stage romance but be more reliable.","zh":"真實婚姻可能比舞台浪漫安靜，但更可靠。"},{"en":"The phrase contrasts performed love with lived love.","zh":"這個片語對比被表演的愛和被生活出來的愛。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"there is more to happiness than","meaning":"幸福不止是……","examples":[{"en":"There is more to happiness than excitement.","zh":"幸福不止是刺激。"},{"en":"There is more to happiness than means happiness includes more than one obvious thing.","zh":"there is more to happiness than 指幸福包含的不只是某個明顯的東西。"},{"en":"There is more to success than high marks.","zh":"成功不止是高分。"},{"en":"There is more to marriage than feeling excited at the beginning.","zh":"婚姻不止是開始時感到興奮。"},{"en":"This phrase helps widen a narrow idea of happiness.","zh":"這個片語有助擴闊對幸福的狹窄理解。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"feel seen","meaning":"感到被看見；被理解","examples":[{"en":"Both partners need to feel seen in a marriage.","zh":"婚姻中，雙方都需要感到被看見。"},{"en":"Feel seen means feel understood, noticed, and valued for who you really are.","zh":"feel seen 指感到自己真正的樣子被理解、被注意和被重視。"},{"en":"A child feels seen when a parent remembers what worries them.","zh":"當父母記得孩子擔心甚麼，孩子會感到被看見。"},{"en":"Partners feel seen when their tiredness, hopes, and fears are taken seriously.","zh":"當疲倦、希望和恐懼被認真看待，伴侶會感到被理解。"},{"en":"Feeling seen can be more comforting than receiving dramatic romantic gestures.","zh":"感到被看見可能比收到戲劇化浪漫舉動更令人安慰。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"feel forgiven","meaning":"感到被原諒","examples":[{"en":"A peaceful home allows both partners to feel forgiven.","zh":"平靜的家讓雙方都能感到被原諒。"},{"en":"Feel forgiven means feel that mistakes have been understood and not held against you forever.","zh":"feel forgiven 指感到錯誤被理解，而且不會永遠被記恨。"},{"en":"A student feels forgiven when a teacher corrects the mistake but still encourages them.","zh":"當老師糾正錯誤但仍鼓勵學生，學生會感到被原諒。"},{"en":"Couples need forgiveness because no one behaves perfectly every day.","zh":"伴侶需要原諒，因為沒有人每天都表現完美。"},{"en":"Feeling forgiven helps a marriage recover after conflict.","zh":"感到被原諒能幫助婚姻在衝突後恢復。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"feel trusted","meaning":"感到被信任","examples":[{"en":"Both partners should feel trusted at home.","zh":"雙方在家中都應感到被信任。"},{"en":"Feel trusted means feel that someone believes in your honesty, judgement, or loyalty.","zh":"feel trusted 指感到有人相信你的誠實、判斷或忠誠。"},{"en":"Teenagers feel trusted when parents give them responsibility and listen to them.","zh":"當父母給青少年責任並聆聽他們時，他們會感到被信任。"},{"en":"In marriage, feeling trusted reduces fear and suspicion.","zh":"在婚姻中，感到被信任可以減少恐懼和猜疑。"},{"en":"Trust makes home feel safer than romance alone can.","zh":"信任令家比單靠浪漫更安全。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"no less precious than","meaning":"不比……遜色；同樣珍貴","examples":[{"en":"A peaceful home can be no less precious than passionate courtship.","zh":"平靜的家可以不比熱烈的追求期遜色，同樣珍貴。"},{"en":"No less precious than means equally valuable or important.","zh":"no less precious than 指同樣有價值或同樣重要。"},{"en":"A quiet friendship can be no less precious than an exciting new relationship.","zh":"安靜的友誼可以不比刺激的新關係遜色。"},{"en":"Daily kindness is no less precious than grand romantic promises.","zh":"每日善意不比盛大的浪漫承諾遜色。"},{"en":"The phrase reminds us not to undervalue ordinary peace.","zh":"這個片語提醒我們不要低估普通的平靜。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"passionate courtship","meaning":"熱烈的追求期","examples":[{"en":"Passionate courtship is not the only path to happiness.","zh":"熱烈的追求期不是通往幸福的唯一道路。"},{"en":"Passionate courtship is the intense period when someone romantically pursues another person.","zh":"passionate courtship 指某人熱烈追求另一人的強烈浪漫階段。"},{"en":"Passionate courtship may include letters, gifts, dates, and strong emotion.","zh":"熱烈的追求期可能包括信件、禮物、約會和強烈情感。"},{"en":"Courtship can be exciting, but marriage requires more than pursuit.","zh":"追求期可以令人興奮，但婚姻需要的不只是追求。"},{"en":"A quiet relationship can still become happy without dramatic courtship.","zh":"安靜的關係即使沒有戲劇化追求期，也可以變得幸福。"}],"source":"2017 Q4.pdf","sourcePage":9},{"front":"admittedly","meaning":"無可否認","examples":[{"en":"Admittedly, some people think romance is necessary.","zh":"無可否認，有些人認為浪漫是必要的。"},{"en":"Admittedly means it is true that something should be accepted before giving another point.","zh":"admittedly 指承認某事是真實或值得接受，然後再提出另一點。"},{"en":"Admittedly, exams are stressful, but they can show what students understand.","zh":"無可否認，考試令人有壓力，但它們可以顯示學生理解了甚麼。"},{"en":"This word helps a writer sound fair by recognising the other side.","zh":"這個詞透過承認另一方，令作者顯得公平。"},{"en":"The writer admits romance matters before explaining why it is not everything.","zh":"作者先承認浪漫重要，再解釋它不是一切。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"argue that","meaning":"主張；認為","examples":[{"en":"Some people argue that marriage needs romantic love.","zh":"有些人主張婚姻需要浪漫愛情。"},{"en":"Argue that means state an opinion and support it with reasons.","zh":"argue that 指提出一個看法，並用理由支持它。"},{"en":"Some teachers argue that reading builds stronger writing skills.","zh":"有些老師認為閱讀能建立更強寫作能力。"},{"en":"In essays, people argue that one idea is better than another using examples.","zh":"在作文中，人們用例子主張某個想法比另一個更好。"},{"en":"The phrase introduces an opposing view about marriage and romance.","zh":"這個片語引出關於婚姻和浪漫的相反觀點。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"without romantic love","meaning":"沒有浪漫愛情","examples":[{"en":"Without romantic love, some people fear marriage becomes a contract.","zh":"沒有浪漫愛情，有些人擔心婚姻會變成合約。"},{"en":"Without romantic love means if romantic feeling is absent.","zh":"without romantic love 指如果浪漫感情不存在。"},{"en":"Without romantic love, a relationship may still have respect, care, and commitment.","zh":"沒有浪漫愛情，一段關係仍可能有尊重、關心和承諾。"},{"en":"Some people worry that marriage without romance may feel cold or practical only.","zh":"有些人擔心沒有浪漫的婚姻可能會冷淡或只講實際。"},{"en":"The writer accepts this worry but argues that initial passion is not always required.","zh":"作者接受這種憂慮，但認為最初的激情未必一定需要。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"little more than","meaning":"不過是；只不過是","examples":[{"en":"Without affection, marriage may become little more than a contract.","zh":"沒有感情，婚姻可能只不過是一份合約。"},{"en":"Little more than means only slightly more than, or almost just.","zh":"little more than 指只比某物多一點，或幾乎只是某物。"},{"en":"A class without discussion may become little more than copying notes.","zh":"沒有討論的課堂可能只不過是抄筆記。"},{"en":"A marriage without warmth may feel little more than a shared arrangement.","zh":"沒有溫暖的婚姻可能感覺只不過是一種共同安排。"},{"en":"This phrase criticises something for being too limited or empty.","zh":"這個片語批評某事太有限或空洞。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"a contract","meaning":"合約","examples":[{"en":"Some people fear marriage will become only a contract.","zh":"有些人擔心婚姻只會變成合約。"},{"en":"A contract is a formal agreement between people, usually with duties and conditions.","zh":"a contract 指人與人之間的正式協議，通常包含責任和條件。"},{"en":"A rental contract explains how much rent a tenant must pay.","zh":"租約合約說明租客必須支付多少租金。"},{"en":"Marriage has legal parts, but it should not feel only like a contract.","zh":"婚姻有法律部分，但不應只感覺像合約。"},{"en":"A loving marriage needs warmth as well as agreement.","zh":"有愛的婚姻除了協議，也需要溫暖。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"take this point","meaning":"明白這一點；接受這一點","examples":[{"en":"The writer takes this point but does not fully agree.","zh":"作者明白這一點，但並不完全同意。"},{"en":"Take this point means understand and accept that an argument has some truth.","zh":"take this point 指理解並接受某個論點有一定道理。"},{"en":"I take your point about costs, but quality also matters.","zh":"我明白你關於成本的看法，但質素也很重要。"},{"en":"Writers use this phrase to sound fair before disagreeing partly.","zh":"作者用這個片語在部分不同意前顯得公平。"},{"en":"The writer takes the concern about cold marriage seriously, but still rejects passion as essential.","zh":"作者認真看待冷淡婚姻的憂慮，但仍拒絕把激情視為必要。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"completely devoid of","meaning":"完全沒有","examples":[{"en":"A marriage completely devoid of warmth may feel lonely.","zh":"一段完全沒有溫暖的婚姻可能令人感到孤單。"},{"en":"Completely devoid of means totally without something.","zh":"completely devoid of 指完全沒有某物。"},{"en":"A classroom completely devoid of encouragement can make students afraid to try.","zh":"完全沒有鼓勵的課室會令學生害怕嘗試。"},{"en":"A home devoid of kindness may feel cold even if it is organised.","zh":"完全沒有善意的家，即使井井有條，也可能感覺冰冷。"},{"en":"Marriage should not be completely devoid of affection, even if passion is not central.","zh":"婚姻不應完全沒有感情，即使激情不是核心。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"warmth, tenderness or attraction","meaning":"溫暖、溫柔和吸引力","examples":[{"en":"A marriage needs some warmth, tenderness or attraction.","zh":"婚姻需要一些溫暖、溫柔或吸引力。"},{"en":"Warmth, tenderness or attraction means kindness, gentle care, or emotional pull between partners.","zh":"warmth, tenderness or attraction 指伴侶之間的善意、溫柔照顧或情感吸引。"},{"en":"Warmth appears when partners greet each other kindly after a long day.","zh":"伴侶在漫長一天後溫柔打招呼，就是溫暖。"},{"en":"Tenderness matters when one partner is tired, sick, or afraid.","zh":"當一方疲倦、生病或害怕時，溫柔很重要。"},{"en":"These qualities keep marriage human, not merely efficient.","zh":"這些特質讓婚姻有人味，而不只是有效率。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"leave both partners lonely","meaning":"令雙方都感到孤單","examples":[{"en":"A cold marriage may leave both partners lonely.","zh":"冷淡的婚姻可能令雙方都感到孤單。"},{"en":"Leave both partners lonely means make both people feel emotionally isolated.","zh":"leave both partners lonely 指令兩個人在情感上都感到孤立。"},{"en":"Two people can live in the same home yet still feel lonely.","zh":"兩個人可以住在同一個家，卻仍然感到孤單。"},{"en":"If partners never listen or show care, marriage may leave them lonely.","zh":"如果伴侶從不聆聽或表達關心，婚姻可能令他們都孤單。"},{"en":"Warmth and communication are needed so marriage does not become isolation.","zh":"婚姻需要溫暖和溝通，才不會變成孤立。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"merely efficient housemates","meaning":"只是有效率的同屋人","examples":[{"en":"Few people want to be merely efficient housemates.","zh":"很少人想只是做有效率的同屋人。"},{"en":"Merely efficient housemates are people who share tasks well but lack emotional closeness.","zh":"merely efficient housemates 指能好好分工但缺乏情感親密的人。"},{"en":"Two roommates may be efficient housemates if they split bills and clean on time.","zh":"如果兩名室友分擔帳單並準時清潔，他們可能是有效率的同屋人。"},{"en":"Marriage should include more than smooth organisation and shared chores.","zh":"婚姻應包括比順暢安排和共同家務更多的東西。"},{"en":"People need affection so they do not feel like housemates only.","zh":"人需要感情，才不會覺得自己只是同屋人。"}],"source":"2017 Q4.pdf","sourcePage":10},{"front":"make sacrifice feel lighter","meaning":"令犧牲感覺輕鬆一點","examples":[{"en":"Romance can make sacrifice feel lighter.","zh":"浪漫可以令犧牲感覺輕鬆一點。"},{"en":"Make sacrifice feel lighter means make difficult giving or effort feel easier to bear.","zh":"make sacrifice feel lighter 指令困難的付出或努力較容易承受。"},{"en":"Parents’ love can make sleepless nights feel lighter when caring for a baby.","zh":"父母的愛可以令照顧嬰兒時的不眠夜感覺輕鬆一點。"},{"en":"A kind word can make sacrifice feel lighter because the effort feels noticed.","zh":"一句溫柔說話可以令犧牲感覺輕鬆，因為付出被看見。"},{"en":"Romance helps, but long-term sacrifice still needs commitment.","zh":"浪漫有幫助，但長期犧牲仍需要承諾。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"remind a couple that","meaning":"提醒一對夫婦","examples":[{"en":"Romance can remind a couple that they are chosen companions.","zh":"浪漫可以提醒一對夫婦，他們是彼此選擇的伴侶。"},{"en":"Remind a couple that means help two partners remember an important truth.","zh":"remind a couple that 指幫助兩位伴侶記起一個重要事實。"},{"en":"An anniversary dinner can remind a couple that they began with hope.","zh":"周年晚餐可以提醒一對夫婦，他們當初是帶着希望開始的。"},{"en":"Small loving gestures remind partners that they are more than task-sharers.","zh":"小小愛意舉動提醒伴侶，他們不只是分工的人。"},{"en":"Romance can remind a couple why they choose each other daily.","zh":"浪漫可以提醒一對夫婦，他們為何每天選擇彼此。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"chosen companions","meaning":"彼此選擇的伴侶","examples":[{"en":"A married couple should feel like chosen companions.","zh":"已婚夫婦應感覺像彼此選擇的伴侶。"},{"en":"Chosen companions are people who stay together because they freely value and choose each other.","zh":"chosen companions 指因自由珍視並選擇彼此而同行的人。"},{"en":"Friends become chosen companions when they support each other through life.","zh":"朋友在人生中互相支持時，可以成為彼此選擇的伴侶。"},{"en":"Marriage should not feel like duty only; partners should feel chosen.","zh":"婚姻不應只感覺像責任；伴侶應感到自己是被選擇的。"},{"en":"The idea of chosen companions connects affection with commitment.","zh":"彼此選擇的伴侶這個概念，把感情和承諾連接起來。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"that said","meaning":"話雖如此","examples":[{"en":"That said, affection is not the same as initial passion.","zh":"話雖如此，感情並不等於最初的激情。"},{"en":"That said means after accepting the previous point, I want to add a different point.","zh":"that said 指接受前一點後，想補充另一個不同重點。"},{"en":"The film is beautiful; that said, its ending is too rushed.","zh":"這部電影很美；話雖如此，它的結尾太倉促。"},{"en":"This phrase helps a writer agree partly but continue the argument.","zh":"這個片語幫助作者部分同意，但繼續論證。"},{"en":"The writer uses it to separate affection from early romantic excitement.","zh":"作者用它把感情和初期浪漫刺激區分開來。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"prove only that","meaning":"只證明","examples":[{"en":"This argument proves only that affection matters.","zh":"這個論點只證明感情很重要。"},{"en":"Prove only that means show just one limited conclusion, not a wider claim.","zh":"prove only that 指只顯示一個有限結論，而不是更廣泛主張。"},{"en":"One high mark proves only that a student did well on one test.","zh":"一次高分只證明學生在一次測驗中表現好。"},{"en":"The need for warmth proves only that affection matters, not that passion is essential.","zh":"對溫暖的需要只證明感情重要，不證明激情必不可少。"},{"en":"This phrase limits what an argument can fairly show.","zh":"這個片語限制一個論點能公平證明的範圍。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"affection matters","meaning":"感情很重要","examples":[{"en":"The argument proves that affection matters in marriage.","zh":"這個論點證明感情在婚姻中很重要。"},{"en":"Affection matters means warmth, care, and fondness are important.","zh":"affection matters 指溫暖、關心和喜愛很重要。"},{"en":"Affection matters when a partner feels tired and needs kindness.","zh":"當伴侶疲倦而需要善意時，感情很重要。"},{"en":"A marriage without affection may become cold, even if it is organised.","zh":"沒有感情的婚姻即使有條理，也可能變得冰冷。"},{"en":"Affection matters, but it can grow through respect and daily care.","zh":"感情很重要，但它可以透過尊重和每日關心而成長。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"initial romantic passion","meaning":"最初的浪漫激情","examples":[{"en":"Initial romantic passion is not always necessary.","zh":"最初的浪漫激情並不總是必要。"},{"en":"Initial romantic passion means strong romantic excitement at the beginning of a relationship.","zh":"initial romantic passion 指一段關係開始時強烈的浪漫興奮。"},{"en":"Some couples begin with friendship rather than initial romantic passion.","zh":"有些伴侶由友誼開始，而不是由最初的浪漫激情開始。"},{"en":"Initial romantic passion may fade unless it grows into trust and respect.","zh":"最初的浪漫激情若不發展成信任和尊重，可能會淡去。"},{"en":"Marriage can still become happy if affection develops slowly.","zh":"如果感情慢慢發展，婚姻仍可以變得幸福。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"work up to a point","meaning":"在某程度上有效","examples":[{"en":"Romantic love works up to a point.","zh":"浪漫愛情在某程度上有效。"},{"en":"Work up to a point means be useful or effective only within limits.","zh":"work up to a point 指只在一定限制內有用或有效。"},{"en":"Memorising answers works up to a point, but students also need understanding.","zh":"背誦答案在某程度上有效，但學生也需要理解。"},{"en":"Romance works up to a point because it can begin love but not solve every problem.","zh":"浪漫在某程度上有效，因為它可以開始愛，卻不能解決所有問題。"},{"en":"This phrase shows that something has value but not unlimited power.","zh":"這個片語顯示某事有價值，但力量不是無限的。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"beyond that point","meaning":"超過那個程度之後","examples":[{"en":"Beyond that point, romance must deepen or fade.","zh":"超過那個程度之後，浪漫必須加深或淡去。"},{"en":"Beyond that point means after a certain limit, stage, or moment.","zh":"beyond that point 指超過某個限制、階段或時刻之後。"},{"en":"Practice helps beginners; beyond that point, they need detailed feedback.","zh":"練習能幫助初學者；超過那個程度之後，他們需要詳細回饋。"},{"en":"Romance can carry a couple at first, but beyond that point character matters more.","zh":"浪漫起初可以支撐伴侶，但超過那個程度之後，品格更重要。"},{"en":"The phrase marks the moment when early excitement is no longer enough.","zh":"這個片語標示初期興奮不再足夠的時刻。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"deepen or fade","meaning":"加深或淡去","examples":[{"en":"Romantic love must either deepen or fade.","zh":"浪漫愛情必須加深或淡去。"},{"en":"Deepen or fade means become stronger and more meaningful, or gradually become weaker.","zh":"deepen or fade 指變得更強更有意義，或逐漸變弱。"},{"en":"A friendship may deepen through honesty or fade through neglect.","zh":"友誼可能因誠實而加深，也可能因忽視而淡去。"},{"en":"Passion deepens when it grows into trust, patience, and loyalty.","zh":"當激情發展成信任、耐性和忠誠，它就會加深。"},{"en":"If romance does not deepen, everyday pressure may make it fade.","zh":"如果浪漫沒有加深，日常壓力可能令它淡去。"}],"source":"2017 Q4.pdf","sourcePage":11},{"front":"intense passion","meaning":"強烈激情","examples":[{"en":"Many marriages begin with intense passion.","zh":"許多婚姻由強烈激情開始。"},{"en":"Intense passion is very strong emotion, attraction, or desire.","zh":"intense passion 指非常強烈的情感、吸引或渴望。"},{"en":"Intense passion may make two people feel that nothing else matters.","zh":"強烈激情可能令人覺得其他一切都不重要。"},{"en":"A marriage that begins with intense passion still needs communication later.","zh":"由強烈激情開始的婚姻，後來仍需要溝通。"},{"en":"Passion is powerful at the start, but it must mature to last.","zh":"激情在開始時很有力量，但必須成熟才會持久。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"collapse when","meaning":"在……時崩潰","examples":[{"en":"Some marriages collapse when poor communication takes over.","zh":"有些婚姻在溝通不良佔上風時崩潰。"},{"en":"Collapse when means fail or break down at the time a certain problem happens.","zh":"collapse when 指在某個問題發生時失敗或瓦解。"},{"en":"A project may collapse when team members stop sharing information.","zh":"當團隊成員停止分享資訊，項目可能會崩潰。"},{"en":"A relationship can collapse when anger replaces listening.","zh":"當憤怒取代聆聽，關係可能會崩潰。"},{"en":"The phrase shows the condition that causes failure.","zh":"這個片語顯示造成失敗的條件。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"selfishness, pride and poor communication","meaning":"自私、驕傲和溝通不良","examples":[{"en":"Selfishness, pride and poor communication can damage a marriage.","zh":"自私、驕傲和溝通不良可以傷害婚姻。"},{"en":"Selfishness, pride and poor communication mean thinking only of oneself, refusing humility, and failing to talk well.","zh":"selfishness, pride and poor communication 指只想到自己、拒絕謙卑，以及無法好好溝通。"},{"en":"Selfishness appears when one partner always demands comfort but gives little help.","zh":"當一方總要求舒服卻很少幫忙，自私就出現了。"},{"en":"Pride makes apology difficult, and poor communication lets resentment grow.","zh":"驕傲令道歉困難，而溝通不良讓怨氣增長。"},{"en":"These problems can destroy marriage even when romance once felt strong.","zh":"即使浪漫曾經強烈，這些問題也能摧毀婚姻。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"take over","meaning":"佔上風；主導","examples":[{"en":"Poor communication can take over when respect disappears.","zh":"當尊重消失，溝通不良可能佔上風。"},{"en":"Take over means become dominant or gain control of a situation.","zh":"take over 指變得主導或控制一個情況。"},{"en":"Panic can take over when people do not receive clear information.","zh":"當人們沒有收到清楚資訊，恐慌可能會佔上風。"},{"en":"In marriage, anger may take over if partners stop listening.","zh":"在婚姻中，如果伴侶停止聆聽，憤怒可能會主導。"},{"en":"Couples must protect respect before poor habits take over.","zh":"伴侶必須保護尊重，以免壞習慣佔上風。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, some friendship-based marriages become happy.","zh":"與此同時，有些以友誼為基礎的婚姻變得幸福。"},{"en":"Meanwhile means at the same time, or in contrast with what was just mentioned.","zh":"meanwhile 指同一時間，或與剛才提到的情況形成對比。"},{"en":"Some shops closed; meanwhile, others adapted and survived.","zh":"有些店舖結業；與此同時，另一些適應並生存下來。"},{"en":"This word can introduce another situation happening alongside the first.","zh":"這個詞可以引出與第一個情況同時存在的另一情況。"},{"en":"Here, it contrasts passionate marriages that fail with quiet marriages that grow.","zh":"在這裏，它對比失敗的激情婚姻和成長的安靜婚姻。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"friendship-based marriages","meaning":"以友誼為基礎的婚姻","examples":[{"en":"Some friendship-based marriages become deeply happy.","zh":"有些以友誼為基礎的婚姻變得深切幸福。"},{"en":"Friendship-based marriages are marriages built mainly on respect, companionship, and trust.","zh":"friendship-based marriages 指主要建基於尊重、陪伴和信任的婚姻。"},{"en":"A friendship-based marriage may begin quietly before affection grows.","zh":"以友誼為基礎的婚姻可能安靜開始，然後感情慢慢增長。"},{"en":"Such marriages can become strong because the partners already know how to listen.","zh":"這類婚姻可以變得穩固，因為伴侶已懂得如何聆聽。"},{"en":"Friendship can be a steady foundation for lasting love.","zh":"友誼可以成為持久愛情的穩定基礎。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"admire, protect and cherish each other","meaning":"欣賞、保護和珍惜彼此","examples":[{"en":"A couple can learn to admire, protect and cherish each other.","zh":"一對伴侶可以學會欣賞、保護和珍惜彼此。"},{"en":"Admire, protect and cherish each other means respect each other’s qualities, keep each other safe, and value each other deeply.","zh":"admire, protect and cherish each other 指尊重彼此特質、保護彼此安全，並深深重視彼此。"},{"en":"Partners admire each other when they notice effort and character.","zh":"伴侶留意到彼此的努力和品格時，就是在欣賞彼此。"},{"en":"They protect each other by refusing to humiliate each other in public.","zh":"他們拒絕在公眾面前羞辱對方，就是在保護彼此。"},{"en":"They cherish each other through small acts that say, “You matter.”","zh":"他們透過小小行動說出「你很重要」，就是在珍惜彼此。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, the kind of love matters more than the beginning.","zh":"換句話說，愛的種類比開始方式更重要。"},{"en":"In other words introduces the same idea again in a clearer or simpler way.","zh":"in other words 用更清楚或更簡單的方式重新表達同一個想法。"},{"en":"She needs rest; in other words, she should not take another job now.","zh":"她需要休息；換句話說，她現在不應再接另一份工作。"},{"en":"This phrase helps readers understand the main point of an argument.","zh":"這個片語幫助讀者理解論點的重點。"},{"en":"Here, it explains that lasting love matters more than how romance starts.","zh":"在這裏，它解釋持久的愛比浪漫如何開始更重要。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"survive time","meaning":"經得起時間考驗","examples":[{"en":"The real question is what kind of love can survive time.","zh":"真正的問題是甚麼樣的愛能經得起時間考驗。"},{"en":"Survive time means continue to exist and stay strong as years pass.","zh":"survive time 指隨着年月過去仍然存在並保持強韌。"},{"en":"A friendship survives time when people stay loyal despite distance.","zh":"即使相隔很遠，人們仍保持忠誠，友誼就能經得起時間考驗。"},{"en":"Love survives time when it adapts to illness, routine, and change.","zh":"當愛能適應疾病、日常生活和改變，它就經得起時間考驗。"},{"en":"Marriage needs love that can survive time, not only a beautiful beginning.","zh":"婚姻需要經得起時間考驗的愛，而不只是美麗開端。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"grow into respect","meaning":"發展成尊重","examples":[{"en":"Romance must grow into respect to serve a marriage.","zh":"浪漫必須發展成尊重，才能有助婚姻。"},{"en":"Grow into respect means gradually become a relationship based on valuing and honouring each other.","zh":"grow into respect 指逐漸變成建基於珍視和敬重彼此的關係。"},{"en":"A friendship may grow into respect when people see each other’s character.","zh":"當人們看見彼此品格，友誼可能發展成尊重。"},{"en":"Romance grows into respect when partners listen even during disagreement.","zh":"當伴侶即使在分歧中仍聆聽，浪漫就會發展成尊重。"},{"en":"Without respect, passion may become selfish or careless.","zh":"沒有尊重，激情可能變得自私或粗心。"}],"source":"2017 Q4.pdf","sourcePage":12},{"front":"truly serve a marriage","meaning":"真正有助於婚姻","examples":[{"en":"Only respect can truly serve a marriage over time.","zh":"只有尊重才能長期真正有助於婚姻。"},{"en":"Truly serve a marriage means genuinely help a marriage survive, improve, and remain healthy.","zh":"truly serve a marriage 指真正幫助婚姻生存、改善並保持健康。"},{"en":"Honest communication truly serves a marriage because it prevents hidden anger.","zh":"誠實溝通真正有助於婚姻，因為它防止隱藏怒氣。"},{"en":"Romantic gestures serve marriage only when they are supported by care.","zh":"浪漫舉動只有在有關心支撐時，才有助婚姻。"},{"en":"Respect serves marriage because it protects both partners’ dignity.","zh":"尊重有助婚姻，因為它保護雙方尊嚴。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, romantic love is not indispensable.","zh":"總括而言，浪漫愛情並非不可或缺。"},{"en":"All things considered means after thinking about all the important points.","zh":"all things considered 指在思考所有重要因素之後。"},{"en":"All things considered, moving closer to school may save time and stress.","zh":"總括而言，搬近學校可能節省時間和壓力。"},{"en":"This phrase is useful near the end of an essay to give a final judgement.","zh":"這個片語在作文結尾附近很有用，可以提出最終判斷。"},{"en":"The writer uses it to conclude after weighing both romance and responsibility.","zh":"作者在衡量浪漫和責任後，用它作結論。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"a qualified no","meaning":"有保留的否定答案","examples":[{"en":"The writer answers the question with a qualified no.","zh":"作者以有保留的否定答案回答這個問題。"},{"en":"A qualified no is a negative answer with limits, conditions, or careful explanation.","zh":"a qualified no 指帶有限制、條件或仔細解釋的否定答案。"},{"en":"If asked whether phones are bad for students, a teacher may give a qualified no.","zh":"如果被問到手機是否對學生有害，老師可能會給出有保留的否定答案。"},{"en":"A qualified no sounds balanced because it does not reject everything completely.","zh":"有保留的否定答案聽起來較平衡，因為它不是完全否定一切。"},{"en":"The writer says romance is not essential, while admitting it can enrich marriage.","zh":"作者說浪漫並非必要，同時承認它可以豐富婚姻。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"enrich a marriage","meaning":"豐富一段婚姻","examples":[{"en":"Romantic love can enrich a marriage.","zh":"浪漫愛情可以豐富一段婚姻。"},{"en":"Enrich a marriage means make a marriage fuller, warmer, or more meaningful.","zh":"enrich a marriage 指令婚姻更充實、更溫暖或更有意義。"},{"en":"Shared hobbies can enrich a marriage by giving couples joyful time together.","zh":"共同興趣可以透過給伴侶快樂相處時間來豐富婚姻。"},{"en":"Romance enriches marriage when it adds affection without replacing responsibility.","zh":"當浪漫增添感情而不取代責任，它就豐富了婚姻。"},{"en":"Something can enrich marriage without being its essential foundation.","zh":"某事可以豐富婚姻，但不一定是婚姻的基本基礎。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"indispensable foundation","meaning":"不可或缺的基礎","examples":[{"en":"Romantic love is not the indispensable foundation of a happy marriage.","zh":"浪漫愛情不是幸福婚姻不可或缺的基礎。"},{"en":"An indispensable foundation is a basic support that is absolutely necessary.","zh":"indispensable foundation 指絕對必要的基本支撐。"},{"en":"Trust is an indispensable foundation of teamwork because members must rely on each other.","zh":"信任是團隊合作不可或缺的基礎，因為成員必須依靠彼此。"},{"en":"If something is indispensable, success is impossible without it.","zh":"如果某事不可或缺，沒有它就不可能成功。"},{"en":"The writer argues that romance is valuable but not the indispensable foundation.","zh":"作者認為浪漫有價值，但不是不可或缺的基礎。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"trust, commitment, maturity and kindness","meaning":"信任、承諾、成熟和善良","examples":[{"en":"Trust, commitment, maturity and kindness are more necessary than passion.","zh":"信任、承諾、成熟和善良比激情更必要。"},{"en":"Trust, commitment, maturity and kindness mean belief in each other, loyalty, emotional growth, and gentle care.","zh":"trust, commitment, maturity and kindness 指相信彼此、忠誠、情感成熟和溫柔關心。"},{"en":"Trust helps couples feel safe, while commitment keeps them present during difficulty.","zh":"信任幫助伴侶感到安全，而承諾讓他們在困難中仍然留下。"},{"en":"Maturity helps people apologise, and kindness softens daily pressure.","zh":"成熟幫助人道歉，善良則緩和日常壓力。"},{"en":"These qualities support marriage after excitement becomes ordinary.","zh":"這些特質在刺激變成日常後仍支撐婚姻。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"far more necessary","meaning":"遠比……更必要","examples":[{"en":"Trust and kindness are far more necessary than romance.","zh":"信任和善良遠比浪漫更必要。"},{"en":"Far more necessary means much more important or needed.","zh":"far more necessary 指重要或需要的程度高得多。"},{"en":"For a child, safety is far more necessary than expensive toys.","zh":"對孩子來說，安全遠比昂貴玩具更必要。"},{"en":"In marriage, honesty is far more necessary than perfect photographs.","zh":"在婚姻中，誠實遠比完美照片更必要。"},{"en":"Romance is pleasant, but trust is far more necessary for long-term peace.","zh":"浪漫令人愉快，但信任對長期平安遠比浪漫更必要。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"beauty fades","meaning":"美貌褪去","examples":[{"en":"Kindness remains when beauty fades.","zh":"當美貌褪去，善良仍然留下。"},{"en":"Beauty fades means physical attractiveness or surface charm becomes weaker over time.","zh":"beauty fades 指外貌吸引或表面魅力隨時間變弱。"},{"en":"Flowers are beautiful, but their beauty fades after several days.","zh":"鮮花很美，但幾天後美麗會褪去。"},{"en":"In marriage, beauty may fade, but kindness can still make a person feel loved.","zh":"在婚姻中，美貌可能褪去，但善良仍能令人感到被愛。"},{"en":"The phrase reminds us that lasting love needs deeper qualities.","zh":"這個片語提醒我們，持久的愛需要更深層特質。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"routine arrives","meaning":"日常生活來臨","examples":[{"en":"Commitment matters when routine arrives.","zh":"當日常生活來臨，承諾就變得重要。"},{"en":"Routine arrives means daily ordinary life begins and excitement becomes less constant.","zh":"routine arrives 指普通日常生活開始，而刺激不再持續。"},{"en":"After a holiday, routine arrives when people return to school and work.","zh":"假期後，人們回到學校和工作，日常生活就來臨。"},{"en":"Marriage is tested when routine arrives and small duties repeat every day.","zh":"當日常生活來臨，小責任每天重複，婚姻就受到考驗。"},{"en":"Commitment keeps love steady after the first excitement fades.","zh":"最初興奮淡去後，承諾讓愛保持穩定。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"difficulties test the couple’s promises","meaning":"困難考驗夫妻的承諾","examples":[{"en":"Difficulties test the couple’s promises.","zh":"困難考驗夫妻的承諾。"},{"en":"Difficulties test promises means hard situations show whether people truly keep what they said.","zh":"difficulties test promises 指艱難情況會顯示人是否真正遵守自己說過的話。"},{"en":"Illness can test a family’s promise to support one another.","zh":"疾病可以考驗家庭彼此支持的承諾。"},{"en":"Couples prove commitment when they keep caring during pressure.","zh":"當伴侶在壓力中仍繼續關心，他們就證明了承諾。"},{"en":"Promises are easy in moonlight, but difficulties reveal their strength.","zh":"在月光下承諾很容易，但困難會揭示承諾有多強。"}],"source":"2017 Q4.pdf","sourcePage":13},{"front":"discover true beauty","meaning":"發現真正的美","examples":[{"en":"Romeo believes he has discovered true beauty.","zh":"羅密歐相信自己發現了真正的美。"},{"en":"Discover true beauty means find what seems to be real, deep, or perfect beauty.","zh":"discover true beauty 指找到看似真實、深刻或完美的美。"},{"en":"A person may discover true beauty in kindness rather than appearance.","zh":"一個人可能在善良而不是外貌中發現真正的美。"},{"en":"Romeo’s discovery feels powerful because he thinks Juliet changes his whole world.","zh":"羅密歐的發現感覺很有力量，因為他認為茱麗葉改變了他的整個世界。"},{"en":"The phrase can be romantic, but true beauty in marriage also includes character.","zh":"這個片語可以很浪漫，但婚姻中的真正美也包括品格。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"admire the spark","meaning":"欣賞那一點火花","examples":[{"en":"We can admire the spark of romantic love.","zh":"我們可以欣賞浪漫愛情的那一點火花。"},{"en":"Admire the spark means appreciate the first bright energy or excitement of something.","zh":"admire the spark 指欣賞某事最初明亮的能量或興奮。"},{"en":"We can admire the spark of a new idea even before it becomes a full plan.","zh":"即使新想法還未變成完整計劃，我們也可以欣賞它的一點火花。"},{"en":"The spark of romance can be beautiful because it begins connection.","zh":"浪漫的火花可以很美，因為它開始了連繫。"},{"en":"Admiring the spark does not mean mistaking it for the whole fire.","zh":"欣賞火花不代表把它誤當成整團火。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"mistake it for the whole fire","meaning":"誤把它當成整團火","examples":[{"en":"We should not mistake the spark for the whole fire.","zh":"我們不應誤把那一點火花當成整團火。"},{"en":"Mistake it for the whole fire means wrongly treat a small beginning as the complete thing.","zh":"mistake it for the whole fire 指錯把一個小開始當成完整事物。"},{"en":"A good first lesson should not be mistaken for the whole education.","zh":"一堂好的第一課不應被誤當成整個教育。"},{"en":"Initial passion is only a spark if it has not grown into trust and commitment.","zh":"如果最初激情還未發展成信任和承諾，它只是一點火花。"},{"en":"This image warns against confusing romantic beginnings with lasting marriage.","zh":"這個意象警告我們不要把浪漫開端和持久婚姻混為一談。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"think about marriage","meaning":"思考婚姻","examples":[{"en":"Young people thinking about marriage should examine character.","zh":"思考婚姻的年輕人應審視品格。"},{"en":"Think about marriage means seriously consider choosing a life partner and married life.","zh":"think about marriage 指認真考慮選擇人生伴侶和婚姻生活。"},{"en":"People thinking about marriage should discuss money, family, and future plans.","zh":"思考婚姻的人應討論金錢、家庭和未來計劃。"},{"en":"Thinking about marriage requires more than imagining a beautiful wedding.","zh":"思考婚姻需要的不只是想像美麗婚禮。"},{"en":"Young people should ask whether love can survive ordinary life.","zh":"年輕人應問愛是否能經得起普通生活考驗。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"the wiser action is clear","meaning":"更明智的做法很清楚","examples":[{"en":"For young people, the wiser action is clear.","zh":"對年輕人來說，更明智的做法很清楚。"},{"en":"The wiser action is clear means the better choice is easy to understand after careful thought.","zh":"the wiser action is clear 指經過仔細思考後，較好的選擇很容易理解。"},{"en":"If a road is dangerous, the wiser action is clear: slow down.","zh":"如果道路危險，更明智的做法很清楚：放慢速度。"},{"en":"When choosing a partner, the wiser action is to examine character, not only chemistry.","zh":"選擇伴侶時，更明智的做法是審視品格，而不只是吸引力。"},{"en":"This phrase prepares readers for practical advice.","zh":"這個片語為讀者準備實用建議。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"enjoy romance","meaning":"享受浪漫","examples":[{"en":"Young people can enjoy romance without worshipping it.","zh":"年輕人可以享受浪漫，而不崇拜它。"},{"en":"Enjoy romance means appreciate romantic feelings, gestures, and moments.","zh":"enjoy romance 指欣賞浪漫感情、舉動和時刻。"},{"en":"A couple may enjoy romance through walks, letters, or quiet dinners.","zh":"伴侶可以透過散步、書信或安靜晚餐享受浪漫。"},{"en":"Enjoying romance is healthy when people do not let it replace judgement.","zh":"當人們不讓浪漫取代判斷，享受浪漫是健康的。"},{"en":"Romance can be enjoyed as part of love, not treated as the whole of love.","zh":"浪漫可以作為愛的一部分被享受，而不是被視為愛的全部。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"examine character","meaning":"審視品格","examples":[{"en":"Young people should examine character before marriage.","zh":"年輕人婚前應審視品格。"},{"en":"Examine character means look carefully at a person’s honesty, kindness, responsibility, and values.","zh":"examine character 指仔細觀察一個人的誠實、善良、責任感和價值觀。"},{"en":"A person’s character appears in how they treat waiters, parents, and tired partners.","zh":"一個人的品格會從他如何對待侍應、父母和疲倦的伴侶中顯現。"},{"en":"Before marriage, people should examine character more carefully than appearance.","zh":"婚前，人們應比外貌更仔細地審視品格。"},{"en":"Character matters because it shapes daily life after romance becomes quiet.","zh":"品格重要，因為當浪漫變安靜後，它會塑造日常生活。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"treasure emotion","meaning":"珍惜情感","examples":[{"en":"It is natural to treasure emotion in love.","zh":"在愛情中珍惜情感是自然的。"},{"en":"Treasure emotion means value feelings deeply and treat them as important.","zh":"treasure emotion 指深深重視感受，並把它們視為重要。"},{"en":"People treasure emotion when they keep letters or remember meaningful words.","zh":"人們保存信件或記住有意義的話，就是珍惜情感。"},{"en":"Emotion should be treasured, but it should also be guided by wisdom.","zh":"情感應被珍惜，但也應受智慧引導。"},{"en":"In marriage, feelings matter, but they need trust and action to last.","zh":"在婚姻中，感受重要，但它們需要信任和行動才能持久。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"build trust","meaning":"建立信任","examples":[{"en":"A couple must build trust over time.","zh":"一對伴侶必須隨着時間建立信任。"},{"en":"Build trust means gradually create confidence through honest and reliable actions.","zh":"build trust 指透過誠實可靠的行動逐漸建立信心。"},{"en":"Friends build trust when they keep secrets and promises.","zh":"朋友保守秘密和遵守承諾時，就會建立信任。"},{"en":"Couples build trust by telling the truth even when it is uncomfortable.","zh":"伴侶即使在不舒服時仍說真話，就是建立信任。"},{"en":"Trust is built slowly, but once built, it can hold a marriage steady.","zh":"信任建立得慢，但一旦建立，就能穩定支撐婚姻。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"seek not merely someone who","meaning":"不只尋找能夠……的人","examples":[{"en":"Seek not merely someone who can make your heart race.","zh":"不只尋找能令你心跳加速的人。"},{"en":"Seek not merely someone who means do not look only for a person with one attractive quality.","zh":"seek not merely someone who 指不要只尋找擁有某一吸引特質的人。"},{"en":"Seek not merely someone who praises you, but someone who tells you the truth kindly.","zh":"不只尋找讚美你的人，也要尋找溫柔說真話的人。"},{"en":"In love, people should not seek merely excitement while ignoring character.","zh":"在愛情中，人不應只尋找刺激而忽略品格。"},{"en":"This phrase gives advice by warning against a narrow choice.","zh":"這個片語透過警告狹窄選擇來給予建議。"}],"source":"2017 Q4.pdf","sourcePage":14},{"front":"make the heart race","meaning":"令心跳加速","examples":[{"en":"Romance can make the heart race.","zh":"浪漫可以令心跳加速。"},{"en":"Make the heart race means cause strong excitement, nervousness, or attraction.","zh":"make the heart race 指引起強烈興奮、緊張或吸引。"},{"en":"A message from someone you like can make your heart race.","zh":"喜歡的人傳來一則訊息，可能會令你心跳加速。"},{"en":"Heart-racing romance feels powerful, but it may not show whether someone is kind.","zh":"令人心跳加速的浪漫感覺很強烈，但未必顯示對方是否善良。"},{"en":"Marriage should not be based only on what makes the heart race.","zh":"婚姻不應只建基於令心跳加速的東西。"}],"source":"2017 Q4.pdf","sourcePage":15},{"front":"with whom the heart can rest","meaning":"能讓心安定下來的人","examples":[{"en":"Choose someone with whom the heart can rest.","zh":"選擇一個能讓心安定下來的人。"},{"en":"With whom the heart can rest means with whom you feel safe, calm, trusted, and at peace.","zh":"with whom the heart can rest 指和那人在一起時，你感到安全、平靜、被信任和安心。"},{"en":"A person with whom the heart can rest listens without mocking your fears.","zh":"能讓心安定下來的人會聆聽你的恐懼，而不嘲笑你。"},{"en":"Excitement may start love, but peace helps love become home.","zh":"刺激可能開始愛情，但平安幫助愛變成家。"},{"en":"The best partner is not only thrilling, but also deeply safe.","zh":"最好的伴侶不只是令人心動，也令人深深安心。"}],"source":"2017 Q4.pdf","sourcePage":15}],"dse/writing/part-b/2017/Q5":[{"front":"living heritage","meaning":"活態文化遺產","examples":[{"en":"Egg tarts and mahjong are part of Hong Kong’s living heritage.","zh":"蛋撻和麻雀是香港活態文化遺產的一部分。"},{"en":"Living heritage means traditions, skills, foods, games, and customs that are still practised in daily life.","zh":"活態文化遺產是仍在日常生活中被實踐的傳統、技藝、食物、遊戲和習俗。"},{"en":"A neighbourhood festival can be living heritage if local people still join it every year.","zh":"如果街坊每年仍然參與社區節慶，它就可以是活態文化遺產。"},{"en":"Living heritage matters because it connects history with people’s ordinary actions today.","zh":"活態文化遺產很重要，因為它把歷史與今天普通人的行動連繫起來。"},{"en":"If living heritage is not practised or taught, it may slowly disappear from everyday life.","zh":"如果活態文化遺產沒有被實踐或教授，它可能會慢慢從日常生活中消失。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"egg tarts","meaning":"蛋撻","examples":[{"en":"Traditional egg tarts are part of Hong Kong’s food culture.","zh":"傳統蛋撻是香港飲食文化的一部分。"},{"en":"Egg tarts are small pastries with a crust and a sweet egg custard filling.","zh":"蛋撻是一種小型酥皮點心，裏面有甜蛋漿餡。"},{"en":"Many people buy egg tarts from neighbourhood bakeries after school or work.","zh":"許多人放學或下班後，會到街坊麵包店買蛋撻。"},{"en":"Egg tarts carry cultural meaning because they connect food, memory, and local history.","zh":"蛋撻承載文化意義，因為它連繫食物、回憶和本地歷史。"},{"en":"Although egg tarts look simple, making them well requires skill and experience.","zh":"雖然蛋撻看起來簡單，但要做好它需要技巧和經驗。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"mahjong","meaning":"麻雀","examples":[{"en":"Mahjong is one of Hong Kong’s most recognisable social traditions.","zh":"麻雀是香港最具辨識度的社交傳統之一。"},{"en":"Mahjong is a tile-based game often played by four people, especially during family gatherings.","zh":"麻雀是一種通常由四人玩的牌類遊戲，常出現在家庭聚會中。"},{"en":"Many families play mahjong during Lunar New Year while chatting and eating snacks.","zh":"許多家庭在農曆新年期間一邊打麻雀，一邊聊天和吃小食。"},{"en":"Mahjong is culturally important because it brings different generations to the same table.","zh":"麻雀具有文化重要性，因為它把不同世代帶到同一張桌旁。"},{"en":"Mahjong should be understood not only as a game, but also as a social tradition.","zh":"麻雀不應只被理解為遊戲，也應被理解為一種社交傳統。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"in recent years","meaning":"近年","examples":[{"en":"In recent years, Hong Kong has become increasingly aware of everyday culture.","zh":"近年，香港越來越意識到日常文化的重要性。"},{"en":"In recent years means during the last few years up to the present time.","zh":"“In recent years” 指由最近數年至現在的一段時間。"},{"en":"In recent years, more schools have taught students about local customs and neighbourhood history.","zh":"近年，更多學校教學生認識本地習俗和社區歷史。"},{"en":"People may value ordinary traditions more in recent years because they fear losing them.","zh":"近年人們可能更重視普通傳統，因為他們害怕失去它們。"},{"en":"This phrase helps connect a present trend with changes that have happened recently.","zh":"這個說法有助把現在的趨勢與近年發生的改變連接起來。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"increasingly aware that","meaning":"越來越意識到","examples":[{"en":"Hong Kong has become increasingly aware that culture is not limited to monuments.","zh":"香港越來越意識到文化不限於紀念建築。"},{"en":"Increasingly aware that means gradually understanding something more clearly over time.","zh":"“Increasingly aware that” 指隨時間逐漸更清楚地理解某事。"},{"en":"Students are increasingly aware that mental health is as important as exam results.","zh":"學生越來越意識到心理健康和考試成績一樣重要。"},{"en":"A city may become increasingly aware that small traditions also deserve protection.","zh":"一個城市可能越來越意識到小傳統也值得保護。"},{"en":"This phrase shows a growing understanding, not a sudden discovery.","zh":"這個說法顯示理解逐漸增長，而不是突然發現。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"exist only in","meaning":"只存在於","examples":[{"en":"Culture does not exist only in grand monuments or museum cabinets.","zh":"文化並不只存在於宏偉紀念建築或博物館展櫃中。"},{"en":"Exist only in means be found only in one place, form, or situation.","zh":"“Exist only in” 指只在某一個地方、形式或情況中存在。"},{"en":"Learning does not exist only in classrooms; it can also happen at home and in the community.","zh":"學習並不只存在於課室，也可以發生在家中和社區裏。"},{"en":"If culture existed only in museums, everyday habits would be ignored.","zh":"如果文化只存在於博物館，日常習慣便會被忽略。"},{"en":"This phrase is often used to challenge a narrow view of where something belongs.","zh":"這個說法常用來挑戰某事只屬於某處的狹窄看法。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"grand monuments","meaning":"宏偉紀念建築","examples":[{"en":"Culture does not exist only in grand monuments.","zh":"文化並不只存在於宏偉紀念建築之中。"},{"en":"Grand monuments are large and impressive buildings or structures built to remember people, events, or history.","zh":"宏偉紀念建築是大型而令人印象深刻，用來紀念人物、事件或歷史的建築或結構。"},{"en":"A city may have grand monuments, but its culture also lives in markets and family habits.","zh":"一個城市可能有宏偉紀念建築，但它的文化也存在於街市和家庭習慣中。"},{"en":"Grand monuments are easy to notice, while everyday heritage may need closer attention.","zh":"宏偉紀念建築容易被看見，而日常文化遺產則可能需要更仔細留意。"},{"en":"Mentioning grand monuments contrasts official history with ordinary daily culture.","zh":"提到宏偉紀念建築，可以把官方歷史與普通日常文化作對比。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"old temples","meaning":"古老廟宇","examples":[{"en":"Culture also exists beyond old temples and museums.","zh":"文化也存在於古老廟宇和博物館以外。"},{"en":"Old temples are long-standing religious buildings where people worship, pray, or keep traditional practices.","zh":"古老廟宇是歷史悠久的宗教建築，人們在那裏敬拜、祈禱或保留傳統習俗。"},{"en":"Old temples may preserve festivals, rituals, stories, and community memories.","zh":"古老廟宇可能保存節日、儀式、故事和社區記憶。"},{"en":"Culture can be found in old temples, but it also appears in food, games, and speech.","zh":"文化可以存在於古老廟宇，也可以出現在食物、遊戲和語言中。"},{"en":"This phrase reminds us that heritage includes both sacred places and ordinary life.","zh":"這個說法提醒我們，文化遺產包括神聖地方，也包括普通生活。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"museum cabinets","meaning":"博物館展櫃","examples":[{"en":"Culture does not exist only in museum cabinets.","zh":"文化並不只存在於博物館展櫃中。"},{"en":"Museum cabinets are display cases that protect and show objects in museums.","zh":"博物館展櫃是博物館中用來保護和展示物件的展示櫃。"},{"en":"Old coins and pottery were kept safely inside museum cabinets.","zh":"古錢幣和陶器被安全地放在博物館展櫃裏。"},{"en":"If heritage stays only in museum cabinets, people may look at it but not practise it.","zh":"如果文化遺產只留在博物館展櫃中，人們可能只會觀看，而不會實踐它。"},{"en":"This phrase contrasts preserved objects with living traditions.","zh":"這個說法把被保存的物件與活生生的傳統作對比。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"lives in","meaning":"存在於","examples":[{"en":"Culture also lives in ordinary sights, sounds and smells.","zh":"文化也存在於普通的景象、聲音和氣味之中。"},{"en":"Lives in means exists actively within a place, habit, object, or experience.","zh":"“Lives in” 指活躍地存在於某個地方、習慣、物件或經驗之中。"},{"en":"Family history lives in old recipes that grandparents still cook.","zh":"家庭歷史存在於祖父母仍會烹調的舊食譜裏。"},{"en":"A city’s identity lives in daily sounds, street food, and the way people greet one another.","zh":"一個城市的身份存在於日常聲音、街頭食物和人們打招呼的方式中。"},{"en":"This phrase makes culture feel alive rather than frozen in the past.","zh":"這個說法令文化感覺有生命，而不是被凍結在過去。"}],"source":"2017 Q5.pdf","sourcePage":1},{"front":"a warm bakery","meaning":"溫暖的麵包店","examples":[{"en":"Culture lives in the smell of a warm bakery at four o’clock.","zh":"文化存在於四點鐘時溫暖麵包店的氣味裏。"},{"en":"A warm bakery is a bakery filled with heat and the smell of freshly baked bread or pastries.","zh":"溫暖的麵包店是充滿熱氣和新鮮麵包或糕點氣味的麵包店。"},{"en":"After school, students often pass a warm bakery and smell fresh egg tarts.","zh":"放學後，學生常經過溫暖的麵包店，聞到新鮮蛋撻的香氣。"},{"en":"A warm bakery can hold neighbourhood memories because many people visit it regularly.","zh":"溫暖的麵包店可以承載街坊回憶，因為許多人會定期光顧。"},{"en":"This phrase connects culture with ordinary food and familiar smells.","zh":"這個說法把文化與普通食物和熟悉氣味連接起來。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"the clatter of mahjong tiles","meaning":"麻雀牌碰撞聲","examples":[{"en":"Culture lives in the clatter of mahjong tiles on a family table.","zh":"文化存在於家庭桌上麻雀牌的碰撞聲中。"},{"en":"The clatter of mahjong tiles is the repeated clicking sound made when mahjong tiles touch one another.","zh":"麻雀牌碰撞聲是麻雀牌互相碰到時發出的重複清脆聲音。"},{"en":"During Lunar New Year, the clatter of mahjong tiles often fills the living room.","zh":"農曆新年期間，客廳常充滿麻雀牌碰撞聲。"},{"en":"This sound can remind people of family gatherings, jokes, and long conversations.","zh":"這種聲音可以令人想起家庭聚會、玩笑和長時間對話。"},{"en":"The clatter of mahjong tiles is culturally meaningful because it carries social memory.","zh":"麻雀牌碰撞聲具有文化意義，因為它承載社交記憶。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"mahjong tiles","meaning":"麻雀牌","examples":[{"en":"Mahjong tiles are familiar objects in many Hong Kong families.","zh":"麻雀牌是許多香港家庭熟悉的物件。"},{"en":"Mahjong tiles are small rectangular pieces used to play mahjong, usually marked with patterns or Chinese characters.","zh":"麻雀牌是用來打麻雀的小長方形牌，通常刻有圖案或中文字。"},{"en":"Players arrange mahjong tiles in front of them before each round begins.","zh":"每局開始前，玩家會把麻雀牌排列在自己面前。"},{"en":"Mahjong tiles are not only game pieces; they can also remind people of family time.","zh":"麻雀牌不只是遊戲工具，也可以令人想起家庭時光。"},{"en":"Old mahjong tiles may carry memories of grandparents, festivals, and home gatherings.","zh":"舊麻雀牌可能承載祖父母、節日和家庭聚會的回憶。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"family table","meaning":"家庭餐桌；家中桌子","examples":[{"en":"The clatter of mahjong tiles can be heard on a family table.","zh":"在家庭餐桌上可以聽到麻雀牌碰撞聲。"},{"en":"A family table is a table at home where family members eat, talk, play games, or gather.","zh":"家庭餐桌是家人吃飯、聊天、玩遊戲或聚在一起的家中桌子。"},{"en":"During dinner, the family table becomes a place for sharing news and stories.","zh":"晚飯時，家庭餐桌成為分享消息和故事的地方。"},{"en":"A family table can hold cultural memory because repeated habits happen around it.","zh":"家庭餐桌可以承載文化記憶，因為重複的習慣在它周圍發生。"},{"en":"In this context, the family table shows that heritage belongs inside ordinary homes.","zh":"在這個語境中，家庭餐桌顯示文化遺產屬於普通家庭生活。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"small rituals","meaning":"小儀式；日常習慣","examples":[{"en":"Culture lives in the small rituals of everyday life.","zh":"文化存在於日常生活的小儀式中。"},{"en":"Small rituals are repeated ordinary actions that carry personal, family, or cultural meaning.","zh":"小儀式是重複出現的普通行動，卻帶有個人、家庭或文化意義。"},{"en":"Drinking tea with grandparents every Sunday can be one of a family’s small rituals.","zh":"每逢星期日與祖父母飲茶，可以是家庭的小儀式之一。"},{"en":"Small rituals help people feel connected because they repeat familiar actions together.","zh":"小儀式幫助人感到連繫，因為大家一起重複熟悉的行動。"},{"en":"Although small rituals may seem ordinary, they can preserve identity over time.","zh":"雖然小儀式看似普通，卻能隨時間保存身份認同。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"through which","meaning":"透過……","examples":[{"en":"These are small rituals through which ordinary people recognise home.","zh":"這些是普通人透過它們認出家的感覺的小儀式。"},{"en":"Through which means by means of which, or using something as the way to do or understand another thing.","zh":"“Through which” 指透過某事，或以某事作為做成或理解另一件事的方法。"},{"en":"Stories are a way through which children learn family history.","zh":"故事是孩子透過它們學習家庭歷史的一種方式。"},{"en":"Food can be a language through which people express care.","zh":"食物可以是一種人們透過它表達關心的語言。"},{"en":"This phrase is useful when explaining how one thing helps another thing happen.","zh":"當解釋一件事如何幫助另一件事發生時，這個說法很有用。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"ordinary people","meaning":"普通人","examples":[{"en":"Ordinary people recognise home through small rituals.","zh":"普通人透過小儀式認出家的感覺。"},{"en":"Ordinary people are everyday members of society, not famous leaders or experts.","zh":"普通人是社會中的日常成員，而不是著名領袖或專家。"},{"en":"Ordinary people keep culture alive when they cook family dishes or join neighbourhood festivals.","zh":"當普通人烹調家庭菜式或參與社區節慶時，他們就在延續文化。"},{"en":"Heritage is meaningful because ordinary people practise it in real life.","zh":"文化遺產有意義，因為普通人在真實生活中實踐它。"},{"en":"This phrase reminds us that culture is not created only by powerful institutions.","zh":"這個說法提醒我們，文化並非只由強大機構創造。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"recognise home","meaning":"認出家的感覺","examples":[{"en":"Ordinary people recognise home through familiar rituals.","zh":"普通人透過熟悉的儀式認出家的感覺。"},{"en":"To recognise home means to feel that a place, sound, smell, or habit belongs to one’s own life and identity.","zh":"「認出家的感覺」指從地方、聲音、氣味或習慣中感到它屬於自己的生活和身份。"},{"en":"The smell of soup in the kitchen helped her recognise home after a long trip.","zh":"長途旅行後，廚房裏的湯味令她認出家的感覺。"},{"en":"People recognise home through familiar details that may seem small to outsiders.","zh":"人們透過熟悉細節認出家的感覺，而這些細節對外人來說可能很小。"},{"en":"This phrase shows that home is felt emotionally, not only located on a map.","zh":"這個說法顯示家是一種情感上的感受，而不只是地圖上的位置。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"strongly support","meaning":"強烈支持","examples":[{"en":"I strongly support the Government’s decision.","zh":"我強烈支持政府的決定。"},{"en":"To strongly support something means to agree with it clearly and firmly.","zh":"「強烈支持」指清楚而堅定地同意某事。"},{"en":"I strongly support the plan to protect old neighbourhood shops.","zh":"我強烈支持保護舊街坊小店的計劃。"},{"en":"People may strongly support a policy when they believe it protects something valuable.","zh":"當人們相信某政策能保護有價值的事物時，可能會強烈支持它。"},{"en":"This phrase is useful in essays because it states the writer’s position directly.","zh":"這個說法適合用於議論文，因為它直接表明作者立場。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"the Government’s decision","meaning":"政府的決定","examples":[{"en":"The writer supports the Government’s decision to protect these traditions.","zh":"作者支持政府保護這些傳統的決定。"},{"en":"The Government’s decision is the official choice or action made by the government.","zh":"政府的決定是政府作出的官方選擇或行動。"},{"en":"The Government’s decision to fund community centres helped more elderly people join activities.","zh":"政府資助社區中心的決定，幫助更多長者參與活動。"},{"en":"A Government decision can affect public understanding by showing what society values.","zh":"政府的決定可以透過顯示社會重視甚麼而影響公眾理解。"},{"en":"In this essay, the Government’s decision gives official attention to everyday traditions.","zh":"在這篇文章中，政府的決定讓日常傳統得到官方關注。"}],"source":"2017 Q5.pdf","sourcePage":2},{"front":"include something on the list","meaning":"把……列入名單","examples":[{"en":"The Government will include egg tarts and mahjong on the list.","zh":"政府會把蛋撻和麻雀列入名單。"},{"en":"To include something on the list means to officially add it to a group of recognised items.","zh":"「把某事物列入名單」指正式把它加入一組被認可的項目之中。"},{"en":"The school decided to include local history books on the reading list.","zh":"學校決定把本地歷史書列入閱讀名單。"},{"en":"Including a tradition on the list can make more people notice and protect it.","zh":"把一項傳統列入名單，可以令更多人留意並保護它。"},{"en":"This phrase is useful when talking about official recognition or selection.","zh":"當談論官方認可或選取時，這個說法很有用。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"traditional egg tarts","meaning":"傳統蛋撻","examples":[{"en":"The Government will include traditional egg tarts on the heritage list.","zh":"政府會把傳統蛋撻列入文化遺產名單。"},{"en":"Traditional egg tarts are egg tarts made with older methods, familiar flavours, and local baking skills.","zh":"傳統蛋撻是以較舊做法、熟悉味道和本地烘焙技巧製作的蛋撻。"},{"en":"Traditional egg tarts from old bakeries often have a flaky crust and smooth custard filling.","zh":"舊式麵包店的傳統蛋撻通常有鬆化酥皮和幼滑蛋漿餡。"},{"en":"Protecting traditional egg tarts means protecting the skills and memories connected with them.","zh":"保護傳統蛋撻，就是保護與它們相關的技術和回憶。"},{"en":"Traditional egg tarts matter because they are ordinary food with cultural history.","zh":"傳統蛋撻重要，因為它們是帶有文化歷史的普通食物。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"the list of","meaning":"……名單","examples":[{"en":"Egg tarts and mahjong are on the list of heritage items.","zh":"蛋撻和麻雀在文化遺產項目名單上。"},{"en":"The list of something is a written or official group of things belonging to the same category.","zh":"“The list of” 指屬於同一類別的一組書面或官方項目。"},{"en":"Her name was added to the list of volunteers for the school fair.","zh":"她的名字被加入學校賣物會義工名單。"},{"en":"A heritage item on the list may receive more public attention and protection.","zh":"列入名單的文化遺產項目可能得到更多公眾關注和保護。"},{"en":"This phrase helps identify what category the item belongs to.","zh":"這個說法有助指出某項目屬於哪一類別。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"intangible cultural heritage","meaning":"非物質文化遺產","examples":[{"en":"Egg tarts and mahjong are intangible cultural heritage.","zh":"蛋撻和麻雀是非物質文化遺產。"},{"en":"Intangible cultural heritage means traditions, skills, knowledge, customs, or performances that people pass on rather than physical buildings alone.","zh":"非物質文化遺產指由人們傳承的傳統、技藝、知識、習俗或表演，而不只是實體建築。"},{"en":"Folk songs, festivals, craft skills, and food traditions can be intangible cultural heritage.","zh":"民歌、節日、工藝技術和飲食傳統都可以是非物質文化遺產。"},{"en":"Intangible cultural heritage needs people to practise it, teach it, and remember its meaning.","zh":"非物質文化遺產需要人們實踐、教授並記住其意義。"},{"en":"It is different from a building because its life depends on continued human action.","zh":"它與建築不同，因為它的生命取決於人持續行動。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"cultural heritage items","meaning":"文化遺產項目","examples":[{"en":"These traditions are cultural heritage items.","zh":"這些傳統是文化遺產項目。"},{"en":"Cultural heritage items are things, practices, or traditions recognised as valuable parts of a community’s culture.","zh":"文化遺產項目是被認為屬於社群文化中有價值部分的事物、習俗或傳統。"},{"en":"A traditional festival can be one of a city’s cultural heritage items.","zh":"一個傳統節日可以是一個城市的文化遺產項目。"},{"en":"Cultural heritage items are protected because they help people understand where they come from.","zh":"文化遺產項目受到保護，因為它們幫助人理解自己的來處。"},{"en":"Some cultural heritage items are grand and formal, while others are ordinary and familiar.","zh":"有些文化遺產項目宏大正式，另一些則普通而熟悉。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"far from being trivial","meaning":"絕非微不足道","examples":[{"en":"Far from being trivial, these traditions reveal Hong Kong’s history.","zh":"這些傳統絕非微不足道，而是展現香港的歷史。"},{"en":"Far from being trivial means not unimportant at all; in fact, quite meaningful.","zh":"“Far from being trivial” 指一點也不微不足道，反而很有意義。"},{"en":"Far from being trivial, a grandmother’s recipe can preserve family memory.","zh":"祖母的食譜絕非微不足道，它可以保存家庭記憶。"},{"en":"Everyday habits may seem small, but they are far from trivial when they shape identity.","zh":"日常習慣看似細小，但當它們塑造身份時，就絕非微不足道。"},{"en":"This phrase corrects the idea that ordinary things have little value.","zh":"這個說法糾正普通事物沒有甚麼價值的想法。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"reveal","meaning":"展現；反映","examples":[{"en":"These two features reveal Hong Kong’s mixed history.","zh":"這兩項特色展現香港融合中西的歷史。"},{"en":"To reveal something means to show or make it easier to understand.","zh":"“Reveal” 指顯示某事，或令某事更容易被理解。"},{"en":"Old shop signs reveal how a neighbourhood has changed over time.","zh":"舊店舖招牌反映一個社區如何隨時間改變。"},{"en":"Food traditions can reveal migration, trade, and family habits.","zh":"飲食傳統可以展現遷徙、貿易和家庭習慣。"},{"en":"In writing, “reveal” is useful when something ordinary shows a deeper meaning.","zh":"在寫作中，當普通事物顯示更深意義時，“reveal” 很有用。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"mixed history","meaning":"融合中西的歷史","examples":[{"en":"Egg tarts reveal Hong Kong’s mixed history.","zh":"蛋撻展現香港融合中西的歷史。"},{"en":"Mixed history means a past shaped by different cultures, influences, people, and events.","zh":"融合中西的歷史是由不同文化、影響、人物和事件塑造的過去。"},{"en":"A city with mixed history may have local temples beside colonial buildings.","zh":"一個有融合歷史的城市，可能有本地廟宇與殖民地建築並存。"},{"en":"Hong Kong’s mixed history can appear in language, food, architecture, and daily habits.","zh":"香港融合中西的歷史可以出現在語言、食物、建築和日常習慣中。"},{"en":"Egg tarts reflect mixed history because they combine different culinary influences.","zh":"蛋撻反映融合中西的歷史，因為它結合了不同飲食影響。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"social warmth","meaning":"社會人情味","examples":[{"en":"These traditions reveal Hong Kong’s social warmth.","zh":"這些傳統反映香港的社會人情味。"},{"en":"Social warmth means the friendliness, care, humour, and human connection found in a community.","zh":"社會人情味指社群中的友善、關心、幽默和人與人之間的連繫。"},{"en":"A neighbour sharing food during a festival shows social warmth.","zh":"節日期間鄰居分享食物，顯示社會人情味。"},{"en":"Social warmth can make a crowded city feel more personal and humane.","zh":"社會人情味可以令擁擠城市感覺更有人性和親切。"},{"en":"Mahjong gatherings reveal social warmth because people talk, joke, and stay connected.","zh":"麻雀聚會反映社會人情味，因為人們會聊天、說笑和保持連繫。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"everyday creativity","meaning":"日常創意","examples":[{"en":"These features reveal Hong Kong’s everyday creativity.","zh":"這些特色展現香港的日常創意。"},{"en":"Everyday creativity is the ability to create useful, interesting, or meaningful things in ordinary life.","zh":"日常創意是在普通生活中創造有用、有趣或有意義事物的能力。"},{"en":"A cha chaan teng menu shows everyday creativity by mixing different food styles.","zh":"茶餐廳餐牌透過混合不同飲食風格，展現日常創意。"},{"en":"Everyday creativity often appears when people adapt traditions to modern needs.","zh":"當人們把傳統調整以配合現代需要時，日常創意常會出現。"},{"en":"This phrase values ordinary invention, not only famous artistic works.","zh":"這個說法重視普通生活中的創造力，而不只是著名藝術作品。"}],"source":"2017 Q5.pdf","sourcePage":3},{"front":"worth protecting","meaning":"值得保護","examples":[{"en":"Egg tarts and mahjong are worth protecting.","zh":"蛋撻和麻雀值得保護。"},{"en":"Worth protecting means valuable enough to be kept safe, taught, or supported.","zh":"“Worth protecting” 指有足夠價值，值得被保存、教授或支持。"},{"en":"Old family recipes are worth protecting because they carry memories of earlier generations.","zh":"舊家庭食譜值得保護，因為它們承載上一代的回憶。"},{"en":"A tradition is worth protecting when losing it would weaken a community’s identity.","zh":"當失去某傳統會削弱社群身份時，它便值得保護。"},{"en":"Something ordinary can still be worth protecting if people rely on it for meaning and connection.","zh":"即使某事物很普通，只要人們從中得到意義和連繫，它仍值得保護。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"not because…, but because…","meaning":"不是因為……而是因為……","examples":[{"en":"They are worth protecting not because they are rare, but because they are woven into daily life.","zh":"它們值得保護，不是因為它們稀有，而是因為它們融入日常生活。"},{"en":"“Not because…, but because…” rejects one reason and gives the true or stronger reason.","zh":"“Not because…, but because…” 先否定一個原因，再提出真正或更有力的原因。"},{"en":"I remember that shop not because it was expensive, but because the owner knew every customer.","zh":"我記得那間店，不是因為它昂貴，而是因為店主認識每位顧客。"},{"en":"Heritage matters not because it is always grand, but because it shapes how people live.","zh":"文化遺產重要，不是因為它總是宏大，而是因為它塑造人們的生活方式。"},{"en":"This structure makes the writer’s reasoning clear and persuasive.","zh":"這個結構令作者的理據清楚而有說服力。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"deeply woven into","meaning":"深深融入","examples":[{"en":"These traditions are deeply woven into our common life.","zh":"這些傳統深深融入我們的共同生活。"},{"en":"Deeply woven into means strongly and closely connected with something over a long time.","zh":"“Deeply woven into” 指長時間與某事物緊密而深厚地連接。"},{"en":"Tea drinking is deeply woven into many families’ daily routines.","zh":"飲茶深深融入許多家庭的日常習慣。"},{"en":"A tradition deeply woven into common life may be noticed only when it starts to disappear.","zh":"深深融入共同生活的傳統，可能要到開始消失時才被注意。"},{"en":"This phrase suggests that culture is part of daily living, not an extra decoration.","zh":"這個說法暗示文化是日常生活的一部分，而不是額外裝飾。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"common life","meaning":"共同生活","examples":[{"en":"Egg tarts and mahjong are woven into our common life.","zh":"蛋撻和麻雀融入我們的共同生活。"},{"en":"Common life means the shared everyday experiences, routines, and habits of ordinary people.","zh":"共同生活指普通人共享的日常經驗、規律和習慣。"},{"en":"Public transport, street food, and family meals are all part of common life.","zh":"公共交通、街頭食物和家庭飯局都是共同生活的一部分。"},{"en":"Heritage in common life matters because many people recognise it personally.","zh":"共同生活中的文化遺產很重要，因為許多人都能親身認出它。"},{"en":"This phrase emphasises shared experience rather than private luxury or official ceremony.","zh":"這個說法強調共享經驗，而不是私人奢侈或官方儀式。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"take something for granted","meaning":"視……為理所當然","examples":[{"en":"We may take these traditions for granted until they disappear.","zh":"我們可能把這些傳統視為理所當然，直到它們消失。"},{"en":"To take something for granted means to fail to value it because it is familiar or always available.","zh":"「視某事為理所當然」指因為某事熟悉或一直存在，而沒有珍惜它。"},{"en":"Students may take clean classrooms for granted until they have to clean them themselves.","zh":"學生可能把乾淨課室視為理所當然，直到需要自己清潔。"},{"en":"People often take old neighbourhood shops for granted while they are still open.","zh":"人們常在舊街坊小店仍然營業時，把它們視為理所當然。"},{"en":"This phrase warns that ordinary things may be valued too late.","zh":"這個說法提醒我們，普通事物可能到太遲時才被珍惜。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"until they disappear","meaning":"直到它們消失","examples":[{"en":"We may not value these traditions until they disappear.","zh":"我們可能直到這些傳統消失才懂得珍惜。"},{"en":"Until they disappear means up to the point when they are gone or no longer practised.","zh":"“Until they disappear” 指直到它們不再存在或不再被實踐的時候。"},{"en":"Some people do not miss old playgrounds until they disappear from the neighbourhood.","zh":"有些人直到舊遊樂場從社區消失後才開始懷念它們。"},{"en":"Waiting until traditions disappear makes protection much harder.","zh":"等到傳統消失才保護，會令保育困難得多。"},{"en":"This phrase warns that loss may be the moment when people finally notice value.","zh":"這個說法警告我們，失去可能正是人們終於看見價值的時刻。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"deserve protection","meaning":"值得受到保護","examples":[{"en":"Traditional egg tarts deserve protection.","zh":"傳統蛋撻值得受到保護。"},{"en":"Deserve protection means be valuable enough to receive care, support, or official safeguarding.","zh":"“Deserve protection” 指某事物有足夠價值，應得到照顧、支持或官方保障。"},{"en":"Old trees in the village deserve protection because they carry history and provide shade.","zh":"村裏的老樹值得受到保護，因為它們承載歷史並提供樹蔭。"},{"en":"A craft deserves protection when few people still know how to practise it properly.","zh":"當很少人仍懂得正確實踐某項工藝時，它便值得受到保護。"},{"en":"Saying something deserves protection argues that it should not be left to disappear by chance.","zh":"說某事物值得受到保護，是主張不應任由它碰運氣地消失。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"more than just","meaning":"不只是","examples":[{"en":"Egg tarts are more than just a sweet snack.","zh":"蛋撻不只是一種甜點。"},{"en":"More than just means something has deeper value beyond its most obvious use or appearance.","zh":"“More than just” 指某事物除了最明顯的用途或外表之外，還有更深價值。"},{"en":"A school uniform is more than just clothing because it can show belonging.","zh":"校服不只是衣服，因為它可以顯示歸屬感。"},{"en":"Egg tarts are more than just food because they carry local memory and skill.","zh":"蛋撻不只是食物，因為它承載本地記憶和技藝。"},{"en":"This phrase helps move from a simple view to a deeper cultural meaning.","zh":"這個說法幫助從簡單看法轉向更深層的文化意義。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"a sweet snack","meaning":"甜點；甜食","examples":[{"en":"An egg tart may look like a simple sweet snack.","zh":"蛋撻可能看起來只是一種簡單甜點。"},{"en":"A sweet snack is a small sweet food eaten between meals or as a treat.","zh":"甜點是正餐之間或作為小享受而吃的小份甜食。"},{"en":"A child may buy a sweet snack from the bakery after school.","zh":"孩子放學後可能在麵包店買一份甜點。"},{"en":"A sweet snack can become culturally meaningful when many people share memories of eating it.","zh":"當許多人都有吃某種甜點的共同回憶時，它可以變得有文化意義。"},{"en":"Calling an egg tart only a sweet snack misses its history and craftsmanship.","zh":"只把蛋撻稱為甜點，會忽略它的歷史和手藝。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"tell the story of","meaning":"講述……的故事","examples":[{"en":"Egg tarts tell the story of Hong Kong’s mixed culture.","zh":"蛋撻講述香港融合文化的故事。"},{"en":"To tell the story of something means to show its history, development, or meaning.","zh":"“Tell the story of” 指顯示某事物的歷史、發展或意義。"},{"en":"Old ferry routes tell the story of how people travelled before new rail lines.","zh":"舊渡輪路線講述新鐵路出現前人們如何出行的故事。"},{"en":"Food can tell the story of a city because recipes often carry cultural exchange.","zh":"食物可以講述一個城市的故事，因為食譜常承載文化交流。"},{"en":"This phrase is useful when an object reveals a wider history.","zh":"當一件物件展現更廣闊歷史時，這個說法很有用。"}],"source":"2017 Q5.pdf","sourcePage":4},{"front":"a place where","meaning":"一個……的地方","examples":[{"en":"Hong Kong is a place where Chinese and Western influences met.","zh":"香港是一個中西影響相遇的地方。"},{"en":"A place where introduces a location connected with a particular action or feature.","zh":"“A place where” 用來介紹與某個行動或特徵相關的地點。"},{"en":"The library is a place where students can read quietly and ask for help.","zh":"圖書館是一個學生可以安靜閱讀和尋求幫助的地方。"},{"en":"A city can become a place where different cultures meet and create new habits.","zh":"一個城市可以成為不同文化相遇並創造新習慣的地方。"},{"en":"This phrase helps describe what happens in a particular location.","zh":"這個說法幫助描述某個地點會發生甚麼。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"Chinese and Western influences","meaning":"中西影響","examples":[{"en":"Egg tarts show how Chinese and Western influences met.","zh":"蛋撻顯示中西影響如何相遇。"},{"en":"Chinese and Western influences are ideas, styles, habits, or techniques from Chinese and Western cultures.","zh":"中西影響是來自中國文化和西方文化的想法、風格、習慣或技術。"},{"en":"A cha chaan teng menu often shows Chinese and Western influences in the same meal.","zh":"茶餐廳餐牌常在同一餐中顯示中西影響。"},{"en":"When Chinese and Western influences meet, new local forms can appear.","zh":"當中西影響相遇，新的本地形式便可能出現。"},{"en":"Egg tarts reflect these influences through both pastry style and local taste.","zh":"蛋撻透過酥皮風格和本地口味反映這些影響。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"met, adapted and became","meaning":"相遇、適應並變成","examples":[{"en":"These influences met, adapted and became something local.","zh":"這些影響相遇、適應並變成具本地特色的東西。"},{"en":"Met, adapted and became describes a process in which different influences came together, changed, and formed a new identity.","zh":"“Met, adapted and became” 描述不同影響走在一起、發生改變，並形成新身份的過程。"},{"en":"In Hong Kong, food ideas from different places met, adapted and became local favourites.","zh":"在香港，來自不同地方的飲食想法相遇、適應並成為本地人喜愛的食物。"},{"en":"Cultures rarely stay unchanged when they meet; they often adapt and become something new.","zh":"文化相遇時很少保持不變；它們常會適應並變成新事物。"},{"en":"This phrase shows cultural change as a living process.","zh":"這個說法把文化改變呈現為活生生的過程。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"unmistakably local","meaning":"明顯具本地特色","examples":[{"en":"Egg tarts became something unmistakably local.","zh":"蛋撻變成明顯具本地特色的東西。"},{"en":"Unmistakably local means clearly belonging to a particular place and not easily confused with somewhere else.","zh":"“Unmistakably local” 指明顯屬於某個地方，不容易與其他地方混淆。"},{"en":"The street market’s sounds and smells felt unmistakably local.","zh":"街市的聲音和氣味感覺明顯具本地特色。"},{"en":"A food becomes unmistakably local when people connect it strongly with their city’s daily life.","zh":"當人們把某種食物強烈連繫到城市日常生活時，它便變得明顯具本地特色。"},{"en":"This phrase emphasises a strong and clear local identity.","zh":"這個說法強調強烈而清楚的本地身份。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"buttery crust","meaning":"牛油酥皮","examples":[{"en":"A traditional egg tart has a buttery crust.","zh":"傳統蛋撻有牛油酥皮。"},{"en":"A buttery crust is the outer pastry layer that tastes rich because it contains butter.","zh":"牛油酥皮是外層糕點皮，因含有牛油而味道香濃。"},{"en":"The bakery’s egg tart had a crisp buttery crust and a warm centre.","zh":"那間麵包店的蛋撻有鬆脆牛油酥皮和溫暖內餡。"},{"en":"Making a good buttery crust requires careful mixing, folding, and baking.","zh":"要做好牛油酥皮，需要仔細混合、摺疊和烘焙。"},{"en":"The crust is important because it affects both the texture and flavour of the egg tart.","zh":"酥皮很重要，因為它影響蛋撻的口感和味道。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"silky custard filling","meaning":"幼滑蛋漿餡","examples":[{"en":"The egg tart has a silky custard filling.","zh":"蛋撻有幼滑蛋漿餡。"},{"en":"A silky custard filling is a smooth, soft egg-based centre inside a tart.","zh":"幼滑蛋漿餡是撻內以蛋製成的柔滑內餡。"},{"en":"The best egg tarts have a silky custard filling that shakes slightly when fresh.","zh":"最好的蛋撻有幼滑蛋漿餡，新鮮時會微微晃動。"},{"en":"If the baking time is wrong, the custard filling may become rough instead of silky.","zh":"如果烘焙時間不正確，蛋漿餡可能變得粗糙，而不是幼滑。"},{"en":"This phrase helps describe the texture that makes an egg tart enjoyable.","zh":"這個說法有助描述令蛋撻好吃的口感。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"paper bag","meaning":"紙袋","examples":[{"en":"A paper bag from a neighbourhood bakery can carry shared memory.","zh":"來自街坊麵包店的紙袋可以承載共同回憶。"},{"en":"A paper bag is a bag made of paper, often used to carry bread, snacks, or small goods.","zh":"紙袋是由紙製成的袋，常用來盛載麵包、小食或小件貨品。"},{"en":"The warm egg tarts were placed inside a brown paper bag.","zh":"熱蛋撻被放進一個啡色紙袋裏。"},{"en":"A simple paper bag can become meaningful if people connect it with familiar shops and childhood routines.","zh":"如果人們把紙袋與熟悉店舖和童年習慣連繫起來，它也可以變得有意義。"},{"en":"In this context, the paper bag carries not only food, but also memory.","zh":"在這個語境中，紙袋承載的不只是食物，也有回憶。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"neighbourhood bakery","meaning":"街坊麵包店","examples":[{"en":"Many egg tarts come from neighbourhood bakeries.","zh":"許多蛋撻來自街坊麵包店。"},{"en":"A neighbourhood bakery is a small local shop that sells bread and pastries to nearby residents.","zh":"街坊麵包店是向附近居民售賣麵包和糕點的小型本地店舖。"},{"en":"The neighbourhood bakery knew which customers wanted egg tarts straight from the oven.","zh":"那間街坊麵包店知道哪些顧客想買剛出爐的蛋撻。"},{"en":"Neighbourhood bakeries matter because they connect food with local relationships.","zh":"街坊麵包店重要，因為它把食物與本地人情關係連接起來。"},{"en":"When a neighbourhood bakery closes, a community may lose more than a place to buy bread.","zh":"當街坊麵包店結業，社區失去的可能不只是一個買麵包的地方。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"may seem simple","meaning":"可能看似簡單","examples":[{"en":"An egg tart may seem simple at first glance.","zh":"蛋撻乍看之下可能看似簡單。"},{"en":"May seem simple means may appear easy or ordinary before one understands it more deeply.","zh":"“May seem simple” 指在深入理解前，某事物可能看起來容易或普通。"},{"en":"A handwritten recipe may seem simple, but it can contain years of family experience.","zh":"一份手寫食譜可能看似簡單，但當中可包含多年家庭經驗。"},{"en":"Traditional crafts may seem simple until you try to learn the techniques yourself.","zh":"傳統工藝可能看似簡單，直到你親自學習其中技術。"},{"en":"This phrase prepares the reader for a deeper explanation.","zh":"這個說法為之後更深入的解釋作準備。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"Egg tarts may seem simple at first glance.","zh":"蛋撻乍看之下可能看似簡單。"},{"en":"At first glance means when you first look at something, before examining it carefully.","zh":"“At first glance” 指初次看見某事物、尚未仔細研究時。"},{"en":"At first glance, the old shop looked ordinary, but it had a long history.","zh":"乍看之下，那間老店很普通，但它有悠久歷史。"},{"en":"At first glance, a tradition may seem common because people see it every day.","zh":"乍看之下，一項傳統可能因每天都被看見而顯得平常。"},{"en":"This phrase often contrasts first impressions with deeper understanding.","zh":"這個說法常把第一印象與深入理解作對比。"}],"source":"2017 Q5.pdf","sourcePage":5},{"front":"on closer inspection","meaning":"仔細看時","examples":[{"en":"On closer inspection, egg tarts represent generations of craftsmanship.","zh":"仔細看時，蛋撻代表幾代人的手藝。"},{"en":"On closer inspection means after looking at or thinking about something more carefully.","zh":"“On closer inspection” 指更仔細觀看或思考某事物之後。"},{"en":"On closer inspection, the simple bowl had tiny hand-painted patterns.","zh":"仔細看時，那個簡單的碗有細小的手繪圖案。"},{"en":"A common tradition may reveal deep meaning on closer inspection.","zh":"一項普通傳統在仔細看時，可能會顯示深層意義。"},{"en":"This phrase helps move from surface appearance to hidden value.","zh":"這個說法幫助從表面外觀轉向隱藏價值。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"represent generations of","meaning":"代表幾代人的……","examples":[{"en":"Egg tarts represent generations of craftsmanship.","zh":"蛋撻代表幾代人的手藝。"},{"en":"Represent generations of means show the skills, efforts, or experiences passed down through many years and many people.","zh":"“Represent generations of” 指展現多年來由許多人傳下來的技術、努力或經驗。"},{"en":"The old fishing method represents generations of knowledge about the sea.","zh":"舊捕魚方法代表幾代人對海洋的認識。"},{"en":"A traditional recipe can represent generations of family care and practice.","zh":"傳統食譜可以代表幾代人的家庭關懷和實踐。"},{"en":"This phrase gives ordinary objects a longer historical meaning.","zh":"這個說法賦予普通物件更長遠的歷史意義。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"craftsmanship","meaning":"手藝；工藝","examples":[{"en":"Traditional egg tarts represent generations of craftsmanship.","zh":"傳統蛋撻代表幾代人的手藝。"},{"en":"Craftsmanship is the skill, care, and knowledge needed to make something well by hand or with experience.","zh":"手藝是透過手工或經驗把東西做好的技巧、用心和知識。"},{"en":"The wooden chair showed fine craftsmanship because every joint was carefully shaped.","zh":"那張木椅展現精細手藝，因為每個接位都被仔細打磨。"},{"en":"Craftsmanship can disappear if young people do not learn from experienced makers.","zh":"如果年輕人不向有經驗的師傅學習，手藝可能會消失。"},{"en":"Egg tart craftsmanship includes controlling the crust, filling, heat, and timing.","zh":"蛋撻手藝包括控制酥皮、餡料、火候和時間。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"old-style bakeries","meaning":"舊式麵包店","examples":[{"en":"Old-style bakeries in Sham Shui Po still sell traditional egg tarts.","zh":"深水埗的舊式麵包店仍然售賣傳統蛋撻。"},{"en":"Old-style bakeries are traditional bakery shops that keep older methods, products, or shop atmospheres.","zh":"舊式麵包店是保留較舊做法、產品或店舖氣氛的傳統麵包店。"},{"en":"An old-style bakery may sell pineapple buns, egg tarts, and paper-wrapped cakes.","zh":"舊式麵包店可能售賣菠蘿包、蛋撻和紙包蛋糕。"},{"en":"Old-style bakeries preserve food memory because customers return for familiar tastes.","zh":"舊式麵包店保存飲食記憶，因為顧客會為熟悉味道而回來。"},{"en":"If old-style bakeries disappear, some traditional baking skills may disappear with them.","zh":"如果舊式麵包店消失，一些傳統烘焙技術也可能隨之消失。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"cha chaan tengs","meaning":"茶餐廳","examples":[{"en":"Egg tarts are served in cha chaan tengs in Wan Chai.","zh":"灣仔的茶餐廳供應蛋撻。"},{"en":"Cha chaan tengs are Hong Kong-style cafés that serve affordable local and mixed Chinese-Western food.","zh":"茶餐廳是香港式咖啡店，供應價錢相宜的本地及中西混合食物。"},{"en":"People may order milk tea, noodles, toast, and egg tarts in cha chaan tengs.","zh":"人們可以在茶餐廳點奶茶、麵、吐司和蛋撻。"},{"en":"Cha chaan tengs are culturally important because they show Hong Kong’s everyday food creativity.","zh":"茶餐廳具有文化重要性，因為它展現香港日常飲食創意。"},{"en":"In cha chaan tengs, food is not only eaten; it is part of local daily rhythm.","zh":"在茶餐廳裏，食物不只是用來吃，也是本地日常節奏的一部分。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"have accompanied","meaning":"陪伴着","examples":[{"en":"Egg tarts have accompanied many kinds of Hong Kong people.","zh":"蛋撻陪伴着許多不同類型的香港人。"},{"en":"Have accompanied means have been present with people during their experiences over time.","zh":"“Have accompanied” 指長時間在人們的經歷中與他們同在。"},{"en":"Street snacks have accompanied students through many after-school afternoons.","zh":"街頭小食陪伴着學生度過許多放學後的下午。"},{"en":"A familiar food can accompany people through workdays, festivals, and family memories.","zh":"熟悉的食物可以陪伴人度過工作日、節日和家庭回憶。"},{"en":"This phrase makes egg tarts seem like a long-term companion in daily life.","zh":"這個說法令蛋撻像是日常生活中的長期陪伴。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"office workers","meaning":"上班族","examples":[{"en":"Egg tarts have accompanied office workers.","zh":"蛋撻陪伴着上班族。"},{"en":"Office workers are people who work in offices, often doing administrative, business, or professional tasks.","zh":"上班族是在辦公室工作的人，通常負責行政、商業或專業工作。"},{"en":"Office workers may buy egg tarts during an afternoon tea break.","zh":"上班族可能在下午茶時間買蛋撻。"},{"en":"Quick bakery snacks suit office workers because their lunch and break times are often short.","zh":"快捷的麵包店小食適合上班族，因為他們的午飯和休息時間通常很短。"},{"en":"Mentioning office workers shows that egg tarts belong to everyday working life.","zh":"提到上班族，顯示蛋撻屬於日常工作生活。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"schoolchildren","meaning":"學童","examples":[{"en":"Egg tarts have accompanied schoolchildren.","zh":"蛋撻陪伴着學童。"},{"en":"Schoolchildren are children who attend school.","zh":"學童是正在上學的孩子。"},{"en":"Schoolchildren often buy snacks near school before going home.","zh":"學童放學回家前，常在學校附近買小食。"},{"en":"A warm egg tart after school can become part of a child’s memory of growing up.","zh":"放學後一個溫暖蛋撻，可以成為孩子成長回憶的一部分。"},{"en":"Including schoolchildren shows that this food connects with childhood as well as adult life.","zh":"提到學童，顯示這種食物不只連繫成人生活，也連繫童年。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"taxi drivers","meaning":"的士司機","examples":[{"en":"Egg tarts have accompanied taxi drivers.","zh":"蛋撻陪伴着的士司機。"},{"en":"Taxi drivers are people whose job is to drive passengers to different places for payment.","zh":"的士司機是以收費方式駕車接載乘客到不同地方的人。"},{"en":"A taxi driver may buy an egg tart during a short break between trips.","zh":"的士司機可能在兩程車之間的短暫休息時買蛋撻。"},{"en":"Portable snacks are useful for taxi drivers because they spend long hours on the road.","zh":"方便攜帶的小食對的士司機有用，因為他們長時間在路上工作。"},{"en":"This example shows how egg tarts fit into busy street-level work.","zh":"這個例子顯示蛋撻如何融入忙碌的街頭工作生活。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"elderly residents","meaning":"年長居民","examples":[{"en":"Egg tarts have accompanied elderly residents.","zh":"蛋撻陪伴着年長居民。"},{"en":"Elderly residents are older people who live in a particular neighbourhood or community.","zh":"年長居民是居住在某個社區或地方的年紀較大的人。"},{"en":"Elderly residents may visit the same bakery every morning because they know the staff.","zh":"年長居民可能每天早上到同一間麵包店，因為他們認識店員。"},{"en":"Familiar foods can comfort elderly residents by connecting them with earlier years.","zh":"熟悉的食物可以安慰年長居民，因為它把他們與早年生活連繫起來。"},{"en":"This phrase shows that food heritage can belong to older generations’ daily routines.","zh":"這個說法顯示飲食文化遺產可以屬於長者的日常習慣。"}],"source":"2017 Q5.pdf","sourcePage":6},{"front":"alike","meaning":"同樣地","examples":[{"en":"Egg tarts have accompanied workers, students and elderly residents alike.","zh":"蛋撻同樣陪伴着工人、學生和年長居民。"},{"en":"Alike means in the same way, applying equally to different people or groups.","zh":"“Alike” 指以同樣方式適用於不同人士或群體。"},{"en":"The park is loved by children and adults alike.","zh":"那個公園同樣受孩子和成人喜愛。"},{"en":"A tradition becomes widely shared when it is familiar to rich and poor alike.","zh":"當一項傳統對富人和窮人同樣熟悉時，它就成為廣泛共享的傳統。"},{"en":"This word shows that egg tarts connect different groups of people.","zh":"這個詞顯示蛋撻把不同群體連繫起來。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"fill your stomach","meaning":"填飽肚子","examples":[{"en":"You do not just buy an egg tart to fill your stomach.","zh":"你買蛋撻不只是為了填飽肚子。"},{"en":"To fill your stomach means to eat enough food so you no longer feel hungry.","zh":"「填飽肚子」指吃足夠食物，使自己不再感到肚餓。"},{"en":"A sandwich can fill your stomach quickly during a short lunch break.","zh":"午飯時間短時，一份三文治可以很快填飽肚子。"},{"en":"Some foods do more than fill your stomach because they also bring comfort or memory.","zh":"有些食物不只是填飽肚子，也會帶來安慰或回憶。"},{"en":"This phrase contrasts physical hunger with emotional or cultural value.","zh":"這個說法把身體上的飢餓與情感或文化價值作對比。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"a small piece of shared memory","meaning":"一小片共同回憶","examples":[{"en":"You buy a small piece of shared memory when you buy an egg tart.","zh":"當你買蛋撻時，你買的是一小片共同回憶。"},{"en":"A small piece of shared memory is a little object or experience that reminds many people of something they have in common.","zh":"一小片共同回憶是能令許多人想起共同經驗的小物件或經歷。"},{"en":"A festival snack can be a small piece of shared memory for people from the same neighbourhood.","zh":"對同一社區的人來說，節日小食可以是一小片共同回憶。"},{"en":"Food becomes shared memory when many people connect it with similar family or childhood experiences.","zh":"當許多人把某種食物與相似的家庭或童年經歷連繫起來，它便成為共同回憶。"},{"en":"This phrase shows that buying food can also mean touching a common past.","zh":"這個說法顯示買食物也可以是接觸共同過去。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"shared memory","meaning":"共同回憶","examples":[{"en":"Egg tarts carry shared memory.","zh":"蛋撻承載共同回憶。"},{"en":"Shared memory is memory held by a group of people because they have similar experiences or traditions.","zh":"共同回憶是一群人因相似經歷或傳統而共同擁有的記憶。"},{"en":"Old songs can carry shared memory for people who grew up in the same period.","zh":"舊歌曲可以為同一年代成長的人承載共同回憶。"},{"en":"Shared memory helps a community feel connected across different ages and backgrounds.","zh":"共同回憶幫助社群在不同年齡和背景之間建立連繫。"},{"en":"Egg tarts carry shared memory because many people remember buying and eating them in familiar places.","zh":"蛋撻承載共同回憶，因為許多人都記得在熟悉地方買和吃蛋撻。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"under pressure","meaning":"承受壓力","examples":[{"en":"The craft of making egg tarts is now under pressure.","zh":"製作蛋撻的手藝現在正承受壓力。"},{"en":"Under pressure means facing stress, difficulty, or threats that make survival or success harder.","zh":"“Under pressure” 指面對壓力、困難或威脅，使生存或成功變得更困難。"},{"en":"Small shops are under pressure when rents rise and customers change their habits.","zh":"當租金上升而顧客習慣改變，小店便會承受壓力。"},{"en":"Traditional crafts under pressure may disappear unless people support and teach them.","zh":"承受壓力的傳統工藝，如果沒有得到支持和教授，可能會消失。"},{"en":"This phrase shows that a tradition is facing real challenges.","zh":"這個說法顯示一項傳統正面對真實挑戰。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"rising rents","meaning":"租金上升","examples":[{"en":"Rising rents may push traditional bakeries aside.","zh":"租金上升可能會排擠傳統麵包店。"},{"en":"Rising rents are increasing costs that shops or residents must pay to use a place.","zh":"租金上升是店舖或居民使用地方所需支付費用增加。"},{"en":"Rising rents forced several small shops to leave the neighbourhood.","zh":"租金上升迫使幾間小店離開社區。"},{"en":"Traditional bakeries may struggle with rising rents because their profits are limited.","zh":"傳統麵包店可能難以應付租金上升，因為利潤有限。"},{"en":"Rising rents can change a community by replacing old local shops with larger chains.","zh":"租金上升可以改變社區，令舊本地小店被大型連鎖店取代。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"standardised chain-store production","meaning":"標準化連鎖店生產","examples":[{"en":"Standardised chain-store production threatens traditional recipes.","zh":"標準化連鎖店生產威脅傳統食譜。"},{"en":"Standardised chain-store production means making goods in the same controlled way across many branches.","zh":"標準化連鎖店生產指在多間分店以同一受控方式製作產品。"},{"en":"Standardised chain-store production can make food cheaper and more consistent, but less personal.","zh":"標準化連鎖店生產可以令食物更便宜、更一致，但也較少個人特色。"},{"en":"Traditional recipes may suffer when standardised production replaces small-batch craftsmanship.","zh":"當標準化生產取代小批量手藝時，傳統食譜可能受損。"},{"en":"This phrase describes a modern business method that can weaken local food traditions.","zh":"這個說法描述一種可能削弱本地飲食傳統的現代商業方法。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"changing eating habits","meaning":"飲食習慣改變","examples":[{"en":"Changing eating habits may affect traditional bakeries.","zh":"飲食習慣改變可能影響傳統麵包店。"},{"en":"Changing eating habits are shifts in what, when, and how people choose to eat.","zh":"飲食習慣改變是人們選擇吃甚麼、何時吃和如何吃的變化。"},{"en":"More people skipping breakfast is one example of changing eating habits.","zh":"越來越多人不吃早餐，就是飲食習慣改變的一個例子。"},{"en":"Traditional bakeries may lose customers if changing eating habits reduce demand for old snacks.","zh":"如果飲食習慣改變令舊式小食需求下降，傳統麵包店可能失去顧客。"},{"en":"This phrase helps explain why food heritage can be affected by modern lifestyles.","zh":"這個說法有助解釋飲食文化遺產為何會受現代生活方式影響。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"gradually push aside","meaning":"逐漸排擠","examples":[{"en":"Modern pressures may gradually push traditional recipes aside.","zh":"現代壓力可能逐漸排擠傳統食譜。"},{"en":"To gradually push something aside means to slowly replace or ignore it over time.","zh":"「逐漸排擠」指隨時間慢慢取代或忽視某事物。"},{"en":"Online shopping gradually pushed aside some small neighbourhood stores.","zh":"網上購物逐漸排擠一些街坊小店。"},{"en":"If convenience becomes the only goal, it may gradually push traditional skills aside.","zh":"如果方便成為唯一目標，它可能逐漸排擠傳統技藝。"},{"en":"This phrase suggests a slow process of loss rather than sudden disappearance.","zh":"這個說法暗示一種緩慢流失的過程，而不是突然消失。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"traditional recipes","meaning":"傳統食譜","examples":[{"en":"Traditional recipes may disappear if they are not protected.","zh":"如果不加保護，傳統食譜可能會消失。"},{"en":"Traditional recipes are cooking or baking methods passed down over time within families, shops, or communities.","zh":"傳統食譜是在家庭、店舖或社區中長時間傳下來的烹飪或烘焙方法。"},{"en":"A traditional recipe may include exact timing that an experienced baker learned by practice.","zh":"傳統食譜可能包含資深麵包師傅透過實踐學到的準確時間掌握。"},{"en":"Traditional recipes need to be taught because written instructions alone may not capture every skill.","zh":"傳統食譜需要被教授，因為單靠書面指示未必能捕捉所有技巧。"},{"en":"Protecting traditional recipes helps preserve taste, memory, and technique.","zh":"保護傳統食譜有助保存味道、記憶和技術。"}],"source":"2017 Q5.pdf","sourcePage":7},{"front":"baking skills","meaning":"烘焙技術","examples":[{"en":"Traditional baking skills need to be passed on.","zh":"傳統烘焙技術需要傳承下去。"},{"en":"Baking skills are the techniques needed to mix, shape, heat, and finish baked food properly.","zh":"烘焙技術是正確混合、塑形、加熱和完成烘焙食物所需的技巧。"},{"en":"Making egg tarts requires baking skills such as controlling oven temperature and pastry texture.","zh":"製作蛋撻需要控制焗爐溫度和酥皮口感等烘焙技術。"},{"en":"Baking skills improve through practice because small differences can change the final result.","zh":"烘焙技術會透過練習提升，因為細小差異可以改變成品。"},{"en":"If baking skills are not passed on, traditional foods may survive only in name.","zh":"如果烘焙技術沒有傳承，傳統食物可能只剩下名字。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"record oral histories","meaning":"記錄口述歷史","examples":[{"en":"The Government should record oral histories from veteran bakers.","zh":"政府應記錄資深麵包師傅的口述歷史。"},{"en":"To record oral histories means to collect spoken memories and experiences from people who lived through or practised something.","zh":"「記錄口述歷史」指收集曾經歷或實踐某事的人所講述的記憶和經驗。"},{"en":"Students recorded oral histories from elderly residents about old market life.","zh":"學生記錄年長居民關於舊街市生活的口述歷史。"},{"en":"Recording oral histories helps preserve knowledge that may not appear in books.","zh":"記錄口述歷史有助保存書本中未必出現的知識。"},{"en":"This method is useful when skills and memories live in people’s voices.","zh":"當技藝和回憶存在於人們的聲音中時，這種方法很有用。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"oral histories","meaning":"口述歷史","examples":[{"en":"Oral histories can preserve the memories of veteran bakers.","zh":"口述歷史可以保存資深麵包師傅的記憶。"},{"en":"Oral histories are recorded spoken accounts of people’s experiences, memories, and knowledge.","zh":"口述歷史是把人們的經歷、記憶和知識以說話方式記錄下來。"},{"en":"Oral histories from former factory workers can explain how a neighbourhood developed.","zh":"前工廠工人的口述歷史可以解釋一個社區如何發展。"},{"en":"Oral histories are important because older people may remember details that documents do not include.","zh":"口述歷史很重要，因為長者可能記得文件沒有記載的細節。"},{"en":"For food heritage, oral histories can capture stories behind recipes and shop routines.","zh":"對飲食文化遺產而言，口述歷史可以捕捉食譜和店舖日常背後的故事。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"veteran bakers","meaning":"資深麵包師傅","examples":[{"en":"Veteran bakers can explain how traditional egg tarts are made.","zh":"資深麵包師傅可以解釋傳統蛋撻如何製作。"},{"en":"Veteran bakers are experienced bakers who have worked in the trade for many years.","zh":"資深麵包師傅是在行內工作多年、經驗豐富的烘焙師傅。"},{"en":"Veteran bakers often know small details that younger workers cannot learn from recipes alone.","zh":"資深麵包師傅常知道年輕工人不能單靠食譜學到的細節。"},{"en":"Interviewing veteran bakers helps preserve practical knowledge before they retire.","zh":"訪問資深麵包師傅有助在他們退休前保存實用知識。"},{"en":"Their experience is valuable because traditional baking depends on judgement as well as instructions.","zh":"他們的經驗很有價值，因為傳統烘焙不只靠指示，也靠判斷。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"support apprenticeship schemes","meaning":"支持學徒計劃","examples":[{"en":"The Government should support apprenticeship schemes.","zh":"政府應支持學徒計劃。"},{"en":"To support apprenticeship schemes means to help programmes where beginners learn skills from experienced workers.","zh":"「支持學徒計劃」指幫助初學者向有經驗工人學習技能的培訓項目。"},{"en":"A bakery apprenticeship scheme can train young people to make traditional pastries.","zh":"麵包店學徒計劃可以培訓年輕人製作傳統糕點。"},{"en":"Supporting apprenticeship schemes helps prevent craft skills from disappearing.","zh":"支持學徒計劃有助防止工藝技術消失。"},{"en":"This action turns heritage protection into real training, not just public praise.","zh":"這項行動把文化遺產保護變成真正培訓，而不只是公開讚揚。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"apprenticeship schemes","meaning":"學徒計劃","examples":[{"en":"Apprenticeship schemes can help pass on baking skills.","zh":"學徒計劃可以幫助傳承烘焙技術。"},{"en":"Apprenticeship schemes are training programmes in which learners gain skills by working with experienced people.","zh":"學徒計劃是學習者透過與有經驗的人工作而獲得技能的培訓項目。"},{"en":"An apprenticeship scheme may allow a young baker to learn directly in an old bakery.","zh":"學徒計劃可以讓年輕麵包師傅直接在舊式麵包店學習。"},{"en":"Apprenticeship schemes are useful for crafts because many techniques are learned by doing.","zh":"學徒計劃對工藝很有用，因為許多技術需要透過實作學習。"},{"en":"Without apprenticeship schemes, fewer young people may enter traditional trades.","zh":"如果沒有學徒計劃，可能較少年輕人加入傳統行業。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"create a recognised label","meaning":"設立認可標籤","examples":[{"en":"The Government could create a recognised label for traditional egg tarts.","zh":"政府可以為傳統蛋撻設立認可標籤。"},{"en":"To create a recognised label means to make an official or trusted mark that identifies approved products or practices.","zh":"「設立認可標籤」指建立一個官方或可信標記，用來識別獲認可的產品或做法。"},{"en":"A recognised label can help customers find shops that use traditional methods.","zh":"認可標籤可以幫助顧客找到使用傳統做法的店舖。"},{"en":"Creating a recognised label may encourage bakeries to maintain quality and authenticity.","zh":"設立認可標籤可能鼓勵麵包店保持質素和正宗性。"},{"en":"Such a label should be clear, fair, and based on real standards.","zh":"這種標籤應清楚、公平，並以真正標準為基礎。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"preserve authentic methods","meaning":"保留正宗做法","examples":[{"en":"Some shops preserve authentic methods of making egg tarts.","zh":"有些店舖保留製作蛋撻的正宗做法。"},{"en":"To preserve authentic methods means to keep original or traditional ways of doing something alive.","zh":"「保留正宗做法」指保存原本或傳統的做事方式，使其繼續存在。"},{"en":"The old noodle shop preserves authentic methods by making its broth by hand every morning.","zh":"那間老麵店每天早上手工熬湯，保留正宗做法。"},{"en":"Preserving authentic methods can protect both taste and skill.","zh":"保留正宗做法可以保護味道和技術。"},{"en":"This phrase is important because heritage is about process, not only final products.","zh":"這個說法很重要，因為文化遺產關乎過程，而不只是成品。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"authentic methods","meaning":"正宗做法","examples":[{"en":"Authentic methods should be protected and taught.","zh":"正宗做法應受到保護和教授。"},{"en":"Authentic methods are original, traditional, or trusted ways of doing something properly.","zh":"正宗做法是原本、傳統或可信的正確做事方式。"},{"en":"Authentic methods of making tea may include water temperature, timing, and serving style.","zh":"正宗泡茶做法可能包括水溫、時間和奉茶方式。"},{"en":"If authentic methods are replaced by shortcuts, the result may look similar but feel different.","zh":"如果正宗做法被捷徑取代，成品可能看似相似，但感覺不同。"},{"en":"Teaching authentic methods helps people understand why a tradition matters.","zh":"教授正宗做法可以幫助人理解一項傳統為何重要。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"organise bakery visits","meaning":"組織麵包店參觀","examples":[{"en":"Schools could organise bakery visits for students.","zh":"學校可以為學生組織麵包店參觀。"},{"en":"To organise bakery visits means to arrange trips for people to visit bakeries and learn how baked goods are made.","zh":"「組織麵包店參觀」指安排人們到麵包店參觀，學習烘焙食物如何製作。"},{"en":"A teacher organised a bakery visit so students could see bread being prepared.","zh":"老師組織了一次麵包店參觀，讓學生看見麵包如何準備。"},{"en":"Bakery visits help students connect food in shops with the labour and skill behind it.","zh":"麵包店參觀幫助學生把店裏的食物與背後的勞動和技術連繫起來。"},{"en":"This activity makes heritage education practical and memorable.","zh":"這項活動令文化遺產教育變得實用而難忘。"}],"source":"2017 Q5.pdf","sourcePage":8},{"front":"understand how food can carry history","meaning":"明白食物如何承載歷史","examples":[{"en":"Students should understand how food can carry history.","zh":"學生應明白食物如何承載歷史。"},{"en":"To understand how food can carry history means to see that dishes and recipes can preserve stories of culture, migration, and daily life.","zh":"「明白食物如何承載歷史」指看見菜式和食譜可以保存文化、遷徙和日常生活的故事。"},{"en":"Learning about mooncakes helps students understand how food can carry history through festivals.","zh":"學習月餅可以幫助學生明白食物如何透過節日承載歷史。"},{"en":"Food can carry history because ingredients, names, and methods often come from earlier times.","zh":"食物可以承載歷史，因為食材、名稱和做法常來自較早年代。"},{"en":"This understanding helps students see ordinary meals as cultural evidence.","zh":"這種理解幫助學生把普通飯菜看成文化證據。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"carry history","meaning":"承載歷史","examples":[{"en":"Food can carry history.","zh":"食物可以承載歷史。"},{"en":"To carry history means to hold and pass on memories, experiences, or meanings from the past.","zh":"「承載歷史」指保存並傳遞來自過去的記憶、經驗或意義。"},{"en":"An old street name can carry history about the people who once lived there.","zh":"一個舊街名可以承載曾經住在那裏的人們的歷史。"},{"en":"A recipe can carry history when it shows how families adapted to different times.","zh":"當食譜顯示家庭如何適應不同年代時，它便能承載歷史。"},{"en":"This phrase gives ordinary objects a deeper connection with the past.","zh":"這個說法賦予普通物件與過去更深的連繫。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"that way","meaning":"這樣","examples":[{"en":"That way, protection would become a living process.","zh":"這樣，保護便會成為一個活生生的過程。"},{"en":"That way means by doing the thing just mentioned or by using that method.","zh":"“That way” 指透過剛才提到的做法或方法。"},{"en":"Students could interview older residents; that way, they would learn history from real voices.","zh":"學生可以訪問年長居民；這樣，他們便能從真實聲音中學習歷史。"},{"en":"This phrase links a suggested action with its expected result.","zh":"這個說法把建議行動與預期結果連接起來。"},{"en":"It is useful when explaining why a proposed method would work.","zh":"當解釋某個建議方法為何有效時，它很有用。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"be reduced to a slogan","meaning":"淪為口號","examples":[{"en":"Protection should not be reduced to a slogan.","zh":"保護不應淪為口號。"},{"en":"To be reduced to a slogan means to become only a simple phrase without real action or meaning.","zh":"「淪為口號」指只變成一句簡單口號，而沒有實際行動或意義。"},{"en":"Environmental care is reduced to a slogan if no one actually reduces waste.","zh":"如果沒有人真正減少浪費，環保便會淪為口號。"},{"en":"Heritage protection may be reduced to a slogan when officials praise traditions but do not support practitioners.","zh":"如果官員只是讚揚傳統，卻不支援實踐者，文化遺產保護便可能淪為口號。"},{"en":"This phrase warns against empty words without practical work.","zh":"這個說法提醒我們避免只有空話而沒有實際工作。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"a living process of transmission","meaning":"活生生的傳承過程","examples":[{"en":"Heritage protection should become a living process of transmission.","zh":"文化遺產保護應成為活生生的傳承過程。"},{"en":"A living process of transmission means an active way of passing knowledge, skills, and customs from one generation to another.","zh":"活生生的傳承過程是把知識、技能和習俗由一代傳給另一代的主動方式。"},{"en":"Cooking with grandparents can be a living process of transmission for family recipes.","zh":"與祖父母一起下廚，可以成為家庭食譜活生生的傳承過程。"},{"en":"Heritage survives better when transmission happens through practice, not only display.","zh":"當傳承透過實踐而不只是展示發生時，文化遺產更容易延續。"},{"en":"This phrase stresses that culture must be taught, used, and continued.","zh":"這個說法強調文化必須被教授、使用和延續。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"transmission","meaning":"傳承","examples":[{"en":"Cultural transmission keeps traditions alive.","zh":"文化傳承令傳統保持生命力。"},{"en":"Transmission is the passing of knowledge, skills, beliefs, or customs from one person or generation to another.","zh":"傳承是把知識、技能、信念或習俗由一個人或一代傳給另一個人或下一代。"},{"en":"A master baker’s teaching is a form of transmission.","zh":"麵包師傅的教導是一種傳承。"},{"en":"Without transmission, a tradition may remain famous but no longer practised.","zh":"如果沒有傳承，一項傳統可能仍然有名，卻不再被實踐。"},{"en":"Transmission is central to living heritage because people must continue the practice.","zh":"傳承是活態文化遺產的核心，因為人們必須繼續實踐它。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"by the same token","meaning":"同樣道理","examples":[{"en":"By the same token, mahjong is worth preserving.","zh":"同樣道理，麻雀值得保存。"},{"en":"By the same token means for the same reason or using the same logic.","zh":"“By the same token” 指基於同一原因或使用同一邏輯。"},{"en":"Old recipes should be recorded; by the same token, old songs should also be preserved.","zh":"舊食譜應被記錄；同樣道理，舊歌曲也應被保存。"},{"en":"This phrase connects a new example to an argument already made.","zh":"這個說法把新的例子與已提出的論點連接起來。"},{"en":"It is useful when showing that the same principle applies to another case.","zh":"當顯示同一原則適用於另一情況時，它很有用。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"worth preserving","meaning":"值得保存","examples":[{"en":"Mahjong is worth preserving as social heritage.","zh":"麻雀作為社會文化遺產值得保存。"},{"en":"Worth preserving means valuable enough to be kept, recorded, taught, or continued.","zh":"“Worth preserving” 指有足夠價值，值得被保存、記錄、教授或延續。"},{"en":"A local dialect is worth preserving because it carries humour and memory.","zh":"本地方言值得保存，因為它承載幽默和記憶。"},{"en":"Traditions worth preserving need active practice, not only praise.","zh":"值得保存的傳統需要積極實踐，而不只是讚揚。"},{"en":"Mahjong is worth preserving because it keeps social relationships and family habits alive.","zh":"麻雀值得保存，因為它延續社交關係和家庭習慣。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"recognisable social languages","meaning":"最具辨識度的社交語言","examples":[{"en":"Mahjong is one of Hong Kong’s most recognisable social languages.","zh":"麻雀是香港最具辨識度的社交語言之一。"},{"en":"Recognisable social languages are familiar ways people communicate, connect, and build relationships through shared activities.","zh":"最具辨識度的社交語言是人們透過共同活動溝通、連繫和建立關係的熟悉方式。"},{"en":"Tea drinking can be a recognisable social language in a community where people gather around it.","zh":"在一個人們常圍繞飲茶相聚的社區中，飲茶可以是一種具辨識度的社交語言。"},{"en":"Mahjong works as a social language because players joke, read expressions, and follow shared rules.","zh":"麻雀像一種社交語言，因為玩家會說笑、讀懂表情和遵守共同規則。"},{"en":"This phrase suggests that culture can communicate even without formal speech.","zh":"這個說法暗示文化即使沒有正式說話，也可以傳遞訊息。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"during Lunar New Year","meaning":"農曆新年期間","examples":[{"en":"Many families play mahjong during Lunar New Year.","zh":"許多家庭在農曆新年期間打麻雀。"},{"en":"During Lunar New Year means in the festival period that begins the traditional lunar calendar year.","zh":"“During Lunar New Year” 指在傳統農曆新年開始的節日期間。"},{"en":"During Lunar New Year, relatives often visit one another and share festive food.","zh":"農曆新年期間，親戚常互相拜訪並分享節日食物。"},{"en":"Mahjong becomes common during Lunar New Year because families have time to gather.","zh":"麻雀在農曆新年期間很常見，因為家人有時間相聚。"},{"en":"This phrase places the activity in an important family and cultural season.","zh":"這個說法把活動放在重要的家庭和文化時節中。"}],"source":"2017 Q5.pdf","sourcePage":9},{"front":"not merely","meaning":"不只是","examples":[{"en":"Mahjong is not merely a game of winning and losing.","zh":"麻雀不只是勝負遊戲。"},{"en":"Not merely means not only or not simply; there is a deeper meaning beyond the obvious one.","zh":"“Not merely” 指不只或不單是，明顯意思背後還有更深意義。"},{"en":"A family meal is not merely eating; it is also a chance to talk and reconnect.","zh":"家庭飯局不只是吃飯，也是聊天和重新連繫的機會。"},{"en":"Mahjong is not merely entertainment because it also carries social habits and language.","zh":"麻雀不只是娛樂，因為它也承載社交習慣和語言。"},{"en":"This phrase helps the writer move from surface function to cultural value.","zh":"這個說法幫助作者由表面功能轉向文化價值。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"winning and losing","meaning":"勝負","examples":[{"en":"Mahjong is more than a game of winning and losing.","zh":"麻雀不只是一個關於勝負的遊戲。"},{"en":"Winning and losing means the result of a game or competition, where someone succeeds and someone does not.","zh":"勝負指遊戲或比賽的結果，有人成功，也有人沒有勝出。"},{"en":"Children should learn that sport is not only about winning and losing.","zh":"孩子應學會運動不只是關於勝負。"},{"en":"If people focus only on winning and losing, they may miss friendship, skill, and enjoyment.","zh":"如果人只專注勝負，可能會忽略友誼、技巧和樂趣。"},{"en":"In mahjong, winning and losing are part of the game, but not the whole cultural meaning.","zh":"在麻雀中，勝負是遊戲的一部分，但不是全部文化意義。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"sit at the same table","meaning":"坐在同一張桌旁","examples":[{"en":"Mahjong allows different generations to sit at the same table.","zh":"麻雀讓不同世代坐在同一張桌旁。"},{"en":"To sit at the same table means to gather in one shared place for conversation, food, work, or play.","zh":"「坐在同一張桌旁」指聚在同一個共同地方聊天、吃飯、工作或遊戲。"},{"en":"During festivals, grandparents and grandchildren sit at the same table for dinner.","zh":"節日期間，祖父母和孫兒會坐在同一張桌旁吃飯。"},{"en":"Sitting at the same table can reduce distance between people of different ages.","zh":"坐在同一張桌旁可以拉近不同年齡人士之間的距離。"},{"en":"In mahjong, the shared table becomes a place for social connection.","zh":"在麻雀中，共同的桌子成為社交連繫的地方。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"exchange jokes","meaning":"開玩笑；互相說笑","examples":[{"en":"Families exchange jokes while playing mahjong.","zh":"家人打麻雀時會互相說笑。"},{"en":"To exchange jokes means to tell funny comments to one another in a friendly way.","zh":"「互相說笑」指以友善方式彼此說有趣的話。"},{"en":"Cousins exchanged jokes while helping prepare dinner.","zh":"表兄弟姊妹一邊幫忙準備晚飯，一邊互相說笑。"},{"en":"Exchanging jokes can make a family gathering feel warmer and less formal.","zh":"互相說笑可以令家庭聚會感覺更溫暖和沒那麼正式。"},{"en":"In mahjong, jokes are part of the social atmosphere around the game.","zh":"在麻雀中，玩笑是圍繞遊戲的社交氣氛的一部分。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"practise calculation","meaning":"練習計算","examples":[{"en":"Players practise calculation during mahjong.","zh":"玩家在打麻雀時練習計算。"},{"en":"To practise calculation means to use and improve number skills through repeated activity.","zh":"「練習計算」指透過重複活動使用並提升數字能力。"},{"en":"Children practise calculation when they add prices at a small shop.","zh":"孩子在小店把價錢加起來時，就是在練習計算。"},{"en":"Mahjong players practise calculation because they must count tiles, points, and possible combinations.","zh":"麻雀玩家要練習計算，因為他們必須數牌、分數和可能組合。"},{"en":"This phrase shows that a game can train thinking skills as well as entertain.","zh":"這個說法顯示遊戲不只娛樂，也可以訓練思考能力。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"read one another’s expressions","meaning":"讀懂彼此表情","examples":[{"en":"Players learn to read one another’s expressions.","zh":"玩家學會讀懂彼此表情。"},{"en":"To read one another’s expressions means to understand other people’s feelings or intentions by looking at their faces.","zh":"「讀懂彼此表情」指透過觀察別人的臉部表情，理解他們的感受或意圖。"},{"en":"During a debate, students learn to read one another’s expressions before responding.","zh":"在辯論中，學生回應前會學習讀懂彼此表情。"},{"en":"Mahjong players read expressions to guess whether someone is confident, worried, or pretending.","zh":"麻雀玩家會讀懂表情，以猜測別人是有信心、擔心還是在假裝。"},{"en":"This skill shows that mahjong involves social awareness, not only rules.","zh":"這種技巧顯示麻雀涉及社交觀察力，而不只是規則。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"tiles being shuffled","meaning":"麻雀牌被洗動","examples":[{"en":"The sound of tiles being shuffled is familiar to many Hongkongers.","zh":"麻雀牌被洗動的聲音對許多香港人來說很熟悉。"},{"en":"Tiles being shuffled refers to mahjong tiles being mixed by players before a new round.","zh":"“Tiles being shuffled” 指玩家在新一局開始前把麻雀牌混在一起洗動。"},{"en":"The sound of tiles being shuffled filled the room before the game began.","zh":"遊戲開始前，房間裏充滿麻雀牌被洗動的聲音。"},{"en":"Shuffling tiles creates a rhythm that many people associate with family gatherings.","zh":"洗牌聲形成一種節奏，許多人會把它與家庭聚會連繫起來。"},{"en":"This phrase focuses on the sound that makes mahjong instantly recognisable.","zh":"這個說法集中於令麻雀立即被認出的聲音。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"almost as familiar as","meaning":"幾乎像……一樣熟悉","examples":[{"en":"The sound of mahjong tiles is almost as familiar as the tram’s ding-ding.","zh":"麻雀牌的聲音幾乎像電車叮叮聲一樣熟悉。"},{"en":"Almost as familiar as means nearly equally well known or easily recognised.","zh":"“Almost as familiar as” 指幾乎同樣為人熟知或容易認出。"},{"en":"The school bell is almost as familiar as my own phone ringtone.","zh":"校鐘聲幾乎像我自己的電話鈴聲一樣熟悉。"},{"en":"Comparing two familiar sounds helps readers understand how common the mahjong sound is.","zh":"把兩種熟悉聲音作比較，有助讀者理解麻雀聲有多普遍。"},{"en":"This phrase shows that mahjong belongs to the soundscape of daily Hong Kong life.","zh":"這個說法顯示麻雀屬於香港日常生活的聲音景觀。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"Hongkongers","meaning":"香港人","examples":[{"en":"The sound is familiar to many Hongkongers.","zh":"這種聲音對許多香港人來說很熟悉。"},{"en":"Hongkongers are people who live in Hong Kong or identify with Hong Kong.","zh":"香港人是居住在香港或認同香港身份的人。"},{"en":"Many Hongkongers recognise the sound of trams, markets, and mahjong tiles.","zh":"許多香港人認得電車、街市和麻雀牌的聲音。"},{"en":"A tradition becomes meaningful when many Hongkongers connect it with personal memory.","zh":"當許多香港人把某項傳統與個人回憶連繫起來，它便變得有意義。"},{"en":"This word identifies the community whose culture is being discussed.","zh":"這個詞指出文章所討論文化所屬的社群。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"the ding-ding of the tram","meaning":"電車叮叮聲","examples":[{"en":"The ding-ding of the tram is a familiar Hong Kong sound.","zh":"電車叮叮聲是熟悉的香港聲音。"},{"en":"The ding-ding of the tram is the bell sound made by Hong Kong trams.","zh":"電車叮叮聲是香港電車發出的鈴聲。"},{"en":"People walking on Hong Kong Island often hear the ding-ding of the tram.","zh":"在港島行走的人常會聽到電車叮叮聲。"},{"en":"This sound is culturally meaningful because it belongs to everyday city life.","zh":"這種聲音具有文化意義，因為它屬於日常城市生活。"},{"en":"Comparing mahjong tiles with the tram’s ding-ding shows both are familiar local sounds.","zh":"把麻雀牌聲與電車叮叮聲相比，顯示兩者都是熟悉的本地聲音。"}],"source":"2017 Q5.pdf","sourcePage":10},{"front":"culturally valuable","meaning":"具有文化價值","examples":[{"en":"Mahjong is culturally valuable because of its social atmosphere.","zh":"麻雀因其社交氣氛而具有文化價值。"},{"en":"Culturally valuable means important to a community’s identity, memory, habits, or way of life.","zh":"“Culturally valuable” 指對社群身份、記憶、習慣或生活方式重要。"},{"en":"A local festival is culturally valuable if it brings neighbours together every year.","zh":"如果一個本地節日每年把鄰里聚在一起，它便具有文化價值。"},{"en":"Something culturally valuable may look ordinary to outsiders but meaningful to the people who practise it.","zh":"具有文化價值的事物對外人來說可能普通，但對實踐者有意義。"},{"en":"Mahjong is culturally valuable because it carries language, family bonds, and shared memories.","zh":"麻雀具有文化價值，因為它承載語言、家庭聯繫和共同回憶。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"not only…, but also…","meaning":"不只是……而且是……","examples":[{"en":"What makes mahjong valuable is not only its rules, but also the atmosphere around it.","zh":"令麻雀有價值的，不只是它的規則，而且是圍繞它的氣氛。"},{"en":"“Not only…, but also…” connects two important points and adds the second as another key idea.","zh":"“Not only…, but also…” 連接兩個重要重點，並把第二個也加入為關鍵想法。"},{"en":"A good school teaches not only knowledge, but also responsibility.","zh":"好學校教授的不只是知識，而且是責任感。"},{"en":"Mahjong matters not only because of how it is played, but also because of how people gather around it.","zh":"麻雀重要，不只是因為玩法，而且因為人們如何圍繞它相聚。"},{"en":"This structure helps show that value has more than one source.","zh":"這個結構幫助顯示價值不只來自一個來源。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"the atmosphere around it","meaning":"圍繞它的氣氛","examples":[{"en":"The atmosphere around mahjong is part of its cultural value.","zh":"圍繞麻雀的氣氛是其文化價值的一部分。"},{"en":"The atmosphere around it means the feelings, sounds, conversations, and social habits surrounding an activity.","zh":"「圍繞它的氣氛」指某項活動周圍的感受、聲音、對話和社交習慣。"},{"en":"The atmosphere around a family meal includes laughter, noise, and shared dishes.","zh":"家庭飯局的氣氛包括笑聲、聲音和共享菜式。"},{"en":"Mahjong’s atmosphere matters because jokes and conversations are part of the experience.","zh":"麻雀的氣氛很重要，因為玩笑和對話都是經驗的一部分。"},{"en":"This phrase shows that culture includes the setting, not only the activity itself.","zh":"這個說法顯示文化包括環境氣氛，而不只是活動本身。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"Cantonese expressions","meaning":"廣東話用語","examples":[{"en":"Mahjong includes many Cantonese expressions.","zh":"麻雀包含許多廣東話用語。"},{"en":"Cantonese expressions are words or phrases used in Cantonese speech, often carrying local humour or meaning.","zh":"廣東話用語是廣東話中使用的詞語或短語，常帶有本地幽默或意思。"},{"en":"Older relatives may use Cantonese expressions while teaching children how to play mahjong.","zh":"年長親戚教孩子打麻雀時，可能會使用廣東話用語。"},{"en":"Cantonese expressions can preserve local ways of speaking that are difficult to translate exactly.","zh":"廣東話用語可以保存難以完全翻譯的本地說話方式。"},{"en":"In mahjong, these expressions make the game feel strongly connected to Hong Kong life.","zh":"在麻雀中，這些用語令遊戲與香港生活有強烈連繫。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"family teasing","meaning":"家人之間的玩笑取笑","examples":[{"en":"Family teasing is part of the mahjong atmosphere.","zh":"家人之間的玩笑取笑是麻雀氣氛的一部分。"},{"en":"Family teasing means playful joking among relatives, usually without serious harm or cruelty.","zh":"家人之間的玩笑取笑是親戚之間帶玩味的說笑，通常沒有真正傷害或惡意。"},{"en":"Grandparents may use family teasing to joke about who always loses at mahjong.","zh":"祖父母可能用玩笑取笑總是輸麻雀的人。"},{"en":"Family teasing can make gatherings warmer when everyone understands it is affectionate.","zh":"當每個人都明白這帶有親情時，家人之間的玩笑取笑可以令聚會更溫暖。"},{"en":"This phrase shows the informal and human side of family culture.","zh":"這個說法顯示家庭文化中非正式而有人情味的一面。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"patience required","meaning":"所需的耐性","examples":[{"en":"Mahjong teaches the patience required to play well.","zh":"麻雀教人打得好所需的耐性。"},{"en":"Patience required means the calm waiting and self-control needed to do something successfully.","zh":"「所需的耐性」指成功做好某事需要的冷靜等待和自我控制。"},{"en":"Gardening teaches the patience required to wait for seeds to grow.","zh":"園藝教人等待種子生長所需的耐性。"},{"en":"Mahjong requires patience because players must wait, observe, and avoid careless moves.","zh":"麻雀需要耐性，因為玩家必須等待、觀察和避免粗心出牌。"},{"en":"This phrase shows that a game can train character as well as skill.","zh":"這個說法顯示遊戲可以訓練品格，也可以訓練技巧。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"unspoken understanding","meaning":"心照不宣的默契","examples":[{"en":"Mahjong creates unspoken understanding between players.","zh":"麻雀在玩家之間建立心照不宣的默契。"},{"en":"Unspoken understanding is a shared awareness that people have without needing to explain everything aloud.","zh":"心照不宣的默契是人們不需要把一切說出口，也能共享的理解。"},{"en":"Close friends often have unspoken understanding about when one of them needs support.","zh":"親密朋友常有心照不宣的默契，知道對方何時需要支持。"},{"en":"In mahjong, players may understand mood, strategy, or humour without direct explanation.","zh":"在麻雀中，玩家可能不用直接解釋，也能理解情緒、策略或幽默。"},{"en":"This phrase shows a quiet form of communication within relationships.","zh":"這個說法顯示關係中安靜的溝通形式。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"between players","meaning":"玩家之間","examples":[{"en":"There is often unspoken understanding between players.","zh":"玩家之間常有心照不宣的默契。"},{"en":"Between players means among the people taking part in the game.","zh":"“Between players” 指參與遊戲的人之間。"},{"en":"Trust between players is important in team sports.","zh":"在團隊運動中，玩家之間的信任很重要。"},{"en":"Communication between players can happen through words, gestures, or shared habits.","zh":"玩家之間的溝通可以透過說話、手勢或共同習慣發生。"},{"en":"In mahjong, the relationships between players are part of the cultural experience.","zh":"在麻雀中，玩家之間的關係是文化經驗的一部分。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"intergenerational bonds","meaning":"跨代聯繫","examples":[{"en":"Mahjong can strengthen intergenerational bonds.","zh":"麻雀可以加強跨代聯繫。"},{"en":"Intergenerational bonds are relationships and connections between people of different age groups, especially within families.","zh":"跨代聯繫是不同年齡群體之間，尤其家庭內不同世代之間的關係和連繫。"},{"en":"Cooking with grandparents can strengthen intergenerational bonds.","zh":"與祖父母一起煮食可以加強跨代聯繫。"},{"en":"Shared activities help intergenerational bonds because older and younger people spend time together.","zh":"共同活動有助跨代聯繫，因為長輩和年輕人能一起花時間。"},{"en":"Mahjong can support these bonds by giving family members a common activity.","zh":"麻雀可以透過給家人一項共同活動來支持這些聯繫。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"become weaker","meaning":"變得較弱","examples":[{"en":"Without shared activities, intergenerational bonds may become weaker.","zh":"如果沒有共同活動，跨代聯繫可能會變得較弱。"},{"en":"Become weaker means lose strength, closeness, influence, or effectiveness over time.","zh":"“Become weaker” 指隨時間失去力量、親近感、影響力或效用。"},{"en":"Friendships may become weaker if people stop meeting or talking.","zh":"如果人們停止見面或聊天，友誼可能會變得較弱。"},{"en":"Family bonds can become weaker when everyone eats alone and rarely shares activities.","zh":"當每個人都獨自吃飯，很少共享活動時，家庭聯繫可能會變得較弱。"},{"en":"This phrase shows a gradual decline that can happen without attention.","zh":"這個說法顯示一種在缺乏關注下可能發生的逐漸衰退。"}],"source":"2017 Q5.pdf","sourcePage":11},{"front":"small flats","meaning":"細小單位","examples":[{"en":"Small flats leave families with fewer chances to gather.","zh":"細小單位令家庭較少機會相聚。"},{"en":"Small flats are small apartments with limited space for living, storage, and visitors.","zh":"細小單位是生活、儲物和接待訪客空間有限的小型住宅。"},{"en":"In small flats, families may not have enough room for a large table or many guests.","zh":"在細小單位裏，家庭可能沒有足夠地方放大桌子或招待很多客人。"},{"en":"Small flats can make family gatherings more difficult because space is limited.","zh":"細小單位可能令家庭聚會更困難，因為空間有限。"},{"en":"This phrase connects housing conditions with changes in social habits.","zh":"這個說法把住屋條件與社交習慣變化連接起來。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"long working hours","meaning":"長工時","examples":[{"en":"Long working hours reduce family time.","zh":"長工時減少家庭時間。"},{"en":"Long working hours mean spending many hours at work, often leaving less time for rest or family.","zh":"長工時指花很多小時工作，通常令休息或家庭時間減少。"},{"en":"Long working hours can make parents too tired to join evening family activities.","zh":"長工時可能令父母太疲累，無法參與晚上的家庭活動。"},{"en":"When long working hours become normal, shared traditions may happen less often.","zh":"當長工時變成常態，共同傳統可能較少發生。"},{"en":"This phrase explains how modern work patterns can weaken family routines.","zh":"這個說法解釋現代工作模式如何削弱家庭習慣。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"digital entertainment","meaning":"數碼娛樂","examples":[{"en":"Digital entertainment gives families fewer chances to gather.","zh":"數碼娛樂令家庭較少機會相聚。"},{"en":"Digital entertainment refers to entertainment using screens or electronic devices, such as games, videos, and apps.","zh":"數碼娛樂指使用螢幕或電子裝置的娛樂，例如遊戲、影片和應用程式。"},{"en":"Many teenagers spend free time on digital entertainment instead of joining family conversations.","zh":"許多少年把空閒時間花在數碼娛樂上，而不是參與家庭對話。"},{"en":"Digital entertainment can be enjoyable, but it may reduce face-to-face activities if used too much.","zh":"數碼娛樂可以令人享受，但如果使用太多，可能減少面對面活動。"},{"en":"This phrase shows one modern reason traditional gatherings may become less common.","zh":"這個說法顯示傳統聚會變少的一個現代原因。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"leave families with fewer chances to gather","meaning":"令家庭較少機會相聚","examples":[{"en":"Modern city life leaves families with fewer chances to gather.","zh":"現代城市生活令家庭較少機會相聚。"},{"en":"To leave families with fewer chances to gather means to reduce the opportunities for family members to spend time together.","zh":"「令家庭較少機會相聚」指減少家庭成員一起花時間的機會。"},{"en":"Busy schedules leave families with fewer chances to gather for dinner.","zh":"忙碌時間表令家庭較少機會一起吃晚飯。"},{"en":"When families have fewer chances to gather, shared traditions may become weaker.","zh":"當家庭較少機會相聚，共同傳統可能會變弱。"},{"en":"This phrase explains how lifestyle changes affect family culture.","zh":"這個說法解釋生活方式改變如何影響家庭文化。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"protect something responsibly","meaning":"負責任地保護","examples":[{"en":"Mahjong should be protected responsibly.","zh":"麻雀應被負責任地保護。"},{"en":"To protect something responsibly means to preserve it carefully while recognising possible risks or concerns.","zh":"「負責任地保護」指在保存某事物時，也小心承認可能的風險或關注。"},{"en":"Schools can protect online learning responsibly by teaching safety as well as skills.","zh":"學校可以透過同時教授安全和技能，負責任地保護網上學習。"},{"en":"Protecting mahjong responsibly means valuing its culture without promoting harmful gambling.","zh":"負責任地保護麻雀，意思是重視其文化，而不推廣有害賭博。"},{"en":"This phrase shows a balanced approach to heritage protection.","zh":"這個說法顯示一種平衡的文化遺產保護方法。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"community centres","meaning":"社區中心","examples":[{"en":"Community centres could introduce non-gambling mahjong workshops.","zh":"社區中心可以引入非賭博麻雀工作坊。"},{"en":"Community centres are local places where residents can join activities, classes, and services.","zh":"社區中心是居民可以參加活動、課程和服務的本地場所。"},{"en":"Elderly residents may attend exercise classes at community centres.","zh":"年長居民可能在社區中心參加運動班。"},{"en":"Community centres are useful for heritage education because they are close to ordinary people.","zh":"社區中心適合文化遺產教育，因為它們貼近普通人。"},{"en":"Holding mahjong workshops in community centres can make learning safe and accessible.","zh":"在社區中心舉辦麻雀工作坊，可以令學習安全而容易參與。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"non-gambling mahjong workshops","meaning":"非賭博麻雀工作坊","examples":[{"en":"Schools could introduce non-gambling mahjong workshops.","zh":"學校可以引入非賭博麻雀工作坊。"},{"en":"Non-gambling mahjong workshops are learning activities that teach mahjong without betting money.","zh":"非賭博麻雀工作坊是不涉及金錢下注、用來教授麻雀的學習活動。"},{"en":"A non-gambling mahjong workshop can focus on rules, counting, strategy, and cultural history.","zh":"非賭博麻雀工作坊可以集中於規則、計分、策略和文化歷史。"},{"en":"These workshops reduce concern because students learn culture rather than gambling habits.","zh":"這些工作坊能減少憂慮，因為學生學的是文化，而不是賭博習慣。"},{"en":"This phrase separates mahjong as heritage from mahjong as betting.","zh":"這個說法把作為文化遺產的麻雀與作為下注的麻雀分開。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"focusing on","meaning":"集中於","examples":[{"en":"The workshops could focus on strategy, arithmetic and cultural history.","zh":"工作坊可以集中於策略、算術和文化歷史。"},{"en":"Focusing on something means giving most attention to that subject or goal.","zh":"“Focusing on” 指把大部分注意力放在某個主題或目標上。"},{"en":"The lesson focused on pronunciation instead of grammar.","zh":"那堂課集中於發音，而不是文法。"},{"en":"Workshops focusing on culture can help people understand mahjong beyond gambling.","zh":"集中於文化的工作坊可以幫助人們理解麻雀不只是賭博。"},{"en":"This phrase shows what the main learning purpose should be.","zh":"這個說法顯示主要學習目的應是甚麼。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"strategy","meaning":"策略","examples":[{"en":"Mahjong workshops can teach strategy.","zh":"麻雀工作坊可以教授策略。"},{"en":"Strategy is a careful plan or way of making decisions to achieve a goal.","zh":"策略是為達成目標而仔細制定的計劃或決策方法。"},{"en":"In chess, players need strategy to protect important pieces and plan future moves.","zh":"在國際象棋中，玩家需要策略來保護重要棋子並計劃下一步。"},{"en":"Mahjong strategy includes deciding which tiles to keep and which risks to take.","zh":"麻雀策略包括決定保留哪些牌和承擔哪些風險。"},{"en":"Learning strategy helps players think ahead rather than act randomly.","zh":"學習策略幫助玩家預先思考，而不是隨意行動。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"arithmetic","meaning":"算術","examples":[{"en":"Mahjong can help students practise arithmetic.","zh":"麻雀可以幫助學生練習算術。"},{"en":"Arithmetic is basic mathematics involving numbers, such as adding, subtracting, multiplying, and dividing.","zh":"算術是涉及數字的基礎數學，例如加、減、乘、除。"},{"en":"Children practise arithmetic when they calculate the total cost of snacks.","zh":"孩子計算小食總價時，就是在練習算術。"},{"en":"Mahjong can involve arithmetic because players count points and possible combinations.","zh":"麻雀可以涉及算術，因為玩家要計分和計算可能組合。"},{"en":"This phrase shows that a traditional game can support number skills.","zh":"這個說法顯示傳統遊戲可以支援數字能力。"}],"source":"2017 Q5.pdf","sourcePage":12},{"front":"cultural history","meaning":"文化歷史","examples":[{"en":"The workshops can also teach cultural history.","zh":"工作坊也可以教授文化歷史。"},{"en":"Cultural history is the study of how people’s customs, beliefs, arts, language, and daily habits developed over time.","zh":"文化歷史是研究人們的習俗、信念、藝術、語言和日常習慣如何隨時間發展。"},{"en":"Learning the cultural history of tea can explain why certain families gather around it.","zh":"學習茶的文化歷史，可以解釋為何某些家庭會圍繞它相聚。"},{"en":"Mahjong’s cultural history includes family gatherings, local expressions, and changing attitudes towards games.","zh":"麻雀的文化歷史包括家庭聚會、本地用語和人們對遊戲態度的改變。"},{"en":"Teaching cultural history helps people see deeper meaning behind ordinary practices.","zh":"教授文化歷史可以幫助人看見普通習俗背後更深的意義。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"display traditional tile sets","meaning":"展示傳統麻雀牌套裝","examples":[{"en":"Museums could display traditional tile sets.","zh":"博物館可以展示傳統麻雀牌套裝。"},{"en":"To display traditional tile sets means to show old or culturally important mahjong sets for people to view and learn from.","zh":"「展示傳統麻雀牌套裝」指展出舊式或有文化重要性的麻雀牌套裝，讓人觀看和學習。"},{"en":"A museum may display traditional tile sets beside photos of family gatherings.","zh":"博物館可以把傳統麻雀牌套裝與家庭聚會照片一同展示。"},{"en":"Displaying tile sets helps visitors see materials, designs, and craft changes over time.","zh":"展示牌套裝可以幫助訪客看見材料、設計和工藝如何隨時間改變。"},{"en":"This method preserves mahjong history visually, but it should be combined with living practice.","zh":"這種方法以視覺方式保存麻雀歷史，但應與活態實踐結合。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"traditional tile sets","meaning":"傳統麻雀牌套裝","examples":[{"en":"Traditional tile sets can show the history of mahjong.","zh":"傳統麻雀牌套裝可以顯示麻雀的歷史。"},{"en":"Traditional tile sets are older or classic groups of mahjong tiles used for playing the game.","zh":"傳統麻雀牌套裝是用來打麻雀的較舊或經典的一整套麻雀牌。"},{"en":"Some traditional tile sets are made from materials and designs no longer common today.","zh":"有些傳統麻雀牌套裝使用今天已不常見的材料和設計。"},{"en":"Traditional tile sets can reveal changes in craft, symbols, and family taste.","zh":"傳統麻雀牌套裝可以反映工藝、符號和家庭品味的變化。"},{"en":"Keeping these sets helps preserve the physical side of mahjong culture.","zh":"保存這些套裝有助保存麻雀文化的實物面向。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"interview tile-makers","meaning":"訪問麻雀牌製作師傅","examples":[{"en":"Museums could interview tile-makers.","zh":"博物館可以訪問麻雀牌製作師傅。"},{"en":"To interview tile-makers means to ask people who make mahjong tiles about their skills, memories, and work.","zh":"「訪問麻雀牌製作師傅」指向製作麻雀牌的人詢問他們的技術、記憶和工作。"},{"en":"Students interviewed tile-makers to learn how old mahjong sets were carved.","zh":"學生訪問麻雀牌製作師傅，了解舊麻雀牌如何雕刻。"},{"en":"Interviewing tile-makers preserves knowledge that may disappear when craftspeople retire.","zh":"訪問製作師傅可以保存他們退休後可能消失的知識。"},{"en":"This action connects museum display with human experience.","zh":"這項行動把博物館展示與人的經驗連接起來。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"tile-makers","meaning":"麻雀牌製作師傅","examples":[{"en":"Tile-makers can explain how mahjong sets are made.","zh":"麻雀牌製作師傅可以解釋麻雀套裝如何製作。"},{"en":"Tile-makers are craftspeople who produce, carve, paint, or repair mahjong tiles.","zh":"麻雀牌製作師傅是製作、雕刻、上色或修補麻雀牌的工藝人。"},{"en":"Experienced tile-makers know how to make markings clear and tiles comfortable to handle.","zh":"有經驗的麻雀牌製作師傅知道如何令字樣清楚，並令牌手感舒適。"},{"en":"Tile-makers are important because they preserve the craft behind the game.","zh":"麻雀牌製作師傅很重要，因為他們保存遊戲背後的工藝。"},{"en":"Without tile-makers, mahjong culture would lose part of its material tradition.","zh":"如果沒有麻雀牌製作師傅，麻雀文化會失去部分實物傳統。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"youth groups","meaning":"青年團體","examples":[{"en":"Youth groups could record grandparents explaining local playing styles.","zh":"青年團體可以記錄祖父母解釋本地玩法。"},{"en":"Youth groups are organised groups of young people who join activities, projects, or community work.","zh":"青年團體是由年輕人組成、參與活動、項目或社區工作的組織。"},{"en":"A youth group may visit elderly residents to collect stories about old neighbourhood life.","zh":"青年團體可能探訪年長居民，收集舊社區生活故事。"},{"en":"Youth groups can help heritage transmission by connecting young people with older generations.","zh":"青年團體可以透過連繫年輕人和長輩，幫助文化遺產傳承。"},{"en":"This phrase shows that young people can actively protect culture.","zh":"這個說法顯示年輕人也可以積極保護文化。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"local playing styles","meaning":"本地玩法","examples":[{"en":"Grandparents can explain local playing styles.","zh":"祖父母可以解釋本地玩法。"},{"en":"Local playing styles are the particular rules, habits, and methods used by people in a specific place.","zh":"本地玩法是某個地方的人使用的特定規則、習慣和方法。"},{"en":"Local playing styles of mahjong may differ between families or neighbourhoods.","zh":"麻雀本地玩法可能因家庭或社區而不同。"},{"en":"Recording local playing styles helps preserve variation instead of treating one version as the only correct one.","zh":"記錄本地玩法有助保存差異，而不是把一種版本視為唯一正確玩法。"},{"en":"This phrase shows that heritage includes small differences in practice.","zh":"這個說法顯示文化遺產包括實踐中的小差異。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"in this way","meaning":"以這種方式","examples":[{"en":"In this way, mahjong can be presented as social heritage.","zh":"以這種方式，麻雀可以被呈現為社會文化遺產。"},{"en":"In this way means by using the method just described.","zh":"“In this way” 指透過剛才描述的方法。"},{"en":"Students can interview older residents; in this way, they learn history through real voices.","zh":"學生可以訪問年長居民；以這種方式，他們透過真實聲音學習歷史。"},{"en":"This phrase links a practical action to a desired result.","zh":"這個說法把實際行動與期望結果連接起來。"},{"en":"It helps the writer explain how a proposal can solve a concern.","zh":"它幫助作者解釋建議如何解決某個關注。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"be presented not as…, but as…","meaning":"不被呈現為……而是呈現為……","examples":[{"en":"Mahjong can be presented not as a vice, but as social heritage.","zh":"麻雀可以不被呈現為惡習，而是呈現為社會文化遺產。"},{"en":"To be presented not as one thing, but as another means to change how people understand or describe it.","zh":"“Be presented not as…, but as…” 指改變人們理解或描述某事物的方式。"},{"en":"Local food can be presented not as cheap snacks, but as cultural memory.","zh":"本地食物可以不被呈現為廉價小食，而是呈現為文化記憶。"},{"en":"This structure rejects a negative label and replaces it with a more accurate meaning.","zh":"這個結構否定負面標籤，並以更準確的意義取代。"},{"en":"It is useful when correcting a misunderstanding about a tradition.","zh":"當要糾正人們對某項傳統的誤解時，它很有用。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"a vice","meaning":"惡習","examples":[{"en":"Mahjong should not simply be presented as a vice.","zh":"麻雀不應只被呈現為一種惡習。"},{"en":"A vice is a bad habit or immoral activity that may harm a person or society.","zh":"惡習是可能傷害個人或社會的壞習慣或不道德活動。"},{"en":"Gambling can become a vice if it causes debt and damages family life.","zh":"如果賭博造成債務並損害家庭生活，它可能成為惡習。"},{"en":"Calling mahjong only a vice ignores its family, cultural, and social meanings.","zh":"只把麻雀稱為惡習，會忽略它的家庭、文化和社交意義。"},{"en":"This word is useful when discussing moral concerns about a practice.","zh":"當討論對某項習俗的道德關注時，這個詞很有用。"}],"source":"2017 Q5.pdf","sourcePage":13},{"front":"a form of social heritage","meaning":"一種社會文化遺產","examples":[{"en":"Mahjong can be presented as a form of social heritage.","zh":"麻雀可以被呈現為一種社會文化遺產。"},{"en":"A form of social heritage is a practice that preserves social relationships, habits, language, or community memory.","zh":"一種社會文化遺產是保存社交關係、習慣、語言或社區記憶的習俗。"},{"en":"Shared festival meals can be a form of social heritage because they bring families together.","zh":"共享節日飯局可以是一種社會文化遺產，因為它把家庭聚在一起。"},{"en":"Mahjong is social heritage when it teaches communication, patience, and intergenerational connection.","zh":"當麻雀教授溝通、耐性和跨代聯繫時，它就是社會文化遺產。"},{"en":"This phrase helps explain why a game can have cultural importance.","zh":"這個說法有助解釋為何一個遊戲也可以有文化重要性。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"admittedly","meaning":"誠然","examples":[{"en":"Admittedly, some people may disagree with the decision.","zh":"誠然，有些人可能不同意這個決定。"},{"en":"Admittedly means the writer accepts that a point is true or reasonable before giving another argument.","zh":"“Admittedly” 指作者先承認某個觀點真實或合理，然後再提出另一個論點。"},{"en":"Admittedly, the plan is expensive, but it may save money in the long term.","zh":"誠然，這個計劃很昂貴，但長遠來說可能節省金錢。"},{"en":"This word makes writing fairer because it recognises another view.","zh":"這個詞令文章更公平，因為它承認另一種看法。"},{"en":"It is often used before responding to an objection.","zh":"它常用於回應反對意見之前。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"argue that","meaning":"認為；主張","examples":[{"en":"Some people may argue that egg tarts are too ordinary.","zh":"有些人可能認為蛋撻太普通。"},{"en":"To argue that means to state a view and support it with reasons.","zh":"“Argue that” 指提出一個觀點，並用理由支持它。"},{"en":"Some students argue that homework should be shorter but more meaningful.","zh":"有些學生主張功課應較短但更有意義。"},{"en":"People may argue that a tradition is not worth protecting if they see it only as ordinary.","zh":"如果人們只把某項傳統看成普通事物，可能會認為它不值得保護。"},{"en":"This phrase introduces an opinion that may later be supported or challenged.","zh":"這個說法引出一個之後可以支持或反駁的意見。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"too ordinary","meaning":"太普通","examples":[{"en":"Some people may think egg tarts are too ordinary for official protection.","zh":"有些人可能認為蛋撻太普通，不值得官方保護。"},{"en":"Too ordinary means so common or familiar that some people fail to see special value in it.","zh":"“Too ordinary” 指某事太常見或熟悉，以致有些人看不到特殊價值。"},{"en":"The old street market seemed too ordinary to tourists, but locals loved it.","zh":"那個舊街市對遊客來說似乎太普通，但本地人很喜愛它。"},{"en":"A thing can seem too ordinary because people meet it every day.","zh":"某事物可能因每天都被看見而顯得太普通。"},{"en":"This phrase shows a misunderstanding: ordinary things can still carry cultural meaning.","zh":"這個說法顯示一種誤解：普通事物仍然可以承載文化意義。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"closely associated with","meaning":"與……密切相關","examples":[{"en":"Mahjong is closely associated with gambling in some people’s minds.","zh":"在有些人心中，麻雀與賭博密切相關。"},{"en":"Closely associated with means strongly connected with something in people’s thoughts or experience.","zh":"“Closely associated with” 指在人們的想法或經驗中與某事物有強烈連繫。"},{"en":"Fast food is closely associated with convenience in many busy cities.","zh":"在許多繁忙城市，快餐與方便密切相關。"},{"en":"When an activity is closely associated with a negative habit, people may overlook its other meanings.","zh":"當一項活動與負面習慣密切相關，人們可能忽略它的其他意義。"},{"en":"This phrase helps explain why some people object to protecting mahjong.","zh":"這個說法有助解釋為何有些人反對保護麻雀。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"gambling","meaning":"賭博","examples":[{"en":"Some people associate mahjong with gambling.","zh":"有些人把麻雀與賭博連繫起來。"},{"en":"Gambling means risking money or valuables on an uncertain result, often in a game or bet.","zh":"賭博指在不確定結果上冒金錢或有價物品的風險，常出現在遊戲或下注中。"},{"en":"Gambling can become harmful when people lose money they cannot afford to lose.","zh":"當人輸掉自己無法承擔的金錢時，賭博可能變得有害。"},{"en":"Mahjong can be played with gambling, but it can also be played without money for social enjoyment.","zh":"麻雀可以涉及賭博，但也可以不涉及金錢，只作社交娛樂。"},{"en":"Distinguishing mahjong from gambling helps people discuss its cultural value fairly.","zh":"把麻雀與賭博區分開，有助公平討論其文化價值。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"deserve official protection","meaning":"值得官方保護","examples":[{"en":"Some people question whether mahjong deserves official protection.","zh":"有些人質疑麻雀是否值得官方保護。"},{"en":"To deserve official protection means to be valuable enough for the government or authorities to help preserve it.","zh":"「值得官方保護」指有足夠價值，值得由政府或官方機構協助保存。"},{"en":"A historic market may deserve official protection if it carries community memory.","zh":"如果一個歷史街市承載社區記憶，它可能值得官方保護。"},{"en":"People may disagree about whether ordinary traditions deserve official protection.","zh":"人們可能會對普通傳統是否值得官方保護有不同意見。"},{"en":"This phrase is useful when discussing what should be included in heritage policy.","zh":"當討論甚麼應納入文化遺產政策時，這個說法很有用。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"that view is understandable","meaning":"這種看法可以理解","examples":[{"en":"That view is understandable, but it misses the point.","zh":"這種看法可以理解，但它沒有抓住重點。"},{"en":"That view is understandable means the opinion is reasonable enough to see why someone holds it.","zh":"“That view is understandable” 指某個意見有一定道理，因此可以明白為何有人持有它。"},{"en":"Some people worry about noise from festivals; that view is understandable, but festivals also support community life.","zh":"有些人擔心節日噪音；這種看法可以理解，但節日也支撐社區生活。"},{"en":"This phrase respects an opposing opinion before explaining why it is incomplete.","zh":"這個說法先尊重反對意見，再解釋它為何不完整。"},{"en":"It helps make an argument balanced rather than dismissive.","zh":"它令論證更平衡，而不是直接否定別人。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"misses the point","meaning":"沒有抓住重點","examples":[{"en":"The argument misses the point of intangible cultural heritage.","zh":"這個論點沒有抓住非物質文化遺產的重點。"},{"en":"To miss the point means to fail to understand the main idea or real issue.","zh":"“Miss the point” 指未能理解主要想法或真正問題。"},{"en":"If someone says old songs are useless because they are not modern, they miss the point of heritage.","zh":"如果有人說舊歌因不現代而沒有用，他就沒有抓住文化遺產的重點。"},{"en":"An argument may miss the point when it focuses on a small detail and ignores the deeper purpose.","zh":"當一個論點專注小細節而忽略更深目的時，它可能沒有抓住重點。"},{"en":"This phrase is useful when correcting a misunderstanding.","zh":"當要糾正誤解時，這個說法很有用。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"declaring something perfect","meaning":"宣稱某事物完美","examples":[{"en":"Heritage protection is not about declaring something perfect.","zh":"文化遺產保護並不是宣稱某事物完美。"},{"en":"Declaring something perfect means officially or openly saying that it has no problems or faults.","zh":"「宣稱某事物完美」指官方或公開地說它沒有任何問題或缺點。"},{"en":"Protecting an old building does not mean declaring it perfect; it means recognising its value.","zh":"保護舊建築不等於宣稱它完美，而是承認它的價值。"},{"en":"Heritage protection can admit problems while still preserving cultural meaning.","zh":"文化遺產保護可以承認問題，同時仍保存文化意義。"},{"en":"This phrase helps separate protection from blind praise.","zh":"這個說法幫助把保護與盲目讚美區分開。"}],"source":"2017 Q5.pdf","sourcePage":14},{"front":"recognising practices","meaning":"承認某些習俗","examples":[{"en":"Heritage protection is about recognising practices that shape identity.","zh":"文化遺產保護是承認塑造身份的某些習俗。"},{"en":"Recognising practices means officially or clearly acknowledging habits, skills, or customs as meaningful.","zh":"「承認某些習俗」指官方或清楚地肯定某些習慣、技藝或風俗具有意義。"},{"en":"A city recognises local practices when it records old festivals and teaches them in schools.","zh":"當一個城市記錄舊節日並在學校教授它們時，就是在承認本地習俗。"},{"en":"Recognising practices gives value to what ordinary people have done for years.","zh":"承認某些習俗，就是賦予普通人多年來所做的事以價值。"},{"en":"This phrase shows that heritage protection begins with seeing importance in daily actions.","zh":"這個說法顯示文化遺產保護始於看見日常行動的重要性。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"shaped a community’s identity","meaning":"塑造了一個社群的身份","examples":[{"en":"These practices have shaped a community’s identity.","zh":"這些習俗塑造了一個社群的身份。"},{"en":"To shape a community’s identity means to influence how a group understands itself and is recognised by others.","zh":"「塑造一個社群的身份」指影響一群人如何理解自己，以及別人如何認出他們。"},{"en":"A fishing tradition may shape a coastal village’s identity.","zh":"捕魚傳統可能塑造一個海邊村落的身份。"},{"en":"Shared foods, festivals, and games shape a community’s identity by giving people common memories.","zh":"共享食物、節日和遊戲透過給人共同回憶，塑造一個社群的身份。"},{"en":"This phrase explains why ordinary practices can have deep cultural importance.","zh":"這個說法解釋為何普通習俗可以有深厚文化重要性。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"community’s identity","meaning":"社群身份","examples":[{"en":"Intangible heritage reflects a community’s identity.","zh":"非物質文化遺產反映社群身份。"},{"en":"A community’s identity is the shared sense of who a group is, shaped by its history, values, language, and habits.","zh":"社群身份是一個群體對「我們是誰」的共同感覺，由歷史、價值、語言和習慣塑造。"},{"en":"A neighbourhood’s markets and festivals can express the community’s identity.","zh":"一個社區的街市和節日可以表達其社群身份。"},{"en":"When traditions disappear, part of a community’s identity may become harder to recognise.","zh":"當傳統消失時，部分社群身份可能變得較難辨認。"},{"en":"This phrase connects heritage with belonging and shared memory.","zh":"這個說法把文化遺產與歸屬感和共同記憶連接起來。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"encouraging unhealthy eating","meaning":"鼓勵不健康飲食","examples":[{"en":"Protecting egg tarts does not mean encouraging unhealthy eating.","zh":"保護蛋撻並不代表鼓勵不健康飲食。"},{"en":"Encouraging unhealthy eating means promoting food habits that may harm health if done too often.","zh":"「鼓勵不健康飲食」指推廣如果太常進行便可能損害健康的飲食習慣。"},{"en":"Teaching the history of sweets does not mean encouraging unhealthy eating every day.","zh":"教授甜食歷史並不等於鼓勵每天不健康飲食。"},{"en":"People can appreciate egg tarts culturally while still eating them in moderation.","zh":"人們可以從文化角度欣賞蛋撻，同時適量食用。"},{"en":"This phrase answers the concern that food heritage protection promotes poor habits.","zh":"這個說法回應了保護飲食文化遺產會推廣不良習慣的憂慮。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"promoting gambling","meaning":"推廣賭博","examples":[{"en":"Protecting mahjong does not mean promoting gambling.","zh":"保護麻雀並不代表推廣賭博。"},{"en":"Promoting gambling means encouraging people to bet money or valuables on uncertain results.","zh":"「推廣賭博」指鼓勵人們在不確定結果上下注金錢或有價物品。"},{"en":"Teaching mahjong rules without money is not the same as promoting gambling.","zh":"不涉及金錢地教授麻雀規則，並不等於推廣賭博。"},{"en":"A responsible heritage programme can discuss mahjong culture while warning against gambling harm.","zh":"負責任的文化遺產計劃可以討論麻雀文化，同時提醒賭博危害。"},{"en":"This phrase separates cultural appreciation from risky behaviour.","zh":"這個說法把文化欣賞與高風險行為區分開。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"preserving knowledge","meaning":"保存知識","examples":[{"en":"Official protection means preserving knowledge.","zh":"官方保護意味着保存知識。"},{"en":"Preserving knowledge means keeping skills, memories, methods, or information from being lost.","zh":"保存知識指防止技能、記憶、方法或資訊流失。"},{"en":"Recording an old baker’s method is one way of preserving knowledge.","zh":"記錄一位老麵包師傅的方法，是保存知識的一種方式。"},{"en":"Preserving knowledge matters because once experienced people retire, details may disappear.","zh":"保存知識很重要，因為有經驗的人退休後，細節可能會消失。"},{"en":"This phrase shows that heritage protection is about learning, not only celebration.","zh":"這個說法顯示文化遺產保護關乎學習，而不只是慶祝。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"social meaning","meaning":"社會意義","examples":[{"en":"Traditions carry stories and social meaning.","zh":"傳統承載故事和社會意義。"},{"en":"Social meaning is the value or message something has within relationships and community life.","zh":"社會意義是某事物在人際關係和社群生活中的價值或訊息。"},{"en":"Sharing food during festivals has social meaning because it shows care and belonging.","zh":"節日期間分享食物具有社會意義，因為它顯示關心和歸屬。"},{"en":"Mahjong has social meaning when it brings relatives together and keeps conversations alive.","zh":"當麻雀把親戚聚在一起並延續對話時，它便具有社會意義。"},{"en":"This phrase helps explain why an activity matters beyond its practical use.","zh":"這個說法有助解釋某項活動為何超越實際用途而重要。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"guiding the public towards","meaning":"引導公眾走向","examples":[{"en":"Protection can guide the public towards responsible appreciation.","zh":"保護可以引導公眾走向負責任的欣賞。"},{"en":"Guiding the public towards something means helping people move in the direction of a better understanding or behaviour.","zh":"「引導公眾走向……」指幫助人們朝向更好的理解或行為。"},{"en":"Clear signs can guide the public towards safer use of a hiking trail.","zh":"清楚指示牌可以引導公眾更安全地使用行山徑。"},{"en":"Heritage education can guide the public towards respecting traditions without misusing them.","zh":"文化遺產教育可以引導公眾尊重傳統，而不是誤用它們。"},{"en":"This phrase shows that official action can shape public attitudes.","zh":"這個說法顯示官方行動可以塑造公眾態度。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"responsible appreciation","meaning":"負責任的欣賞","examples":[{"en":"People should learn responsible appreciation of heritage.","zh":"人們應學會對文化遺產作負責任的欣賞。"},{"en":"Responsible appreciation means valuing something carefully while understanding its limits, risks, and proper context.","zh":"負責任的欣賞指在珍惜某事物時，也理解其限制、風險和適當語境。"},{"en":"Responsible appreciation of traditional food includes learning its history without overeating it.","zh":"對傳統食物作負責任的欣賞，包括學習其歷史，而不是過量食用。"},{"en":"Responsible appreciation of mahjong means enjoying its social value without promoting gambling.","zh":"對麻雀作負責任的欣賞，意思是享受其社交價值，而不推廣賭博。"},{"en":"This phrase offers a balanced way to respect culture.","zh":"這個說法提供一種平衡的文化尊重方式。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"if anything","meaning":"反而；真要說的話","examples":[{"en":"If anything, official recognition helps explain these traditions.","zh":"真要說的話，官方認可反而有助解釋這些傳統。"},{"en":"If anything means actually, the opposite or a stronger version of what some people fear is true.","zh":"“If anything” 指實際上，與某些人擔心的相反，或情況更接近另一種說法。"},{"en":"Some worry that discussion will confuse students; if anything, it helps them understand the issue more clearly.","zh":"有些人擔心討論會令學生混亂；真要說的話，它會幫助他們更清楚理解問題。"},{"en":"This phrase is used to correct an assumption gently but firmly.","zh":"這個說法用來溫和但堅定地糾正一個假設。"},{"en":"It shows that official recognition may reduce misunderstanding rather than increase it.","zh":"它顯示官方認可可能減少誤解，而不是增加誤解。"}],"source":"2017 Q5.pdf","sourcePage":15},{"front":"official recognition","meaning":"官方認可","examples":[{"en":"Official recognition gives Hong Kong a chance to explain its traditions.","zh":"官方認可給香港一個機會去解釋自己的傳統。"},{"en":"Official recognition means formal acknowledgement by an authority that something has value or importance.","zh":"官方認可是由權威機構正式承認某事物具有價值或重要性。"},{"en":"Official recognition of a festival can encourage schools to teach its history.","zh":"對一個節日作官方認可，可以鼓勵學校教授其歷史。"},{"en":"A tradition may gain public attention after official recognition.","zh":"一項傳統在得到官方認可後，可能會得到公眾關注。"},{"en":"This phrase shows how government acknowledgement can support cultural education.","zh":"這個說法顯示政府承認如何支持文化教育。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"gives Hong Kong a chance to","meaning":"給香港一個機會去","examples":[{"en":"Official recognition gives Hong Kong a chance to explain these traditions.","zh":"官方認可給香港一個機會去解釋這些傳統。"},{"en":"Gives Hong Kong a chance to means provides Hong Kong with an opportunity to do something.","zh":"“Gives Hong Kong a chance to” 指為香港提供做某事的機會。"},{"en":"A cultural festival gives Hong Kong a chance to introduce local arts to visitors.","zh":"文化節給香港一個機會向訪客介紹本地藝術。"},{"en":"Official recognition gives Hong Kong a chance to teach people why ordinary traditions matter.","zh":"官方認可給香港一個機會教導人們為何普通傳統重要。"},{"en":"This phrase shows that a policy can create an opportunity for public education.","zh":"這個說法顯示政策可以創造公共教育的機會。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"more carefully","meaning":"更仔細地","examples":[{"en":"These traditions should be explained more carefully.","zh":"這些傳統應被更仔細地解釋。"},{"en":"More carefully means with greater attention, accuracy, and thought.","zh":"“More carefully” 指以更高的注意力、準確度和思考去做。"},{"en":"The teacher explained the difficult question more carefully after students looked confused.","zh":"學生看起來困惑後，老師更仔細地解釋那道難題。"},{"en":"Sensitive traditions should be explained more carefully so people do not misunderstand them.","zh":"敏感傳統應被更仔細地解釋，以免人們誤解。"},{"en":"This phrase suggests that better explanation can improve public understanding.","zh":"這個說法暗示更好的解釋可以改善公眾理解。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"instead of leaving them to","meaning":"而不是任由它們","examples":[{"en":"Hong Kong should explain these traditions instead of leaving them to fade.","zh":"香港應解釋這些傳統，而不是任由它們淡出。"},{"en":"Instead of leaving them to means choosing action rather than allowing something to happen without care or intervention.","zh":"“Instead of leaving them to” 指選擇採取行動，而不是任由某事在缺乏照顧或介入下發生。"},{"en":"The school repaired the old garden instead of leaving it to become useless.","zh":"學校修復舊花園，而不是任由它變得無用。"},{"en":"Heritage should be taught instead of being left to disappear silently.","zh":"文化遺產應被教授，而不是任由它默默消失。"},{"en":"This phrase contrasts active protection with passive neglect.","zh":"這個說法把積極保護與被動忽視作對比。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"fade","meaning":"淡出；消失","examples":[{"en":"Traditions may fade if they are not protected.","zh":"如果不受保護，傳統可能會淡出。"},{"en":"To fade means to gradually become weaker, less visible, less remembered, or less practised.","zh":"“Fade” 指逐漸變弱、較少被看見、較少被記得或較少被實踐。"},{"en":"Old handwriting skills may fade when people type everything on phones.","zh":"當人們所有東西都用電話打字時，舊式書寫技巧可能會淡出。"},{"en":"Traditions often fade slowly, so people may not notice the loss at first.","zh":"傳統常是慢慢淡出，所以人們起初未必注意到流失。"},{"en":"This word suggests quiet disappearance rather than sudden destruction.","zh":"這個詞暗示安靜消失，而不是突然被摧毀。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"commercialise","meaning":"商業化","examples":[{"en":"Some traditions may commercialise if they are not handled carefully.","zh":"如果處理不小心，有些傳統可能會商業化。"},{"en":"To commercialise means to turn something mainly into a product or business opportunity for profit.","zh":"“Commercialise” 指把某事物主要變成為賺取利潤而設的產品或商機。"},{"en":"A local festival may commercialise if every activity is changed only to attract tourists.","zh":"如果本地節日的每項活動都只為吸引遊客而改變，它可能會商業化。"},{"en":"Commercialising a tradition can weaken its meaning when profit becomes more important than practice.","zh":"當利潤比實踐更重要時，傳統商業化可能削弱其意義。"},{"en":"This word warns that protection should not turn heritage into empty marketing.","zh":"這個詞提醒我們，保護不應把文化遺產變成空洞行銷。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"be misunderstood","meaning":"被誤解","examples":[{"en":"Mahjong may be misunderstood if it is only seen as gambling.","zh":"如果麻雀只被看成賭博，它可能會被誤解。"},{"en":"To be misunderstood means to be interpreted wrongly or incompletely.","zh":"“Be misunderstood” 指被錯誤或不完整地理解。"},{"en":"A quiet student may be misunderstood as unfriendly when she is simply shy.","zh":"一個安靜的學生可能被誤解為不友善，但她其實只是害羞。"},{"en":"Traditions can be misunderstood when people focus on one negative part and ignore the wider context.","zh":"當人們只專注一個負面部分而忽略更廣闊語境，傳統可能會被誤解。"},{"en":"Explaining mahjong as social heritage helps prevent it from being misunderstood.","zh":"把麻雀解釋為社會文化遺產，有助防止它被誤解。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, the Government has made a wise choice.","zh":"綜合而言，政府作出了明智選擇。"},{"en":"All things considered means after thinking about all the important facts and arguments.","zh":"“All things considered” 指在思考所有重要事實和論點之後。"},{"en":"All things considered, moving closer to school was the better decision.","zh":"綜合而言，搬近學校是較好的決定。"},{"en":"This phrase is often used before a final judgement or conclusion.","zh":"這個說法常用於最終判斷或結論之前。"},{"en":"It shows that the writer has considered more than one side of the issue.","zh":"它顯示作者已考慮問題不只一面。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"made a wise choice","meaning":"作出明智選擇","examples":[{"en":"The Government has made a wise choice.","zh":"政府作出了明智選擇。"},{"en":"To make a wise choice means to choose carefully and sensibly after considering the likely results.","zh":"「作出明智選擇」指在考慮可能結果後，謹慎而合理地作出決定。"},{"en":"She made a wise choice by saving part of her salary each month.","zh":"她每月儲起部分薪金，作出了明智選擇。"},{"en":"A government makes a wise choice when a policy protects long-term public value.","zh":"當一項政策能保護長遠公共價值時，政府就是作出明智選擇。"},{"en":"This phrase gives a positive judgement about a decision.","zh":"這個說法對一個決定作出正面判斷。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"humble, familiar and deeply human","meaning":"樸實、熟悉而充滿人情味","examples":[{"en":"Traditional egg tarts and mahjong are humble, familiar and deeply human.","zh":"傳統蛋撻和麻雀樸實、熟悉而充滿人情味。"},{"en":"Humble, familiar and deeply human means ordinary, easily recognised, and closely connected with real human feelings and relationships.","zh":"「樸實、熟悉而充滿人情味」指普通、容易認出，並與真實人的感受和關係緊密相連。"},{"en":"A simple family meal can be humble, familiar and deeply human.","zh":"一頓簡單家庭飯可以樸實、熟悉而充滿人情味。"},{"en":"These traditions matter because their value comes from daily use, not grand appearance.","zh":"這些傳統重要，因為它們的價值來自日常使用，而不是宏大外表。"},{"en":"This phrase praises ordinary culture for its warmth and honesty.","zh":"這個說法讚揚普通文化的溫暖和真實。"}],"source":"2017 Q5.pdf","sourcePage":16},{"front":"precisely for that reason","meaning":"正正因為這個原因","examples":[{"en":"Precisely for that reason, they reveal Hong Kong honestly.","zh":"正正因為這個原因，它們真實地展現香港。"},{"en":"Precisely for that reason means exactly because of the reason just mentioned.","zh":"“Precisely for that reason” 指正是因為剛才提到的原因。"},{"en":"The shop is small and ordinary; precisely for that reason, it feels close to local life.","zh":"那間店細小而普通；正正因為這個原因，它感覺貼近本地生活。"},{"en":"This phrase turns a possible weakness into the main reason for value.","zh":"這個說法把可能的弱點轉化為價值的主要原因。"},{"en":"It helps explain why humble traditions may show a city more truthfully.","zh":"它幫助解釋為何樸實傳統可能更真實地展現一個城市。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"polished tourist attractions","meaning":"包裝精美的旅遊景點","examples":[{"en":"These traditions reveal Hong Kong more honestly than polished tourist attractions do.","zh":"這些傳統比包裝精美的旅遊景點更真實地展現香港。"},{"en":"Polished tourist attractions are places or experiences made attractive, tidy, and marketable for visitors.","zh":"包裝精美的旅遊景點是為訪客而被整理得吸引、整齊和容易推廣的地方或體驗。"},{"en":"A polished tourist attraction may look beautiful but show only a carefully selected image of a city.","zh":"包裝精美的旅遊景點可能很漂亮，但只展示城市經過挑選的形象。"},{"en":"Everyday traditions can reveal more honest culture than polished tourist attractions because locals actually use them.","zh":"日常傳統可能比包裝精美的旅遊景點更真實地展現文化，因為本地人真正使用它們。"},{"en":"This phrase contrasts real daily life with packaged public images.","zh":"這個說法把真實日常生活與被包裝的公共形象作對比。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"the next step is clear","meaning":"下一步很清楚","examples":[{"en":"The next step is clear: different groups should work together.","zh":"下一步很清楚：不同群體應共同努力。"},{"en":"The next step is clear means the following action is obvious after considering the situation.","zh":"“The next step is clear” 指在考慮情況後，接下來應做的行動很明顯。"},{"en":"The survey shows students need help; the next step is clear: the school should offer support classes.","zh":"調查顯示學生需要幫助；下一步很清楚：學校應提供支援課程。"},{"en":"This phrase is useful near the end of an essay when moving from opinion to action.","zh":"這個說法適合在文章結尾附近，由意見轉向行動。"},{"en":"It suggests that the argument naturally leads to a practical plan.","zh":"它暗示論點自然引向實際計劃。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"work together to","meaning":"共同努力去","examples":[{"en":"The Government, schools and citizens should work together to protect these traditions.","zh":"政府、學校和市民應共同努力去保護這些傳統。"},{"en":"To work together to do something means different people or groups cooperate to achieve the same goal.","zh":"“Work together to” 指不同人或群體合作，以達成同一目標。"},{"en":"Parents and teachers work together to help students build better study habits.","zh":"家長和老師共同努力去幫助學生建立更好的學習習慣。"},{"en":"Heritage protection works better when officials, schools, shops, and families work together.","zh":"當官員、學校、店舖和家庭共同努力時，文化遺產保護會更有效。"},{"en":"This phrase emphasises cooperation rather than leaving the task to one group.","zh":"這個說法強調合作，而不是把任務留給單一群體。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"document, teach and practise","meaning":"記錄、教授和實踐","examples":[{"en":"People should document, teach and practise these traditions.","zh":"人們應記錄、教授和實踐這些傳統。"},{"en":"Document, teach and practise means record information, pass it to others, and continue doing it in real life.","zh":"「記錄、教授和實踐」指保存資料、傳授給他人，並在真實生活中繼續進行。"},{"en":"A community can document, teach and practise a festival by filming it, explaining it in schools, and joining it yearly.","zh":"社區可以透過拍攝、在學校解釋和每年參與，記錄、教授和實踐一個節日。"},{"en":"These three actions protect heritage more fully because they combine memory, education, and use.","zh":"這三個行動能更完整地保護文化遺產，因為它們結合記憶、教育和使用。"},{"en":"This phrase shows that living heritage needs more than storage.","zh":"這個說法顯示活態文化遺產需要的不只是收藏。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"locked behind glass","meaning":"被鎖在玻璃後","examples":[{"en":"Heritage should not be locked behind glass.","zh":"文化遺產不應被鎖在玻璃後。"},{"en":"Locked behind glass means kept only as a display object, protected but separated from everyday use.","zh":"「被鎖在玻璃後」指只被當作展示物保存，受到保護卻與日常使用分離。"},{"en":"A traditional tool locked behind glass can be seen, but people may no longer know how to use it.","zh":"被鎖在玻璃後的傳統工具可以被看見，但人們可能不再知道如何使用它。"},{"en":"If heritage is locked behind glass, it may survive physically but lose its living meaning.","zh":"如果文化遺產被鎖在玻璃後，它可能在實物上保存下來，卻失去活生生的意義。"},{"en":"This phrase criticises preservation that removes traditions from real life.","zh":"這個說法批評把傳統從真實生活中抽離的保存方式。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"tasted, heard, shared and passed on","meaning":"被品嚐、聽見、分享和傳承","examples":[{"en":"Heritage should be tasted, heard, shared and passed on.","zh":"文化遺產應被品嚐、聽見、分享和傳承。"},{"en":"Tasted, heard, shared and passed on means people should experience heritage with the senses, enjoy it together, and teach it to others.","zh":"「被品嚐、聽見、分享和傳承」指人們應透過感官體驗文化遺產，一起享受它，並把它教給他人。"},{"en":"Food heritage is tasted, songs are heard, stories are shared, and skills are passed on.","zh":"飲食文化遺產被品嚐，歌曲被聽見，故事被分享，技藝被傳承。"},{"en":"Heritage stays alive when people do these actions instead of only looking at displays.","zh":"當人們這樣做，而不只是觀看展品時，文化遺產便能保持生命力。"},{"en":"This phrase makes cultural protection active, human, and practical.","zh":"這個說法令文化保護變得主動、有人情味和實際。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"passed on","meaning":"傳承下去","examples":[{"en":"Living heritage should be passed on to the next generation.","zh":"活態文化遺產應傳承給下一代。"},{"en":"Passed on means given, taught, or transferred from one person or generation to another.","zh":"“Passed on” 指由一個人或一代傳授、給予或轉交給另一個人或下一代。"},{"en":"Grandparents passed on family recipes by cooking with their grandchildren.","zh":"祖父母透過與孫兒一起煮食，把家庭食譜傳承下去。"},{"en":"A tradition is more likely to survive when skills and stories are passed on regularly.","zh":"當技藝和故事定期被傳承，一項傳統更有可能延續。"},{"en":"This phrase is central to heritage because culture must move forward through people.","zh":"這個說法是文化遺產的核心，因為文化必須透過人繼續向前。"}],"source":"2017 Q5.pdf","sourcePage":17},{"front":"Yours faithfully","meaning":"謹啟；此致","examples":[{"en":"The letter ends with “Yours faithfully.”","zh":"這封信以 “Yours faithfully” 作結。"},{"en":"Yours faithfully is a formal closing used at the end of a letter, especially when the writer does not know the recipient’s name.","zh":"“Yours faithfully” 是正式信件結尾用語，尤其在作者不知道收件人姓名時使用。"},{"en":"A formal complaint letter may end with “Yours faithfully” before the writer’s name.","zh":"正式投訴信可能在作者姓名前以 “Yours faithfully” 作結。"},{"en":"This closing shows respect and keeps the tone professional.","zh":"這個結尾語顯示尊重，並保持專業語氣。"},{"en":"In formal writing, the closing should match the greeting and the relationship with the reader.","zh":"在正式寫作中，結尾語應配合稱呼和與讀者的關係。"}],"source":"2017 Q5.pdf","sourcePage":17}],"dse/writing/part-b/2017/Q6":[{"front":"sharpen the mind","meaning":"令頭腦更敏銳","examples":[{"en":"Good television can sharpen the mind.","zh":"優質電視節目可以令頭腦更敏銳。"},{"en":"To sharpen the mind means to make people think more clearly, quickly, or deeply.","zh":"令頭腦更敏銳意思是令人思考得更清楚、更快或更深入。"},{"en":"Reading difficult books can sharpen the mind because readers must follow ideas carefully.","zh":"閱讀有難度的書可以令頭腦更敏銳，因為讀者必須仔細跟隨思想。"},{"en":"Debate programmes sharpen the mind when they make viewers compare evidence and arguments.","zh":"當辯論節目令觀眾比較證據和論點時，它們可以令頭腦更敏銳。"},{"en":"Television sharpens the mind only when viewers watch actively, not lazily.","zh":"電視只有在觀眾主動觀看而不是懶散觀看時，才會令頭腦更敏銳。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"good morning, adjudicators","meaning":"各位評判早晨","examples":[{"en":"The speaker begins by greeting the adjudicators.","zh":"演講者一開始向評判問好。"},{"en":"“Good morning, adjudicators” is a polite opening used in a debate speech.","zh":"「各位評判早晨」是在辯論演辭中使用的禮貌開場白。"},{"en":"A student may say, “Good morning, adjudicators,” before presenting the team’s case.","zh":"學生在陳述隊伍立場前，可能會說：「各位評判早晨。」"},{"en":"This greeting shows respect for the people judging the debate.","zh":"這句問候顯示對評判辯論的人尊重。"},{"en":"A clear opening helps the speaker sound calm and prepared.","zh":"清晰開場能令演講者聽起來冷靜和準備充足。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"fellow students","meaning":"各位同學","examples":[{"en":"The speaker addresses teachers, fellow students, and honourable opponents.","zh":"演講者向老師、各位同學和尊敬的對方辯友致意。"},{"en":"Fellow students are other students in the same school, class, or event.","zh":"各位同學是指同一學校、班級或活動中的其他學生。"},{"en":"In a speech, saying “fellow students” creates a friendly connection with the audience.","zh":"在演講中說「各位同學」，能與聽眾建立友善連繫。"},{"en":"Fellow students may share the same worries about homework, exams, and school life.","zh":"各位同學可能有相同的功課、考試和校園生活憂慮。"},{"en":"This phrase is formal enough for a debate but still warm.","zh":"這個稱呼對辯論來說夠正式，同時仍然親切。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"honourable opponents","meaning":"尊敬的對方辯友","examples":[{"en":"The speaker greets the honourable opponents at the start of the debate.","zh":"演講者在辯論開始時向尊敬的對方辯友問好。"},{"en":"Honourable opponents are the opposing debaters who should be treated with respect.","zh":"尊敬的對方辯友是指應受到尊重的反方辯論員。"},{"en":"Calling the other side honourable opponents shows that disagreement can be polite.","zh":"稱對方為尊敬的對方辯友，顯示分歧也可以有禮貌。"},{"en":"In a debate, honourable opponents challenge your ideas, not your personal worth.","zh":"在辯論中，尊敬的對方辯友挑戰的是你的想法，而不是你的個人價值。"},{"en":"Respecting honourable opponents makes the debate fairer and more mature.","zh":"尊重對方辯友令辯論更公平和成熟。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"for years","meaning":"多年來","examples":[{"en":"For years, television has been accused of being the “idiot box”.","zh":"多年來，電視一直被指責為「傻瓜盒」。"},{"en":"For years means over a long period of time.","zh":"多年來意思是在很長一段時間中。"},{"en":"For years, parents have worried that too much screen time harms learning.","zh":"多年來，父母一直擔心過多螢幕時間會損害學習。"},{"en":"This phrase helps show that an opinion or problem has existed for a long time.","zh":"這個短語有助顯示某種看法或問題已存在很久。"},{"en":"For years, people may repeat an idea before questioning whether it is fair.","zh":"多年來，人們可能反覆說同一個想法，卻未必質疑它是否公平。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"be accused of","meaning":"被指責為……","examples":[{"en":"Television has been accused of being the “idiot box”.","zh":"電視一直被指責為「傻瓜盒」。"},{"en":"To be accused of something means to be blamed for doing or causing it.","zh":"被指責為某事，意思是因做了或造成某事而被責備。"},{"en":"Social media is often accused of shortening people’s attention span.","zh":"社交媒體常被指責為縮短人們專注力的原因。"},{"en":"Television is accused of harming students when viewers watch without purpose.","zh":"當觀眾沒有目的地觀看時，電視會被指責為傷害學生的事物。"},{"en":"Being accused of something does not prove the accusation is fully true.","zh":"被指責為某事並不證明指責完全正確。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"the idiot box","meaning":"傻瓜盒；令人變笨的電視","examples":[{"en":"Some people unfairly call television the “idiot box”.","zh":"有些人不公平地把電視稱為「傻瓜盒」。"},{"en":"The idiot box is an insulting name for television, suggesting that it makes people stupid.","zh":"「傻瓜盒」是對電視的貶義稱呼，暗示電視令人變笨。"},{"en":"Critics call television the idiot box when they think viewers watch passively.","zh":"當批評者認為觀眾被動觀看時，他們會把電視稱為傻瓜盒。"},{"en":"This phrase is negative because it ignores educational and thoughtful programmes.","zh":"這個短語帶有負面意思，因為它忽視了教育性和有思考性的節目。"},{"en":"Good television proves that the idiot box label can be unfair.","zh":"優質電視節目證明「傻瓜盒」這個標籤可能不公平。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"a glowing rectangle","meaning":"發光的長方形","examples":[{"en":"Television is sometimes described as a glowing rectangle.","zh":"電視有時被形容為發光的長方形。"},{"en":"A glowing rectangle refers to the bright screen of a television or digital device.","zh":"發光的長方形是指電視或數碼裝置的明亮螢幕。"},{"en":"A child may sit in front of a glowing rectangle instead of playing outside.","zh":"孩子可能坐在發光的長方形前，而不是到戶外玩耍。"},{"en":"This image can make television seem lifeless and mechanical.","zh":"這個意象可以令電視看似沒有生命和很機械化。"},{"en":"However, what matters is not the glowing rectangle itself, but the content it shows.","zh":"然而，重要的不是發光的長方形本身，而是它顯示的內容。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"steal our time","meaning":"偷走我們的時間","examples":[{"en":"Critics say television steals our time.","zh":"批評者說電視偷走我們的時間。"},{"en":"To steal our time means to take away hours that could be used for something better.","zh":"偷走我們的時間意思是拿走本可用於更好事情的時間。"},{"en":"Endless scrolling can steal our time if we do it without noticing.","zh":"如果我們不知不覺地不停滑手機，這也會偷走我們的時間。"},{"en":"Television steals our time only when we watch carelessly for too long.","zh":"只有當我們長時間漫不經心觀看時，電視才會偷走我們的時間。"},{"en":"Purposeful viewing can use time well instead of stealing it.","zh":"有目的地觀看可以善用時間，而不是偷走時間。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"weaken our concentration","meaning":"削弱我們的專注力","examples":[{"en":"Critics argue that television weakens our concentration.","zh":"批評者認為電視削弱我們的專注力。"},{"en":"To weaken our concentration means to reduce our ability to focus for a period of time.","zh":"削弱我們的專注力意思是降低我們持續集中注意力的能力。"},{"en":"Constant phone notifications can weaken our concentration during homework.","zh":"不斷出現的手機通知會在做功課時削弱我們的專注力。"},{"en":"Fast-changing images may weaken concentration if viewers never pause to think.","zh":"如果觀眾從不停下思考，快速變化的影像可能削弱專注力。"},{"en":"Good programmes can also train concentration when students follow complex ideas.","zh":"當學生跟隨複雜思想時，優質節目也可以訓練專注力。"}],"source":"2017 Q6.pdf","sourcePage":1},{"front":"turn active students into passive viewers","meaning":"把主動的學生變成被動觀眾","examples":[{"en":"Television is blamed for turning active students into passive viewers.","zh":"電視被責怪把主動的學生變成被動觀眾。"},{"en":"To turn active students into passive viewers means to make learners stop thinking and only receive information.","zh":"把主動的學生變成被動觀眾，意思是令學習者停止思考，只接收資訊。"},{"en":"A student becomes a passive viewer when they watch for hours without asking questions.","zh":"當學生看電視數小時卻不提問時，他就成為被動觀眾。"},{"en":"Poor television habits can turn active students into passive viewers by rewarding laziness.","zh":"差劣的觀看習慣會獎勵懶散，從而把主動的學生變成被動觀眾。"},{"en":"Teachers can prevent this by asking students to discuss what they watch.","zh":"老師可以透過要求學生討論所觀看的內容來防止這情況。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"active students","meaning":"主動的學生","examples":[{"en":"Good learning should turn passive viewers back into active students.","zh":"良好學習應把被動觀眾重新變成主動的學生。"},{"en":"Active students are learners who ask questions, think carefully, and take part.","zh":"主動的學生是會提問、仔細思考和參與的學習者。"},{"en":"Active students do not simply copy notes; they test ideas and seek reasons.","zh":"主動的學生不只是抄筆記；他們會檢驗想法和尋找理由。"},{"en":"Television can support active students if they compare claims and evidence.","zh":"如果學生比較說法和證據，電視可以支持他們成為主動的學生。"},{"en":"The goal is to make viewers active students of the world.","zh":"目標是令觀眾成為世界的主動學習者。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"passive viewers","meaning":"被動觀眾","examples":[{"en":"Television can turn students into passive viewers if they watch without thinking.","zh":"如果學生不經思考地觀看，電視可以把他們變成被動觀眾。"},{"en":"Passive viewers receive images and sounds without questioning or responding.","zh":"被動觀眾接收影像和聲音，卻不質疑或回應。"},{"en":"A passive viewer may finish a programme without remembering its main idea.","zh":"被動觀眾可能看完整個節目後，仍記不起主要意思。"},{"en":"Passive viewing becomes a problem when students stop connecting ideas.","zh":"當學生停止連繫思想時，被動觀看就成為問題。"},{"en":"Discussion can turn passive viewers into thoughtful learners.","zh":"討論可以把被動觀眾變成有思考的學習者。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"understandably","meaning":"可以理解地","examples":[{"en":"Understandably, parents and schools sometimes worry about television.","zh":"可以理解地，父母和學校有時會擔心電視。"},{"en":"Understandably means in a way that is reasonable or easy to understand.","zh":"可以理解地意思是以合理或容易明白的方式。"},{"en":"Understandably, parents worry when children watch screens late at night.","zh":"可以理解地，當孩子深夜看螢幕時，父母會擔心。"},{"en":"This word shows that the writer respects the other side’s concern.","zh":"這個詞顯示作者尊重另一方的憂慮。"},{"en":"Understandably, people fear bad television, but that does not mean all television is harmful.","zh":"可以理解地，人們害怕差劣電視，但這不代表所有電視都有害。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"consider cutting television out","meaning":"考慮戒掉電視","examples":[{"en":"Parents and schools sometimes consider cutting television out.","zh":"父母和學校有時會考慮戒掉電視。"},{"en":"To consider cutting television out means to think about removing television completely.","zh":"考慮戒掉電視意思是思考是否完全移除電視。"},{"en":"A parent may consider cutting television out if a child stops doing homework.","zh":"如果孩子停止做功課，父母可能會考慮戒掉電視。"},{"en":"This reaction may solve one problem but remove useful programmes too.","zh":"這種反應可能解決一個問題，但也會移除有用節目。"},{"en":"Instead of cutting television out, families can choose better programmes.","zh":"與其戒掉電視，家庭可以選擇更好的節目。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"in order to","meaning":"為了","examples":[{"en":"Parents may limit television in order to protect young people’s learning.","zh":"父母可能限制看電視時間，為了保護年輕人的學習。"},{"en":"In order to means for the purpose of doing something.","zh":"為了意思是出於做某事的目的。"},{"en":"Students revise early in order to feel calmer before exams.","zh":"學生提早溫習，為了在考試前感到更冷靜。"},{"en":"Schools may recommend quality programmes in order to guide students.","zh":"學校可能推薦優質節目，為了引導學生。"},{"en":"This phrase clearly explains the reason behind an action.","zh":"這個短語清楚解釋行動背後的原因。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"protect young people’s learning","meaning":"保護年輕人的學習","examples":[{"en":"Schools may reduce screen time to protect young people’s learning.","zh":"學校可能減少螢幕時間，以保護年輕人的學習。"},{"en":"To protect young people’s learning means to prevent habits that harm students’ study and development.","zh":"保護年輕人的學習意思是防止傷害學生學習和發展的習慣。"},{"en":"Parents protect young people’s learning by setting clear screen-time rules.","zh":"父母透過設定清晰螢幕時間規則來保護年輕人的學習。"},{"en":"Schools protect learning when they teach students how to watch critically.","zh":"當學校教學生如何批判地觀看時，就是在保護學習。"},{"en":"The aim is not to ban all screens, but to protect young people’s learning.","zh":"目標不是禁止所有螢幕，而是保護年輕人的學習。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"today, however","meaning":"然而今天","examples":[{"en":"Today, however, I stand firmly for the motion.","zh":"然而今天，我堅定支持這個辯題。"},{"en":"Today, however introduces a contrast between common worries and the speaker’s present argument.","zh":"然而今天引出常見憂慮和演講者當前論點之間的對比。"},{"en":"Many people blame television; today, however, I will defend good television.","zh":"許多人責怪電視；然而今天，我會為優質電視辯護。"},{"en":"This phrase helps a speaker shift from background to position.","zh":"這個短語幫助演講者從背景轉向立場。"},{"en":"It signals that a different view is about to be presented.","zh":"它表示一個不同觀點即將被提出。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"as captain of","meaning":"作為……隊長","examples":[{"en":"As captain of the debate team, I speak for the motion.","zh":"作為辯論隊隊長，我支持這個辯題發言。"},{"en":"As captain of means speaking or acting in the role of leader of a group.","zh":"作為某隊隊長，意思是以群體領袖的身份發言或行動。"},{"en":"As captain of the football team, she thanked the coach after the match.","zh":"作為足球隊隊長，她在比賽後感謝教練。"},{"en":"This phrase gives the speaker authority and responsibility.","zh":"這個短語給予演講者權威和責任。"},{"en":"As captain of a team, a student should represent others clearly and fairly.","zh":"作為隊長，學生應清楚而公平地代表其他人。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"debate team","meaning":"辯論隊","examples":[{"en":"The speaker is captain of the debate team.","zh":"演講者是辯論隊隊長。"},{"en":"A debate team is a group of students who prepare and present arguments in debates.","zh":"辯論隊是一組準備和提出辯論論點的學生。"},{"en":"A debate team practises speaking, listening, and responding to opposing views.","zh":"辯論隊會練習演說、聆聽和回應反方觀點。"},{"en":"Joining a debate team can sharpen critical thinking and confidence.","zh":"加入辯論隊可以提升批判性思維和自信。"},{"en":"A strong debate team uses evidence, logic, and teamwork.","zh":"強大的辯論隊會使用證據、邏輯和團隊合作。"}],"source":"2017 Q6.pdf","sourcePage":2},{"front":"stand firmly for the motion","meaning":"堅定支持辯題","examples":[{"en":"I stand firmly for the motion that watching TV makes us smarter.","zh":"我堅定支持「看電視令我們更聰明」這個辯題。"},{"en":"To stand firmly for the motion means to strongly support the debate topic.","zh":"堅定支持辯題意思是強烈支持辯論題目。"},{"en":"A speaker stands firmly for the motion when they defend it with clear reasons.","zh":"當演講者以清晰理由維護辯題時，就是堅定支持辯題。"},{"en":"This phrase shows confidence at the beginning of a debate speech.","zh":"這個短語在辯論演辭開頭顯示信心。"},{"en":"Standing firmly for a motion requires evidence, not just emotion.","zh":"堅定支持辯題需要證據，而不只是情緒。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"the motion that","meaning":"……這個辯題","examples":[{"en":"I support the motion that watching TV makes us smarter.","zh":"我支持「看電視令我們更聰明」這個辯題。"},{"en":"The motion that introduces the debate statement being supported or opposed.","zh":"……這個辯題用來引出被支持或反對的辯論陳述。"},{"en":"The motion that homework should be reduced caused strong discussion in class.","zh":"「應減少功課」這個辯題在班中引起熱烈討論。"},{"en":"In debate, speakers must clearly understand the motion that they are arguing about.","zh":"在辯論中，演講者必須清楚理解自己正在辯論的辯題。"},{"en":"This phrase helps connect a position with a specific claim.","zh":"這個短語幫助把立場和具體主張連接起來。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"watching TV makes us smarter","meaning":"看電視令我們更聰明","examples":[{"en":"The speaker argues that watching TV makes us smarter.","zh":"演講者主張看電視令我們更聰明。"},{"en":"Watching TV makes us smarter means television can improve knowledge, judgement, or understanding.","zh":"看電視令我們更聰明，意思是電視可以提升知識、判斷力或理解力。"},{"en":"Watching TV makes us smarter when programmes explain science, history, and real human problems.","zh":"當節目解釋科學、歷史和真實人類問題時，看電視可以令我們更聰明。"},{"en":"The claim depends on how people watch and what programmes they choose.","zh":"這個主張取決於人們如何觀看以及選擇甚麼節目。"},{"en":"Careless viewing may not help, but thoughtful watching can make us smarter.","zh":"漫不經心觀看未必有幫助，但有思考地觀看可以令我們更聰明。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"let me be clear","meaning":"讓我說清楚","examples":[{"en":"Let me be clear: I am not defending careless binge-watching.","zh":"讓我說清楚：我不是在為漫無目的地煲劇辯護。"},{"en":"Let me be clear means the speaker wants to remove possible misunderstanding.","zh":"讓我說清楚意思是演講者想消除可能的誤解。"},{"en":"Let me be clear: I support technology, not addiction to screens.","zh":"讓我說清楚：我支持科技，而不是沉迷螢幕。"},{"en":"This phrase is useful before making a careful distinction.","zh":"這個短語在作出仔細區分前很有用。"},{"en":"It helps the audience understand exactly what the speaker means.","zh":"它幫助聽眾準確理解演講者的意思。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"defend endless channel-surfing","meaning":"為無止境轉台辯護","examples":[{"en":"I am not defending endless channel-surfing.","zh":"我不是在為無止境轉台辯護。"},{"en":"To defend endless channel-surfing means to support the habit of switching channels without purpose.","zh":"為無止境轉台辯護，意思是支持沒有目的地不停轉台的習慣。"},{"en":"A student wastes time when they spend an hour on endless channel-surfing.","zh":"如果學生花一小時無止境轉台，就是浪費時間。"},{"en":"The speaker rejects channel-surfing because it does not involve real thinking.","zh":"演講者反對轉台，因為它不涉及真正思考。"},{"en":"Good television watching is selective, not endless channel-surfing.","zh":"優質看電視方式是有選擇地觀看，而不是無止境轉台。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"channel-surfing","meaning":"不停轉台","examples":[{"en":"Endless channel-surfing is not the kind of viewing I support.","zh":"無止境不停轉台不是我支持的觀看方式。"},{"en":"Channel-surfing means quickly switching from one television channel to another.","zh":"不停轉台意思是快速從一個電視頻道轉到另一個頻道。"},{"en":"Channel-surfing may feel relaxing but often leaves viewers with little memory of what they watched.","zh":"不停轉台可能令人放鬆，但觀眾往往不太記得自己看了甚麼。"},{"en":"Students learn more from one good programme than from hours of channel-surfing.","zh":"學生從一個好節目中學到的，會比從數小時不停轉台中學到的更多。"},{"en":"Channel-surfing becomes careless when there is no purpose or attention.","zh":"如果沒有目的或注意力，不停轉台就會變得漫不經心。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"careless binge-watching","meaning":"漫無目的地煲劇","examples":[{"en":"I am not defending careless binge-watching.","zh":"我不是在為漫無目的地煲劇辯護。"},{"en":"Careless binge-watching means watching many episodes for a long time without thinking or control.","zh":"漫無目的地煲劇意思是長時間觀看很多集節目，卻沒有思考或控制。"},{"en":"A student practises careless binge-watching when they watch a whole season before an exam.","zh":"學生在考試前看完整季劇集，就是漫無目的地煲劇。"},{"en":"This habit can harm sleep, homework, and concentration.","zh":"這種習慣可能傷害睡眠、功課和專注力。"},{"en":"Thoughtful television is different from careless binge-watching.","zh":"有思考地看電視與漫無目的地煲劇不同。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"argue that","meaning":"主張；論證","examples":[{"en":"I am arguing that thoughtful television can educate us.","zh":"我主張有思考地觀看電視可以教育我們。"},{"en":"To argue that means to give reasons for believing a particular idea.","zh":"主張某事意思是提出理由去支持某個想法。"},{"en":"A student may argue that homework should focus on quality, not quantity.","zh":"學生可能主張功課應重質不重量。"},{"en":"In debate, speakers argue that their side is more reasonable.","zh":"在辯論中，演講者會論證自己一方更合理。"},{"en":"This phrase introduces a claim that needs support.","zh":"這個短語引出一個需要支持的主張。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"watched thoughtfully","meaning":"被有思考地觀看","examples":[{"en":"When television is watched thoughtfully, it can broaden our knowledge.","zh":"當電視被有思考地觀看時，它可以擴闊我們的知識。"},{"en":"Watched thoughtfully means viewed with attention, questions, and reflection.","zh":"被有思考地觀看意思是帶著注意、問題和反思去觀看。"},{"en":"A documentary is watched thoughtfully when students take notes and discuss its message.","zh":"當學生做筆記並討論紀錄片訊息時，紀錄片就是被有思考地觀看。"},{"en":"Television watched thoughtfully can become learning instead of background noise.","zh":"被有思考地觀看的電視可以成為學習，而不是背景聲音。"},{"en":"The same programme may teach more when it is watched thoughtfully.","zh":"同一個節目在被有思考地觀看時，可能教會人更多。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"broaden our knowledge","meaning":"擴闊我們的知識","examples":[{"en":"Thoughtful television can broaden our knowledge.","zh":"有思考地觀看電視可以擴闊我們的知識。"},{"en":"To broaden our knowledge means to help us learn more about different subjects and people.","zh":"擴闊我們的知識意思是幫助我們學到更多不同主題和人的事情。"},{"en":"A history programme can broaden our knowledge of ancient civilisations.","zh":"歷史節目可以擴闊我們對古代文明的知識。"},{"en":"News reports broaden our knowledge when they explain causes, effects, and human stories.","zh":"當新聞報道解釋原因、結果和人的故事時，它能擴闊我們的知識。"},{"en":"Television broadens our knowledge best when it leads us to ask further questions.","zh":"電視在引導我們提出更多問題時，最能擴闊我們的知識。"}],"source":"2017 Q6.pdf","sourcePage":3},{"front":"train our judgement","meaning":"訓練我們的判斷力","examples":[{"en":"Good television can train our judgement.","zh":"優質電視節目可以訓練我們的判斷力。"},{"en":"To train our judgement means to improve our ability to decide what is reasonable or true.","zh":"訓練我們的判斷力意思是改善我們判斷甚麼合理或真實的能力。"},{"en":"A debate programme trains our judgement when it shows both sides of an issue.","zh":"當辯論節目展示議題雙方時，它可以訓練我們的判斷力。"},{"en":"Viewers train their judgement by asking whether claims are supported by evidence.","zh":"觀眾透過詢問說法是否有證據支持來訓練判斷力。"},{"en":"Television trains judgement only when viewers do not accept everything blindly.","zh":"只有當觀眾不盲目接受一切時，電視才會訓練判斷力。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"deepen our command of language","meaning":"加深我們對語言的掌握","examples":[{"en":"Good television can deepen our command of language.","zh":"優質電視節目可以加深我們對語言的掌握。"},{"en":"To deepen our command of language means to improve how well we understand and use words, tone, and structure.","zh":"加深我們對語言的掌握意思是提升我們理解和使用詞語、語氣和結構的能力。"},{"en":"English documentaries deepen language command by showing formal explanation in context.","zh":"英文紀錄片透過在語境中展示正式解釋，能加深語言掌握。"},{"en":"Dramas deepen language command when viewers hear natural conversation and emotion.","zh":"當觀眾聽到自然對話和情感時，劇集能加深語言掌握。"},{"en":"Television deepens language learning when students listen actively and repeat useful phrases.","zh":"當學生主動聆聽並重複有用短語時，電視能加深語言學習。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"command of language","meaning":"語言掌握能力","examples":[{"en":"Television can improve a student’s command of language.","zh":"電視可以提升學生的語言掌握能力。"},{"en":"Command of language means the ability to understand and use a language well.","zh":"語言掌握能力是理解和良好使用一種語言的能力。"},{"en":"A student with good command of language can explain ideas clearly.","zh":"語言掌握能力好的學生能清楚解釋想法。"},{"en":"Listening to natural speech can improve command of language beyond textbook examples.","zh":"聆聽自然說話可以提升課本例子以外的語言掌握能力。"},{"en":"Command of language grows when learners hear words used in real situations.","zh":"當學習者聽到詞語在真實情況中使用時，語言掌握能力會成長。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"as well as","meaning":"以及","examples":[{"en":"Television can deepen our command of language as well as human experience.","zh":"電視可以加深我們對語言以及人生經驗的掌握。"},{"en":"As well as means and also.","zh":"以及意思是並且也包括。"},{"en":"A good documentary teaches facts as well as emotions behind those facts.","zh":"好紀錄片會教事實，以及事實背後的情感。"},{"en":"Television can build vocabulary as well as empathy.","zh":"電視可以建立詞彙，以及同理心。"},{"en":"This phrase adds another important benefit to the sentence.","zh":"這個短語為句子加入另一個重要好處。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"human experience","meaning":"人生經驗；人類經驗","examples":[{"en":"Good television can deepen our understanding of human experience.","zh":"優質電視節目可以加深我們對人生經驗的理解。"},{"en":"Human experience means the feelings, struggles, choices, and stories people go through in life.","zh":"人生經驗是指人們在生活中經歷的感受、掙扎、選擇和故事。"},{"en":"A drama about illness can teach viewers about human experience beyond medical facts.","zh":"關於疾病的劇集可以教觀眾了解醫學事實以外的人生經驗。"},{"en":"Television shows human experience when it lets us see fear, hope, loss, and courage.","zh":"當電視讓我們看見恐懼、希望、失去和勇氣時，它就在呈現人類經驗。"},{"en":"Understanding human experience makes people more thoughtful and empathetic.","zh":"理解人生經驗會令人更有思考和同理心。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"open a window onto","meaning":"打開通往……的窗口","examples":[{"en":"Television opens a window onto knowledge that textbooks alone cannot provide.","zh":"電視打開通往單靠課本未必能提供的知識的窗口。"},{"en":"To open a window onto something means to give people a view or understanding of it.","zh":"打開通往某事的窗口意思是讓人看見或理解某事。"},{"en":"A travel programme opens a window onto lives in distant villages.","zh":"旅遊節目打開通往遙遠村莊生活的窗口。"},{"en":"Documentaries open a window onto science by showing real images and experiments.","zh":"紀錄片透過展示真實影像和實驗，打開通往科學的窗口。"},{"en":"This phrase suggests television can help viewers see beyond their own world.","zh":"這個短語暗示電視可以幫助觀眾看見自身世界以外的事物。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"textbooks alone","meaning":"單靠課本","examples":[{"en":"Television offers knowledge that textbooks alone cannot always provide.","zh":"電視提供單靠課本未必總能提供的知識。"},{"en":"Textbooks alone means only textbooks, without other learning materials or experiences.","zh":"單靠課本意思是只有課本，沒有其他學習材料或經驗。"},{"en":"Textbooks alone may explain volcanoes, but videos can show their movement and danger.","zh":"單靠課本可以解釋火山，但影片能展示它們的活動和危險。"},{"en":"Students learn better when textbooks are supported by images, discussion, and experience.","zh":"當課本配合影像、討論和經驗時，學生會學得更好。"},{"en":"Television should not replace textbooks alone, but it can enrich them.","zh":"電視不應取代課本，但可以豐富課本學習。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"cannot always provide","meaning":"未必總能提供","examples":[{"en":"Textbooks alone cannot always provide vivid experience.","zh":"單靠課本未必總能提供生動經驗。"},{"en":"Cannot always provide means does not give something in every situation.","zh":"未必總能提供意思是不是在每種情況下都能給予某事。"},{"en":"A worksheet cannot always provide the sound and emotion of real speech.","zh":"工作紙未必總能提供真實說話的聲音和情感。"},{"en":"Textbooks cannot always provide moving images of natural disasters.","zh":"課本未必總能提供自然災害的動態影像。"},{"en":"This phrase shows that one learning tool has limits.","zh":"這個短語顯示一種學習工具有其限制。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"reading about","meaning":"閱讀有關……的內容","examples":[{"en":"Reading about volcanoes is useful.","zh":"閱讀有關火山的內容是有用的。"},{"en":"Reading about something means learning information from written words.","zh":"閱讀有關某事的內容，意思是從文字中學習資訊。"},{"en":"Reading about history helps students understand dates and events.","zh":"閱讀有關歷史的內容幫助學生理解日期和事件。"},{"en":"Reading about science is important, but seeing examples can make ideas clearer.","zh":"閱讀有關科學的內容很重要，但看見例子能令想法更清晰。"},{"en":"Television can support reading about a topic by showing what the words describe.","zh":"電視可以透過展示文字所描述的東西，支援有關主題的閱讀。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"molten lava","meaning":"熔岩","examples":[{"en":"Seeing molten lava on screen makes the science memorable.","zh":"在螢幕上看見熔岩，會令科學知識令人難忘。"},{"en":"Molten lava is hot liquid rock that flows from a volcano.","zh":"熔岩是從火山流出的高溫液態岩石。"},{"en":"A documentary may show molten lava moving slowly down a mountain.","zh":"紀錄片可能展示熔岩慢慢流下山坡。"},{"en":"Molten lava helps students understand that volcanoes are powerful and dangerous.","zh":"熔岩幫助學生明白火山強大而危險。"},{"en":"Seeing molten lava can make geology feel real instead of abstract.","zh":"看見熔岩可以令地質學變得真實，而不是抽象。"}],"source":"2017 Q6.pdf","sourcePage":4},{"front":"ash clouds","meaning":"火山灰雲","examples":[{"en":"Television can show molten lava, ash clouds, and frightened villagers.","zh":"電視可以展示熔岩、火山灰雲和驚恐的村民。"},{"en":"Ash clouds are large clouds of dust and ash thrown into the air by a volcano.","zh":"火山灰雲是火山把塵和灰噴到空中形成的大雲團。"},{"en":"Ash clouds can darken the sky and make breathing difficult.","zh":"火山灰雲可以令天空變暗，並令人呼吸困難。"},{"en":"Seeing ash clouds helps viewers understand why eruptions affect nearby communities.","zh":"看見火山灰雲幫助觀眾理解為何火山爆發會影響附近社區。"},{"en":"Ash clouds show that volcanoes can harm people even far from the lava.","zh":"火山灰雲顯示火山即使在熔岩以外的地方也能傷害人。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"terrified villagers","meaning":"驚恐的村民","examples":[{"en":"Images of terrified villagers make the danger memorable.","zh":"驚恐村民的影像令危險令人難忘。"},{"en":"Terrified villagers are village residents who feel extremely afraid.","zh":"驚恐的村民是感到極度害怕的村莊居民。"},{"en":"A news report may show terrified villagers leaving their homes during a flood.","zh":"新聞報道可能展示洪水期間驚恐的村民離開家園。"},{"en":"Seeing terrified villagers reminds viewers that disasters affect real people.","zh":"看見驚恐的村民提醒觀眾災難會影響真實的人。"},{"en":"Such images make learning emotional as well as factual.","zh":"這類影像令學習既有情感，也有事實。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"on screen","meaning":"在螢幕上","examples":[{"en":"Seeing volcanoes on screen makes the science memorable.","zh":"在螢幕上看見火山，會令科學知識令人難忘。"},{"en":"On screen means shown on television, a computer, or another display.","zh":"在螢幕上意思是在電視、電腦或其他顯示器上呈現。"},{"en":"Students may understand coral reefs better when they see them on screen.","zh":"當學生在螢幕上看見珊瑚礁時，可能更能理解它們。"},{"en":"On-screen images can make invisible or distant topics easier to imagine.","zh":"螢幕上的影像可以令看不見或遙遠的主題更容易想像。"},{"en":"What appears on screen can influence how viewers understand the world.","zh":"螢幕上出現的內容可以影響觀眾如何理解世界。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"make the science memorable","meaning":"令科學知識令人難忘","examples":[{"en":"Seeing molten lava makes the science memorable.","zh":"看見熔岩會令科學知識令人難忘。"},{"en":"To make the science memorable means to help people remember scientific ideas clearly.","zh":"令科學知識令人難忘意思是幫助人清楚記住科學概念。"},{"en":"A video of a hurricane can make weather science memorable for students.","zh":"颶風影片可以令天氣科學對學生來說令人難忘。"},{"en":"Science becomes memorable when facts are connected with images and real events.","zh":"當事實與影像和真實事件連接時，科學知識會令人難忘。"},{"en":"Television makes the science memorable by turning abstract ideas into visible examples.","zh":"電視透過把抽象想法轉化為可見例子，令科學知識令人難忘。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"a documentary about","meaning":"關於……的紀錄片","examples":[{"en":"A documentary about coral reefs can teach environmental science.","zh":"關於珊瑚礁的紀錄片可以教授環境科學。"},{"en":"A documentary about something is a factual programme that explains a real topic.","zh":"關於某事的紀錄片，是解釋真實主題的事實性節目。"},{"en":"A documentary about poverty may show interviews, statistics, and daily life.","zh":"關於貧窮的紀錄片可能展示訪問、統計和日常生活。"},{"en":"Students learn from documentaries because they connect facts with real scenes.","zh":"學生從紀錄片中學習，因為它們把事實和真實場景連接起來。"},{"en":"A documentary about nature can make distant problems feel close.","zh":"關於自然的紀錄片可以令遙遠問題感覺貼近。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"coral reefs","meaning":"珊瑚礁","examples":[{"en":"A documentary about coral reefs can show living ecosystems.","zh":"關於珊瑚礁的紀錄片可以展示活生態系統。"},{"en":"Coral reefs are underwater structures built by tiny sea animals called corals.","zh":"珊瑚礁是由稱為珊瑚的微小海洋動物建成的水底結構。"},{"en":"Many fish and sea creatures live around coral reefs.","zh":"許多魚類和海洋生物生活在珊瑚礁附近。"},{"en":"Coral reefs are important because they protect coastlines and support marine life.","zh":"珊瑚礁很重要，因為它們保護海岸線並支持海洋生命。"},{"en":"Television can show coral reefs in colours and movement that textbooks cannot fully capture.","zh":"電視可以展示珊瑚礁的色彩和動態，而課本未必能完全呈現。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"warmer oceans","meaning":"變暖的海洋","examples":[{"en":"Warmer oceans can bleach living ecosystems.","zh":"變暖的海洋可以令活生態系統白化。"},{"en":"Warmer oceans are seas with rising temperatures caused by environmental change.","zh":"變暖的海洋是因環境變化而溫度上升的海洋。"},{"en":"Warmer oceans can harm coral reefs by making corals lose their colour.","zh":"變暖的海洋會令珊瑚失去顏色，從而傷害珊瑚礁。"},{"en":"A documentary can show how warmer oceans affect fish, storms, and coastal communities.","zh":"紀錄片可以展示變暖的海洋如何影響魚類、風暴和沿岸社區。"},{"en":"Seeing warmer oceans on television helps students connect climate change with real effects.","zh":"在電視上看見變暖的海洋，幫助學生把氣候變化和真實影響連接起來。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"bleach living ecosystems","meaning":"令活生態系統白化","examples":[{"en":"Warmer oceans can bleach living ecosystems.","zh":"變暖的海洋可以令活生態系統白化。"},{"en":"To bleach living ecosystems means to make living natural systems lose colour and health.","zh":"令活生態系統白化意思是令有生命的自然系統失去顏色和健康。"},{"en":"Coral reefs are bleached when heat stress causes corals to turn pale.","zh":"當熱壓力令珊瑚變白時，珊瑚礁就被白化。"},{"en":"Bleaching shows that environmental damage can be visible and serious.","zh":"白化顯示環境破壞可以是可見而嚴重的。"},{"en":"Television helps viewers understand bleaching by showing before-and-after images.","zh":"電視透過展示前後對比影像，幫助觀眾理解白化。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"living ecosystems","meaning":"活生態系統","examples":[{"en":"Coral reefs are living ecosystems.","zh":"珊瑚礁是活生態系統。"},{"en":"Living ecosystems are natural systems made up of plants, animals, and their environment.","zh":"活生態系統是由植物、動物和其環境組成的自然系統。"},{"en":"A forest is a living ecosystem because trees, insects, birds, and soil affect one another.","zh":"森林是活生態系統，因為樹木、昆蟲、鳥類和泥土互相影響。"},{"en":"Coral reefs are living ecosystems that can be damaged by heat and pollution.","zh":"珊瑚礁是會受熱力和污染破壞的活生態系統。"},{"en":"Understanding living ecosystems helps students see nature as connected, not separate pieces.","zh":"理解活生態系統幫助學生把自然看成互相連繫，而不是分散部分。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"a news feature on","meaning":"關於……的新聞專題","examples":[{"en":"A news feature on food waste can show the problem clearly.","zh":"關於食物浪費的新聞專題可以清楚展示問題。"},{"en":"A news feature on something is a detailed news report about a particular topic.","zh":"關於某事的新聞專題，是對特定主題的詳細新聞報道。"},{"en":"A news feature on housing may include interviews with residents and experts.","zh":"關於住屋的新聞專題可能包括居民和專家的訪問。"},{"en":"News features teach viewers by showing causes, examples, and consequences.","zh":"新聞專題透過展示原因、例子和後果來教育觀眾。"},{"en":"A news feature on food waste can make a common habit look serious.","zh":"關於食物浪費的新聞專題可以令常見習慣看起來嚴重。"}],"source":"2017 Q6.pdf","sourcePage":5},{"front":"food waste","meaning":"食物浪費","examples":[{"en":"A news feature on food waste can take us from a supermarket shelf to a landfill.","zh":"關於食物浪費的新聞專題可以帶我們由超級市場貨架到堆填區。"},{"en":"Food waste means food that is thrown away instead of being eaten.","zh":"食物浪費是指食物被丟棄而不是被食用。"},{"en":"Restaurants create food waste when they throw away unsold meals every night.","zh":"餐廳每晚丟棄賣不出的餐食時，就會造成食物浪費。"},{"en":"Food waste harms society because money, labour, and resources are wasted too.","zh":"食物浪費傷害社會，因為金錢、勞力和資源也被浪費。"},{"en":"Television can make food waste visible by following food from shop to rubbish site.","zh":"電視可以透過追蹤食物從商店到垃圾場的過程，令食物浪費變得可見。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"take us from…to…","meaning":"帶我們由……到……","examples":[{"en":"A news feature can take us from a supermarket shelf to a landfill.","zh":"新聞專題可以帶我們由超級市場貨架到堆填區。"},{"en":"To take us from one place to another means to guide viewers through different stages or locations.","zh":"帶我們由一處到另一處，意思是引導觀眾經歷不同階段或地點。"},{"en":"A documentary may take us from a factory to a family dinner table.","zh":"紀錄片可能帶我們由工廠到家庭飯桌。"},{"en":"This structure helps viewers understand a process step by step.","zh":"這個結構幫助觀眾一步一步理解過程。"},{"en":"Television can take us from facts to feelings through images and stories.","zh":"電視可以透過影像和故事，帶我們由事實走向感受。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"supermarket shelf","meaning":"超級市場貨架","examples":[{"en":"Food may travel from a supermarket shelf to a landfill.","zh":"食物可能由超級市場貨架去到堆填區。"},{"en":"A supermarket shelf is the place where food and products are displayed for shoppers.","zh":"超級市場貨架是展示食物和產品給購物者看的地方。"},{"en":"A colourful cereal box may look attractive on a supermarket shelf.","zh":"色彩鮮艷的早餐穀物盒在超級市場貨架上可能看起來吸引。"},{"en":"Seeing food on a supermarket shelf makes waste feel unlikely, but much of it may be thrown away later.","zh":"看見食物在超級市場貨架上，會令人覺得浪費不太可能，但很多食物之後可能被丟棄。"},{"en":"A news report can show the journey from supermarket shelf to rubbish bin.","zh":"新聞報道可以展示食物由超級市場貨架到垃圾桶的旅程。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"landfill","meaning":"堆填區","examples":[{"en":"Food waste often ends up in a landfill.","zh":"食物浪費常最終進入堆填區。"},{"en":"A landfill is a place where rubbish is buried or stored.","zh":"堆填區是垃圾被掩埋或存放的地方。"},{"en":"Food thrown away by shops may be carried to a landfill by rubbish trucks.","zh":"商店丟棄的食物可能由垃圾車運到堆填區。"},{"en":"Landfills create environmental problems when too much waste is produced.","zh":"當產生太多垃圾時，堆填區會造成環境問題。"},{"en":"Seeing a landfill on television can make waste feel real and urgent.","zh":"在電視上看見堆填區，可以令浪費感覺真實而迫切。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"step by step","meaning":"一步一步地","examples":[{"en":"Step by step, the viewer connects cause and effect.","zh":"一步一步地，觀眾連繫因果關係。"},{"en":"Step by step means one stage at a time in a clear order.","zh":"一步一步地意思是按清晰次序，一個階段一個階段地進行。"},{"en":"A science programme explains an experiment step by step so students can follow it.","zh":"科學節目一步一步地解釋實驗，讓學生能跟上。"},{"en":"Learning step by step helps viewers understand complex problems.","zh":"一步一步地學習幫助觀眾理解複雜問題。"},{"en":"Television can show processes step by step through images, narration, and examples.","zh":"電視可以透過影像、旁白和例子，一步一步地展示過程。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"connect cause and effect","meaning":"連繫因果關係","examples":[{"en":"The viewer connects cause and effect through images.","zh":"觀眾透過影像連繫因果關係。"},{"en":"To connect cause and effect means to understand how one thing leads to another.","zh":"連繫因果關係意思是理解一件事如何導致另一件事。"},{"en":"A programme on food waste helps students connect overbuying with landfill growth.","zh":"關於食物浪費的節目幫助學生把過量購買和堆填區增加連繫起來。"},{"en":"Connecting cause and effect is important for science, history, and social issues.","zh":"連繫因果關係對科學、歷史和社會議題都很重要。"},{"en":"Television supports this thinking when it shows actions and consequences clearly.","zh":"當電視清楚展示行動和後果時，它能支持這種思考。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"capture attention","meaning":"吸引注意力","examples":[{"en":"Images capture attention and encourage curiosity.","zh":"影像吸引注意力並激發好奇心。"},{"en":"To capture attention means to make people notice and focus on something.","zh":"吸引注意力意思是令人注意並集中於某事。"},{"en":"A dramatic image of a volcano can capture students’ attention immediately.","zh":"火山的震撼影像可以立即吸引學生注意力。"},{"en":"Television captures attention through movement, sound, faces, and stories.","zh":"電視透過動態、聲音、面孔和故事吸引注意力。"},{"en":"Captured attention becomes useful when it leads to learning.","zh":"當被吸引的注意力引向學習時，它就變得有用。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"encourage curiosity","meaning":"激發好奇心","examples":[{"en":"Attention encourages curiosity.","zh":"注意力會激發好奇心。"},{"en":"To encourage curiosity means to make people want to know more.","zh":"激發好奇心意思是令人想知道更多。"},{"en":"A mystery in a history programme can encourage curiosity about the past.","zh":"歷史節目中的謎團可以激發人對過去的好奇心。"},{"en":"Curiosity helps students ask questions after watching television.","zh":"好奇心幫助學生在看電視後提出問題。"},{"en":"Good television encourages curiosity instead of giving only simple answers.","zh":"優質電視節目會激發好奇心，而不是只給簡單答案。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"lead to questions","meaning":"引出問題","examples":[{"en":"Curiosity leads to questions.","zh":"好奇心會引出問題。"},{"en":"To lead to questions means to make people start asking about causes, meanings, or results.","zh":"引出問題意思是令人開始詢問原因、意義或結果。"},{"en":"A programme about poverty may lead to questions about fairness and policy.","zh":"關於貧窮的節目可能引出關於公平和政策的問題。"},{"en":"Questions are valuable because they push learning beyond the programme itself.","zh":"問題有價值，因為它們把學習推到節目本身之外。"},{"en":"Good television leads to questions rather than passive acceptance.","zh":"優質電視會引出問題，而不是令人被動接受。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"push learning beyond","meaning":"把學習推到……之外","examples":[{"en":"Questions push learning beyond the living room.","zh":"問題把學習推到客廳之外。"},{"en":"To push learning beyond something means to extend learning past its original place or limit.","zh":"把學習推到某處之外，意思是把學習延伸到原本地點或限制以外。"},{"en":"A documentary can push learning beyond the classroom when students research further at home.","zh":"當學生在家進一步研究時，紀錄片可以把學習推到課室之外。"},{"en":"Television pushes learning beyond entertainment if it leads to reading and discussion.","zh":"如果電視引導閱讀和討論，它就把學習推到娛樂之外。"},{"en":"The best programmes push learning beyond the screen.","zh":"最優質的節目會把學習推到螢幕之外。"}],"source":"2017 Q6.pdf","sourcePage":6},{"front":"beyond the living room","meaning":"客廳以外","examples":[{"en":"Good television can push learning beyond the living room.","zh":"優質電視可以把學習推到客廳以外。"},{"en":"Beyond the living room means outside the home space where people usually watch television.","zh":"客廳以外意思是離開人們通常看電視的家中空間。"},{"en":"A student may watch a science programme, then research the topic beyond the living room.","zh":"學生可能看完科學節目後，在客廳以外繼續研究該主題。"},{"en":"Learning goes beyond the living room when it affects schoolwork, conversations, and choices.","zh":"當學習影響功課、對話和選擇時，它就走到客廳以外。"},{"en":"Television becomes powerful when it sends curiosity beyond the living room.","zh":"當電視把好奇心送到客廳以外時，它就變得有力量。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"some may say that","meaning":"有些人可能會說","examples":[{"en":"Some may say that this is only entertainment.","zh":"有些人可能會說這只是娛樂。"},{"en":"Some may say that introduces a possible opposing opinion.","zh":"有些人可能會說，用來引出可能的反方意見。"},{"en":"Some may say that television wastes time, but that depends on how it is used.","zh":"有些人可能會說電視浪費時間，但這取決於它如何被使用。"},{"en":"This phrase helps a speaker acknowledge criticism before answering it.","zh":"這個短語幫助演講者先承認批評，再作回應。"},{"en":"In debate, “some may say that” prepares the audience for a counterargument.","zh":"在辯論中，「有些人可能會說」讓聽眾準備聽反方論點。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"only entertainment","meaning":"只是娛樂","examples":[{"en":"Some critics claim that television is only entertainment.","zh":"有些批評者聲稱電視只是娛樂。"},{"en":"Only entertainment means just for fun and not useful for learning or thinking.","zh":"只是娛樂意思是只為了好玩，對學習或思考沒有用。"},{"en":"A comedy may seem like only entertainment, but it can reveal social habits.","zh":"喜劇可能看似只是娛樂，但它可以揭示社會習慣。"},{"en":"Calling television only entertainment ignores educational documentaries and serious interviews.","zh":"把電視稱為只是娛樂，會忽略教育紀錄片和嚴肅訪問。"},{"en":"Entertainment can still teach if it encourages thought and empathy.","zh":"如果娛樂能激發思考和同理心，它仍然可以教育人。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"what matters is not…, but…","meaning":"重要的不是……而是……","examples":[{"en":"What matters is not the screen itself, but the quality of what appears on it.","zh":"重要的不是螢幕本身，而是螢幕上內容的質素。"},{"en":"This structure contrasts the less important point with the truly important point.","zh":"這個結構把較不重要的一點和真正重要的一點作對比。"},{"en":"What matters is not how long a book is, but how deeply it makes us think.","zh":"重要的不是一本書有多長，而是它令我們思考得多深。"},{"en":"In television, the key issue is content, not the object itself.","zh":"在電視方面，關鍵問題是內容，而不是物件本身。"},{"en":"This phrase helps writers focus an argument on the real issue.","zh":"這個短語幫助作者把論點集中在真正問題上。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"the screen itself","meaning":"螢幕本身","examples":[{"en":"What matters is not the screen itself.","zh":"重要的不是螢幕本身。"},{"en":"The screen itself means the physical display, separate from the content shown on it.","zh":"螢幕本身是指物理顯示屏，與其上顯示的內容分開。"},{"en":"A screen itself cannot teach; the programme and the viewer’s attention matter.","zh":"螢幕本身不能教育人；節目和觀眾的注意力才重要。"},{"en":"Blaming the screen itself ignores how people choose and use media.","zh":"責怪螢幕本身會忽略人們如何選擇和使用媒體。"},{"en":"The screen itself is only a tool, not automatically a danger.","zh":"螢幕本身只是一種工具，不會自動成為危險。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"the quality of what appears on it","meaning":"螢幕上內容的質素","examples":[{"en":"The quality of what appears on television matters most.","zh":"電視上內容的質素最重要。"},{"en":"The quality of what appears on it means how good, useful, or meaningful the screen content is.","zh":"螢幕上內容的質素，是指螢幕內容有多好、有用或有意義。"},{"en":"A screen showing a thoughtful documentary has higher value than one showing careless noise.","zh":"播放有思想紀錄片的螢幕，比播放無意義聲音的螢幕更有價值。"},{"en":"Viewers learn more when the quality of what appears on television is high.","zh":"當電視上內容的質素高時，觀眾會學到更多。"},{"en":"This phrase reminds us to judge television by content, not by the device.","zh":"這個短語提醒我們按內容而不是按裝置判斷電視。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"space exploration","meaning":"太空探索","examples":[{"en":"A student may learn about space exploration from a science programme.","zh":"學生可能從科學節目中學到太空探索。"},{"en":"Space exploration is the study and travel beyond Earth to learn about planets, stars, and the universe.","zh":"太空探索是研究和前往地球以外，以了解行星、星星和宇宙。"},{"en":"Programmes about space exploration can show rockets, astronauts, and distant planets.","zh":"關於太空探索的節目可以展示火箭、太空人和遙遠行星。"},{"en":"Space exploration teaches students about science, technology, and human curiosity.","zh":"太空探索教學生認識科學、科技和人類好奇心。"},{"en":"Television makes space exploration easier to imagine through images and animation.","zh":"電視透過影像和動畫令太空探索更容易想像。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"science programme","meaning":"科學節目","examples":[{"en":"A science programme can teach students about space exploration.","zh":"科學節目可以教學生認識太空探索。"},{"en":"A science programme is a television show that explains scientific ideas or discoveries.","zh":"科學節目是解釋科學概念或發現的電視節目。"},{"en":"A science programme may show experiments, interviews, and real-world examples.","zh":"科學節目可能展示實驗、訪問和真實例子。"},{"en":"Students can learn faster when a science programme makes abstract ideas visible.","zh":"當科學節目令抽象概念變得可見時，學生可以學得更快。"},{"en":"A good science programme encourages viewers to ask why and how.","zh":"優質科學節目會鼓勵觀眾問為甚麼和如何發生。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"world poverty","meaning":"世界貧窮問題","examples":[{"en":"A student may learn about world poverty from a report.","zh":"學生可能從報道中學到世界貧窮問題。"},{"en":"World poverty means serious lack of money, food, housing, or opportunity in different parts of the world.","zh":"世界貧窮問題是指世界不同地方嚴重缺乏金錢、食物、住屋或機會。"},{"en":"A television report on world poverty may show families struggling to afford meals.","zh":"關於世界貧窮問題的電視報道可能展示難以負擔餐食的家庭。"},{"en":"Learning about world poverty can help students understand inequality beyond their own city.","zh":"學習世界貧窮問題可以幫助學生理解自己城市以外的不平等。"},{"en":"Good television turns world poverty from a distant statistic into a human story.","zh":"優質電視把世界貧窮問題由遙遠統計變成人的故事。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"ancient Egypt","meaning":"古埃及","examples":[{"en":"A history series may introduce students to ancient Egypt.","zh":"歷史系列節目可能向學生介紹古埃及。"},{"en":"Ancient Egypt was an early civilisation known for pyramids, pharaohs, writing, and the Nile River.","zh":"古埃及是早期文明，以金字塔、法老、文字和尼羅河聞名。"},{"en":"A programme about ancient Egypt may show temples, tombs, and daily life.","zh":"關於古埃及的節目可能展示神廟、陵墓和日常生活。"},{"en":"Seeing ancient Egypt on television can make history feel more alive.","zh":"在電視上看見古埃及，可以令歷史感覺更鮮活。"},{"en":"Students may remember ancient Egypt better when they see images as well as read facts.","zh":"當學生看見影像並閱讀事實時，可能更容易記住古埃及。"}],"source":"2017 Q6.pdf","sourcePage":7},{"front":"history series","meaning":"歷史系列節目","examples":[{"en":"A history series can teach students about ancient Egypt.","zh":"歷史系列節目可以教學生認識古埃及。"},{"en":"A history series is a set of television episodes about past events or civilisations.","zh":"歷史系列節目是一組關於過去事件或文明的電視集數。"},{"en":"A history series may explain wars, inventions, leaders, and ordinary lives.","zh":"歷史系列節目可能解釋戰爭、發明、領袖和普通人的生活。"},{"en":"History series help students see how events connect across time.","zh":"歷史系列節目幫助學生看見事件如何跨越時間連接。"},{"en":"A good history series makes the past understandable without oversimplifying it.","zh":"優質歷史系列節目能令過去容易理解，同時不過分簡化。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"dull the mind","meaning":"令頭腦遲鈍","examples":[{"en":"Good television does not dull the mind.","zh":"優質電視節目不會令頭腦遲鈍。"},{"en":"To dull the mind means to make thinking slower, weaker, or less active.","zh":"令頭腦遲鈍意思是令思考變慢、變弱或不活躍。"},{"en":"Repeating easy tasks without thought may dull the mind.","zh":"不經思考地重複簡單任務，可能令頭腦遲鈍。"},{"en":"Bad television habits can dull the mind if viewers never question anything.","zh":"如果觀眾從不質疑任何內容，差劣看電視習慣可能令頭腦遲鈍。"},{"en":"Good television does the opposite: it wakes the mind up.","zh":"優質電視做的是相反的事：它喚醒頭腦。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"enlarge the mind","meaning":"擴闊思維","examples":[{"en":"Educational television can enlarge the mind.","zh":"教育電視可以擴闊思維。"},{"en":"To enlarge the mind means to expand a person’s understanding, imagination, and awareness.","zh":"擴闊思維意思是擴展一個人的理解、想像和意識。"},{"en":"Travel documentaries enlarge the mind by showing different ways of life.","zh":"旅遊紀錄片透過展示不同生活方式來擴闊思維。"},{"en":"Stories about unfamiliar people can enlarge the mind beyond local experience.","zh":"關於陌生人的故事可以把思維擴闊到本地經驗以外。"},{"en":"Television enlarges the mind when it makes viewers think more widely.","zh":"當電視令觀眾想得更廣，它就能擴闊思維。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"sharpen critical thinking","meaning":"提升批判性思維","examples":[{"en":"Watching TV can sharpen critical thinking.","zh":"看電視可以提升批判性思維。"},{"en":"To sharpen critical thinking means to improve the ability to judge claims carefully.","zh":"提升批判性思維意思是改善仔細判斷說法的能力。"},{"en":"A debate programme sharpens critical thinking by showing different arguments.","zh":"辯論節目透過展示不同論點來提升批判性思維。"},{"en":"Viewers sharpen critical thinking when they ask what evidence is missing.","zh":"當觀眾詢問缺少了甚麼證據時，他們就在提升批判性思維。"},{"en":"Television sharpens critical thinking only if viewers watch actively.","zh":"只有當觀眾主動觀看時，電視才會提升批判性思維。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"unlike","meaning":"不像……","examples":[{"en":"Unlike a worksheet, television presents many conflicting voices.","zh":"不像工作紙，電視呈現許多互相衝突的聲音。"},{"en":"Unlike means different from another thing being compared.","zh":"不像意思是與被比較的另一事物不同。"},{"en":"Unlike a textbook, a documentary can show movement and sound.","zh":"不像課本，紀錄片可以展示動態和聲音。"},{"en":"This word helps writers make a clear contrast.","zh":"這個詞幫助作者作出清楚對比。"},{"en":"Unlike passive entertainment, good television can invite active thinking.","zh":"不像被動娛樂，優質電視可以邀請人主動思考。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"a worksheet","meaning":"工作紙","examples":[{"en":"A worksheet often has one correct answer.","zh":"工作紙通常有一個正確答案。"},{"en":"A worksheet is a printed or digital exercise sheet used for learning or practice.","zh":"工作紙是用於學習或練習的紙本或電子練習表。"},{"en":"Students may complete a worksheet after watching a documentary.","zh":"學生可能在觀看紀錄片後完成工作紙。"},{"en":"A worksheet can test knowledge, but it may not show real-life complexity.","zh":"工作紙可以測試知識，但未必能展示現實生活的複雜性。"},{"en":"Television and worksheets can work together when students watch, think, and answer.","zh":"當學生觀看、思考和作答時，電視和工作紙可以配合使用。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"one correct answer","meaning":"一個正確答案","examples":[{"en":"A worksheet often has one correct answer.","zh":"工作紙通常有一個正確答案。"},{"en":"One correct answer means only one response is accepted as right.","zh":"一個正確答案意思是只有一個回應被接受為正確。"},{"en":"In maths, a simple calculation may have one correct answer.","zh":"在數學中，簡單計算可能有一個正確答案。"},{"en":"Social issues rarely have one correct answer because they involve values and evidence.","zh":"社會議題很少只有一個正確答案，因為它們涉及價值和證據。"},{"en":"Television can show problems that are more complex than one correct answer.","zh":"電視可以展示比一個正確答案更複雜的問題。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"constantly presents","meaning":"不斷呈現","examples":[{"en":"Television constantly presents voices that clash.","zh":"電視不斷呈現互相衝突的聲音。"},{"en":"Constantly presents means repeatedly shows or offers something.","zh":"不斷呈現意思是反覆展示或提供某事。"},{"en":"The news constantly presents new events from around the world.","zh":"新聞不斷呈現世界各地的新事件。"},{"en":"Television constantly presents different opinions, so viewers must judge carefully.","zh":"電視不斷呈現不同意見，所以觀眾必須謹慎判斷。"},{"en":"When a medium constantly presents information, critical thinking becomes necessary.","zh":"當一種媒體不斷呈現資訊時，批判性思維就變得必要。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"voices that clash","meaning":"互相衝突的聲音","examples":[{"en":"Television presents voices that clash.","zh":"電視呈現互相衝突的聲音。"},{"en":"Voices that clash are opinions or arguments that disagree strongly with each other.","zh":"互相衝突的聲音是彼此強烈不同意的意見或論點。"},{"en":"In a debate programme, voices that clash help viewers compare reasons.","zh":"在辯論節目中，互相衝突的聲音幫助觀眾比較理由。"},{"en":"Clashing voices can be confusing, but they also train judgement.","zh":"衝突的聲音可能令人困惑，但也能訓練判斷力。"},{"en":"Good viewers listen to voices that clash before forming their own view.","zh":"優秀觀眾會先聆聽互相衝突的聲音，再形成自己的看法。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"defend a policy","meaning":"為政策辯護","examples":[{"en":"A politician may appear on television defending a policy.","zh":"政治人物可能在電視上為政策辯護。"},{"en":"To defend a policy means to explain why a rule or plan is right or necessary.","zh":"為政策辯護意思是解釋為何某項規則或計劃正確或必要。"},{"en":"A government officer may defend a transport policy during an interview.","zh":"政府官員可能在訪問中為交通政策辯護。"},{"en":"Defending a policy requires evidence, not only confidence.","zh":"為政策辯護需要證據，而不只是信心。"},{"en":"Viewers should ask whether the defence answers real concerns.","zh":"觀眾應詢問這種辯護是否回應了真正關注。"}],"source":"2017 Q6.pdf","sourcePage":8},{"front":"oppose a policy","meaning":"反對政策","examples":[{"en":"A resident may appear on television opposing a policy.","zh":"居民可能在電視上反對政策。"},{"en":"To oppose a policy means to disagree with a rule or plan and argue against it.","zh":"反對政策意思是不同意某項規則或計劃，並提出反對理由。"},{"en":"Residents may oppose a housing policy if it increases rent pressure.","zh":"如果住屋政策增加租金壓力，居民可能會反對它。"},{"en":"Opposing a policy can be responsible when people give reasons and evidence.","zh":"當人們給出理由和證據時，反對政策可以是負責任的行為。"},{"en":"Television lets viewers hear why different groups oppose a policy.","zh":"電視讓觀眾聽到不同群體為何反對政策。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"explain the evidence","meaning":"解釋證據","examples":[{"en":"An expert may explain the evidence in an interview.","zh":"專家可能在訪問中解釋證據。"},{"en":"To explain the evidence means to show what facts support a claim and how they matter.","zh":"解釋證據意思是說明哪些事實支持某個說法，以及它們為何重要。"},{"en":"A doctor may explain the evidence behind a health warning.","zh":"醫生可能解釋健康警告背後的證據。"},{"en":"Evidence becomes useful only when people understand what it shows.","zh":"只有當人們明白證據顯示甚麼時，證據才有用。"},{"en":"Television interviews can help viewers follow evidence more clearly.","zh":"電視訪問可以幫助觀眾更清楚跟隨證據。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"challenge weak claims","meaning":"質疑薄弱的說法","examples":[{"en":"A presenter may challenge weak claims.","zh":"主持人可能會質疑薄弱的說法。"},{"en":"To challenge weak claims means to question statements that lack evidence or logic.","zh":"質疑薄弱的說法意思是追問缺乏證據或邏輯的陳述。"},{"en":"A journalist challenges weak claims by asking, “What proof do you have?”","zh":"記者問「你有甚麼證明？」就是在質疑薄弱的說法。"},{"en":"Weak claims should be challenged before they mislead the public.","zh":"薄弱的說法應在誤導公眾前受到質疑。"},{"en":"Watching weak claims being challenged can train viewers to think critically.","zh":"觀看薄弱說法被質疑，可以訓練觀眾批判思考。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"debate programme","meaning":"辯論節目","examples":[{"en":"A debate programme can train viewers to examine arguments.","zh":"辯論節目可以訓練觀眾檢視論點。"},{"en":"A debate programme is a television show where people discuss opposing views.","zh":"辯論節目是人們討論相反觀點的電視節目。"},{"en":"A debate programme may include politicians, experts, residents, and students.","zh":"辯論節目可能包括政治人物、專家、居民和學生。"},{"en":"Viewers learn from debate programmes by comparing logic and evidence.","zh":"觀眾透過比較邏輯和證據，從辯論節目中學習。"},{"en":"A good debate programme teaches disagreement without personal attack.","zh":"優質辯論節目教人不同意而不作人身攻擊。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"serious interview","meaning":"嚴肅訪問","examples":[{"en":"A serious interview can teach viewers to question evidence.","zh":"嚴肅訪問可以教觀眾質疑證據。"},{"en":"A serious interview is a careful conversation about important issues.","zh":"嚴肅訪問是關於重要議題的仔細對話。"},{"en":"A serious interview with a scientist may explain climate data clearly.","zh":"與科學家的嚴肅訪問可能清楚解釋氣候數據。"},{"en":"Such interviews teach viewers how experts support their claims.","zh":"這類訪問教觀眾專家如何支持自己的說法。"},{"en":"A serious interview is different from light entertainment because it demands attention.","zh":"嚴肅訪問不同於輕鬆娛樂，因為它要求注意力。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"learn to ask","meaning":"學會提問","examples":[{"en":"When we watch a debate programme, we learn to ask better questions.","zh":"當我們觀看辯論節目時，我們學會提出更好的問題。"},{"en":"To learn to ask means to develop the habit of raising useful questions.","zh":"學會提問意思是培養提出有用問題的習慣。"},{"en":"Students learn to ask whether a speaker has evidence.","zh":"學生學會提問，詢問演講者是否有證據。"},{"en":"Television helps viewers learn to ask when it presents conflicting views.","zh":"當電視呈現互相衝突的觀點時，它幫助觀眾學會提問。"},{"en":"Learning to ask is the beginning of critical thinking.","zh":"學會提問是批判性思維的開始。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"logical","meaning":"合乎邏輯的","examples":[{"en":"We should ask whether an argument is logical.","zh":"我們應該問某個論點是否合乎邏輯。"},{"en":"Logical means clear, reasonable, and following good reasoning.","zh":"合乎邏輯的意思是清晰、合理，並遵循良好推理。"},{"en":"A logical argument connects evidence with conclusion.","zh":"合乎邏輯的論點會把證據和結論連接起來。"},{"en":"An argument is not logical if the conclusion does not follow from the facts.","zh":"如果結論不能由事實推導出來，論點就不合乎邏輯。"},{"en":"Television debates can train viewers to notice whether claims are logical.","zh":"電視辯論可以訓練觀眾注意說法是否合乎邏輯。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"strong evidence","meaning":"有力證據","examples":[{"en":"We should ask whether the evidence is strong.","zh":"我們應該問證據是否有力。"},{"en":"Strong evidence is information that clearly supports a claim.","zh":"有力證據是清楚支持某個說法的資訊。"},{"en":"Statistics from reliable research can be strong evidence in a debate.","zh":"來自可靠研究的統計可以成為辯論中的有力證據。"},{"en":"Strong evidence matters because confident speech alone can mislead people.","zh":"有力證據很重要，因為單靠自信演說可以誤導人。"},{"en":"Viewers become smarter when they look for strong evidence behind claims.","zh":"當觀眾尋找說法背後的有力證據時，他們會變得更聰明。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"be left out","meaning":"被遺漏","examples":[{"en":"Viewers should ask whether something important has been left out.","zh":"觀眾應該問是否有重要東西被遺漏。"},{"en":"To be left out means to be omitted or not included.","zh":"被遺漏意思是被省略或沒有被包括。"},{"en":"A news report may be unfair if key facts are left out.","zh":"如果關鍵事實被遺漏，新聞報道可能不公平。"},{"en":"Viewers should ask what voices or evidence have been left out.","zh":"觀眾應該問哪些聲音或證據被遺漏了。"},{"en":"Critical thinking includes noticing what is present and what is left out.","zh":"批判性思維包括注意到有甚麼出現，也注意到有甚麼被遺漏。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"precisely the habit","meaning":"正正是這種習慣","examples":[{"en":"This is precisely the habit that schools try to cultivate.","zh":"這正正是學校嘗試培養的習慣。"},{"en":"Precisely the habit means exactly the kind of behaviour or thinking being discussed.","zh":"正正是這種習慣，意思是剛才所討論的那種行為或思考方式。"},{"en":"Asking for evidence is precisely the habit good teachers encourage.","zh":"要求證據正正是好老師鼓勵的習慣。"},{"en":"The phrase stresses that television can support an educational goal.","zh":"這個短語強調電視可以支持教育目標。"},{"en":"When students question claims, they practise precisely the habit needed for learning.","zh":"當學生質疑說法時，他們就在練習學習所需的這種習慣。"}],"source":"2017 Q6.pdf","sourcePage":9},{"front":"cultivate","meaning":"培養","examples":[{"en":"Schools try to cultivate critical thinking.","zh":"學校嘗試培養批判性思維。"},{"en":"To cultivate something means to develop it carefully over time.","zh":"培養某事意思是隨時間仔細發展它。"},{"en":"Teachers cultivate curiosity by welcoming student questions.","zh":"老師透過歡迎學生提問來培養好奇心。"},{"en":"Critical thinking is cultivated through practice, discussion, and feedback.","zh":"批判性思維透過練習、討論和回饋培養出來。"},{"en":"Good television can help cultivate judgement if students watch actively.","zh":"如果學生主動觀看，優質電視可以幫助培養判斷力。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"even drama","meaning":"甚至劇集","examples":[{"en":"Even drama can help students think more carefully.","zh":"甚至劇集也可以幫助學生更仔細思考。"},{"en":"Even drama means drama too, although people may not expect it to be educational.","zh":"甚至劇集意思是劇集也可以，雖然人們未必預期它有教育作用。"},{"en":"Even drama can teach viewers about motives, mistakes, and moral choices.","zh":"甚至劇集也能教觀眾認識動機、錯誤和道德選擇。"},{"en":"This phrase challenges the belief that only documentaries can educate.","zh":"這個短語挑戰只有紀錄片才能教育人的想法。"},{"en":"Even drama becomes useful when viewers reflect on characters and consequences.","zh":"當觀眾反思角色和後果時，甚至劇集也會變得有用。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"legal series","meaning":"法律劇","examples":[{"en":"In a legal series, the truth may be more complicated than it first seems.","zh":"在法律劇中，真相可能比一開始看起來更複雜。"},{"en":"A legal series is a drama or programme about lawyers, courts, crimes, or justice.","zh":"法律劇是關於律師、法庭、罪案或公義的劇集或節目。"},{"en":"A legal series may show how evidence changes people’s first impressions.","zh":"法律劇可能展示證據如何改變人的第一印象。"},{"en":"Students can learn from legal series by watching how arguments are tested.","zh":"學生可以透過觀看論點如何被檢驗，從法律劇中學習。"},{"en":"A good legal series teaches viewers not to judge before hearing all sides.","zh":"優質法律劇教觀眾在聽完各方前不要下判斷。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"sympathise with","meaning":"同情；認同","examples":[{"en":"We may first sympathise with one character.","zh":"我們一開始可能同情或認同某個角色。"},{"en":"To sympathise with someone means to understand or feel sorry for their pain or situation.","zh":"同情某人意思是理解或為他的痛苦或處境感到難過。"},{"en":"Viewers may sympathise with a student who is unfairly blamed.","zh":"觀眾可能同情一位被不公平責怪的學生。"},{"en":"Drama encourages sympathy by showing private struggles behind public actions.","zh":"劇集透過展示公開行動背後的私人掙扎來激發同情。"},{"en":"We should sympathise with characters while still judging their choices carefully.","zh":"我們可以同情角色，同時仍仔細判斷他們的選擇。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"only to discover later that","meaning":"結果後來才發現","examples":[{"en":"We may sympathise with one character, only to discover later that the truth is more complicated.","zh":"我們可能同情某個角色，結果後來才發現真相比想像中更複雜。"},{"en":"Only to discover later that means a later event changes what we first believed.","zh":"結果後來才發現，意思是之後的事件改變了我們最初相信的東西。"},{"en":"Viewers may trust a witness, only to discover later that important facts were hidden.","zh":"觀眾可能相信一位證人，結果後來才發現重要事實被隱藏了。"},{"en":"This phrase is useful for describing a surprise or twist.","zh":"這個短語適合描述驚喜或反轉。"},{"en":"It teaches viewers that first impressions can be incomplete.","zh":"它教觀眾第一印象可能並不完整。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"more complicated","meaning":"更複雜","examples":[{"en":"The truth is often more complicated than it first appears.","zh":"真相往往比一開始看來更複雜。"},{"en":"More complicated means involving more details, causes, or sides than expected.","zh":"更複雜意思是涉及比預期更多細節、原因或角度。"},{"en":"A family argument may be more complicated when each person has a different memory.","zh":"當每個人都有不同記憶時，家庭爭執可能更複雜。"},{"en":"Drama shows that people’s motives are often more complicated than good or bad.","zh":"劇集顯示人的動機常比好或壞更複雜。"},{"en":"Recognising complexity helps viewers judge more slowly and fairly.","zh":"承認複雜性幫助觀眾更慢、更公平地下判斷。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"that twist","meaning":"那個反轉情節","examples":[{"en":"That twist teaches us not to judge too quickly.","zh":"那個反轉情節教我們不要太快下判斷。"},{"en":"That twist means the surprising change in a story that changes our understanding.","zh":"那個反轉情節是故事中令人驚訝、並改變我們理解的轉變。"},{"en":"A drama twist may reveal that the quiet character was protecting someone.","zh":"劇集反轉可能揭示安靜的角色其實在保護某人。"},{"en":"Twists train viewers to reconsider earlier clues.","zh":"反轉情節訓練觀眾重新思考早前的線索。"},{"en":"That twist matters because it changes judgement into reflection.","zh":"那個反轉情節很重要，因為它把判斷變成反思。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"judge too quickly","meaning":"太快下判斷","examples":[{"en":"Drama can teach us not to judge too quickly.","zh":"劇集可以教我們不要太快下判斷。"},{"en":"To judge too quickly means to decide what is true or right before knowing enough.","zh":"太快下判斷意思是在知道足夠資訊前就決定甚麼是真或對。"},{"en":"Students may judge too quickly if they believe a rumour before asking questions.","zh":"如果學生未提問就相信謠言，他們可能太快下判斷。"},{"en":"Television dramas show the danger of judging too quickly through mistaken blame.","zh":"電視劇透過錯誤責怪展示太快下判斷的危險。"},{"en":"Good viewers pause before they judge too quickly.","zh":"好觀眾在太快下判斷前會停一停。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"not so much…as…","meaning":"與其說是……不如說是……","examples":[{"en":"Television is not so much a replacement for thinking as a training ground for thinking.","zh":"電視與其說是思考的替代品，不如說是思考的訓練場。"},{"en":"Not so much A as B means B is a better description than A.","zh":"與其說是 A 不如說是 B，意思是 B 比 A 更能準確描述某事。"},{"en":"A good debate is not so much a fight as a test of ideas.","zh":"優質辯論與其說是爭吵，不如說是思想的測試。"},{"en":"This structure helps correct a mistaken label.","zh":"這個結構幫助糾正錯誤標籤。"},{"en":"The speaker uses it to show television can support thinking rather than replace it.","zh":"演講者用它來顯示電視可以支持思考，而不是取代思考。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"a replacement for thinking","meaning":"思考的替代品","examples":[{"en":"Television should not be a replacement for thinking.","zh":"電視不應是思考的替代品。"},{"en":"A replacement for thinking is something people use instead of thinking for themselves.","zh":"思考的替代品是人們用來代替自己思考的東西。"},{"en":"Copying an online answer is a replacement for thinking if students do not understand it.","zh":"如果學生不理解就抄網上答案，這就是思考的替代品。"},{"en":"Television becomes a replacement for thinking only when viewers accept everything blindly.","zh":"只有當觀眾盲目接受一切時，電視才會成為思考的替代品。"},{"en":"Good television should invite thought, not replace it.","zh":"優質電視應邀請思考，而不是取代思考。"}],"source":"2017 Q6.pdf","sourcePage":10},{"front":"a training ground for thinking","meaning":"思考的訓練場","examples":[{"en":"Television can be a training ground for thinking.","zh":"電視可以成為思考的訓練場。"},{"en":"A training ground for thinking is a place or situation where people practise judgement and reflection.","zh":"思考的訓練場是人們練習判斷和反思的地方或情況。"},{"en":"Debate programmes are a training ground for thinking because viewers compare claims.","zh":"辯論節目是思考的訓練場，因為觀眾會比較說法。"},{"en":"Dramas can become a training ground for thinking when they challenge first impressions.","zh":"當劇集挑戰第一印象時，它們可以成為思考的訓練場。"},{"en":"Television becomes a training ground when viewers ask questions while watching.","zh":"當觀眾一邊觀看一邊提問，電視就成為思考的訓練場。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"the more carefully…, the more intelligently…","meaning":"越仔細……就越有智慧地……","examples":[{"en":"The more carefully we watch, the more intelligently we question.","zh":"我們越仔細觀看，就越有智慧地質疑。"},{"en":"This structure shows that one improvement leads to another improvement.","zh":"這個結構顯示一種改善會帶來另一種改善。"},{"en":"The more carefully students read, the more intelligently they answer.","zh":"學生越仔細閱讀，就越有智慧地回答。"},{"en":"Careful viewing helps people notice weak evidence and hidden bias.","zh":"仔細觀看幫助人注意薄弱證據和隱藏偏見。"},{"en":"This pattern is useful for showing how active watching improves thinking.","zh":"這個句式適合顯示主動觀看如何改善思考。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"question intelligently","meaning":"有智慧地質疑","examples":[{"en":"Careful viewers learn to question intelligently.","zh":"細心的觀眾會學會有智慧地質疑。"},{"en":"To question intelligently means to ask thoughtful, relevant, and evidence-based questions.","zh":"有智慧地質疑意思是提出有思考、相關和以證據為本的問題。"},{"en":"A viewer questions intelligently when they ask who benefits from a claim.","zh":"當觀眾問某個說法令誰受益時，就是有智慧地質疑。"},{"en":"Intelligent questioning helps people avoid being misled.","zh":"有智慧的質疑幫助人避免被誤導。"},{"en":"Television can train viewers to question intelligently if they compare different voices.","zh":"如果觀眾比較不同聲音，電視可以訓練他們有智慧地質疑。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"strengthen language","meaning":"強化語言能力","examples":[{"en":"Television can strengthen language, empathy, and cultural understanding.","zh":"電視可以強化語言能力、同理心和文化理解。"},{"en":"To strengthen language means to improve vocabulary, listening, pronunciation, and expression.","zh":"強化語言能力意思是提升詞彙、聆聽、發音和表達。"},{"en":"Watching English news can strengthen language by showing formal speech.","zh":"觀看英文新聞可以透過展示正式說話來強化語言能力。"},{"en":"Dramas strengthen language when students hear idioms in natural situations.","zh":"當學生在自然情境中聽到慣用語時，劇集可以強化語言能力。"},{"en":"Television strengthens language best when learners listen actively and review useful phrases.","zh":"當學習者主動聆聽並重溫有用短語時，電視最能強化語言能力。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"empathy","meaning":"同理心","examples":[{"en":"Good television can strengthen empathy.","zh":"優質電視節目可以強化同理心。"},{"en":"Empathy is the ability to understand and care about another person’s feelings.","zh":"同理心是理解和關心他人感受的能力。"},{"en":"A drama about a refugee family can help viewers develop empathy.","zh":"關於難民家庭的劇集可以幫助觀眾培養同理心。"},{"en":"Empathy grows when people see life from another person’s point of view.","zh":"當人們從另一個人的角度看生活時，同理心會成長。"},{"en":"Television strengthens empathy by showing faces, voices, and personal stories.","zh":"電視透過展示面孔、聲音和個人故事來強化同理心。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"cultural understanding","meaning":"文化理解","examples":[{"en":"Television can deepen cultural understanding.","zh":"電視可以加深文化理解。"},{"en":"Cultural understanding means knowing how different groups live, speak, believe, and behave.","zh":"文化理解是指了解不同群體如何生活、說話、相信和行動。"},{"en":"Travel programmes can deepen cultural understanding by showing festivals and family life.","zh":"旅遊節目透過展示節日和家庭生活，可以加深文化理解。"},{"en":"Cultural understanding reduces quick judgement and prejudice.","zh":"文化理解可以減少倉促判斷和偏見。"},{"en":"Television builds cultural understanding when it presents people respectfully.","zh":"當電視尊重地呈現人物時，它能建立文化理解。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"well-produced TV programmes","meaning":"製作優良的電視節目","examples":[{"en":"Well-produced TV programmes offer rhythm, pronunciation, and idioms.","zh":"製作優良的電視節目提供語調節奏、發音和慣用語。"},{"en":"Well-produced TV programmes are shows made carefully with good writing, sound, visuals, and structure.","zh":"製作優良的電視節目是以良好寫作、聲音、影像和結構仔細製作的節目。"},{"en":"A well-produced documentary explains difficult ideas in a clear and engaging way.","zh":"製作優良的紀錄片會以清楚而吸引人的方式解釋困難想法。"},{"en":"Students learn more from well-produced programmes because the message is organised.","zh":"學生從製作優良的節目中學到更多，因為訊息有組織。"},{"en":"Poorly made programmes may confuse viewers, but well-produced TV programmes can educate them.","zh":"製作差的節目可能令人困惑，但製作優良的電視節目可以教育人。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"offer rhythm and pronunciation","meaning":"提供語調節奏和發音","examples":[{"en":"TV programmes can offer rhythm and pronunciation that textbooks cannot reproduce.","zh":"電視節目可以提供課本難以重現的語調節奏和發音。"},{"en":"To offer rhythm and pronunciation means to provide examples of natural sound, stress, and speech patterns.","zh":"提供語調節奏和發音意思是提供自然聲音、重音和說話模式的例子。"},{"en":"English news offers rhythm and pronunciation through clear spoken sentences.","zh":"英文新聞透過清楚說出的句子提供語調節奏和發音。"},{"en":"Listening to real speech helps learners hear how language moves.","zh":"聆聽真實說話幫助學習者聽到語言如何流動。"},{"en":"Television offers rhythm and pronunciation in a way printed words cannot fully show.","zh":"電視以印刷文字無法完全展示的方式提供語調節奏和發音。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"idioms","meaning":"慣用語","examples":[{"en":"Television helps students hear idioms in context.","zh":"電視幫助學生在語境中聽到慣用語。"},{"en":"Idioms are expressions whose meanings are not always clear from the individual words.","zh":"慣用語是不能總是從個別字詞看出意思的表達。"},{"en":"“Break the ice” is an idiom meaning to make people feel more comfortable.","zh":"“Break the ice” 是慣用語，意思是令大家感到較自在。"},{"en":"Students understand idioms better when they hear who says them and why.","zh":"當學生聽到誰在甚麼原因下說慣用語時，他們會更理解。"},{"en":"Television shows idioms with tone, situation, and body language.","zh":"電視用語氣、情境和身體語言展示慣用語。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"natural interaction","meaning":"自然互動","examples":[{"en":"Television can show natural interaction between speakers.","zh":"電視可以展示說話者之間的自然互動。"},{"en":"Natural interaction means real or realistic communication between people.","zh":"自然互動是指人與人之間真實或接近真實的溝通。"},{"en":"A drama shows natural interaction when characters interrupt, pause, and react emotionally.","zh":"當角色打斷、停頓和有情緒反應時，劇集展示了自然互動。"},{"en":"Natural interaction helps language learners understand how conversation works.","zh":"自然互動幫助語言學習者理解對話如何運作。"},{"en":"Textbooks can teach grammar, but television can show natural interaction.","zh":"課本可以教文法，但電視可以展示自然互動。"}],"source":"2017 Q6.pdf","sourcePage":11},{"front":"vocabulary list","meaning":"生字表","examples":[{"en":"A vocabulary list can hardly reproduce natural interaction.","zh":"生字表難以重現自然互動。"},{"en":"A vocabulary list is a set of words or phrases for learners to study.","zh":"生字表是一組供學習者學習的字詞或短語。"},{"en":"A vocabulary list may explain meanings, but it cannot fully show tone and timing.","zh":"生字表可能解釋意思，但不能完全展示語氣和時機。"},{"en":"Students need examples because words in a vocabulary list can feel lifeless.","zh":"學生需要例子，因為生字表中的詞語可能感覺沒有生命。"},{"en":"Television can bring a vocabulary list to life through real speech.","zh":"電視可以透過真實說話令生字表活起來。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"can hardly reproduce","meaning":"難以重現","examples":[{"en":"A vocabulary list can hardly reproduce natural spoken English.","zh":"生字表難以重現自然英語口語。"},{"en":"Can hardly reproduce means can almost not copy or recreate something well.","zh":"難以重現意思是幾乎不能很好地複製或再現某事。"},{"en":"A written script can hardly reproduce the emotion of a real apology.","zh":"書面稿難以重現真正道歉中的情感。"},{"en":"A worksheet can hardly reproduce the speed and rhythm of live debate.","zh":"工作紙難以重現現場辯論的速度和節奏。"},{"en":"Television helps because printed materials can hardly reproduce natural speech fully.","zh":"電視有幫助，因為印刷材料難以完全重現自然說話。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"English documentary","meaning":"英文紀錄片","examples":[{"en":"A student who watches an English documentary hears how ideas are organised.","zh":"觀看英文紀錄片的學生會聽到思想如何組織。"},{"en":"An English documentary is a factual programme presented in English.","zh":"英文紀錄片是以英語呈現的事實性節目。"},{"en":"An English documentary about oceans may teach both science and language.","zh":"關於海洋的英文紀錄片可能同時教授科學和語言。"},{"en":"Students hear formal vocabulary and clear explanations in English documentaries.","zh":"學生在英文紀錄片中聽到正式詞彙和清晰解釋。"},{"en":"Watching English documentaries can improve listening, vocabulary, and knowledge together.","zh":"觀看英文紀錄片可以同時提升聆聽、詞彙和知識。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"how ideas are organised","meaning":"思想如何組織","examples":[{"en":"An English documentary shows how ideas are organised.","zh":"英文紀錄片展示思想如何組織。"},{"en":"How ideas are organised means the way information is arranged and connected.","zh":"思想如何組織，是指資訊如何被安排和連接。"},{"en":"A good speaker shows how ideas are organised by using clear topic sentences.","zh":"好演講者透過使用清晰主題句來展示思想如何組織。"},{"en":"Students learn writing when they hear how ideas move from cause to effect.","zh":"當學生聽到思想如何從原因走向結果時，他們會學到寫作。"},{"en":"Television can show how ideas are organised through narration and images.","zh":"電視可以透過旁白和影像展示思想如何組織。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"follow a drama","meaning":"追看劇集","examples":[{"en":"A student who follows a drama notices changes in tone.","zh":"追看劇集的學生會注意到語氣變化。"},{"en":"To follow a drama means to watch a drama regularly and understand its story.","zh":"追看劇集意思是定期觀看劇集並理解其故事。"},{"en":"Students who follow a drama may remember characters, conflicts, and language patterns.","zh":"追看劇集的學生可能記得角色、衝突和語言模式。"},{"en":"Following a drama helps learners notice how meaning changes across episodes.","zh":"追看劇集幫助學習者注意意思如何在不同集數中變化。"},{"en":"A drama is most useful when viewers follow it actively, not only emotionally.","zh":"當觀眾主動追看，而不只是情緒投入時，劇集最有用。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"tone changes with","meaning":"語氣隨……而轉變","examples":[{"en":"A drama shows how tone changes with anger, fear, or embarrassment.","zh":"劇集展示語氣如何隨憤怒、恐懼或尷尬而轉變。"},{"en":"Tone changes with something means a speaker’s voice or manner changes because of that feeling or situation.","zh":"語氣隨某事而轉變，意思是說話者的聲音或方式因該感受或情況而改變。"},{"en":"A student’s tone changes with nervousness during a presentation.","zh":"學生演講時，語氣可能隨緊張而轉變。"},{"en":"Television helps learners hear how tone changes with emotion.","zh":"電視幫助學習者聽到語氣如何隨情緒而轉變。"},{"en":"Understanding tone helps viewers grasp meaning beyond words.","zh":"理解語氣幫助觀眾掌握文字以外的意思。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"embarrassment","meaning":"尷尬","examples":[{"en":"Tone may change with anger, fear, or embarrassment.","zh":"語氣可能隨憤怒、恐懼或尷尬而轉變。"},{"en":"Embarrassment is the uncomfortable feeling people have when they feel ashamed or awkward.","zh":"尷尬是人在感到羞愧或不自在時的不舒服感覺。"},{"en":"A student may feel embarrassment after giving the wrong answer loudly.","zh":"學生大聲答錯問題後可能感到尷尬。"},{"en":"In drama, embarrassment can be heard in pauses, quiet voices, or nervous laughter.","zh":"在劇集中，尷尬可以從停頓、細聲或緊張笑聲中聽到。"},{"en":"Watching embarrassment on screen helps learners understand emotional language.","zh":"在螢幕上觀看尷尬情境，幫助學習者理解情感語言。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, television lets us step into lives beyond our own.","zh":"更重要的是，電視讓我們走進遠超我們自身的人生。"},{"en":"More importantly introduces a point that the speaker considers more significant.","zh":"更重要的是，用來引出演講者認為更重要的一點。"},{"en":"Television teaches facts; more importantly, it can teach empathy.","zh":"電視教授事實；更重要的是，它可以教授同理心。"},{"en":"Writers use this phrase to guide readers toward the strongest idea.","zh":"作者使用這個短語來引導讀者走向最有力的想法。"},{"en":"More importantly, good viewing can change how we understand people.","zh":"更重要的是，優質觀看可以改變我們如何理解人。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"step into lives","meaning":"走進別人的人生","examples":[{"en":"Television lets us step into lives far beyond our own.","zh":"電視讓我們走進遠超我們自身的人生。"},{"en":"To step into lives means to imagine or experience other people’s situations through stories.","zh":"走進別人的人生意思是透過故事想像或體驗他人的處境。"},{"en":"A documentary lets viewers step into the lives of farmers facing drought.","zh":"紀錄片讓觀眾走進面對旱災的農民人生。"},{"en":"Stepping into others’ lives helps people understand pain and hope beyond their own experience.","zh":"走進別人的人生幫助人理解自身經驗以外的痛苦和希望。"},{"en":"Television can help us step into lives we may never meet directly.","zh":"電視可以幫助我們走進可能永遠不會直接遇見的人生。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"far beyond our own","meaning":"遠超我們自身的","examples":[{"en":"Television introduces us to lives far beyond our own.","zh":"電視向我們介紹遠超我們自身的人生。"},{"en":"Far beyond our own means much outside our personal experience or usual world.","zh":"遠超我們自身的，意思是大大超出個人經驗或日常世界。"},{"en":"A student may learn about life in a refugee camp far beyond their own daily routine.","zh":"學生可能了解遠超自己日常生活的難民營生活。"},{"en":"Stories far beyond our own experience can reduce narrow thinking.","zh":"遠超我們自身經驗的故事可以減少狹隘思維。"},{"en":"Television connects viewers with worlds far beyond their own neighbourhood.","zh":"電視把觀眾連接到遠超自己社區的世界。"}],"source":"2017 Q6.pdf","sourcePage":12},{"front":"refugee family","meaning":"難民家庭","examples":[{"en":"Television may introduce us to a refugee family.","zh":"電視可能向我們介紹一個難民家庭。"},{"en":"A refugee family is a family forced to leave home because of war, danger, or persecution.","zh":"難民家庭是因戰爭、危險或迫害而被迫離家的家庭。"},{"en":"A programme about a refugee family may show the difficulty of finding safety.","zh":"關於難民家庭的節目可能展示尋找安全的困難。"},{"en":"Seeing a refugee family on screen can turn statistics into human lives.","zh":"在螢幕上看見難民家庭，可以把統計變成人的生命。"},{"en":"Such stories build empathy by showing loss, courage, and hope.","zh":"這類故事透過展示失去、勇氣和希望來建立同理心。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"under pressure","meaning":"在壓力下","examples":[{"en":"We may see a doctor working under pressure.","zh":"我們可能看見一位醫生在壓力下工作。"},{"en":"Under pressure means facing stress, urgency, or heavy responsibility.","zh":"在壓力下意思是面對緊張、迫切或重大責任。"},{"en":"Students feel under pressure when several exams happen in the same week.","zh":"當一星期內有多個考試時，學生會在壓力下。"},{"en":"A doctor under pressure must make careful decisions quickly.","zh":"在壓力下的醫生必須快速而謹慎地作決定。"},{"en":"Television shows pressure through facial expressions, time limits, and difficult choices.","zh":"電視透過表情、時間限制和困難選擇展示壓力。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"recover from failure","meaning":"從失敗中恢復","examples":[{"en":"We may see an athlete recovering from failure.","zh":"我們可能看見運動員從失敗中恢復。"},{"en":"To recover from failure means to regain confidence or strength after not succeeding.","zh":"從失敗中恢復意思是在未成功後重新獲得信心或力量。"},{"en":"A student recovers from failure by learning from a low mark and trying again.","zh":"學生透過從低分中學習並再次嘗試，從失敗中恢復。"},{"en":"Sports documentaries show how athletes recover from failure through training and support.","zh":"體育紀錄片展示運動員如何透過訓練和支持從失敗中恢復。"},{"en":"Seeing recovery from failure teaches viewers resilience.","zh":"看見人從失敗中恢復，能教觀眾堅韌。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"grow up in a culture different from ours","meaning":"在與我們不同的文化中成長","examples":[{"en":"We may meet a child growing up in a culture different from ours.","zh":"我們可能遇見一個在與我們不同的文化中成長的孩子。"},{"en":"To grow up in a culture different from ours means to be raised with different customs, language, and values.","zh":"在與我們不同的文化中成長，意思是在不同習俗、語言和價值觀中長大。"},{"en":"A documentary may show a child growing up in a rural culture far from city life.","zh":"紀錄片可能展示一個孩子在遠離城市生活的鄉村文化中成長。"},{"en":"Seeing different childhoods helps students question their own assumptions.","zh":"看見不同童年幫助學生質疑自己的假設。"},{"en":"Television can make unfamiliar cultures feel human and understandable.","zh":"電視可以令陌生文化感覺有人性和容易理解。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"such stories","meaning":"這類故事","examples":[{"en":"Such stories do not merely feed us information.","zh":"這類故事不只是向我們灌輸資料。"},{"en":"Such stories means the stories just mentioned or stories of this kind.","zh":"這類故事意思是剛才提到的故事，或這種類型的故事。"},{"en":"Stories about doctors, refugees, and athletes can teach more than facts.","zh":"關於醫生、難民和運動員的故事，能教人的不只是事實。"},{"en":"Such stories help viewers understand emotions behind events.","zh":"這類故事幫助觀眾理解事件背後的情感。"},{"en":"The phrase connects earlier examples to a wider point.","zh":"這個短語把早前例子連接到更廣泛的觀點。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"not merely feed us information","meaning":"不只是向我們灌輸資料","examples":[{"en":"Good stories do not merely feed us information.","zh":"好故事不只是向我們灌輸資料。"},{"en":"Not merely feed us information means not only give facts, but also help us feel and understand.","zh":"不只是向我們灌輸資料，意思是不只提供事實，也幫助我們感受和理解。"},{"en":"A documentary about poverty does not merely feed us information if it shows real families.","zh":"如果關於貧窮的紀錄片展示真實家庭，它就不只是向我們灌輸資料。"},{"en":"Information becomes deeper when stories include human voices.","zh":"當故事包括人的聲音時，資訊會變得更深。"},{"en":"Good television teaches both facts and feeling, not merely information.","zh":"優質電視教授事實和感受，而不只是資料。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"make us better listeners","meaning":"令我們成為更好的聆聽者","examples":[{"en":"Television can make us better listeners.","zh":"電視可以令我們成為更好的聆聽者。"},{"en":"To make us better listeners means to help us understand others more patiently and carefully.","zh":"令我們成為更好的聆聽者，意思是幫助我們更耐心和仔細地理解他人。"},{"en":"Interviews with people from different backgrounds can make viewers better listeners.","zh":"與不同背景人士的訪問可以令觀眾成為更好的聆聽者。"},{"en":"Listening to real stories teaches people not to interrupt with quick judgement.","zh":"聆聽真實故事教人不要急於判斷和打斷。"},{"en":"Television makes us better listeners when it gives space to voices we rarely hear.","zh":"當電視給我們少聽見的聲音空間時，它能令我們成為更好的聆聽者。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"the ability to calculate","meaning":"計算能力","examples":[{"en":"Intelligence is not only the ability to calculate.","zh":"智力不只是計算能力。"},{"en":"The ability to calculate means the skill of working with numbers and solving mathematical problems.","zh":"計算能力是處理數字和解決數學問題的技能。"},{"en":"A student with strong ability to calculate can solve sums quickly.","zh":"計算能力強的學生可以快速解答算式。"},{"en":"Calculation is useful, but intelligence also includes judgement, language, and empathy.","zh":"計算很有用，但智力也包括判斷力、語言和同理心。"},{"en":"The sentence reminds us that being smart is broader than maths.","zh":"這句話提醒我們，聰明比數學能力更廣泛。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"the ability to understand people","meaning":"理解他人的能力","examples":[{"en":"Intelligence is also the ability to understand people.","zh":"智力也是理解他人的能力。"},{"en":"The ability to understand people means knowing their feelings, motives, and situations.","zh":"理解他人的能力是知道他人的感受、動機和處境。"},{"en":"A good leader needs the ability to understand people, not only technical skill.","zh":"好領袖需要理解他人的能力，而不只是技術能力。"},{"en":"Drama can build this ability by showing why characters act as they do.","zh":"劇集透過展示角色為何如此行動，可以建立這種能力。"},{"en":"Television makes us smarter when it improves our ability to understand people.","zh":"當電視提升我們理解他人的能力時，它令我們更聰明。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"in that sense","meaning":"從這個意義上說","examples":[{"en":"In that sense, good television educates both the mind and the heart.","zh":"從這個意義上說，優質電視同時教育頭腦和心靈。"},{"en":"In that sense means from that particular point of view.","zh":"從這個意義上說，意思是從某個特定角度理解。"},{"en":"In that sense, a drama can be educational even without being a school lesson.","zh":"從這個意義上說，劇集即使不是學校課堂，也可以有教育性。"},{"en":"Writers use this phrase to explain how a previous idea should be understood.","zh":"作者使用這個短語來解釋前一個想法應如何理解。"},{"en":"In that sense, intelligence includes both thought and empathy.","zh":"從這個意義上說，智力包括思想和同理心。"}],"source":"2017 Q6.pdf","sourcePage":13},{"front":"educate both the mind and the heart","meaning":"同時教育頭腦和心靈","examples":[{"en":"Good television educates both the mind and the heart.","zh":"優質電視同時教育頭腦和心靈。"},{"en":"To educate both the mind and the heart means to teach knowledge as well as empathy and values.","zh":"同時教育頭腦和心靈，意思是既教授知識，也教授同理心和價值。"},{"en":"A documentary about refugees educates the mind with facts and the heart with personal stories.","zh":"關於難民的紀錄片以事實教育頭腦，並以個人故事教育心靈。"},{"en":"Education is deeper when students learn to think and care.","zh":"當學生學會思考和關心時，教育會更深。"},{"en":"Good television educates both the mind and the heart by combining information with human experience.","zh":"優質電視透過結合資訊和人生經驗，同時教育頭腦和心靈。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"honourable opponents may warn us that","meaning":"對方辯友可能警告我們","examples":[{"en":"Honourable opponents may warn us that television can be addictive.","zh":"對方辯友可能警告我們電視可以令人上癮。"},{"en":"This phrase politely introduces a warning from the other side in a debate.","zh":"這個短語在辯論中有禮貌地引出對方的警告。"},{"en":"Honourable opponents may warn us that screen time harms sleep.","zh":"對方辯友可能警告我們螢幕時間會傷害睡眠。"},{"en":"Using this phrase shows respect while preparing to answer criticism.","zh":"使用這個短語顯示尊重，同時準備回應批評。"},{"en":"A strong speaker listens to opponents before explaining why the warning is incomplete.","zh":"有力的演講者會先聆聽對手，再解釋為何該警告並不完整。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"addictive","meaning":"令人上癮的","examples":[{"en":"Television can be addictive if viewers lack self-control.","zh":"如果觀眾缺乏自制力，電視可以令人上癮。"},{"en":"Addictive means difficult to stop because it strongly attracts people again and again.","zh":"令人上癮的意思是因強烈吸引人反覆使用而難以停止。"},{"en":"Online games can be addictive when players keep playing despite homework or sleep.","zh":"當玩家即使有功課或需要睡眠仍不停玩，網上遊戲就可能令人上癮。"},{"en":"Some television platforms are addictive because the next episode starts automatically.","zh":"有些電視平台令人上癮，因為下一集會自動播放。"},{"en":"Something addictive needs boundaries, not necessarily complete rejection.","zh":"令人上癮的東西需要界限，不一定要完全拒絕。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"shallow","meaning":"膚淺的","examples":[{"en":"Some television programmes are shallow.","zh":"有些電視節目是膚淺的。"},{"en":"Shallow means lacking depth, seriousness, or meaningful thought.","zh":"膚淺的意思是缺乏深度、嚴肅性或有意義思考。"},{"en":"A shallow programme may focus only on gossip and appearance.","zh":"膚淺的節目可能只集中於八卦和外表。"},{"en":"Shallow entertainment can fill time without teaching viewers much.","zh":"膚淺娛樂可以填滿時間，卻不會教觀眾很多。"},{"en":"The existence of shallow programmes does not mean all television is shallow.","zh":"有膚淺節目的存在，不代表所有電視都是膚淺的。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"misleading","meaning":"誤導人的","examples":[{"en":"Some television programmes can be misleading.","zh":"有些電視節目可能是誤導人的。"},{"en":"Misleading means giving people a wrong idea or impression.","zh":"誤導人的意思是給人錯誤想法或印象。"},{"en":"An advertisement is misleading if it makes unhealthy food look like a health product.","zh":"如果廣告令不健康食物看似健康產品，它就是誤導人的。"},{"en":"Misleading programmes are dangerous because viewers may trust false information.","zh":"誤導人的節目很危險，因為觀眾可能相信錯誤資訊。"},{"en":"Critical thinking helps viewers recognise misleading messages.","zh":"批判性思維幫助觀眾識別誤導人的訊息。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"I hear that concern","meaning":"我明白這個憂慮","examples":[{"en":"I hear that concern, but it does not defeat our case.","zh":"我明白這個憂慮，但它不能推翻我們的論點。"},{"en":"I hear that concern means I understand the worry being raised.","zh":"我明白這個憂慮意思是我理解被提出的擔心。"},{"en":"A speaker may say this to show respect before disagreeing.","zh":"演講者可能用這句話，在不同意前先表示尊重。"},{"en":"This phrase makes an argument sound calm rather than dismissive.","zh":"這個短語令論點聽起來冷靜，而不是輕視對方。"},{"en":"I hear that concern, but a concern can be answered with better habits and rules.","zh":"我明白這個憂慮，但憂慮可以透過更好習慣和規則回應。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"defeat our case","meaning":"推翻我們的論點","examples":[{"en":"That concern does not defeat our case.","zh":"那個憂慮不能推翻我們的論點。"},{"en":"To defeat our case means to prove our argument wrong or too weak.","zh":"推翻我們的論點意思是證明我們的主張錯誤或太薄弱。"},{"en":"One weak example does not defeat a case supported by strong evidence.","zh":"一個薄弱例子不能推翻由有力證據支持的論點。"},{"en":"The risk of bad television does not defeat the case for good television.","zh":"差劣電視的風險不能推翻支持優質電視的論點。"},{"en":"A case is defeated only when its main reasoning fails.","zh":"只有當主要推理失敗時，論點才會被推翻。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"unhealthy","meaning":"不健康的","examples":[{"en":"Food can be unhealthy if we eat badly.","zh":"如果我們飲食不當，食物可以是不健康的。"},{"en":"Unhealthy means harmful to physical or mental well-being.","zh":"不健康的意思是對身體或心理健康有害。"},{"en":"A diet full of sugar and fried food is unhealthy.","zh":"充滿糖和油炸食物的飲食是不健康的。"},{"en":"Television habits can be unhealthy if they replace sleep, exercise, and study.","zh":"如果電視習慣取代睡眠、運動和學習，它可以是不健康的。"},{"en":"Something useful can become unhealthy when used without balance.","zh":"有用的東西在缺乏平衡下使用，也可以變得不健康。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"eat badly","meaning":"飲食不當","examples":[{"en":"Food can be unhealthy if we eat badly.","zh":"如果我們飲食不當，食物可以是不健康的。"},{"en":"To eat badly means to choose food in a way that harms health.","zh":"飲食不當意思是以傷害健康的方式選擇食物。"},{"en":"A student eats badly if they skip meals and drink only sugary drinks.","zh":"如果學生不吃正餐，只喝含糖飲品，就是飲食不當。"},{"en":"Eating badly is not proof that food itself is the enemy.","zh":"飲食不當並不證明食物本身是敵人。"},{"en":"The problem is poor use, just as with television.","zh":"問題在於使用方式不佳，電視也是一樣。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"the enemy","meaning":"敵人","examples":[{"en":"That does not mean food is the enemy.","zh":"那並不代表食物是敵人。"},{"en":"The enemy means something treated as harmful, dangerous, or opposed to us.","zh":"敵人是指被視為有害、危險或與我們對立的東西。"},{"en":"Technology is not the enemy if students use it to learn responsibly.","zh":"如果學生負責任地用科技學習，科技就不是敵人。"},{"en":"Food becomes harmful through bad habits, but food itself is not the enemy.","zh":"食物會因壞習慣而變得有害，但食物本身不是敵人。"},{"en":"Television is not the enemy; careless viewing is the problem.","zh":"電視不是敵人；漫不經心觀看才是問題。"}],"source":"2017 Q6.pdf","sourcePage":14},{"front":"the answer is not to…, but to…","meaning":"答案不是……而是……","examples":[{"en":"The answer is not to reject television, but to choose it wisely.","zh":"答案不是拒絕電視，而是明智地選擇它。"},{"en":"This structure rejects one solution and presents a better one.","zh":"這個結構否定一個解決方法，並提出更好的方法。"},{"en":"The answer is not to ban phones, but to teach responsible use.","zh":"答案不是禁止手機，而是教授負責任使用。"},{"en":"It helps writers avoid extreme solutions.","zh":"它幫助作者避免極端解決方案。"},{"en":"For television, the answer is better choice, not total rejection.","zh":"對電視而言，答案是更好選擇，而不是完全拒絕。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"reject television","meaning":"拒絕電視","examples":[{"en":"The answer is not to reject television completely.","zh":"答案不是完全拒絕電視。"},{"en":"To reject television means to refuse to watch or accept it.","zh":"拒絕電視意思是拒絕觀看或接受電視。"},{"en":"Some parents reject television because they fear addiction.","zh":"有些父母因害怕上癮而拒絕電視。"},{"en":"Rejecting television completely may also remove documentaries, news, and educational programmes.","zh":"完全拒絕電視也可能移除紀錄片、新聞和教育節目。"},{"en":"It is wiser to reject bad habits than to reject television itself.","zh":"拒絕壞習慣比拒絕電視本身更明智。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"choose it wisely","meaning":"明智地選擇","examples":[{"en":"Students should choose television programmes wisely.","zh":"學生應明智地選擇電視節目。"},{"en":"To choose it wisely means to select carefully and sensibly.","zh":"明智地選擇意思是仔細而理性地挑選。"},{"en":"A student chooses television wisely by watching a science documentary before entertainment.","zh":"學生先看科學紀錄片再看娛樂節目，就是明智地選擇電視。"},{"en":"Wise choice includes checking quality, purpose, and time spent.","zh":"明智選擇包括查看質素、目的和花費時間。"},{"en":"Television helps learning when students choose it wisely.","zh":"當學生明智地選擇電視時，它能幫助學習。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"discuss it actively","meaning":"主動討論","examples":[{"en":"Students should discuss television actively.","zh":"學生應主動討論電視內容。"},{"en":"To discuss it actively means to talk about it with questions, opinions, and evidence.","zh":"主動討論意思是帶著問題、意見和證據談論它。"},{"en":"A class discusses a programme actively when students compare what they learned.","zh":"當學生比較自己學到甚麼時，全班就是在主動討論節目。"},{"en":"Active discussion stops television from becoming passive entertainment.","zh":"主動討論防止電視變成被動娛樂。"},{"en":"Students understand more when they discuss it actively after watching.","zh":"學生在觀看後主動討論，會理解得更多。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"watch it with purpose","meaning":"有目的地觀看","examples":[{"en":"Students should watch television with purpose.","zh":"學生應有目的地觀看電視。"},{"en":"To watch it with purpose means to view it for a clear reason, such as learning, discussion, or relaxation within limits.","zh":"有目的地觀看意思是為清晰原因觀看，例如學習、討論，或有節制地放鬆。"},{"en":"A student watches with purpose when they choose a documentary for a geography project.","zh":"學生為地理項目選擇紀錄片時，就是有目的地觀看。"},{"en":"Purposeful watching helps viewers avoid endless channel-surfing.","zh":"有目的地觀看幫助觀眾避免無止境轉台。"},{"en":"Television becomes more valuable when people watch it with purpose.","zh":"當人們有目的地觀看時，電視會更有價值。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"recommend quality programmes","meaning":"推薦優質節目","examples":[{"en":"Schools can recommend quality programmes.","zh":"學校可以推薦優質節目。"},{"en":"To recommend quality programmes means to suggest television shows that are useful, accurate, or well made.","zh":"推薦優質節目意思是建議有用、準確或製作良好的電視節目。"},{"en":"A teacher may recommend a history series before a lesson on ancient Egypt.","zh":"老師可能在教授古埃及前推薦一套歷史系列節目。"},{"en":"Recommendations help students choose better content from many options.","zh":"推薦能幫助學生從眾多選項中選擇更好內容。"},{"en":"Schools can guide viewing by recommending quality programmes instead of banning all television.","zh":"學校可以透過推薦優質節目來引導觀看，而不是禁止所有電視。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"learn to question what they see","meaning":"學會質疑自己所看到的內容","examples":[{"en":"Students must learn to question what they see.","zh":"學生必須學會質疑自己所看到的內容。"},{"en":"To learn to question what they see means to examine images and messages instead of accepting them immediately.","zh":"學會質疑自己所看到的內容，意思是檢視影像和訊息，而不是立即接受。"},{"en":"Students should ask who made the programme and what evidence it uses.","zh":"學生應詢問節目由誰製作，以及使用了甚麼證據。"},{"en":"Questioning what they see protects students from misleading information.","zh":"質疑自己所看到的內容能保護學生免受誤導資訊影響。"},{"en":"Television becomes educational when viewers learn to question what they see.","zh":"當觀眾學會質疑自己所看到的內容時，電視就變得有教育性。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"not because…, but because…","meaning":"不是因為……而是因為……","examples":[{"en":"Watching TV makes us smarter not because every programme is brilliant, but because the best television teaches us to think.","zh":"看電視令我們更聰明，不是因為每個節目都出色，而是因為最優質的電視節目教我們思考。"},{"en":"This structure contrasts a false reason with the real reason.","zh":"這個結構把錯誤原因和真正原因作對比。"},{"en":"Students improve not because learning is easy, but because they practise carefully.","zh":"學生進步不是因為學習容易，而是因為他們仔細練習。"},{"en":"Television helps not because all content is good, but because selected programmes can train thought.","zh":"電視有幫助不是因為所有內容都好，而是因為經選擇的節目能訓練思考。"},{"en":"This pattern makes the speaker’s reasoning clearer and more persuasive.","zh":"這個句式令演講者的推理更清晰和更有說服力。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"every programme is brilliant","meaning":"每個節目都出色","examples":[{"en":"Not every television programme is brilliant.","zh":"並非每個電視節目都出色。"},{"en":"Every programme is brilliant would mean all programmes are excellent, which is unrealistic.","zh":"每個節目都出色，意思是所有節目都非常好，但這並不現實。"},{"en":"Some programmes are shallow, while others are thoughtful and educational.","zh":"有些節目膚淺，另一些則有思想和教育性。"},{"en":"Admitting that not every programme is brilliant makes the argument more honest.","zh":"承認並非每個節目都出色，令論點更誠實。"},{"en":"The speaker supports good television, not the claim that every programme is brilliant.","zh":"演講者支持優質電視，而不是主張每個節目都出色。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"the best television","meaning":"最優質的電視節目","examples":[{"en":"The best television turns information into images.","zh":"最優質的電視節目把資料轉化為影像。"},{"en":"The best television means high-quality programmes that educate, challenge, or move viewers.","zh":"最優質的電視節目是能教育、挑戰或感動觀眾的高質素節目。"},{"en":"The best television can explain science through real footage and clear narration.","zh":"最優質的電視節目可以透過真實片段和清晰旁白解釋科學。"},{"en":"It does not only entertain; it helps viewers think and feel more deeply.","zh":"它不只是娛樂；它幫助觀眾更深入地思考和感受。"},{"en":"The best television is chosen carefully, not watched by accident.","zh":"最優質的電視節目是被仔細選擇的，而不是偶然觀看的。"}],"source":"2017 Q6.pdf","sourcePage":15},{"front":"turn information into images","meaning":"把資料轉化為影像","examples":[{"en":"The best television turns information into images.","zh":"最優質的電視節目把資料轉化為影像。"},{"en":"To turn information into images means to make facts visible through pictures, video, and scenes.","zh":"把資料轉化為影像，意思是透過圖片、影片和場景令事實變得可見。"},{"en":"A climate programme turns information into images by showing melting ice.","zh":"氣候節目透過展示融化的冰，把資料轉化為影像。"},{"en":"Images help viewers remember information because they can see what it means.","zh":"影像幫助觀眾記住資料，因為他們能看見其意思。"},{"en":"Television is powerful when it turns difficult information into clear images.","zh":"當電視把困難資料轉化為清晰影像時，它就很有力量。"}],"source":"2017 Q6.pdf","sourcePage":16},{"front":"turn arguments into questions","meaning":"把論點轉化為問題","examples":[{"en":"The best television turns arguments into questions.","zh":"最優質的電視節目把論點轉化為問題。"},{"en":"To turn arguments into questions means to make viewers examine claims instead of accepting them.","zh":"把論點轉化為問題，意思是令觀眾檢視說法，而不是直接接受。"},{"en":"A debate programme turns arguments into questions when viewers ask who has stronger evidence.","zh":"當觀眾問誰的證據更有力時，辯論節目就把論點轉化為問題。"},{"en":"This process trains critical thinking because viewers must judge reasons.","zh":"這個過程訓練批判性思維，因為觀眾必須判斷理由。"},{"en":"Good television turns arguments into questions rather than slogans.","zh":"優質電視把論點轉化為問題，而不是口號。"}],"source":"2017 Q6.pdf","sourcePage":16},{"front":"turn strangers into human beings","meaning":"把陌生人變成我們能理解的人","examples":[{"en":"The best television turns strangers into human beings we can understand.","zh":"最優質的電視節目把陌生人變成我們能理解的人。"},{"en":"To turn strangers into human beings means to help us see unfamiliar people as real individuals with feelings and stories.","zh":"把陌生人變成我們能理解的人，意思是幫助我們看見陌生人也是有感受和故事的真實個體。"},{"en":"A documentary about refugees can turn strangers into human beings by showing family life.","zh":"關於難民的紀錄片可以透過展示家庭生活，把陌生人變成我們能理解的人。"},{"en":"This change reduces prejudice because viewers see people, not labels.","zh":"這種轉變可以減少偏見，因為觀眾看見的是人，而不是標籤。"},{"en":"Television builds empathy when it turns strangers into human beings.","zh":"當電視把陌生人變成我們能理解的人時，它建立同理心。"}],"source":"2017 Q6.pdf","sourcePage":16},{"front":"the next time","meaning":"下一次","examples":[{"en":"The next time someone calls television an idiot box, we should question that claim.","zh":"下一次有人把電視稱為傻瓜盒時，我們應該質疑這個說法。"},{"en":"The next time means when the same situation happens again in the future.","zh":"下一次意思是同樣情況將來再次發生時。"},{"en":"The next time a friend repeats a rumour, ask for evidence before believing it.","zh":"下一次朋友重複謠言時，在相信前先要求證據。"},{"en":"This phrase prepares listeners to act differently in a future situation.","zh":"這個短語讓聽眾準備在未來情況中採取不同做法。"},{"en":"The next time we watch television, we should choose and question carefully.","zh":"下一次我們看電視時，應該仔細選擇和質疑。"}],"source":"2017 Q6.pdf","sourcePage":16},{"front":"call television an idiot box","meaning":"把電視稱為傻瓜盒","examples":[{"en":"Some people call television an idiot box.","zh":"有些人把電視稱為傻瓜盒。"},{"en":"To call television an idiot box means to describe it as something that makes viewers stupid.","zh":"把電視稱為傻瓜盒，意思是形容它令人變笨。"},{"en":"Critics call television an idiot box when they focus only on passive watching.","zh":"當批評者只集中於被動觀看時，他們會把電視稱為傻瓜盒。"},{"en":"This label is unfair if it ignores documentaries, debates, and serious interviews.","zh":"如果這個標籤忽略紀錄片、辯論和嚴肅訪問，它就是不公平的。"},{"en":"We should question people who call television an idiot box too quickly.","zh":"對於太快把電視稱為傻瓜盒的人，我們應該質疑。"}],"source":"2017 Q6.pdf","sourcePage":16},{"front":"watch without thinking","meaning":"不經思考地觀看","examples":[{"en":"Television is foolish only when we watch without thinking.","zh":"只有當我們不經思考地觀看時，電視才是愚蠢的。"},{"en":"To watch without thinking means to view passively without questions, purpose, or reflection.","zh":"不經思考地觀看意思是被動觀看，沒有問題、目的或反思。"},{"en":"A student watches without thinking when they accept every claim in a programme.","zh":"當學生接受節目中的每個說法時，就是不經思考地觀看。"},{"en":"Watching without thinking can waste time and weaken judgement.","zh":"不經思考地觀看可能浪費時間並削弱判斷力。"},{"en":"Television becomes smarter when viewers refuse to watch without thinking.","zh":"當觀眾拒絕不經思考地觀看時，電視會變得更有智慧。"}],"source":"2017 Q6.pdf","sourcePage":16},{"front":"thank you","meaning":"多謝","examples":[{"en":"The speaker ends the debate speech by saying thank you.","zh":"演講者以說多謝結束辯論演辭。"},{"en":"Thank you is a polite expression used to show gratitude or close a speech.","zh":"多謝是用來表達感謝或結束演講的禮貌用語。"},{"en":"A debater says thank you after presenting the final argument.","zh":"辯論員在提出最後論點後會說多謝。"},{"en":"Ending with thank you shows respect for the audience and adjudicators.","zh":"以多謝作結顯示對聽眾和評判的尊重。"},{"en":"In formal speaking, a simple thank you can create a clear and courteous ending.","zh":"在正式演說中，簡單一句多謝可以帶來清晰而有禮的結尾。"}],"source":"2017 Q6.pdf","sourcePage":16}],"dse/writing/part-b/2017/Q8":[{"front":"brought to mind","meaning":"令人想起","examples":[{"en":"For years, the word “athlete” has brought to mind swimmers and basketball players.","zh":"多年來，「運動員」這個詞令人想起游泳健兒和籃球員。"},{"en":"If something brings an image to mind, it makes people think of that image immediately.","zh":"如果某事 brought an image to mind，就是它令人立刻想起那個畫面。"},{"en":"The smell of chlorine brought to mind summer swimming lessons.","zh":"氯氣的氣味令人想起夏天的游泳課。"},{"en":"The word “teamwork” may bring to mind football players passing the ball.","zh":"「團隊合作」這個詞可能令人想起足球員傳球。"},{"en":"This phrase is useful when explaining the first idea people usually imagine.","zh":"這個短語適合用來解釋人們通常首先想像到的畫面。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"swimmers slicing through water","meaning":"游泳健兒破水前進","examples":[{"en":"The word “athlete” may bring to mind swimmers slicing through water.","zh":"「運動員」這個詞可能令人想起游泳健兒破水前進。"},{"en":"Swimmers slicing through water means swimmers moving quickly and smoothly through water.","zh":"swimmers slicing through water 指游泳健兒快速而流暢地在水中前進。"},{"en":"In a race, swimmers slicing through water show strength, rhythm and control.","zh":"在比賽中，游泳健兒破水前進，展現力量、節奏和控制。"},{"en":"The phrase makes swimming sound fast because the body seems to cut through the pool.","zh":"這個短語令游泳聽起來很快，因為身體像切開泳池的水。"},{"en":"It creates a strong image of athletic power and speed.","zh":"它製造出運動力量和速度的鮮明畫面。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"sprinting across the court","meaning":"在球場上衝刺","examples":[{"en":"Basketball players are often imagined sprinting across the court.","zh":"籃球員常被想像成在球場上衝刺。"},{"en":"Sprinting across the court means running very fast from one side of the playing area to another.","zh":"sprinting across the court 指在球場上從一邊快速跑到另一邊。"},{"en":"A player may sprint across the court to stop an opponent from scoring.","zh":"球員可能在球場上衝刺，阻止對手得分。"},{"en":"Sprinting across the court requires speed, stamina and quick judgement.","zh":"在球場上衝刺需要速度、耐力和快速判斷。"},{"en":"This phrase helps readers picture basketball as an energetic sport.","zh":"這個短語幫助讀者想像籃球是一項充滿活力的運動。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"collapsing breathlessly","meaning":"氣喘吁吁地倒下","examples":[{"en":"Runners may collapse breathlessly at the finish line.","zh":"跑手可能在終點線氣喘吁吁地倒下。"},{"en":"Collapsing breathlessly means falling down because you are extremely tired and short of breath.","zh":"collapsing breathlessly 指因極度疲倦和呼吸急促而倒下。"},{"en":"After the long race, the athlete collapsed breathlessly beside the track.","zh":"長跑後，那名運動員在跑道旁氣喘吁吁地倒下。"},{"en":"Someone collapsing breathlessly shows how much effort the activity required.","zh":"一個人氣喘吁吁地倒下，顯示那項活動需要很多努力。"},{"en":"This phrase makes physical exhaustion easy to imagine.","zh":"這個短語令身體疲憊變得容易想像。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"at the finish line","meaning":"在終點線","examples":[{"en":"Runners often push themselves hard at the finish line.","zh":"跑手常在終點線全力推動自己。"},{"en":"At the finish line means at the point where a race ends.","zh":"at the finish line 指在比賽結束的位置。"},{"en":"Many runners speed up at the finish line because they can see the end.","zh":"許多跑手在終點線加速，因為他們看見終點。"},{"en":"A close race can be decided by one step at the finish line.","zh":"一場接近的比賽可能在終點線由一步決定勝負。"},{"en":"This phrase often suggests final effort, pressure and determination.","zh":"這個短語常暗示最後的努力、壓力和決心。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"Dancers, by contrast, are often pictured under soft stage lights.","zh":"相比之下，舞者常被想像成在柔和的舞台燈光下。"},{"en":"By contrast means when compared with something different.","zh":"by contrast 指與不同的事物作比較時。"},{"en":"Swimmers show speed in water; dancers, by contrast, show power through controlled movement.","zh":"游泳健兒在水中展現速度；相比之下，舞者透過受控制的動作展現力量。"},{"en":"One student learns best by listening; another, by contrast, needs diagrams.","zh":"一名學生最適合靠聆聽學習；相比之下，另一名學生需要圖像。"},{"en":"This phrase helps writers show a clear difference between two ideas.","zh":"這個短語幫助作者清楚顯示兩個想法之間的差異。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"be pictured under","meaning":"被想像成在……之下","examples":[{"en":"Dancers are often pictured under soft stage lights.","zh":"舞者常被想像成在柔和的舞台燈光下。"},{"en":"To be pictured under something means to be imagined or shown beneath it.","zh":"be pictured under something 指被想像或呈現為在某物之下。"},{"en":"Singers are often pictured under bright concert lights.","zh":"歌手常被想像成在明亮的演唱會燈光下。"},{"en":"A dancer pictured under soft lights may seem graceful rather than athletic.","zh":"被想像成在柔和燈光下的舞者，可能看起來優雅多於像運動員。"},{"en":"This phrase shows how people’s mental images can shape their opinions.","zh":"這個短語顯示人們腦海中的畫面如何影響看法。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"soft stage lights","meaning":"柔和的舞台燈光","examples":[{"en":"Dancers are often seen performing under soft stage lights.","zh":"舞者常被看見在柔和的舞台燈光下表演。"},{"en":"Soft stage lights are gentle lights used on stage to create a calm or beautiful mood.","zh":"soft stage lights 指舞台上用來營造平靜或美麗氣氛的柔和燈光。"},{"en":"Soft stage lights can make a dance performance look graceful and dreamlike.","zh":"柔和的舞台燈光可以令舞蹈表演看起來優雅而夢幻。"},{"en":"Because soft stage lights hide sweat and effort, audiences may forget how hard dancers work.","zh":"因為柔和的舞台燈光掩蓋汗水和努力，觀眾可能忘記舞者有多辛苦。"},{"en":"This phrase creates a beautiful image but may hide physical difficulty.","zh":"這個短語製造美麗畫面，但也可能隱藏身體上的困難。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"dressed beautifully","meaning":"打扮得漂亮","examples":[{"en":"Dancers are often pictured dressed beautifully and smiling effortlessly.","zh":"舞者常被想像成打扮得漂亮，並看似毫不費力地微笑。"},{"en":"Dressed beautifully means wearing attractive clothes or costumes.","zh":"dressed beautifully 指穿着漂亮的衣服或服裝。"},{"en":"The team was dressed beautifully for the school performance.","zh":"那隊伍為學校表演打扮得很漂亮。"},{"en":"Being dressed beautifully does not mean the dancer is not working hard.","zh":"打扮得漂亮並不代表舞者沒有努力。"},{"en":"This phrase reminds readers that appearance can hide effort.","zh":"這個短語提醒讀者，外表可以掩蓋努力。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"smiling effortlessly","meaning":"看似毫不費力地微笑","examples":[{"en":"Dancers may appear to be smiling effortlessly on stage.","zh":"舞者在舞台上可能看似毫不費力地微笑。"},{"en":"Smiling effortlessly means smiling as if the action requires no effort.","zh":"smiling effortlessly 指微笑得好像完全不需要用力。"},{"en":"A dancer may be exhausted but still smile effortlessly during the final pose.","zh":"舞者可能已很疲倦，但在最後定格時仍看似毫不費力地微笑。"},{"en":"Performers practise smiling effortlessly so the audience does not see their pain.","zh":"表演者練習看似毫不費力地微笑，讓觀眾看不見痛楚。"},{"en":"This phrase shows the gap between appearance and real effort.","zh":"這個短語顯示外表和真正努力之間的差距。"}],"source":"2017 Q8.pdf","sourcePage":1},{"front":"this picture is incomplete","meaning":"這種看法並不完整","examples":[{"en":"Yet this picture is incomplete.","zh":"然而，這種看法並不完整。"},{"en":"This picture is incomplete means this way of seeing something leaves out important facts.","zh":"this picture is incomplete 指這種看法漏掉了重要事實。"},{"en":"Saying dancers only look graceful is incomplete because it ignores their training.","zh":"說舞者只是看起來優雅是不完整的，因為它忽略了訓練。"},{"en":"A report about school life is incomplete if it discusses exams but not mental health.","zh":"如果一份關於校園生活的報告只談考試而不談心理健康，就是不完整的。"},{"en":"This phrase prepares readers to consider a fuller argument.","zh":"這個短語為讀者準備一個更完整的論點。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"as a member of","meaning":"作為……的一員","examples":[{"en":"As a member of our school dance team, I understand how demanding dance is.","zh":"作為我們學校舞蹈隊的一員，我明白舞蹈有多高要求。"},{"en":"As a member of means speaking from the position of belonging to a group.","zh":"as a member of 指以屬於某個群體的身分說話。"},{"en":"As a member of the debate team, I know preparation matters.","zh":"作為辯論隊的一員，我知道準備很重要。"},{"en":"A student can speak more personally as a member of the group being discussed.","zh":"作為被討論群體的一員，學生可以說得更個人和真實。"},{"en":"This phrase gives the writer direct experience and credibility.","zh":"這個短語令作者有直接經驗和可信度。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"school dance team","meaning":"學校舞蹈隊","examples":[{"en":"I am a member of our school dance team.","zh":"我是我們學校舞蹈隊的一員。"},{"en":"A school dance team is a group of students who train and perform dance for school events or competitions.","zh":"school dance team 指為學校活動或比賽訓練和表演舞蹈的學生團體。"},{"en":"The school dance team rehearses after lessons before the annual show.","zh":"學校舞蹈隊在周年表演前放學後排練。"},{"en":"A school dance team needs teamwork, discipline and physical fitness.","zh":"學校舞蹈隊需要團隊合作、紀律和體能。"},{"en":"This phrase shows dance as organised training, not casual movement.","zh":"這個短語顯示舞蹈是有組織的訓練，而不是隨意活動。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"school community","meaning":"學校群體","examples":[{"en":"I am writing to ask our school community to respect dance as a sport.","zh":"我寫這篇文章，是為了請我們的學校群體尊重舞蹈作為一項運動。"},{"en":"A school community includes students, teachers, parents and staff connected to the school.","zh":"school community 包括與學校有關的學生、老師、家長和職員。"},{"en":"The school community should support both academic work and team activities.","zh":"學校群體應支持學業和團隊活動。"},{"en":"When the school community respects dancers, students feel their effort is seen.","zh":"當學校群體尊重舞者，學生會感到自己的努力被看見。"},{"en":"This phrase appeals to everyone in the school, not only one class.","zh":"這個短語呼籲學校裏所有人，而不只是一班學生。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"see dance not as…, but as…","meaning":"不把舞蹈視為……，而是視為……","examples":[{"en":"We should see dance not as decoration for assemblies, but as a demanding sport.","zh":"我們不應把舞蹈視為集會上的點綴，而應視為一項要求極高的運動。"},{"en":"See dance not as A, but as B means reject one view and replace it with another.","zh":"see dance not as A, but as B 指拒絕一種看法，改用另一種看法。"},{"en":"We should see homework not as punishment, but as practice for understanding.","zh":"我們不應把功課視為懲罰，而應視為理解知識的練習。"},{"en":"This structure helps writers correct a mistaken attitude clearly.","zh":"這個結構幫助作者清楚糾正錯誤態度。"},{"en":"In the essay, it changes dance from something pretty into something athletic.","zh":"在文章中，它把舞蹈從漂亮的東西改寫成運動性的東西。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"decoration for assemblies","meaning":"集會上的點綴","examples":[{"en":"Dance should not be treated merely as decoration for assemblies.","zh":"舞蹈不應只被當作集會上的點綴。"},{"en":"Decoration for assemblies means something added to school gatherings only to make them look nicer.","zh":"decoration for assemblies 指在學校集會中加入、只為令場面好看的東西。"},{"en":"A song used as decoration for assemblies may be enjoyed but not respected as serious work.","zh":"一首被用作集會點綴的歌曲可能受歡迎，但未必被視為認真的作品。"},{"en":"Treating dance as decoration for assemblies ignores the training behind it.","zh":"把舞蹈視為集會上的點綴，忽略了背後的訓練。"},{"en":"This phrase criticises a shallow view of performance.","zh":"這個短語批評對表演的膚淺看法。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"a demanding sport","meaning":"要求極高的運動","examples":[{"en":"Dance is a demanding sport in its own right.","zh":"舞蹈本身就是一項要求極高的運動。"},{"en":"A demanding sport is a sport that requires great effort, skill, fitness and discipline.","zh":"a demanding sport 指需要大量努力、技巧、體能和紀律的運動。"},{"en":"Gymnastics is a demanding sport because athletes must combine strength and balance.","zh":"體操是要求極高的運動，因為運動員必須結合力量和平衡。"},{"en":"Dance is demanding because dancers must move powerfully while looking controlled.","zh":"舞蹈要求很高，因為舞者必須有力地移動，同時看起來受控制。"},{"en":"This phrase argues that dance should be taken seriously as sport.","zh":"這個短語主張舞蹈應被認真視為運動。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"in its own right","meaning":"本身就是；憑本身條件","examples":[{"en":"Dance deserves to be recognised as a sport in its own right.","zh":"舞蹈值得憑本身條件被承認為一項運動。"},{"en":"In its own right means because of its own qualities, not because it is connected to something else.","zh":"in its own right 指憑自己的特質，而不是靠與其他事物的關係。"},{"en":"School drama is valuable in its own right, not only because it improves confidence.","zh":"學校戲劇本身就有價值，不只是因為它提升自信。"},{"en":"A small local team can be respected in its own right even without national awards.","zh":"小型本地隊伍即使沒有全國獎項，也可以憑本身條件受到尊重。"},{"en":"This phrase helps argue that dance itself has athletic value.","zh":"這個短語幫助論證舞蹈本身具有運動價值。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"exceptional physical strength","meaning":"出色的體能力量","examples":[{"en":"Dance requires exceptional physical strength.","zh":"舞蹈需要出色的體能力量。"},{"en":"Exceptional physical strength means unusually high body strength.","zh":"exceptional physical strength 指非常高的身體力量。"},{"en":"A dancer needs exceptional physical strength to jump, turn and hold difficult positions.","zh":"舞者需要出色的體能力量來跳躍、轉身和保持困難姿勢。"},{"en":"Exceptional physical strength is easy to miss when movements look smooth.","zh":"當動作看起來流暢，出色的體能力量很容易被忽略。"},{"en":"This phrase shows that dance depends on the body as much as other sports do.","zh":"這個短語顯示舞蹈和其他運動一樣依賴身體。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"refined skills","meaning":"精細的技巧","examples":[{"en":"Dancers need refined skills as well as physical strength.","zh":"舞者除了體能力量，還需要精細的技巧。"},{"en":"Refined skills are careful, polished abilities developed through practice.","zh":"refined skills 指透過練習培養出來的仔細而成熟的能力。"},{"en":"A pianist needs refined skills to control timing, touch and emotion.","zh":"鋼琴家需要精細的技巧來控制時間、觸鍵和情感。"},{"en":"Dancers use refined skills when they make difficult movements look clean.","zh":"當舞者令困難動作看起來乾淨俐落，就是在使用精細技巧。"},{"en":"This phrase shows that dance is not only strong but also technically precise.","zh":"這個短語顯示舞蹈不只有力量，也有技術上的精準。"}],"source":"2017 Q8.pdf","sourcePage":2},{"front":"strict self-discipline","meaning":"嚴格的自律","examples":[{"en":"Dancers need strict self-discipline to improve.","zh":"舞者需要嚴格的自律才能進步。"},{"en":"Strict self-discipline means controlling yourself carefully so you keep practising and making good choices.","zh":"strict self-discipline 指嚴格控制自己，持續練習並作出好選擇。"},{"en":"A student needs strict self-discipline to study every day without being reminded.","zh":"學生需要嚴格的自律，才能不用別人提醒也每天溫習。"},{"en":"Dancers use strict self-discipline when they warm up, rehearse and rest properly.","zh":"舞者正確熱身、排練和休息時，就是在運用嚴格的自律。"},{"en":"This phrase shows that progress depends on habits, not only talent.","zh":"這個短語顯示進步取決於習慣，而不只是天分。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"relentless training","meaning":"不懈的訓練","examples":[{"en":"Dancers become stronger through relentless training.","zh":"舞者透過不懈的訓練變得更強。"},{"en":"Relentless training means continuous hard practice that does not stop easily.","zh":"relentless training 指持續而艱苦、不輕易停止的練習。"},{"en":"Athletes improve through relentless training even when progress feels slow.","zh":"即使進步感覺緩慢，運動員也透過不懈訓練改善。"},{"en":"Relentless training can be tiring, but it builds strength and automatic timing.","zh":"不懈的訓練可以令人疲倦，但能建立力量和自然反應。"},{"en":"This phrase suggests effort repeated over a long period.","zh":"這個短語暗示長時間反覆付出的努力。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"to begin with","meaning":"首先","examples":[{"en":"To begin with, dancers possess a special kind of athletic strength.","zh":"首先，舞者擁有一種特別的運動員力量。"},{"en":"To begin with means firstly, or as the first point in an explanation.","zh":"to begin with 指首先，或作為解釋中的第一點。"},{"en":"To begin with, we should define what an athlete is.","zh":"首先，我們應定義甚麼是運動員。"},{"en":"To begin with, a healthy team needs regular practice.","zh":"首先，健康的隊伍需要定期練習。"},{"en":"This phrase helps organise an essay by introducing the first argument.","zh":"這個短語透過引入第一個論點來幫助組織文章。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"possess a kind of","meaning":"擁有一種……","examples":[{"en":"Dancers possess a kind of athletic strength that is easy to overlook.","zh":"舞者擁有一種容易被忽略的運動員力量。"},{"en":"Possess a kind of means have a particular type of quality or ability.","zh":"possess a kind of 指擁有某種特定的特質或能力。"},{"en":"Quiet leaders possess a kind of confidence that does not need shouting.","zh":"安靜的領袖擁有一種不需要大聲說話的自信。"},{"en":"Dancers possess a kind of strength that appears as control rather than force.","zh":"舞者擁有一種表現為控制力而不是蠻力的力量。"},{"en":"This phrase helps describe a quality that may not be obvious at first.","zh":"這個短語有助描述起初不明顯的特質。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"athletic strength","meaning":"運動員般的力量","examples":[{"en":"Dancers possess athletic strength as well as artistic expression.","zh":"舞者既有藝術表達，也有運動員般的力量。"},{"en":"Athletic strength means the physical power and control needed for sport.","zh":"athletic strength 指運動所需的身體力量和控制力。"},{"en":"A gymnast shows athletic strength when she holds her body steady on the bars.","zh":"體操運動員在高低槓上穩定身體時，展現運動員般的力量。"},{"en":"Dancers need athletic strength to jump, balance and recover from fast movements.","zh":"舞者需要運動員般的力量來跳躍、平衡和從快速動作中恢復。"},{"en":"This phrase connects dance with the physical demands of sport.","zh":"這個短語把舞蹈與運動的身體要求連在一起。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"easy to overlook","meaning":"容易被忽略","examples":[{"en":"A dancer’s strength is easy to overlook because it looks effortless.","zh":"舞者的力量容易被忽略，因為它看起來毫不費力。"},{"en":"Easy to overlook means easy not to notice or take seriously.","zh":"easy to overlook 指容易沒有注意到或沒有認真看待。"},{"en":"A quiet student’s hard work is easy to overlook if she never complains.","zh":"如果安靜的學生從不抱怨，她的努力很容易被忽略。"},{"en":"Dance strength is easy to overlook because audiences often focus on beauty.","zh":"舞蹈力量容易被忽略，因為觀眾常集中在美感上。"},{"en":"This phrase shows why people may undervalue something important.","zh":"這個短語顯示人們為何可能低估重要的東西。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"precisely because","meaning":"正正因為","examples":[{"en":"This strength is easy to overlook precisely because it is made to look effortless.","zh":"這種力量容易被忽略，正正因為它被塑造成看似毫不費力。"},{"en":"Precisely because means exactly because of that reason.","zh":"precisely because 指正是因為那個原因。"},{"en":"The task is difficult precisely because it looks simple to outsiders.","zh":"這項任務困難，正正因為外人覺得它簡單。"},{"en":"Dance is misunderstood precisely because good dancers hide the effort.","zh":"舞蹈被誤解，正正因為優秀舞者把努力隱藏起來。"},{"en":"This phrase strongly connects a cause with a surprising result.","zh":"這個短語把原因和令人意外的結果強烈連接起來。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"be made to look effortless","meaning":"被塑造成看似毫不費力","examples":[{"en":"A dancer’s movement is made to look effortless.","zh":"舞者的動作被塑造成看似毫不費力。"},{"en":"If something is made to look effortless, hard work is hidden so the result appears easy.","zh":"如果某事 is made to look effortless，就是艱苦努力被隱藏，令成果看起來輕鬆。"},{"en":"A speech may be made to look effortless after weeks of practice.","zh":"一場演講經過數星期練習後，可能被塑造成看似毫不費力。"},{"en":"Dancers train for hours so difficult turns are made to look effortless.","zh":"舞者訓練數小時，令困難轉身被塑造成看似毫不費力。"},{"en":"This phrase explains how performance can hide labour.","zh":"這個短語解釋表演如何隱藏勞動。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"expect power","meaning":"預期看到力量","examples":[{"en":"When a basketball player jumps, the audience expects power.","zh":"當籃球員跳起時，觀眾預期看到力量。"},{"en":"Expect power means believe that strength and force will be clearly shown.","zh":"expect power 指相信力量和爆發力會被清楚展現。"},{"en":"In a sprint race, spectators expect power from the runners’ first steps.","zh":"在短跑比賽中，觀眾從跑手第一步開始就預期看到力量。"},{"en":"People expect power in basketball because jumping and blocking look physically obvious.","zh":"人們在籃球中預期看到力量，因為跳躍和封阻看起來很明顯地需要體力。"},{"en":"This phrase helps compare visible strength with hidden strength.","zh":"這個短語幫助比較可見力量和隱藏力量。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"leaps, turns and lands silently","meaning":"跳躍、轉身並輕聲落地","examples":[{"en":"When a dancer leaps, turns and lands silently, the audience often sees only grace.","zh":"當舞者跳躍、轉身並輕聲落地時，觀眾常只看到優雅。"},{"en":"Leaps, turns and lands silently means jumps, rotates and comes down without making much sound.","zh":"leaps, turns and lands silently 指跳起、旋轉，然後幾乎不發出聲音地落地。"},{"en":"A dancer who leaps, turns and lands silently must control every part of the body.","zh":"一個能跳躍、轉身並輕聲落地的舞者，必須控制身體每一部分。"},{"en":"Silent landings require strong legs, balance and careful timing.","zh":"輕聲落地需要強壯雙腿、平衡和仔細時間掌握。"},{"en":"This phrase shows physical difficulty hidden inside elegance.","zh":"這個短語顯示優雅之中隱藏的身體難度。"}],"source":"2017 Q8.pdf","sourcePage":3},{"front":"see only grace","meaning":"只看到優雅","examples":[{"en":"The audience often sees only grace when a dancer performs.","zh":"舞者表演時，觀眾常只看到優雅。"},{"en":"See only grace means notice only beauty and smoothness, not the effort behind them.","zh":"see only grace 指只留意美感和流暢，而不是背後的努力。"},{"en":"People may see only grace in ballet and miss the pain of training.","zh":"人們可能在芭蕾中只看到優雅，卻錯過訓練的痛苦。"},{"en":"If viewers see only grace, they may not understand dance as sport.","zh":"如果觀眾只看到優雅，他們可能不明白舞蹈是一項運動。"},{"en":"This phrase points out a limited way of watching.","zh":"這個短語指出一種有限的觀看方式。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"far from the absence of","meaning":"絕不是沒有……","examples":[{"en":"Grace is far from the absence of strength.","zh":"優雅絕不是沒有力量。"},{"en":"Far from the absence of something means not lacking that thing at all.","zh":"far from the absence of something 指完全不是缺乏某物。"},{"en":"Silence in class is far from the absence of thought; students may be thinking deeply.","zh":"課室中的安靜絕不是沒有思考；學生可能正在深入思考。"},{"en":"A calm performance is far from the absence of effort.","zh":"平靜的表演絕不是沒有努力。"},{"en":"This phrase corrects a mistaken idea strongly.","zh":"這個短語有力地糾正錯誤想法。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"the absence of strength","meaning":"缺乏力量","examples":[{"en":"Grace is not the absence of strength.","zh":"優雅不是缺乏力量。"},{"en":"The absence of strength means a lack of physical power or control.","zh":"the absence of strength 指缺少身體力量或控制力。"},{"en":"A slow movement in dance is not the absence of strength if the body is fully controlled.","zh":"如果身體完全受控制，舞蹈中的慢動作並不是缺乏力量。"},{"en":"Weak posture may show the absence of strength in the core or back.","zh":"姿勢不穩可能顯示核心或背部缺乏力量。"},{"en":"This phrase helps explain that softness and weakness are not the same.","zh":"這個短語幫助說明柔和和軟弱並不相同。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"strength controlled so precisely","meaning":"被精準控制的力量","examples":[{"en":"Grace is strength controlled so precisely that it becomes beautiful.","zh":"優雅是被精準控制的力量，精準到變得美麗。"},{"en":"Strength controlled so precisely means power is managed with exact timing and shape.","zh":"strength controlled so precisely 指力量被以精確時間和形態控制。"},{"en":"A gymnast shows strength controlled so precisely when she lands without wobbling.","zh":"體操運動員落地不搖晃時，展現被精準控制的力量。"},{"en":"Dancers turn strength into beauty by controlling it precisely.","zh":"舞者透過精準控制，把力量變成美感。"},{"en":"This phrase explains why graceful dance is also athletic.","zh":"這個短語解釋為何優雅的舞蹈也是運動性的。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"hold the core tight","meaning":"收緊核心肌群","examples":[{"en":"A dancer must hold the core tight during turns and jumps.","zh":"舞者在轉身和跳躍時必須收緊核心肌群。"},{"en":"Hold the core tight means keep the stomach and middle-body muscles firm and controlled.","zh":"hold the core tight 指保持腹部和身體中央肌肉穩定受控。"},{"en":"Pilates teaches students to hold the core tight to protect the back.","zh":"普拉提教學生收緊核心肌群，以保護背部。"},{"en":"If dancers do not hold the core tight, they may lose balance during turns.","zh":"如果舞者不收緊核心肌群，轉身時可能失去平衡。"},{"en":"This phrase shows that dance strength begins from the centre of the body.","zh":"這個短語顯示舞蹈力量從身體中心開始。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"keep the back lifted","meaning":"保持背部挺直上提","examples":[{"en":"A dancer must keep the back lifted while moving.","zh":"舞者移動時必須保持背部挺直上提。"},{"en":"Keep the back lifted means hold the spine tall and active instead of collapsing.","zh":"keep the back lifted 指保持脊椎挺拔有力，而不是塌下來。"},{"en":"Good posture requires students to keep the back lifted when sitting at a desk.","zh":"良好姿勢要求學生坐在書桌前時保持背部挺直上提。"},{"en":"Dancers keep the back lifted so their lines look clear and strong.","zh":"舞者保持背部挺直上提，令線條清晰有力。"},{"en":"This phrase shows how posture is part of physical control.","zh":"這個短語顯示姿勢是身體控制的一部分。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"extend the legs","meaning":"伸展雙腿","examples":[{"en":"A dancer must extend the legs with control.","zh":"舞者必須有控制地伸展雙腿。"},{"en":"Extend the legs means stretch the legs outward or make them long and straight.","zh":"extend the legs 指把雙腿向外伸展，或令它們修長筆直。"},{"en":"A dancer extends the legs during a jump to create a clear line.","zh":"舞者在跳躍時伸展雙腿，以製造清晰線條。"},{"en":"If the legs are extended without control, the movement may look messy or unsafe.","zh":"如果伸展雙腿時沒有控制，動作可能顯得凌亂或不安全。"},{"en":"This phrase shows how flexibility and strength work together.","zh":"這個短語顯示柔韌性和力量如何一起運作。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"control the arms","meaning":"控制手臂動作","examples":[{"en":"A dancer has to control the arms while keeping rhythm.","zh":"舞者必須在保持節奏時控制手臂動作。"},{"en":"Control the arms means move the arms deliberately instead of letting them swing randomly.","zh":"control the arms 指有意識地移動手臂，而不是讓它們隨意擺動。"},{"en":"In dance, arms can show emotion only if the dancer controls them carefully.","zh":"在舞蹈中，只有仔細控制手臂動作，手臂才能表達情感。"},{"en":"If a dancer cannot control the arms, the whole movement may look unfinished.","zh":"如果舞者不能控制手臂動作，整個動作可能看起來未完成。"},{"en":"This phrase shows that small body parts also need discipline.","zh":"這個短語顯示細小身體部位也需要紀律。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"remember the rhythm","meaning":"記住節奏","examples":[{"en":"A dancer must remember the rhythm, spacing and facial expression.","zh":"舞者必須記住節奏、走位距離和面部表情。"},{"en":"Remember the rhythm means keep the beat and timing in mind while moving.","zh":"remember the rhythm 指移動時把拍子和時間記在心裏。"},{"en":"Students remember the rhythm by counting music during rehearsal.","zh":"學生在排練時透過數拍子記住節奏。"},{"en":"If dancers forget the rhythm, they may move too early or too late.","zh":"如果舞者忘記節奏，可能會太早或太遲移動。"},{"en":"This phrase shows that dance requires memory as well as movement.","zh":"這個短語顯示舞蹈需要記憶，也需要動作。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"spacing","meaning":"走位距離；空間安排","examples":[{"en":"Dancers need to remember the rhythm, spacing and facial expression.","zh":"舞者需要記住節奏、走位距離和面部表情。"},{"en":"Spacing means the distance and position between dancers or objects.","zh":"spacing 指舞者或物件之間的距離和位置。"},{"en":"In a group dance, good spacing stops dancers from bumping into each other.","zh":"在群舞中，良好走位距離可以防止舞者互相碰撞。"},{"en":"If spacing is wrong, the formation may look crowded or uneven.","zh":"如果空間安排錯誤，隊形可能顯得擠迫或不平均。"},{"en":"This word shows that dance depends on awareness of space.","zh":"這個詞顯示舞蹈依賴對空間的意識。"}],"source":"2017 Q8.pdf","sourcePage":4},{"front":"facial expression","meaning":"面部表情","examples":[{"en":"A dancer must control movement and facial expression at the same time.","zh":"舞者必須同時控制動作和面部表情。"},{"en":"Facial expression means the look on a person’s face that shows feeling or meaning.","zh":"facial expression 指人的臉上顯示感受或意思的表情。"},{"en":"A dancer may use facial expression to show joy, anger or sadness.","zh":"舞者可能用面部表情表達喜悅、憤怒或悲傷。"},{"en":"If the body dances beautifully but the facial expression is blank, the performance may feel weak.","zh":"如果身體跳得漂亮，但面部表情空白，表演可能顯得薄弱。"},{"en":"This phrase shows that dance requires emotional control too.","zh":"這個短語顯示舞蹈也需要情感控制。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"one weak muscle","meaning":"一塊乏力的肌肉","examples":[{"en":"One weak muscle can ruin a turn.","zh":"一塊乏力的肌肉可以毀掉一個轉身動作。"},{"en":"One weak muscle means even one part of the body lacks enough strength.","zh":"one weak muscle 指身體某一部分即使只有一塊肌肉力量不足。"},{"en":"One weak muscle in the ankle can make a landing unstable.","zh":"腳踝一塊乏力的肌肉可以令落地不穩。"},{"en":"In dance, one weak muscle may affect the whole body’s balance.","zh":"在舞蹈中，一塊乏力的肌肉可能影響整個身體的平衡。"},{"en":"This phrase shows how precise and demanding dance can be.","zh":"這個短語顯示舞蹈可以多麼精準和高要求。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"ruin a turn","meaning":"毀掉一個轉身動作","examples":[{"en":"One weak muscle can ruin a turn.","zh":"一塊乏力的肌肉可以毀掉一個轉身動作。"},{"en":"Ruin a turn means spoil a spinning movement so it fails or looks wrong.","zh":"ruin a turn 指破壞旋轉動作，令它失敗或看起來不對。"},{"en":"Bad balance can ruin a turn even if the dancer starts well.","zh":"即使舞者開始得好，差劣平衡也可以毀掉一個轉身動作。"},{"en":"A small mistake in timing may ruin a turn during a competition.","zh":"比賽中一個細小時間錯誤可能毀掉一個轉身動作。"},{"en":"This phrase shows that dance movements depend on many details working together.","zh":"這個短語顯示舞蹈動作依賴許多細節一起配合。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"worse still","meaning":"更糟的是","examples":[{"en":"Worse still, one careless landing can lead to injury.","zh":"更糟的是，一次不小心的落地可以導致受傷。"},{"en":"Worse still means even more seriously or more badly than the previous point.","zh":"worse still 指比前一點更嚴重或更糟糕。"},{"en":"The team lost the match; worse still, their captain was injured.","zh":"球隊輸了比賽；更糟的是，隊長受傷了。"},{"en":"A dancer may miss the beat; worse still, she may land badly and hurt herself.","zh":"舞者可能錯拍；更糟的是，她可能落地不穩並受傷。"},{"en":"This phrase adds a stronger negative consequence.","zh":"這個短語加入更強烈的負面後果。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"careless landing","meaning":"不小心的落地","examples":[{"en":"One careless landing can lead to serious injury.","zh":"一次不小心的落地可以導致嚴重受傷。"},{"en":"A careless landing is a jump ending without enough control or attention.","zh":"careless landing 指跳躍結束時缺乏足夠控制或注意。"},{"en":"A gymnast can hurt her ankle after one careless landing.","zh":"體操運動員可能因一次不小心的落地扭傷腳踝。"},{"en":"Dancers practise landing safely because a careless landing can damage knees or feet.","zh":"舞者練習安全落地，因為不小心的落地可能傷害膝蓋或腳。"},{"en":"This phrase shows why dance needs careful technique.","zh":"這個短語顯示為何舞蹈需要仔細技巧。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"lead to","meaning":"導致","examples":[{"en":"One careless landing can lead to potentially permanent injury.","zh":"一次不小心的落地可以導致可能永久性的受傷。"},{"en":"Lead to means cause something to happen or create a result.","zh":"lead to 指造成某事發生或產生某個結果。"},{"en":"Poor warm-up can lead to muscle pain during practice.","zh":"熱身不足可以導致練習時肌肉疼痛。"},{"en":"Good training can lead to stronger jumps and safer movement.","zh":"良好訓練可以導致更有力的跳躍和更安全的動作。"},{"en":"This phrase is useful for showing cause and effect.","zh":"這個短語適合用來顯示因果關係。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"potentially permanent injury","meaning":"可能永久性的受傷","examples":[{"en":"A careless landing can lead to potentially permanent injury.","zh":"一次不小心的落地可以導致可能永久性的受傷。"},{"en":"Potentially permanent injury means an injury that may last for life or a very long time.","zh":"potentially permanent injury 指可能持續一生或很長時間的傷患。"},{"en":"A serious knee injury can be potentially permanent if it is not treated properly.","zh":"如果沒有妥善治療，嚴重膝傷可能成為可能永久性的受傷。"},{"en":"Dancers must land carefully to avoid potentially permanent injury.","zh":"舞者必須小心落地，以避免可能永久性的受傷。"},{"en":"This phrase shows that mistakes in dance can have serious consequences.","zh":"這個短語顯示舞蹈中的錯誤可能有嚴重後果。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"take…, for example","meaning":"以……為例","examples":[{"en":"Take our school team’s recent jazz routine, for example.","zh":"以我們校隊最近的爵士舞套路為例。"},{"en":"Take something for example means use it as a clear case to explain a point.","zh":"take something for example 指用某事作為清楚例子來解釋觀點。"},{"en":"Take school sports day, for example: it shows how teamwork builds confidence.","zh":"以學校運動會為例：它顯示團隊合作如何建立自信。"},{"en":"A writer uses this phrase before giving specific evidence.","zh":"作者在給出具體證據前會使用這個短語。"},{"en":"This phrase helps move from general argument to concrete example.","zh":"這個短語幫助從一般論點轉向具體例子。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"recent jazz routine","meaning":"最近的爵士舞套路","examples":[{"en":"Our recent jazz routine required strength, speed and control.","zh":"我們最近的爵士舞套路需要力量、速度和控制。"},{"en":"A recent jazz routine is a jazz dance sequence the team practised or performed not long ago.","zh":"recent jazz routine 指隊伍不久前練習或表演的爵士舞動作組合。"},{"en":"The recent jazz routine included sharp arms, quick turns and floor movements.","zh":"最近的爵士舞套路包括俐落手部動作、快速轉身和地板動作。"},{"en":"A recent jazz routine can show how demanding school dance really is.","zh":"最近的爵士舞套路可以顯示學校舞蹈真正有多高要求。"},{"en":"This phrase gives the argument a real example from the writer’s experience.","zh":"這個短語為論點提供來自作者經驗的真實例子。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"thirty-second section","meaning":"三十秒的一段","examples":[{"en":"During one thirty-second section, we had to complete many movements.","zh":"在三十秒的一段中，我們必須完成許多動作。"},{"en":"A thirty-second section is a short part of a performance lasting half a minute.","zh":"thirty-second section 指表演中持續半分鐘的一小段。"},{"en":"A thirty-second section can feel long when it contains jumps, turns and floorwork.","zh":"如果包含跳躍、轉身和地板動作，三十秒的一段也可以感覺很長。"},{"en":"Dancers may rehearse one thirty-second section many times until it becomes clean.","zh":"舞者可能反覆排練三十秒的一段，直到它變得乾淨俐落。"},{"en":"This phrase shows how much effort can be packed into a short time.","zh":"這個短語顯示短時間內可以包含多少努力。"}],"source":"2017 Q8.pdf","sourcePage":5},{"front":"complete a jump","meaning":"完成一個跳躍動作","examples":[{"en":"We had to complete a jump and drop to the floor.","zh":"我們必須完成一個跳躍動作，然後倒到地上。"},{"en":"Complete a jump means finish a jump safely and correctly from take-off to landing.","zh":"complete a jump 指從起跳到落地都安全而正確地完成跳躍。"},{"en":"A dancer must complete a jump with pointed feet and controlled landing.","zh":"舞者必須以繃直腳背和受控制的落地完成一個跳躍動作。"},{"en":"If she cannot complete a jump, the next movement may also go wrong.","zh":"如果她不能完成一個跳躍動作，下一個動作也可能出錯。"},{"en":"This phrase shows that even one jump has several technical parts.","zh":"這個短語顯示即使一個跳躍也有多個技術部分。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"drop to the floor","meaning":"倒到地上","examples":[{"en":"During the routine, we had to drop to the floor and roll.","zh":"在舞蹈套路中，我們必須倒到地上再翻滾。"},{"en":"Drop to the floor means move quickly down from standing to the floor.","zh":"drop to the floor 指快速從站立姿勢移到地上。"},{"en":"In jazz dance, performers may drop to the floor on a strong beat.","zh":"在爵士舞中，表演者可能在強拍時倒到地上。"},{"en":"Dancers must control the body when they drop to the floor to avoid injury.","zh":"舞者倒到地上時必須控制身體，以避免受傷。"},{"en":"This phrase shows that dance includes powerful low movements as well as jumps.","zh":"這個短語顯示舞蹈不只有跳躍，也有強而有力的低位動作。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"move into a new formation","meaning":"走入新的隊形","examples":[{"en":"We had to move into a new formation without losing the beat.","zh":"我們必須走入新的隊形，而不失去拍子。"},{"en":"Move into a new formation means change positions so the group creates a different shape.","zh":"move into a new formation 指改變位置，讓團隊形成不同形狀。"},{"en":"During the school show, dancers moved into a new formation after the chorus.","zh":"在學校表演中，舞者在副歌後走入新的隊形。"},{"en":"If one dancer moves into a new formation too late, the group shape becomes uneven.","zh":"如果一名舞者太遲走入新的隊形，整個團隊形狀會變得不平均。"},{"en":"This phrase shows that group dance requires timing and teamwork.","zh":"這個短語顯示群舞需要時間掌握和團隊合作。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"without losing the beat","meaning":"沒有失去拍子","examples":[{"en":"The team moved into a new formation without losing the beat.","zh":"隊伍走入新的隊形，沒有失去拍子。"},{"en":"Without losing the beat means without falling out of rhythm or timing.","zh":"without losing the beat 指沒有脫離節奏或時間。"},{"en":"The drummer changed speed without losing the beat.","zh":"鼓手改變速度時沒有失去拍子。"},{"en":"Dancers must travel across the stage without losing the beat.","zh":"舞者必須橫過舞台而不失去拍子。"},{"en":"This phrase shows that movement and music must stay connected.","zh":"這個短語顯示動作和音樂必須保持連繫。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"look smooth on stage","meaning":"在舞台上看起來流暢","examples":[{"en":"The routine looked smooth on stage.","zh":"那套舞蹈在舞台上看起來流暢。"},{"en":"Look smooth on stage means appear flowing, controlled and easy during performance.","zh":"look smooth on stage 指在表演時看起來流動、受控制而輕鬆。"},{"en":"The dance looked smooth on stage because the team had practised each transition.","zh":"因為隊伍練習了每個轉接，那段舞蹈在舞台上看起來流暢。"},{"en":"A routine can look smooth on stage while being exhausting to perform.","zh":"一套舞蹈可以在舞台上看起來流暢，但表演時非常疲累。"},{"en":"This phrase shows how training turns difficulty into beauty.","zh":"這個短語顯示訓練如何把困難變成美感。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"behind those thirty seconds","meaning":"在那三十秒背後","examples":[{"en":"Behind those thirty seconds were aching thighs and bruised knees.","zh":"在那三十秒背後，是痠痛的大腿和瘀傷的膝蓋。"},{"en":"Behind those thirty seconds means hidden behind that short performance time.","zh":"behind those thirty seconds 指隱藏在那短短表演時間背後。"},{"en":"Behind those thirty seconds of music were weeks of rehearsal.","zh":"在那三十秒音樂背後，是數星期的排練。"},{"en":"Behind a smooth routine may be pain, corrections and repeated practice.","zh":"流暢舞蹈背後可能是痛楚、糾正和反覆練習。"},{"en":"This phrase helps reveal effort that the audience cannot see.","zh":"這個短語幫助揭示觀眾看不見的努力。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"aching thighs","meaning":"痠痛的大腿","examples":[{"en":"Behind the performance were aching thighs and repeated corrections.","zh":"表演背後是痠痛的大腿和反覆的糾正。"},{"en":"Aching thighs are upper legs that hurt after hard physical work.","zh":"aching thighs 指在艱苦體力活動後感到疼痛的大腿。"},{"en":"After many jumps, the dancers had aching thighs the next morning.","zh":"多次跳躍後，舞者第二天早上大腿痠痛。"},{"en":"Aching thighs can show that the body has worked hard during training.","zh":"痠痛的大腿可以顯示身體在訓練中付出了很多。"},{"en":"This phrase makes the physical cost of dance concrete.","zh":"這個短語令舞蹈的身體代價變得具體。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"bruised knees","meaning":"瘀傷的膝蓋","examples":[{"en":"Behind the routine were bruised knees and aching muscles.","zh":"那套舞蹈背後是瘀傷的膝蓋和痠痛的肌肉。"},{"en":"Bruised knees are knees with dark marks or pain from being hit or pressed.","zh":"bruised knees 指因碰撞或受壓而有瘀痕或痛楚的膝蓋。"},{"en":"Floorwork can leave dancers with bruised knees after rehearsal.","zh":"地板動作可能令舞者在排練後膝蓋瘀傷。"},{"en":"Bruised knees remind us that graceful movements can involve impact.","zh":"瘀傷的膝蓋提醒我們，優雅動作也可能包含撞擊。"},{"en":"This phrase helps readers see the hidden pain behind performance.","zh":"這個短語幫助讀者看見表演背後隱藏的痛楚。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"repeated corrections","meaning":"反覆的糾正","examples":[{"en":"Repeated corrections from our coach helped us improve the routine.","zh":"教練反覆的糾正幫助我們改善那套舞蹈。"},{"en":"Repeated corrections are comments or instructions given again and again to fix mistakes.","zh":"repeated corrections 指為改正錯誤而一次又一次給出的評語或指示。"},{"en":"The coach gave repeated corrections about timing until the team moved together.","zh":"教練就時間掌握給出反覆的糾正，直到隊伍動作一致。"},{"en":"Repeated corrections can feel tiring, but they make the final performance cleaner.","zh":"反覆的糾正可能令人疲倦，但會令最後表演更乾淨。"},{"en":"This phrase shows that improvement comes from feedback and patience.","zh":"這個短語顯示進步來自回饋和耐性。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"unlike many sports","meaning":"不同於許多運動","examples":[{"en":"Unlike many sports, dance does not allow athletes to show tiredness.","zh":"不同於許多運動，舞蹈不容許運動員表現疲倦。"},{"en":"Unlike many sports means different from many other athletic activities.","zh":"unlike many sports 指與許多其他運動活動不同。"},{"en":"Unlike many sports, dance often requires performers to smile while exhausted.","zh":"不同於許多運動，舞蹈常要求表演者在疲憊時仍微笑。"},{"en":"Unlike many sports, the effort in dance must often be hidden from the audience.","zh":"不同於許多運動，舞蹈中的努力常必須對觀眾隱藏。"},{"en":"This phrase introduces an important difference between dance and other sports.","zh":"這個短語引入舞蹈與其他運動之間的重要差異。"}],"source":"2017 Q8.pdf","sourcePage":6},{"front":"show how tired they are","meaning":"表現出自己有多疲倦","examples":[{"en":"Dancers cannot show how tired they are during a performance.","zh":"舞者在表演中不能表現出自己有多疲倦。"},{"en":"Show how tired they are means let others see their exhaustion clearly.","zh":"show how tired they are 指讓別人清楚看見自己的疲憊。"},{"en":"A runner may show how tired they are by slowing down or breathing heavily.","zh":"跑手可能透過放慢速度或大口喘氣，表現出自己有多疲倦。"},{"en":"Dancers must hide how tired they are so the routine still looks controlled.","zh":"舞者必須隱藏自己有多疲倦，讓整套舞蹈仍看起來受控制。"},{"en":"This phrase shows the extra performance pressure dancers face.","zh":"這個短語顯示舞者面對額外的表演壓力。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"gasp after a race","meaning":"比賽後大口喘氣","examples":[{"en":"A swimmer may gasp after a race.","zh":"游泳健兒可能在比賽後大口喘氣。"},{"en":"Gasp after a race means breathe quickly and loudly after intense effort.","zh":"gasp after a race 指在劇烈努力後快速而大聲地呼吸。"},{"en":"Sprinters often gasp after a race because their bodies need oxygen.","zh":"短跑選手常在比賽後大口喘氣，因為身體需要氧氣。"},{"en":"In many sports, gasping after a race is accepted as proof of effort.","zh":"在許多運動中，比賽後大口喘氣被接受為努力的證明。"},{"en":"This phrase contrasts visible exhaustion with dancers’ hidden exhaustion.","zh":"這個短語把可見的疲憊與舞者隱藏的疲憊形成對比。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"finish the final pose","meaning":"完成最後定格姿勢","examples":[{"en":"A dancer must finish the final pose with control.","zh":"舞者必須有控制地完成最後定格姿勢。"},{"en":"Finish the final pose means complete the last held position of a routine.","zh":"finish the final pose 指完成整套舞蹈最後保持的姿勢。"},{"en":"Even when exhausted, dancers must finish the final pose without shaking.","zh":"即使筋疲力盡，舞者也必須完成最後定格姿勢而不發抖。"},{"en":"A strong final pose can make the whole performance feel complete.","zh":"有力的最後定格姿勢可以令整個表演感覺完整。"},{"en":"This phrase shows that control is required until the very last moment.","zh":"這個短語顯示控制力需要維持到最後一刻。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"as if","meaning":"彷彿","examples":[{"en":"A dancer must finish the final pose as if the routine has cost nothing.","zh":"舞者必須完成最後定格姿勢，彷彿整套舞蹈毫不費力。"},{"en":"As if means in a way that makes something seem true, even if it is not.","zh":"as if 指以某種方式令某事看似真實，即使未必如此。"},{"en":"She smiled as if the exam had been easy, although it was difficult.","zh":"她微笑得彷彿考試很容易，雖然其實很難。"},{"en":"Dancers perform as if they are not tired, even when their muscles hurt.","zh":"舞者表演得彷彿不累，即使肌肉疼痛。"},{"en":"This phrase shows the difference between appearance and reality.","zh":"這個短語顯示外表和現實之間的分別。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"the whole routine","meaning":"整套舞蹈","examples":[{"en":"The whole routine requires enormous strength and control.","zh":"整套舞蹈需要巨大的力量和控制。"},{"en":"The whole routine means the complete dance sequence from beginning to end.","zh":"the whole routine 指從開始到結束的完整舞蹈組合。"},{"en":"The whole routine lasted three minutes but took months to prepare.","zh":"整套舞蹈持續三分鐘，但準備了數月。"},{"en":"If one part of the whole routine is weak, the final performance may suffer.","zh":"如果整套舞蹈中有一部分薄弱，最後表演可能受影響。"},{"en":"This phrase reminds readers to judge the entire performance, not only one moment.","zh":"這個短語提醒讀者要評價整個表演，而不只是一刻。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"cost nothing","meaning":"毫不費力","examples":[{"en":"The dancer must perform as if the whole routine has cost nothing.","zh":"舞者必須表演得彷彿整套舞蹈毫不費力。"},{"en":"Cost nothing here means require no effort, pain or sacrifice.","zh":"cost nothing 在這裏指不需要努力、痛楚或犧牲。"},{"en":"The singer smiled as if the high note had cost nothing.","zh":"歌手微笑得彷彿那個高音毫不費力。"},{"en":"A dance may look as if it cost nothing, but the training behind it is exhausting.","zh":"一段舞蹈可能看似毫不費力，但背後訓練非常疲累。"},{"en":"This phrase shows how performers hide effort from the audience.","zh":"這個短語顯示表演者如何對觀眾隱藏努力。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"if anything","meaning":"甚至可以說","examples":[{"en":"If anything, dance is more demanding in a different way.","zh":"甚至可以說，舞蹈以另一種方式要求更高。"},{"en":"If anything means the truth is closer to the opposite of what someone may think.","zh":"if anything 指事實更接近某人想法的相反方向。"},{"en":"The routine was not easy; if anything, it was harder than last year’s.","zh":"那套舞蹈並不容易；甚至可以說，它比去年的更難。"},{"en":"Dance is not less athletic; if anything, it demands extra control.","zh":"舞蹈並非較不具運動性；甚至可以說，它需要額外控制。"},{"en":"This phrase is used to strengthen an argument politely.","zh":"這個短語用來禮貌地加強論點。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"more demanding","meaning":"要求更高","examples":[{"en":"Dance is more demanding than many people realise.","zh":"舞蹈比許多人意識到的要求更高。"},{"en":"More demanding means requiring more effort, skill or discipline.","zh":"more demanding 指需要更多努力、技巧或紀律。"},{"en":"Learning a language is more demanding when students must speak, write and listen every day.","zh":"當學生每天都要說、寫和聽，學語言就要求更高。"},{"en":"Dance becomes more demanding when performers must hide their tiredness.","zh":"當表演者必須隱藏疲倦，舞蹈就要求更高。"},{"en":"This phrase shows that an activity is harder than it first appears.","zh":"這個短語顯示某活動比起初看來更困難。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"in an entirely different way","meaning":"以完全不同的方式","examples":[{"en":"Dance is more demanding in an entirely different way.","zh":"舞蹈以完全不同的方式要求更高。"},{"en":"In an entirely different way means by a completely different method or form.","zh":"in an entirely different way 指以完全不同的方法或形式。"},{"en":"Swimming tests endurance, while dance is demanding in an entirely different way through control and expression.","zh":"游泳考驗耐力，而舞蹈則以控制和表達這種完全不同的方式要求很高。"},{"en":"Two subjects can both be hard, but in entirely different ways.","zh":"兩個科目都可以很難，但難在完全不同的方式。"},{"en":"This phrase helps compare without saying one thing is simply better.","zh":"這個短語有助比較，而不是簡單地說某事更好。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"a rare combination of","meaning":"罕見的……組合","examples":[{"en":"Dance requires a rare combination of flexibility, coordination and balance.","zh":"舞蹈需要柔韌性、協調能力和平衡力這種罕見組合。"},{"en":"A rare combination of means an unusual mix of qualities that do not often appear together.","zh":"a rare combination of 指不常同時出現的多種特質組合。"},{"en":"Good leadership needs a rare combination of confidence, patience and honesty.","zh":"好領袖需要自信、耐性和誠實這種罕見組合。"},{"en":"Dancers need a rare combination of strength and softness.","zh":"舞者需要力量和柔和這種罕見組合。"},{"en":"This phrase shows that dance demands several difficult abilities at once.","zh":"這個短語顯示舞蹈同時要求多種困難能力。"}],"source":"2017 Q8.pdf","sourcePage":7},{"front":"flexibility","meaning":"柔韌性","examples":[{"en":"Dance requires flexibility as well as strength.","zh":"舞蹈除了力量，也需要柔韌性。"},{"en":"Flexibility is the ability to bend, stretch or move the body easily.","zh":"flexibility 指身體容易彎曲、伸展或移動的能力。"},{"en":"Gymnasts and dancers both need flexibility to perform wide, controlled movements.","zh":"體操運動員和舞者都需要柔韌性來完成大幅度而受控的動作。"},{"en":"Without flexibility, a dancer may struggle to extend the legs fully.","zh":"沒有柔韌性，舞者可能難以完全伸展雙腿。"},{"en":"This word shows that athletic ability is not only about power.","zh":"這個詞顯示運動能力不只是關於力量。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"coordination","meaning":"協調能力","examples":[{"en":"Dancers need excellent coordination to control different body parts.","zh":"舞者需要出色的協調能力來控制不同身體部位。"},{"en":"Coordination is the ability to make body parts work together smoothly.","zh":"coordination 指令身體部位順暢配合的能力。"},{"en":"A drummer needs coordination to move hands and feet in different rhythms.","zh":"鼓手需要協調能力，讓手腳以不同節奏移動。"},{"en":"Dancers use coordination when arms, legs, head and eyes move together correctly.","zh":"舞者在手臂、腿、頭和眼睛正確配合移動時，就是在使用協調能力。"},{"en":"This word shows that dance depends on organised movement.","zh":"這個詞顯示舞蹈依賴有組織的動作。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"balance","meaning":"平衡力","examples":[{"en":"Dancers need balance when they turn, leap and land.","zh":"舞者在轉身、跳躍和落地時需要平衡力。"},{"en":"Balance is the ability to stay steady without falling.","zh":"balance 指保持穩定而不跌倒的能力。"},{"en":"A dancer standing on one leg needs strong balance.","zh":"單腳站立的舞者需要強大平衡力。"},{"en":"Poor balance can ruin a turn or make a landing dangerous.","zh":"平衡力差可以毀掉一個轉身動作，或令落地變得危險。"},{"en":"This word shows that dance requires control even during fast movement.","zh":"這個詞顯示舞蹈即使在快速移動中也需要控制。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"spatial awareness","meaning":"空間感","examples":[{"en":"Group performances require strong spatial awareness.","zh":"群舞表演需要強烈的空間感。"},{"en":"Spatial awareness is the ability to know where your body is in relation to people and space around you.","zh":"spatial awareness 指知道自己身體與周圍人物和空間關係的能力。"},{"en":"Dancers need spatial awareness so they do not crash into teammates.","zh":"舞者需要空間感，才不會撞到隊友。"},{"en":"Drivers also need spatial awareness when parking in a narrow space.","zh":"司機在狹窄位置泊車時也需要空間感。"},{"en":"This phrase shows that dance requires awareness beyond one’s own body.","zh":"這個短語顯示舞蹈需要不只關注自己的身體。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"not only…, but also…","meaning":"不但……，而且……","examples":[{"en":"A dancer has to know not only what their body is doing, but also where others are moving.","zh":"舞者不但要知道自己身體正在做甚麼，而且要知道其他人正移向哪裏。"},{"en":"Not only A, but also B means both A and B are important.","zh":"not only A, but also B 指 A 和 B 都重要。"},{"en":"A team captain needs not only skill, but also patience.","zh":"隊長不但需要技巧，而且需要耐性。"},{"en":"Dancers need to think not only about timing, but also about spacing.","zh":"舞者不但要思考時間掌握，而且要思考走位距離。"},{"en":"This structure helps writers add a second important idea.","zh":"這個結構幫助作者加入第二個重要想法。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"what their own body is doing","meaning":"自己身體正在做甚麼","examples":[{"en":"Dancers must know what their own body is doing.","zh":"舞者必須知道自己身體正在做甚麼。"},{"en":"What their own body is doing means how each part of their body is moving or positioned.","zh":"what their own body is doing 指身體每一部分如何移動或擺放。"},{"en":"A dancer must know what her own body is doing during a turn.","zh":"舞者在轉身時必須知道自己身體正在做甚麼。"},{"en":"If performers do not know what their own body is doing, they may lose control.","zh":"如果表演者不知道自己身體正在做甚麼，他們可能失去控制。"},{"en":"This phrase shows the need for body awareness.","zh":"這個短語顯示對身體意識的需要。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"where every teammate is moving","meaning":"每位隊友正移向哪裏","examples":[{"en":"Dancers must know where every teammate is moving.","zh":"舞者必須知道每位隊友正移向哪裏。"},{"en":"Where every teammate is moving means the direction and position of each person in the group.","zh":"where every teammate is moving 指團隊中每個人的方向和位置。"},{"en":"In group dance, knowing where every teammate is moving prevents collisions.","zh":"在群舞中，知道每位隊友正移向哪裏可以避免碰撞。"},{"en":"If one dancer forgets where every teammate is moving, the formation can break.","zh":"如果一名舞者忘記每位隊友正移向哪裏，隊形可能崩散。"},{"en":"This phrase shows that dance is a team activity, not only a solo display.","zh":"這個短語顯示舞蹈是團隊活動，而不只是個人展示。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"a group performance","meaning":"群舞表演","examples":[{"en":"In a group performance, one small mistake can affect everyone.","zh":"在群舞表演中，一個小錯誤可以影響所有人。"},{"en":"A group performance is a show done by several performers together.","zh":"group performance 指由多名表演者一起完成的演出。"},{"en":"A group performance requires timing because everyone must move as one team.","zh":"群舞表演需要時間掌握，因為每個人都必須像一隊般移動。"},{"en":"If one dancer stands in the wrong place, the group performance may look uneven.","zh":"如果一名舞者站錯位置，群舞表演可能看起來不平均。"},{"en":"This phrase highlights teamwork and shared responsibility.","zh":"這個短語突出團隊合作和共同責任。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"travel too far forward","meaning":"向前移動得太多","examples":[{"en":"If one person travels too far forward, the formation changes.","zh":"如果一個人向前移動得太多，隊形就會改變。"},{"en":"Travel too far forward means move farther toward the front than planned.","zh":"travel too far forward 指比計劃中更向前移動。"},{"en":"A dancer who travels too far forward may block another performer.","zh":"向前移動得太多的舞者可能擋住另一名表演者。"},{"en":"In formation work, travelling too far forward can make the line look uneven.","zh":"在隊形訓練中，向前移動得太多可以令線條不平均。"},{"en":"This phrase shows how small spacing mistakes affect the whole group.","zh":"這個短語顯示細小走位錯誤如何影響整個團隊。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"half a beat late","meaning":"慢了半拍","examples":[{"en":"If one dancer turns half a beat late, the whole formation changes.","zh":"如果一名舞者轉身慢了半拍，整個隊形就會改變。"},{"en":"Half a beat late means slightly behind the music’s timing.","zh":"half a beat late 指比音樂拍子稍微慢了一點。"},{"en":"A dancer who enters half a beat late can make the group look untidy.","zh":"進場慢了半拍的舞者可以令團隊看起來不整齊。"},{"en":"In fast music, being half a beat late is easy for the audience to notice.","zh":"在快音樂中，慢了半拍很容易被觀眾看見。"},{"en":"This phrase shows how exact timing must be in dance.","zh":"這個短語顯示舞蹈中的時間掌握必須多精確。"}],"source":"2017 Q8.pdf","sourcePage":8},{"front":"the whole formation","meaning":"整個隊形","examples":[{"en":"One late turn can change the whole formation.","zh":"一個遲了的轉身可以改變整個隊形。"},{"en":"The whole formation means the complete shape or arrangement of the group.","zh":"the whole formation 指團隊完整的形狀或排列。"},{"en":"The whole formation looked like a triangle before the dancers moved again.","zh":"在舞者再次移動前，整個隊形看起來像三角形。"},{"en":"If one person stands too far left, the whole formation may look wrong.","zh":"如果一個人站得太左，整個隊形可能看起來不對。"},{"en":"This phrase shows that every dancer affects the group picture.","zh":"這個短語顯示每位舞者都影響整體畫面。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"be similar to","meaning":"與……相似","examples":[{"en":"This is similar to basketball teamwork.","zh":"這與籃球團隊合作相似。"},{"en":"Be similar to means be like something in an important way.","zh":"be similar to 指在某個重要方面與某事相像。"},{"en":"Dance spacing is similar to basketball positioning because both require awareness of others.","zh":"舞蹈走位與籃球站位相似，因為兩者都需要留意其他人。"},{"en":"Group study is similar to team sport when everyone has a role.","zh":"小組溫習與團隊運動相似，因為每個人都有角色。"},{"en":"This phrase helps compare two different things clearly.","zh":"這個短語幫助清楚比較兩種不同事物。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"basketball teamwork","meaning":"籃球團隊合作","examples":[{"en":"Dance requires teamwork similar to basketball teamwork.","zh":"舞蹈需要與籃球團隊合作相似的合作。"},{"en":"Basketball teamwork means players passing, moving, defending and making decisions together.","zh":"basketball teamwork 指球員一起傳球、移動、防守和作決定。"},{"en":"Good basketball teamwork helps a team score even when no single player is the star.","zh":"良好的籃球團隊合作令球隊即使沒有單一明星球員也能得分。"},{"en":"Dance is like basketball teamwork because each person’s movement affects others.","zh":"舞蹈像籃球團隊合作，因為每個人的動作都影響其他人。"},{"en":"This phrase helps readers understand dance through a familiar sport.","zh":"這個短語幫助讀者透過熟悉的運動理解舞蹈。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"according to others","meaning":"按照其他人的動作","examples":[{"en":"Each player must pass, defend and move according to others.","zh":"每位球員都必須按照其他人的動作傳球、防守和移動。"},{"en":"According to others means based on what other people are doing.","zh":"according to others 指根據其他人正在做的事。"},{"en":"In a group dance, performers move according to others to keep spacing correct.","zh":"在群舞中，表演者按照其他人的動作移動，以保持正確距離。"},{"en":"A basketball player passes according to others’ positions on the court.","zh":"籃球員會按照其他人在球場上的位置傳球。"},{"en":"This phrase shows that teamwork requires constant attention.","zh":"這個短語顯示團隊合作需要持續留意。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"the same applies to","meaning":"同樣適用於","examples":[{"en":"The same applies to dancers.","zh":"同樣也適用於舞者。"},{"en":"The same applies to means the same idea is also true for another person or situation.","zh":"the same applies to 指同一個想法也適用於另一個人或情況。"},{"en":"Students need discipline, and the same applies to athletes.","zh":"學生需要紀律，這同樣適用於運動員。"},{"en":"Basketball players must watch teammates; the same applies to dancers in a formation.","zh":"籃球員必須留意隊友；這同樣適用於隊形中的舞者。"},{"en":"This phrase connects one example to another clearly.","zh":"這個短語清楚地把一個例子連接到另一個例子。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"count music","meaning":"數音樂拍子","examples":[{"en":"Dancers count music like athletes read the game.","zh":"舞者數音樂拍子，就像運動員判讀比賽形勢。"},{"en":"Count music means follow the beats in music by numbering them in your head or aloud.","zh":"count music 指在心裏或口中數拍子來跟隨音樂。"},{"en":"Dancers count music as “one, two, three, four” to stay together.","zh":"舞者數「一、二、三、四」的音樂拍子，以保持一致。"},{"en":"If dancers cannot count music, they may enter too early or too late.","zh":"如果舞者不能數音樂拍子，可能會太早或太遲進入動作。"},{"en":"This phrase shows how dancers use rhythm like a guide.","zh":"這個短語顯示舞者如何把節奏當作指引。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"read the game","meaning":"判讀比賽形勢","examples":[{"en":"Athletes read the game and react quickly.","zh":"運動員判讀比賽形勢並迅速反應。"},{"en":"Read the game means understand what is happening in a match and predict what may happen next.","zh":"read the game 指理解比賽中正在發生甚麼，並預測接下來可能發生甚麼。"},{"en":"A good footballer reads the game before passing the ball.","zh":"好足球員在傳球前會判讀比賽形勢。"},{"en":"Dancers also read the performance by noticing spacing, timing and mistakes.","zh":"舞者也會透過留意走位、時間和錯誤來判讀表演情況。"},{"en":"This phrase shows mental skill, not only physical action.","zh":"這個短語顯示心理技巧，而不只是身體動作。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"react to pressure","meaning":"應對壓力","examples":[{"en":"Dancers react to pressure during live performances.","zh":"舞者在現場表演中應對壓力。"},{"en":"React to pressure means respond when stress, difficulty or urgency appears.","zh":"react to pressure 指在壓力、困難或緊急情況出現時作出反應。"},{"en":"A goalkeeper must react to pressure when the ball comes suddenly.","zh":"當球突然射來，守門員必須應對壓力。"},{"en":"Dancers react to pressure when music continues after someone makes a mistake.","zh":"當有人出錯但音樂繼續，舞者必須應對壓力。"},{"en":"This phrase shows that performance requires quick decisions under stress.","zh":"這個短語顯示表演需要在壓力下快速決定。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"adjust to mistakes","meaning":"因應錯誤作出調整","examples":[{"en":"Dancers must adjust to mistakes instantly.","zh":"舞者必須立即因應錯誤作出調整。"},{"en":"Adjust to mistakes means change your action quickly after something goes wrong.","zh":"adjust to mistakes 指在出錯後快速改變自己的行動。"},{"en":"If one dancer slips, others may adjust to the mistake by changing spacing.","zh":"如果一名舞者滑倒，其他人可能透過改變距離來因應錯誤作出調整。"},{"en":"Students adjust to mistakes when they correct an answer after feedback.","zh":"學生在收到回饋後改正答案，就是因應錯誤作出調整。"},{"en":"This phrase shows flexibility and quick thinking.","zh":"這個短語顯示靈活性和快速思考。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"carry on instantly","meaning":"立即繼續","examples":[{"en":"Dancers have to carry on instantly after a mistake.","zh":"舞者出錯後必須立即繼續。"},{"en":"Carry on instantly means continue immediately without stopping.","zh":"carry on instantly 指毫不停下來地立刻繼續。"},{"en":"If the music skips, performers must carry on instantly and stay calm.","zh":"如果音樂跳了一下，表演者必須立即繼續並保持冷靜。"},{"en":"A speaker who forgets one sentence should carry on instantly instead of freezing.","zh":"演講者忘記一句話時，應立即繼續，而不是僵住。"},{"en":"This phrase shows resilience during performance.","zh":"這個短語顯示表演中的韌性。"}],"source":"2017 Q8.pdf","sourcePage":9},{"front":"physical beauty","meaning":"身體美感","examples":[{"en":"Physical beauty is only the surface of dance.","zh":"身體美感只是舞蹈的表面。"},{"en":"Physical beauty means the attractive appearance of the body and movement.","zh":"physical beauty 指身體和動作所呈現的吸引外觀。"},{"en":"A dancer’s physical beauty may come from posture, line and control.","zh":"舞者的身體美感可能來自姿勢、線條和控制。"},{"en":"Physical beauty can impress the audience, but it does not show all the training.","zh":"身體美感可以打動觀眾，但不能顯示全部訓練。"},{"en":"This phrase separates appearance from deeper athletic skill.","zh":"這個短語把外觀與更深層的運動技巧分開。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"only the surface","meaning":"只是表面","examples":[{"en":"Physical beauty is only the surface.","zh":"身體美感只是表面。"},{"en":"Only the surface means only the visible outer part, not the deeper truth.","zh":"only the surface 指只是看得見的外層部分，而不是更深層的真相。"},{"en":"Good grades are only the surface if they hide stress and exhaustion.","zh":"如果好成績隱藏了壓力和疲憊，那它們只是表面。"},{"en":"Graceful dancing is only the surface of years of training.","zh":"優雅舞蹈只是多年訓練的表面。"},{"en":"This phrase encourages readers to look deeper.","zh":"這個短語鼓勵讀者看得更深。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"underneath it lies","meaning":"其背後是","examples":[{"en":"Underneath it lies athletic precision.","zh":"其背後是運動員般的精準。"},{"en":"Underneath it lies means hidden below the surface is something important.","zh":"underneath it lies 指表面之下隱藏着重要的東西。"},{"en":"Underneath the quiet classroom lies weeks of exam pressure.","zh":"安靜課室背後是數星期的考試壓力。"},{"en":"Underneath a smooth performance lies hard training and discipline.","zh":"流暢表演背後是艱苦訓練和紀律。"},{"en":"This phrase reveals the deeper truth behind appearance.","zh":"這個短語揭示外表背後更深層的真相。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"athletic precision","meaning":"運動員般的精準","examples":[{"en":"Underneath the beauty of dance lies athletic precision.","zh":"舞蹈的美感背後，是運動員般的精準。"},{"en":"Athletic precision means exact physical control like that required in sport.","zh":"athletic precision 指像運動中所需的精確身體控制。"},{"en":"A diver needs athletic precision to enter the water cleanly.","zh":"跳水運動員需要運動員般的精準，才能乾淨入水。"},{"en":"Dancers show athletic precision when they turn together on the same beat.","zh":"當舞者在同一拍一起轉身，就是展現運動員般的精準。"},{"en":"This phrase proves that dance requires both sport-level accuracy and beauty.","zh":"這個短語證明舞蹈需要運動級準確度和美感。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, dancers are athletes because their progress depends on training.","zh":"更重要的是，舞者是運動員，因為他們的進步取決於訓練。"},{"en":"More importantly means this next point matters even more.","zh":"more importantly 指接下來這一點更加重要。"},{"en":"The shoes look good; more importantly, they protect the dancer’s feet.","zh":"那雙鞋看起來好看；更重要的是，它保護舞者的腳。"},{"en":"Dance is beautiful; more importantly, it requires training and discipline.","zh":"舞蹈很美；更重要的是，它需要訓練和紀律。"},{"en":"This phrase helps introduce a stronger argument.","zh":"這個短語幫助引入更有力的論點。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"progress depends on","meaning":"進步取決於","examples":[{"en":"A dancer’s progress depends on disciplined training.","zh":"舞者的進步取決於有紀律的訓練。"},{"en":"Progress depends on means improvement is caused by or relies on something.","zh":"progress depends on 指進步由某事造成或依賴某事。"},{"en":"A student’s progress depends on regular practice and honest feedback.","zh":"學生的進步取決於定期練習和真誠回饋。"},{"en":"A dancer’s progress depends on stretching, strengthening and repetition.","zh":"舞者的進步取決於拉筋、強化訓練和重複。"},{"en":"This phrase shows what makes improvement possible.","zh":"這個短語顯示甚麼令進步成為可能。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"disciplined training","meaning":"有紀律的訓練","examples":[{"en":"Dancers improve through disciplined training.","zh":"舞者透過有紀律的訓練進步。"},{"en":"Disciplined training means regular, controlled practice done with focus and responsibility.","zh":"disciplined training 指專注而負責任地進行定期、受控的練習。"},{"en":"Disciplined training helps athletes build skill without forming bad habits.","zh":"有紀律的訓練幫助運動員建立技巧，而不形成壞習慣。"},{"en":"Dancers need disciplined training to improve timing, strength and safety.","zh":"舞者需要有紀律的訓練來改善時間掌握、力量和安全。"},{"en":"This phrase shows that success comes from organised effort.","zh":"這個短語顯示成功來自有組織的努力。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"neither…nor…","meaning":"既不是……也不是……","examples":[{"en":"Success in dance is neither luck nor natural talent alone.","zh":"舞蹈成功既不是運氣，也不是單靠天賦。"},{"en":"Neither A nor B means not A and not B.","zh":"neither A nor B 指不是 A，也不是 B。"},{"en":"Good teamwork is neither shouting nor blaming others.","zh":"良好團隊合作既不是大喊，也不是責怪別人。"},{"en":"Dance success is neither instant nor easy; it is built through practice.","zh":"舞蹈成功既不是即時的，也不是容易的；它是透過練習建立的。"},{"en":"This structure helps reject two wrong explanations at once.","zh":"這個結構幫助同時否定兩個錯誤解釋。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"natural talent alone","meaning":"單靠天賦","examples":[{"en":"Dance is not about natural talent alone.","zh":"舞蹈不是單靠天賦。"},{"en":"Natural talent alone means ability someone is born with, without enough training or discipline.","zh":"natural talent alone 指只依靠天生能力，而沒有足夠訓練或紀律。"},{"en":"A naturally flexible dancer still cannot succeed through natural talent alone.","zh":"天生柔韌的舞者仍不能單靠天賦成功。"},{"en":"Natural talent alone may start a journey, but practice carries it forward.","zh":"單靠天賦也許能開始旅程，但練習才能推動它前進。"},{"en":"This phrase shows that talent needs effort to become achievement.","zh":"這個短語顯示天分需要努力才能變成成就。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"fundamentally","meaning":"從根本上來說","examples":[{"en":"Fundamentally, discipline determines long-term success.","zh":"從根本上來說，紀律決定長遠成功。"},{"en":"Fundamentally means at the most basic or important level.","zh":"fundamentally 指在最基本或最重要的層面上。"},{"en":"Fundamentally, a team succeeds when members trust one another.","zh":"從根本上來說，隊伍成功是因為成員互相信任。"},{"en":"Fundamentally, dance is built on repeated practice and control.","zh":"從根本上來說，舞蹈建立在反覆練習和控制之上。"},{"en":"This word introduces the deepest reason behind an argument.","zh":"這個詞引入論點背後最深層的原因。"}],"source":"2017 Q8.pdf","sourcePage":10},{"front":"determine long-term success","meaning":"決定長遠成功","examples":[{"en":"Discipline determines long-term success in dance.","zh":"在舞蹈中，紀律決定長遠成功。"},{"en":"Determine long-term success means decide whether someone succeeds over a long period.","zh":"determine long-term success 指決定某人能否在長時間內成功。"},{"en":"Daily habits often determine long-term success more than one lucky result.","zh":"日常習慣常比一次幸運結果更能決定長遠成功。"},{"en":"In dance, training and self-control determine long-term success.","zh":"在舞蹈中，訓練和自我控制決定長遠成功。"},{"en":"This phrase focuses on lasting achievement, not short-term praise.","zh":"這個短語關注持久成就，而不是短期讚賞。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"rather than mere talent","meaning":"而不是單靠天分","examples":[{"en":"Discipline determines success rather than mere talent.","zh":"紀律決定成功，而不是單靠天分。"},{"en":"Rather than mere talent means instead of only natural ability.","zh":"rather than mere talent 指不是只依靠天生能力。"},{"en":"A student improves through revision rather than mere talent.","zh":"學生透過溫習進步，而不是單靠天分。"},{"en":"Dancers succeed through training rather than mere talent because technique must be built.","zh":"舞者靠訓練成功，而不是單靠天分，因為技巧必須建立。"},{"en":"This phrase contrasts effort with the idea of effortless ability.","zh":"這個短語把努力與毫不費力的能力觀念形成對比。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"final performance","meaning":"最後演出","examples":[{"en":"Many people see the final performance but not the training behind it.","zh":"許多人看見最後演出，卻看不見背後的訓練。"},{"en":"The final performance is the finished show seen by the audience.","zh":"final performance 指觀眾看到的完成版表演。"},{"en":"The final performance may last only minutes, but preparation can take months.","zh":"最後演出可能只持續數分鐘，但準備可以花數月。"},{"en":"Viewers may praise the final performance without knowing the injuries and corrections behind it.","zh":"觀眾可能稱讚最後演出，卻不知道背後的傷痛和糾正。"},{"en":"This phrase contrasts visible results with hidden preparation.","zh":"這個短語把可見成果與隱藏準備形成對比。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"repeated stretching","meaning":"反覆拉筋","examples":[{"en":"Repeated stretching is part of a dancer’s training.","zh":"反覆拉筋是舞者訓練的一部分。"},{"en":"Repeated stretching means stretching the muscles again and again to improve flexibility safely.","zh":"repeated stretching 指一次又一次伸展肌肉，以安全地改善柔韌性。"},{"en":"Dancers do repeated stretching before difficult kicks and extensions.","zh":"舞者在困難踢腿和伸展動作前會反覆拉筋。"},{"en":"Repeated stretching can prevent injury when it is done carefully.","zh":"如果小心進行，反覆拉筋可以預防受傷。"},{"en":"This phrase shows that flexibility is trained, not simply given.","zh":"這個短語顯示柔韌性是訓練出來的，不是單純天生的。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"strengthening and drilling","meaning":"強化訓練和反覆操練","examples":[{"en":"Strengthening and drilling come before the final performance.","zh":"強化訓練和反覆操練出現在最後演出之前。"},{"en":"Strengthening and drilling means building physical power and repeating skills many times.","zh":"strengthening and drilling 指建立身體力量，並多次重複技巧。"},{"en":"Athletes use strengthening and drilling to prepare the body for competition.","zh":"運動員透過強化訓練和反覆操練，為比賽準備身體。"},{"en":"Dancers do strengthening and drilling so movements become safer and cleaner.","zh":"舞者進行強化訓練和反覆操練，令動作更安全、更乾淨。"},{"en":"This phrase shows the serious preparation behind performance.","zh":"這個短語顯示表演背後嚴肅的準備。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"before competitions","meaning":"比賽前","examples":[{"en":"Before competitions, our team often rehearses after lessons.","zh":"比賽前，我們隊常在放學後排練。"},{"en":"Before competitions means in the period leading up to contests or events.","zh":"before competitions 指在比賽或活動來臨前的時段。"},{"en":"Before competitions, dancers practise more often to improve confidence.","zh":"比賽前，舞者更頻繁練習以提升信心。"},{"en":"Athletes may eat carefully and sleep earlier before competitions.","zh":"運動員比賽前可能小心飲食並早點睡覺。"},{"en":"This phrase shows preparation for an important challenge.","zh":"這個短語顯示為重要挑戰作準備。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"school shows","meaning":"學校表演","examples":[{"en":"Our team rehearses hard before competitions and school shows.","zh":"我們隊在比賽和學校表演前努力排練。"},{"en":"School shows are performances organised by or held at school.","zh":"school shows 指由學校組織或在學校舉行的表演。"},{"en":"A school show may include dance, drama, music and speeches.","zh":"學校表演可能包括舞蹈、戲劇、音樂和演講。"},{"en":"Dancers prepare seriously for school shows because classmates and teachers are watching.","zh":"舞者認真準備學校表演，因為同學和老師都在觀看。"},{"en":"This phrase shows that school performances can still require real effort.","zh":"這個短語顯示學校表演也可以需要真正努力。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"rehearse after lessons","meaning":"放學後排練","examples":[{"en":"Our team often rehearses after lessons.","zh":"我們隊常在放學後排練。"},{"en":"Rehearse after lessons means practise a performance after the school day’s classes.","zh":"rehearse after lessons 指在一天課堂結束後練習表演。"},{"en":"Students who rehearse after lessons must manage homework and rest carefully.","zh":"放學後排練的學生必須小心安排功課和休息。"},{"en":"A dance team may rehearse after lessons for weeks before a show.","zh":"舞蹈隊可能在表演前數星期放學後排練。"},{"en":"This phrase shows the sacrifice of free time.","zh":"這個短語顯示對自由時間的犧牲。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"practise the same eight counts","meaning":"反覆練習同樣八拍","examples":[{"en":"We practise the same eight counts again and again.","zh":"我們一次又一次反覆練習同樣八拍。"},{"en":"Practise the same eight counts means repeat one short eight-beat section of dance many times.","zh":"practise the same eight counts 指多次重複一小段八拍舞蹈。"},{"en":"Dancers practise the same eight counts until everyone turns together.","zh":"舞者反覆練習同樣八拍，直到所有人一起轉身。"},{"en":"Practising the same eight counts can feel boring, but it improves timing.","zh":"反覆練習同樣八拍可能沉悶，但能改善時間掌握。"},{"en":"This phrase shows how small details are perfected through repetition.","zh":"這個短語顯示細節如何透過重複被完善。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"again and again","meaning":"一次又一次","examples":[{"en":"We practise the same movements again and again.","zh":"我們一次又一次練習同樣的動作。"},{"en":"Again and again means repeatedly, many times.","zh":"again and again 指反覆地、很多次。"},{"en":"The pianist played the difficult line again and again until it sounded smooth.","zh":"鋼琴家一次又一次彈那段困難旋律，直到它聽起來流暢。"},{"en":"Dancers repeat steps again and again so the body remembers them.","zh":"舞者一次又一次重複步伐，讓身體記住它們。"},{"en":"This phrase shows patience and repeated effort.","zh":"這個短語顯示耐性和反覆努力。"}],"source":"2017 Q8.pdf","sourcePage":11},{"front":"timing becomes automatic","meaning":"時間掌握變成自然反應","examples":[{"en":"We repeat the steps until the timing becomes automatic.","zh":"我們重複步伐，直到時間掌握變成自然反應。"},{"en":"Timing becomes automatic means the body follows the correct rhythm without conscious effort.","zh":"timing becomes automatic 指身體不用刻意思考也能跟隨正確節奏。"},{"en":"After enough practice, a drummer’s timing becomes automatic.","zh":"經過足夠練習後，鼓手的時間掌握會變成自然反應。"},{"en":"Dancers repeat counts so timing becomes automatic under pressure.","zh":"舞者重複數拍子，令時間掌握在壓力下也變成自然反應。"},{"en":"This phrase shows how practice turns thinking into instinct.","zh":"這個短語顯示練習如何把思考變成本能。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"step onto the stage","meaning":"踏上舞台","examples":[{"en":"By the time we step onto the stage, the routine is already in our muscles.","zh":"到我們踏上舞台時，那套舞蹈已經在我們的肌肉裏。"},{"en":"Step onto the stage means walk onto the performance area in front of an audience.","zh":"step onto the stage 指走上觀眾面前的表演區域。"},{"en":"Dancers feel nervous before they step onto the stage.","zh":"舞者踏上舞台前會感到緊張。"},{"en":"When performers step onto the stage, preparation must turn into action.","zh":"當表演者踏上舞台，準備就必須轉化成行動。"},{"en":"This phrase marks the moment practice becomes performance.","zh":"這個短語標示練習變成表演的一刻。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"through enormous effort and sacrifice","meaning":"經過巨大努力和犧牲","examples":[{"en":"The routine is built into our muscles through enormous effort and sacrifice.","zh":"那套舞蹈經過巨大努力和犧牲，已經成為我們的肌肉記憶。"},{"en":"Through enormous effort and sacrifice means by working very hard and giving up time, comfort or other things.","zh":"through enormous effort and sacrifice 指透過非常努力，並放棄時間、舒適或其他事物。"},{"en":"Athletes improve through enormous effort and sacrifice over many months.","zh":"運動員經過數月巨大努力和犧牲而進步。"},{"en":"Dancers learn routines through enormous effort and sacrifice after school and on weekends.","zh":"舞者在放學後和週末經過巨大努力和犧牲學會舞蹈套路。"},{"en":"This phrase shows that achievement has a real cost.","zh":"這個短語顯示成就有真正代價。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"be built into our muscles","meaning":"已經成為肌肉記憶","examples":[{"en":"By the time we perform, the routine has already been built into our muscles.","zh":"到我們表演時，那套舞蹈已經成為我們的肌肉記憶。"},{"en":"Be built into our muscles means repeated practice has made the body remember the movement.","zh":"be built into our muscles 指反覆練習令身體記住動作。"},{"en":"After weeks of training, the footwork was built into the players’ muscles.","zh":"經過數星期訓練後，步法已經成為球員的肌肉記憶。"},{"en":"Dancers repeat steps until the routine is built into their muscles.","zh":"舞者重複步伐，直到整套舞蹈成為肌肉記憶。"},{"en":"This phrase describes muscle memory created by practice.","zh":"這個短語描述由練習建立的肌肉記憶。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"demand mental toughness","meaning":"需要心理韌性","examples":[{"en":"This training also demands mental toughness.","zh":"這種訓練也需要心理韌性。"},{"en":"Demand mental toughness means require the ability to stay strong under stress, failure or pain.","zh":"demand mental toughness 指需要在壓力、失敗或痛楚下保持堅強的能力。"},{"en":"Long rehearsals demand mental toughness because dancers must keep trying after mistakes.","zh":"長時間排練需要心理韌性，因為舞者出錯後仍要繼續嘗試。"},{"en":"Exams also demand mental toughness when students feel tired or disappointed.","zh":"當學生感到疲倦或失望時，考試也需要心理韌性。"},{"en":"This phrase shows that training tests the mind as well as the body.","zh":"這個短語顯示訓練考驗心理，也考驗身體。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"mental toughness","meaning":"心理韌性","examples":[{"en":"Dancers need mental toughness as well as physical strength.","zh":"舞者除了體能力量，也需要心理韌性。"},{"en":"Mental toughness is the ability to stay focused, brave and determined under pressure.","zh":"mental toughness 指在壓力下保持專注、勇敢和堅定的能力。"},{"en":"A runner shows mental toughness by finishing a race despite pain.","zh":"跑手即使痛楚仍完成比賽，就是展現心理韌性。"},{"en":"Dancers use mental toughness when they return after criticism or injury.","zh":"舞者在批評或受傷後仍回來練習，就是運用心理韌性。"},{"en":"This phrase shows that athletes need inner strength too.","zh":"這個短語顯示運動員也需要內在力量。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"There are days when","meaning":"有些日子","examples":[{"en":"There are days when the mirror feels cruel.","zh":"有些日子，鏡子顯得殘酷。"},{"en":"There are days when means sometimes, on certain difficult days.","zh":"there are days when 指有時候，在某些困難日子裏。"},{"en":"There are days when practice feels endless and progress feels invisible.","zh":"有些日子，練習感覺沒完沒了，進步也看不見。"},{"en":"There are days when students study hard but still feel unprepared.","zh":"有些日子，學生努力溫習，卻仍感到未準備好。"},{"en":"This phrase introduces a realistic difficulty rather than a perfect story.","zh":"這個短語引入真實困難，而不是完美故事。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"the mirror feels cruel","meaning":"鏡子顯得殘酷","examples":[{"en":"There are days when the mirror feels cruel.","zh":"有些日子，鏡子顯得殘酷。"},{"en":"The mirror feels cruel means looking at yourself makes every mistake seem painfully clear.","zh":"the mirror feels cruel 指看着自己時，每個錯誤都痛苦地清楚。"},{"en":"During rehearsal, the mirror feels cruel when a dancer keeps seeing poor posture.","zh":"排練時，如果舞者不斷看見姿勢不佳，鏡子就會顯得殘酷。"},{"en":"The mirror can feel cruel because it reflects mistakes without kindness.","zh":"鏡子可能顯得殘酷，因為它不帶安慰地反映錯誤。"},{"en":"This phrase describes self-criticism in a vivid way.","zh":"這個短語生動地描述自我批評。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"refuse to cooperate","meaning":"不肯配合","examples":[{"en":"There are days when the body refuses to cooperate.","zh":"有些日子，身體不肯配合。"},{"en":"Refuse to cooperate means not work as expected, even when you try.","zh":"refuse to cooperate 指即使你努力，也不能如預期般運作。"},{"en":"A dancer’s body may refuse to cooperate when muscles are tired.","zh":"當肌肉疲倦時，舞者的身體可能不肯配合。"},{"en":"During illness, even simple schoolwork can feel as if the brain refuses to cooperate.","zh":"生病時，即使簡單功課也可能感覺大腦不肯配合。"},{"en":"This phrase shows frustration when effort does not produce control.","zh":"這個短語顯示努力未能帶來控制時的挫敗。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"criticism from the coach","meaning":"教練的批評","examples":[{"en":"Criticism from the coach may sound sharper than usual.","zh":"教練的批評可能聽起來比平日更刺耳。"},{"en":"Criticism from the coach means feedback or correction given by the trainer.","zh":"criticism from the coach 指教練給出的回饋或糾正。"},{"en":"Criticism from the coach can help dancers fix mistakes before a competition.","zh":"教練的批評可以幫助舞者在比賽前改正錯誤。"},{"en":"Even useful criticism from the coach may hurt when a dancer is tired.","zh":"即使教練的批評有用，當舞者疲倦時也可能令人受傷。"},{"en":"This phrase shows that training involves emotional pressure too.","zh":"這個短語顯示訓練也包含情緒壓力。"}],"source":"2017 Q8.pdf","sourcePage":12},{"front":"sound sharper than usual","meaning":"聽起來比平日更刺耳","examples":[{"en":"Criticism from the coach can sound sharper than usual.","zh":"教練的批評可能聽起來比平日更刺耳。"},{"en":"Sound sharper than usual means seem more hurtful, severe or direct than normal.","zh":"sound sharper than usual 指聽起來比平常更傷人、更嚴厲或更直接。"},{"en":"A teacher’s advice may sound sharper than usual when students are already stressed.","zh":"當學生已經有壓力，老師的建議可能聽起來比平日更刺耳。"},{"en":"After a bad rehearsal, even small corrections can sound sharper than usual.","zh":"在一次差劣排練後，即使小小糾正也可能聽起來比平日更刺耳。"},{"en":"This phrase explains how mood changes the way words feel.","zh":"這個短語解釋心情如何改變語言的感覺。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"return the next day","meaning":"第二天再回來","examples":[{"en":"Still, dancers have to return the next day.","zh":"即使如此，舞者仍必須第二天再回來。"},{"en":"Return the next day means come back again on the following day.","zh":"return the next day 指在翌日再次回來。"},{"en":"After a difficult rehearsal, the team returned the next day to practise again.","zh":"經過一次困難排練後，隊伍第二天再回來繼續練習。"},{"en":"Athletes return the next day because progress requires consistency.","zh":"運動員第二天再回來，因為進步需要持續。"},{"en":"This phrase shows commitment after disappointment.","zh":"這個短語顯示失望後的承諾。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"accept corrections","meaning":"接受糾正","examples":[{"en":"Dancers learn to accept corrections.","zh":"舞者學會接受糾正。"},{"en":"Accept corrections means listen to feedback and use it to improve.","zh":"accept corrections 指聆聽回饋並用它來改善。"},{"en":"Students accept corrections when they rewrite an essay after teacher comments.","zh":"學生根據老師評語重寫文章，就是接受糾正。"},{"en":"Dancers who accept corrections improve faster than those who make excuses.","zh":"接受糾正的舞者比找藉口的人進步更快。"},{"en":"This phrase shows humility and willingness to learn.","zh":"這個短語顯示謙卑和學習意願。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"without taking them personally","meaning":"不把它們視作針對自己","examples":[{"en":"Dancers learn to accept corrections without taking them personally.","zh":"舞者學會接受糾正，而不把它們視作針對自己。"},{"en":"Without taking them personally means without feeling the comments are attacks on you as a person.","zh":"without taking them personally 指不覺得那些評語是在攻擊自己這個人。"},{"en":"A student should accept grammar corrections without taking them personally.","zh":"學生應接受文法糾正，而不把它們視作針對自己。"},{"en":"Dancers improve when they see corrections as help, not insults.","zh":"當舞者把糾正視為幫助，而不是侮辱，他們就會進步。"},{"en":"This phrase shows emotional maturity during training.","zh":"這個短語顯示訓練中的情緒成熟。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"support teammates","meaning":"支持隊友","examples":[{"en":"Dancers learn to support teammates whose confidence has dropped.","zh":"舞者學會支持信心下跌的隊友。"},{"en":"Support teammates means help, encourage and stand beside people on your team.","zh":"support teammates 指幫助、鼓勵並陪伴隊友。"},{"en":"Players support teammates after a missed goal instead of blaming them.","zh":"球員在隊友失球後支持他們，而不是責怪他們。"},{"en":"Dancers support teammates by practising together and giving calm encouragement.","zh":"舞者透過一起練習和平靜鼓勵來支持隊友。"},{"en":"This phrase shows that sport is also about care and teamwork.","zh":"這個短語顯示運動也關乎關懷和團隊合作。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"confidence has dropped","meaning":"信心下跌","examples":[{"en":"We support teammates whose confidence has dropped.","zh":"我們支持信心下跌的隊友。"},{"en":"Confidence has dropped means someone feels less sure of their ability than before.","zh":"confidence has dropped 指某人比以前更不確定自己的能力。"},{"en":"A dancer’s confidence may drop after forgetting steps on stage.","zh":"舞者在舞台上忘記步伐後，信心可能下跌。"},{"en":"When confidence has dropped, kind feedback can help a teammate recover.","zh":"當信心下跌時，友善回饋可以幫助隊友恢復。"},{"en":"This phrase shows that emotional support matters in teams.","zh":"這個短語顯示情感支持在團隊中很重要。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"practice makes perfect","meaning":"熟能生巧","examples":[{"en":"Dancers know that “practice makes perfect” is a daily discipline.","zh":"舞者知道「熟能生巧」是一種每天的紀律。"},{"en":"Practice makes perfect means repeated practice helps people improve toward excellence.","zh":"practice makes perfect 指反覆練習幫助人逐步走向出色。"},{"en":"A pianist repeats scales because practice makes perfect.","zh":"鋼琴家反覆練習音階，因為熟能生巧。"},{"en":"In dance, practice makes perfect only when the practice is careful and consistent.","zh":"在舞蹈中，只有仔細而持續的練習才能熟能生巧。"},{"en":"This phrase is common, but the essay treats it as serious work.","zh":"這個短語很常見，但文章把它視為嚴肅工作。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"a cheerful slogan","meaning":"樂觀口號","examples":[{"en":"“Practice makes perfect” is not just a cheerful slogan.","zh":"「熟能生巧」不只是一句樂觀口號。"},{"en":"A cheerful slogan is a positive phrase that sounds encouraging but may seem simple.","zh":"cheerful slogan 指聽起來鼓舞人心但可能簡單化的正面句子。"},{"en":"“Keep going” is a cheerful slogan, but it needs action behind it.","zh":"「繼續努力」是一句樂觀口號，但背後需要行動。"},{"en":"For dancers, “practice makes perfect” is more than a cheerful slogan because it requires daily effort.","zh":"對舞者來說，「熟能生巧」不只是一句樂觀口號，因為它需要每日努力。"},{"en":"This phrase contrasts easy words with difficult reality.","zh":"這個短語把容易說出口的話與困難現實形成對比。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"a daily discipline","meaning":"每天的紀律","examples":[{"en":"Practice is a daily discipline for dancers.","zh":"練習是舞者每天的紀律。"},{"en":"A daily discipline is a habit or rule followed every day with self-control.","zh":"daily discipline 指每天以自我控制遵守的習慣或規則。"},{"en":"Reading for twenty minutes can become a daily discipline for students.","zh":"每天閱讀二十分鐘可以成為學生每天的紀律。"},{"en":"For dancers, warming up and stretching are daily disciplines.","zh":"對舞者來說，熱身和拉筋是每天的紀律。"},{"en":"This phrase shows that success is built through repeated habits.","zh":"這個短語顯示成功是透過重複習慣建立的。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"sharper turn","meaning":"更俐落的轉身","examples":[{"en":"Every sharper turn is earned little by little.","zh":"每一個更俐落的轉身都是一點一滴掙回來的。"},{"en":"A sharper turn is a cleaner, quicker and more controlled spinning movement.","zh":"sharper turn 指更乾淨、更快速、更受控制的旋轉動作。"},{"en":"A dancer gets a sharper turn by strengthening the core and spotting correctly.","zh":"舞者透過強化核心和正確定點，得到更俐落的轉身。"},{"en":"Sharper turns do not appear suddenly; they come from repeated correction.","zh":"更俐落的轉身不會突然出現；它來自反覆糾正。"},{"en":"This phrase shows improvement in a specific dance skill.","zh":"這個短語顯示某項舞蹈技巧的進步。"}],"source":"2017 Q8.pdf","sourcePage":13},{"front":"cleaner line","meaning":"更乾淨俐落的線條","examples":[{"en":"Every cleaner line comes from repeated practice.","zh":"每一條更乾淨俐落的線條都來自反覆練習。"},{"en":"A cleaner line is a clearer and neater body shape in dance.","zh":"cleaner line 指舞蹈中更清楚、更整齊的身體形狀。"},{"en":"Dancers create a cleaner line by extending the legs and arms carefully.","zh":"舞者透過仔細伸展雙腿和手臂，製造更乾淨俐落的線條。"},{"en":"A cleaner line makes the movement easier for the audience to read.","zh":"更乾淨俐落的線條令觀眾更容易看懂動作。"},{"en":"This phrase shows how small technical improvements affect beauty.","zh":"這個短語顯示細小技術改善如何影響美感。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"stronger jump","meaning":"更有力的跳躍","examples":[{"en":"Every stronger jump is earned through training.","zh":"每一個更有力的跳躍都是透過訓練掙回來的。"},{"en":"A stronger jump is a jump with more power, height, control or safety.","zh":"stronger jump 指更有力量、高度、控制或安全性的跳躍。"},{"en":"Dancers build stronger jumps by training legs, core and landing technique.","zh":"舞者透過訓練腿部、核心和落地技巧，建立更有力的跳躍。"},{"en":"A stronger jump looks impressive only when it also lands safely.","zh":"更有力的跳躍只有在安全落地時才真正出色。"},{"en":"This phrase connects visible movement with hidden preparation.","zh":"這個短語把可見動作與隱藏準備連在一起。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"be earned little by little","meaning":"一點一滴掙回來","examples":[{"en":"Improvement is earned little by little.","zh":"進步是一點一滴掙回來的。"},{"en":"Be earned little by little means be gained slowly through repeated effort.","zh":"be earned little by little 指透過反覆努力慢慢得到。"},{"en":"Confidence is earned little by little when students practise speaking every week.","zh":"學生每週練習說話時，自信是一點一滴掙回來的。"},{"en":"Dancers earn better balance little by little through daily training.","zh":"舞者透過每天訓練，一點一滴掙回更好的平衡。"},{"en":"This phrase shows that progress is gradual, not sudden.","zh":"這個短語顯示進步是漸進的，而不是突然的。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"with blood, sweat and tears","meaning":"以血汗和淚水換來","examples":[{"en":"Every improvement is earned with blood, sweat and tears.","zh":"每一點進步都是以血汗和淚水換來的。"},{"en":"With blood, sweat and tears means through great effort, pain and emotional struggle.","zh":"with blood, sweat and tears 指透過巨大努力、痛楚和情緒掙扎。"},{"en":"The team prepared for the final match with blood, sweat and tears.","zh":"球隊以血汗和淚水準備最後一場比賽。"},{"en":"A polished dance routine may be built with blood, sweat and tears.","zh":"一套精緻舞蹈可能是以血汗和淚水建立的。"},{"en":"This phrase strongly emphasises sacrifice behind success.","zh":"這個短語強烈強調成功背後的犧牲。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"look after the body","meaning":"照顧身體","examples":[{"en":"Self-discipline also means looking after the body.","zh":"自律也意味着照顧身體。"},{"en":"Look after the body means care for physical health through rest, food, warm-up and safe habits.","zh":"look after the body 指透過休息、飲食、熱身和安全習慣照顧身體健康。"},{"en":"Dancers look after the body by stretching safely and sleeping enough.","zh":"舞者透過安全拉筋和充足睡眠來照顧身體。"},{"en":"Athletes who do not look after the body may get injured or lose energy.","zh":"不照顧身體的運動員可能受傷或失去精力。"},{"en":"This phrase shows that discipline includes care, not only hard work.","zh":"這個短語顯示紀律包括照顧，而不只是努力。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"warm up properly","meaning":"正確熱身","examples":[{"en":"Dancers must warm up properly before training.","zh":"舞者在訓練前必須正確熱身。"},{"en":"Warm up properly means prepare the body safely before exercise.","zh":"warm up properly 指在運動前安全地準備身體。"},{"en":"Athletes warm up properly by raising the heart rate and moving joints gently.","zh":"運動員透過提升心跳和輕柔活動關節來正確熱身。"},{"en":"If dancers do not warm up properly, muscles may be easier to injure.","zh":"如果舞者沒有正確熱身，肌肉可能更容易受傷。"},{"en":"This phrase shows a basic rule of safe training.","zh":"這個短語顯示安全訓練的基本規則。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"stretch safely","meaning":"安全地拉筋","examples":[{"en":"Dancers must stretch safely to avoid injury.","zh":"舞者必須安全地拉筋，以避免受傷。"},{"en":"Stretch safely means lengthen muscles carefully without forcing the body too far.","zh":"stretch safely 指小心伸展肌肉，而不是強迫身體過度。"},{"en":"A dancer should stretch safely instead of pushing into pain.","zh":"舞者應安全地拉筋，而不是強忍痛楚。"},{"en":"Stretching safely helps flexibility improve over time.","zh":"安全地拉筋有助柔韌性隨時間改善。"},{"en":"This phrase shows that training must protect the body.","zh":"這個短語顯示訓練必須保護身體。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"sleep enough","meaning":"睡眠充足","examples":[{"en":"Dancers need to sleep enough to recover.","zh":"舞者需要睡眠充足，才能恢復。"},{"en":"Sleep enough means get enough rest for the body and mind to repair.","zh":"sleep enough 指得到足夠休息，讓身體和大腦修復。"},{"en":"Students who sleep enough can concentrate better in class.","zh":"睡眠充足的學生在課堂上能更集中。"},{"en":"Dancers who do not sleep enough may lose strength and focus during rehearsal.","zh":"沒有睡眠充足的舞者，在排練中可能失去力量和專注。"},{"en":"This phrase shows that recovery is part of serious training.","zh":"這個短語顯示恢復是認真訓練的一部分。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"avoid careless injuries","meaning":"避免因疏忽而受傷","examples":[{"en":"Dancers must avoid careless injuries.","zh":"舞者必須避免因疏忽而受傷。"},{"en":"Avoid careless injuries means prevent injuries caused by poor attention or unsafe habits.","zh":"avoid careless injuries 指防止因不專心或不安全習慣造成的傷患。"},{"en":"Athletes avoid careless injuries by using proper equipment and technique.","zh":"運動員透過使用合適裝備和技巧，避免因疏忽而受傷。"},{"en":"Dancers avoid careless injuries when they warm up and land correctly.","zh":"舞者正確熱身和落地時，就是在避免因疏忽而受傷。"},{"en":"This phrase shows that responsibility protects performance.","zh":"這個短語顯示責任感能保護表現。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"ignore fitness","meaning":"忽視體能","examples":[{"en":"A dancer who ignores fitness soon loses stamina.","zh":"忽視體能的舞者很快會失去耐力。"},{"en":"Ignore fitness means fail to care about physical strength, health and conditioning.","zh":"ignore fitness 指沒有重視身體力量、健康和體能訓練。"},{"en":"A player who ignores fitness may struggle during the second half of a match.","zh":"忽視體能的球員可能在比賽下半場感到吃力。"},{"en":"Dancers cannot ignore fitness because routines require endurance.","zh":"舞者不能忽視體能，因為整套舞蹈需要耐力。"},{"en":"This phrase warns that skill alone is not enough.","zh":"這個短語提醒我們，單靠技巧並不足夠。"}],"source":"2017 Q8.pdf","sourcePage":14},{"front":"lose stamina","meaning":"失去耐力","examples":[{"en":"A dancer who ignores fitness may lose stamina.","zh":"忽視體能的舞者可能失去耐力。"},{"en":"Lose stamina means lose the ability to keep going physically for a long time.","zh":"lose stamina 指失去長時間持續體力活動的能力。"},{"en":"A runner may lose stamina if he stops training for several weeks.","zh":"如果跑手停止訓練數星期，可能會失去耐力。"},{"en":"Dancers who lose stamina may become tired before the routine ends.","zh":"失去耐力的舞者可能在整套舞蹈結束前已經疲倦。"},{"en":"This phrase shows why regular conditioning matters.","zh":"這個短語顯示為何定期體能訓練重要。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"skip practice","meaning":"缺席練習","examples":[{"en":"A dancer who skips practice quickly falls behind.","zh":"缺席練習的舞者很快會落後。"},{"en":"Skip practice means miss or choose not to attend training.","zh":"skip practice 指錯過或選擇不參加訓練。"},{"en":"A student who skips practice before a speech may forget important lines.","zh":"演講前缺席練習的學生可能忘記重要句子。"},{"en":"Dancers who skip practice may not know new formations.","zh":"缺席練習的舞者可能不知道新隊形。"},{"en":"This phrase shows how missing training affects the whole team.","zh":"這個短語顯示缺席訓練如何影響整個團隊。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"fall behind","meaning":"落後","examples":[{"en":"A dancer who skips practice quickly falls behind.","zh":"缺席練習的舞者很快會落後。"},{"en":"Fall behind means become slower or less advanced than others.","zh":"fall behind 指變得比其他人慢或進度較差。"},{"en":"Students may fall behind if they miss several lessons.","zh":"如果學生缺席幾堂課，可能會落後。"},{"en":"A dancer can fall behind when the team learns new steps without her.","zh":"當隊伍學新步伐而她不在，舞者可能會落後。"},{"en":"This phrase shows the result of lost practice time.","zh":"這個短語顯示失去練習時間的結果。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"in this sense","meaning":"從這個意義上說","examples":[{"en":"In this sense, dance is no less serious than swimming or basketball.","zh":"從這個意義上說，舞蹈不比游泳或籃球遜色。"},{"en":"In this sense means from this particular point of view.","zh":"in this sense 指從這個特定角度來看。"},{"en":"In this sense, homework is like training because both build habits.","zh":"從這個意義上說，功課像訓練，因為兩者都建立習慣。"},{"en":"In this sense, dancers are athletes because they train their bodies and minds.","zh":"從這個意義上說，舞者是運動員，因為他們訓練身體和心理。"},{"en":"This phrase helps explain exactly how the comparison should be understood.","zh":"這個短語幫助解釋應如何理解比較。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"no less serious than","meaning":"不比……遜色；同樣嚴肅","examples":[{"en":"Dance is no less serious than swimming, athletics or basketball.","zh":"舞蹈不比游泳、田徑或籃球遜色。"},{"en":"No less serious than means just as serious as something else.","zh":"no less serious than 指與另一事物同樣嚴肅。"},{"en":"School drama is no less serious than music when students train hard for it.","zh":"如果學生努力訓練，學校戲劇不比音樂遜色。"},{"en":"Dance is no less serious than other sports because it requires strength and discipline.","zh":"舞蹈不比其他運動遜色，因為它需要力量和紀律。"},{"en":"This phrase argues for equal respect.","zh":"這個短語主張同等尊重。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"athletics","meaning":"田徑","examples":[{"en":"Dance is as demanding as swimming, athletics or basketball.","zh":"舞蹈和游泳、田徑或籃球一樣高要求。"},{"en":"Athletics means track and field sports such as running, jumping and throwing.","zh":"athletics 指跑、跳、擲等田徑運動。"},{"en":"Athletics requires speed, strength, technique and regular training.","zh":"田徑需要速度、力量、技巧和定期訓練。"},{"en":"Like athletics, dance tests the body through repetition and control.","zh":"像田徑一樣，舞蹈透過重複和控制考驗身體。"},{"en":"This word helps compare dance with recognised physical sports.","zh":"這個詞幫助把舞蹈與公認的體育項目作比較。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"the costume may sparkle","meaning":"服裝或許閃亮","examples":[{"en":"The costume may sparkle, but the training behind it is hard work.","zh":"服裝或許閃亮，但背後的訓練是艱苦工作。"},{"en":"The costume may sparkle means the dancer’s outfit may shine and look beautiful.","zh":"the costume may sparkle 指舞者的服裝可能閃閃發光、看起來漂亮。"},{"en":"The costume may sparkle under stage lights, but the dancer’s legs may be aching.","zh":"服裝或許在舞台燈下閃亮，但舞者雙腿可能正在痠痛。"},{"en":"A sparkling costume can attract attention while hiding effort.","zh":"閃亮服裝可以吸引注意，同時隱藏努力。"},{"en":"This phrase contrasts surface glamour with real labour.","zh":"這個短語把表面華麗與真正勞動形成對比。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"sweat, repetition and responsibility","meaning":"汗水、重複和責任","examples":[{"en":"The training behind dance is sweat, repetition and responsibility.","zh":"舞蹈背後的訓練是汗水、重複和責任。"},{"en":"Sweat, repetition and responsibility means hard physical effort, repeated practice and duty to the team.","zh":"sweat, repetition and responsibility 指艱苦體力努力、反覆練習和對團隊的責任。"},{"en":"A serious athlete’s progress often comes from sweat, repetition and responsibility.","zh":"認真運動員的進步常來自汗水、重複和責任。"},{"en":"Dancers show responsibility by practising until the team moves together.","zh":"舞者透過練習到隊伍動作一致來展現責任。"},{"en":"This phrase summarises the real work behind performance.","zh":"這個短語總結表演背後真正的工作。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"ultimately","meaning":"最終","examples":[{"en":"Ultimately, our school should recognise dancers as athletes.","zh":"最終，我們學校應承認舞者是運動員。"},{"en":"Ultimately means in the end, after considering all the reasons.","zh":"ultimately 指在考慮所有理由之後，最終而言。"},{"en":"Ultimately, students learn best when effort and support work together.","zh":"最終，當努力和支持一起出現，學生學得最好。"},{"en":"Ultimately, dance should be respected because it requires strength, skill and discipline.","zh":"最終，舞蹈應受尊重，因為它需要力量、技巧和紀律。"},{"en":"This word introduces a final conclusion.","zh":"這個詞引入最後結論。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"recognise dancers as athletes","meaning":"承認舞者是運動員","examples":[{"en":"Our school should recognise dancers as athletes.","zh":"我們學校應承認舞者是運動員。"},{"en":"Recognise dancers as athletes means officially or socially accept that dancers train like sportspeople.","zh":"recognise dancers as athletes 指正式或在社群中接受舞者像運動員一樣訓練。"},{"en":"Schools recognise dancers as athletes when they give dance teams proper space and support.","zh":"當學校給舞蹈隊合適空間和支持，就是承認舞者是運動員。"},{"en":"If people recognise dancers as athletes, they will value rehearsal as real training.","zh":"如果人們承認舞者是運動員，就會重視排練作為真正訓練。"},{"en":"This phrase is the central claim of the essay.","zh":"這個短語是文章的核心主張。"}],"source":"2017 Q8.pdf","sourcePage":15},{"front":"not merely performers","meaning":"不只是表演者","examples":[{"en":"Dancers are athletes, not merely performers.","zh":"舞者是運動員，不只是表演者。"},{"en":"Not merely performers means not only people who entertain an audience.","zh":"not merely performers 指不只是娛樂觀眾的人。"},{"en":"Dancers are not merely performers because they train strength, stamina and control.","zh":"舞者不只是表演者，因為他們訓練力量、耐力和控制。"},{"en":"A school team should be seen as athletes, not merely performers for assemblies.","zh":"學校隊伍應被視為運動員，而不只是集會上的表演者。"},{"en":"This phrase pushes readers to respect the work behind the show.","zh":"這個短語推動讀者尊重表演背後的工作。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"give dance the same respect","meaning":"給予舞蹈同等尊重","examples":[{"en":"We should give dance the same respect we give to other sports teams.","zh":"我們應給予舞蹈與其他運動隊伍同等的尊重。"},{"en":"Give dance the same respect means treat dance as equally serious and valuable.","zh":"give dance the same respect 指把舞蹈視為同樣嚴肅和有價值。"},{"en":"Schools give dance the same respect when they celebrate dancers’ hard work publicly.","zh":"當學校公開表揚舞者努力，就是給予舞蹈同等尊重。"},{"en":"Giving dance the same respect can encourage more students to train seriously.","zh":"給予舞蹈同等尊重可以鼓勵更多學生認真訓練。"},{"en":"This phrase asks for fairness, not special treatment.","zh":"這個短語要求公平，而不是特殊待遇。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"sports teams","meaning":"運動隊伍","examples":[{"en":"Dance teams deserve the same respect as other sports teams.","zh":"舞蹈隊值得得到與其他運動隊伍同樣的尊重。"},{"en":"Sports teams are groups of athletes who train and compete or perform together.","zh":"sports teams 指一起訓練、比賽或表現的運動員團體。"},{"en":"Football, swimming and athletics teams are common school sports teams.","zh":"足球、游泳和田徑隊是常見的學校運動隊伍。"},{"en":"Sports teams need coaches, practice time, equipment and encouragement.","zh":"運動隊伍需要教練、練習時間、設備和鼓勵。"},{"en":"This phrase helps place dance teams beside recognised athletic groups.","zh":"這個短語幫助把舞蹈隊放在公認的運動團體旁邊。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"proper rehearsal space","meaning":"合適的排練空間","examples":[{"en":"Dancers need proper rehearsal space.","zh":"舞者需要合適的排練空間。"},{"en":"Proper rehearsal space means a safe and suitable place for practising performance.","zh":"proper rehearsal space 指安全而適合練習表演的地方。"},{"en":"A proper rehearsal space should have enough room, safe flooring and mirrors.","zh":"合適的排練空間應有足夠位置、安全地板和鏡子。"},{"en":"Without proper rehearsal space, dancers may injure themselves or practise poorly.","zh":"沒有合適的排練空間，舞者可能受傷或練習效果差。"},{"en":"This phrase shows a practical form of support.","zh":"這個短語顯示一種實際支持。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"serious encouragement","meaning":"認真的鼓勵","examples":[{"en":"Dance teams deserve serious encouragement.","zh":"舞蹈隊值得得到認真的鼓勵。"},{"en":"Serious encouragement means sincere support that recognises real effort.","zh":"serious encouragement 指真誠支持，並承認真正努力。"},{"en":"Students need serious encouragement when training becomes tiring.","zh":"當訓練變得疲累時，學生需要認真的鼓勵。"},{"en":"Serious encouragement is more helpful than treating dance as a pretty extra activity.","zh":"認真的鼓勵比把舞蹈視為漂亮的附加活動更有幫助。"},{"en":"This phrase shows that dancers need respect, not casual praise.","zh":"這個短語顯示舞者需要尊重，而不是隨便讚美。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"genuine applause","meaning":"真誠的掌聲","examples":[{"en":"Dancers deserve genuine applause for their effort.","zh":"舞者的努力值得真誠的掌聲。"},{"en":"Genuine applause means honest appreciation, not polite clapping only.","zh":"genuine applause 指真心欣賞，而不只是禮貌拍手。"},{"en":"The audience gave genuine applause after seeing the team’s difficult routine.","zh":"觀眾看見隊伍困難的舞蹈後，給予真誠的掌聲。"},{"en":"Genuine applause can make performers feel their hard work has been recognised.","zh":"真誠的掌聲可以令表演者感到自己的努力被承認。"},{"en":"This phrase connects audience response with respect.","zh":"這個短語把觀眾反應與尊重連在一起。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"the next time","meaning":"下一次","examples":[{"en":"The next time you watch dancers on stage, think about their discipline.","zh":"下一次你看舞者在舞台上表演時，想想他們的紀律。"},{"en":"The next time means when this situation happens again in the future.","zh":"the next time 指將來這種情況再次發生時。"},{"en":"The next time you see a dance performance, notice the strength behind the smile.","zh":"下一次你看舞蹈表演時，留意微笑背後的力量。"},{"en":"The next time students complain about practice, remind them progress takes time.","zh":"下一次學生抱怨練習時，提醒他們進步需要時間。"},{"en":"This phrase directly invites readers to change future behaviour.","zh":"這個短語直接邀請讀者改變未來行為。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"on stage","meaning":"在舞台上","examples":[{"en":"The next time you watch dancers on stage, notice their strength.","zh":"下一次你看舞者在舞台上表演時，留意他們的力量。"},{"en":"On stage means performing in front of an audience.","zh":"on stage 指在觀眾面前表演。"},{"en":"A dancer may look calm on stage even when nervous inside.","zh":"舞者在舞台上可能看起來冷靜，即使內心緊張。"},{"en":"Mistakes on stage must be handled quickly because the performance continues.","zh":"舞台上的錯誤必須快速處理，因為表演會繼續。"},{"en":"This phrase marks the public side of performance.","zh":"這個短語標示表演的公開一面。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"ask instead","meaning":"反而要問","examples":[{"en":"Ask instead how much strength and discipline the performance required.","zh":"反而要問那場表演需要多少力量和紀律。"},{"en":"Ask instead means ask a different, better question rather than the usual one.","zh":"ask instead 指提出另一個更好的問題，而不是平常那個問題。"},{"en":"Do not ask only whether the costume is pretty; ask instead how hard the routine was.","zh":"不要只問服裝是否漂亮；反而要問那套舞蹈有多困難。"},{"en":"When judging a trend, ask instead whether it has real value.","zh":"評價潮流時，反而要問它是否有真正價值。"},{"en":"This phrase guides readers toward deeper thinking.","zh":"這個短語引導讀者作更深入思考。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"strength, control and discipline","meaning":"力量、控制力和紀律","examples":[{"en":"Dance requires strength, control and discipline.","zh":"舞蹈需要力量、控制力和紀律。"},{"en":"Strength, control and discipline means physical power, careful movement and steady self-training.","zh":"strength, control and discipline 指身體力量、仔細動作和穩定自我訓練。"},{"en":"A dancer needs strength, control and discipline to jump safely and perform confidently.","zh":"舞者需要力量、控制力和紀律，才能安全跳躍並自信表演。"},{"en":"Without strength, control and discipline, a routine may look weak or unsafe.","zh":"沒有力量、控制力和紀律，整套舞蹈可能看起來薄弱或不安全。"},{"en":"This phrase summarises the main athletic qualities in dance.","zh":"這個短語總結舞蹈中的主要運動員特質。"}],"source":"2017 Q8.pdf","sourcePage":16},{"front":"more than enough to","meaning":"足以……","examples":[{"en":"The effort is more than enough to prove the point.","zh":"這份努力足以證明這一點。"},{"en":"More than enough to means fully sufficient to do something.","zh":"more than enough to 指完全足夠做到某事。"},{"en":"One month of daily rehearsal is more than enough to show the team’s commitment.","zh":"一個月每天排練，足以顯示隊伍的承諾。"},{"en":"The injuries, sweat and training are more than enough to prove dance is demanding.","zh":"傷患、汗水和訓練足以證明舞蹈要求很高。"},{"en":"This phrase strengthens a conclusion by saying the evidence is already sufficient.","zh":"這個短語透過說證據已經足夠來加強結論。"}],"source":"2017 Q8.pdf","sourcePage":17},{"front":"prove the point","meaning":"證明這一點","examples":[{"en":"The training behind dance proves the point.","zh":"舞蹈背後的訓練證明這一點。"},{"en":"Prove the point means show that an argument is true.","zh":"prove the point 指顯示某個論點是真的。"},{"en":"The team’s strict rehearsal schedule proves the point that dance needs discipline.","zh":"隊伍嚴格的排練時間表證明舞蹈需要紀律這一點。"},{"en":"A difficult routine can prove the point better than a long explanation.","zh":"一套困難舞蹈可以比長篇解釋更能證明這一點。"},{"en":"This phrase connects evidence with the writer’s claim.","zh":"這個短語把證據與作者主張連在一起。"}],"source":"2017 Q8.pdf","sourcePage":17},{"front":"treat them as such","meaning":"以此身分看待他們","examples":[{"en":"Dancers are athletes, and it is time we treated them as such.","zh":"舞者是運動員，是時候我們以此身分看待他們了。"},{"en":"Treat them as such means treat them according to the identity just named.","zh":"treat them as such 指按照剛才提到的身分對待他們。"},{"en":"If students are leaders, teachers should treat them as such by trusting them with responsibility.","zh":"如果學生是領袖，老師應透過信任他們承擔責任來以此身分看待他們。"},{"en":"If dancers are athletes, schools should treat them as such with space, support and respect.","zh":"如果舞者是運動員，學校就應以空間、支持和尊重來以此身分看待他們。"},{"en":"This phrase gives a clear final call to action.","zh":"這個短語給出清楚的最後行動呼籲。"}],"source":"2017 Q8.pdf","sourcePage":17}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2017_SEED);
